struct BrowserProfileModel {
    profiles: Vec<BrowserProfileId>,
    active_profile: BrowserProfileId,
    next_profile_id: u64,
}

impl BrowserProfileModel {
    fn shell_default() -> Self {
        /*
        CDXC:GPUIBrowserProfiles 2026-06-23-11:14:
        GPUI Browser profile parity is shell-owned and generated-only for this slice: keep a built-in Default profile plus app-generated Profile N ids, persist only those stable ids and the active id, and avoid user-entered names, profile paths, imported browser data, cookies, credentials, history, page titles, URLs, command text, or local paths.
        */
        Self {
            profiles: vec![BrowserProfileId::default_profile()],
            active_profile: BrowserProfileId::default_profile(),
            next_profile_id: BROWSER_PROFILE_FIRST_GENERATED_ID,
        }
    }

    fn contains_profile(&self, profile_id: BrowserProfileId) -> bool {
        self.profiles.contains(&profile_id)
    }

    fn active_profile_id(&self) -> BrowserProfileId {
        if self.contains_profile(self.active_profile) {
            self.active_profile
        } else {
            BrowserProfileId::default_profile()
        }
    }

    fn profile_ids(&self) -> impl Iterator<Item = BrowserProfileId> + '_ {
        self.profiles.iter().copied()
    }

    fn select_profile(&mut self, profile_id: BrowserProfileId) -> bool {
        if !self.contains_profile(profile_id) || self.active_profile_id() == profile_id {
            return false;
        }

        self.active_profile = profile_id;
        true
    }

    fn create_generated_profile(&mut self) -> Option<BrowserProfileId> {
        if self.profiles.len() >= BROWSER_PROFILE_MAX_PROFILES {
            return None;
        }

        let mut next_id = self.next_profile_id.max(BROWSER_PROFILE_FIRST_GENERATED_ID);
        while self.contains_profile(BrowserProfileId(next_id)) {
            if next_id == u64::MAX {
                return None;
            }
            next_id = next_id.saturating_add(1);
        }

        let profile_id = BrowserProfileId(next_id);
        self.profiles.push(profile_id);
        self.active_profile = profile_id;
        self.next_profile_id = next_id.saturating_add(1);
        Some(profile_id)
    }
}

