fn terminal_clipboard_explicit_string_text(item: &ClipboardItem) -> Option<String> {
    let mut text = String::new();

    for entry in item.entries() {
        if let ClipboardEntry::String(clipboard_string) = entry {
            text.push_str(clipboard_string.text());
        }
    }

    if text.is_empty() { None } else { Some(text) }
}

fn terminal_runtime_clipboard_read_explicit_string_text(
    read_standard_clipboard: impl FnOnce() -> Option<ClipboardItem>,
) -> Option<String> {
    read_standard_clipboard()
        .as_ref()
        .and_then(terminal_clipboard_explicit_string_text)
}

fn terminal_runtime_clipboard_write_standard_text(
    text: String,
    mut write_standard_clipboard: impl FnMut(ClipboardItem),
) {
    write_standard_clipboard(ClipboardItem::new_string(text));
}

