    fn select_agents_tab_from_action(
        &mut self,
        pane_id: WorkspacePaneId,
        session_id: TerminalSessionId,
        cx: &mut gpui::Context<Self>,
    ) {
        if self
            .agents_workspace
            .find_leaf(pane_id)
            .is_some_and(|leaf| leaf.tab_group.has_session(session_id))
        {
            self.select_agents_tab(pane_id, session_id);
            cx.notify();
        }
    }

    fn close_agents_tab_from_action(
        &mut self,
        pane_id: WorkspacePaneId,
        session_id: TerminalSessionId,
        cx: &mut gpui::Context<Self>,
    ) {
        self.close_agents_tab(pane_id, session_id, cx);
    }

    fn close_agents_tab(
        &mut self,
        pane_id: WorkspacePaneId,
        session_id: TerminalSessionId,
        cx: &mut gpui::Context<Self>,
    ) -> bool {
        if self.request_close_agents_running_surface_if_mounted(AgentsTerminalBodyMountSlotId {
            pane_id,
            session_id,
        }) {
            cx.notify();
            return true;
        }

        if !self.agents_workspace.close_tab(pane_id, session_id) {
            return false;
        }
        self.set_shell_focus(ShellFocusTarget::AgentsPane(
            self.agents_workspace.focused_pane,
        ));
        self.scroll_workspace_pane_active_tab(self.agents_workspace.focused_pane);
        self.persist_shell_layout_state();
        cx.notify();
        true
    }

    fn request_close_focused_agents_running_surface(&mut self) -> bool {
        let Some(slot_id) = focused_agents_terminal_surface_mount_slot(
            self.active_mode,
            self.shell_focus,
            &self.agents_workspace,
        ) else {
            return false;
        };
        self.request_close_agents_running_surface_if_mounted(slot_id)
    }

