    fn add_agents_placeholder_terminal_tab(
        &mut self,
        pane_id: WorkspacePaneId,
        cx: &mut gpui::Context<Self>,
    ) {
        if self
            .agents_workspace
            .add_mounting_session_to_pane(pane_id)
            .is_some()
        {
            self.set_shell_focus(ShellFocusTarget::AgentsPane(
                self.agents_workspace.focused_pane,
            ));
            self.workspace_drop_feedback = None;
            self.scroll_workspace_pane_active_tab(self.agents_workspace.focused_pane);
            self.persist_shell_layout_state();
            cx.notify();
        }
    }

    fn add_terminal_placeholder_tab_from_hotkey(&mut self, cx: &mut gpui::Context<Self>) {
        /*
        CDXC:GPUIFocusedNewTabs 2026-06-22-23:33:
        Cmd+T follows the shell surface that owns keyboard focus. Command-pane focus adds a command-only placeholder to the focused command group and never creates an Agents workspace tab; Agents-pane focus in Agents mode creates a selected Mounting terminal session in that focused Agents pane because no real process has started yet. Browser, Source, Kanban, and Manage surface focus remain out of scope for terminal creation.
        */
        match self.shell_focus {
            ShellFocusTarget::CommandPane => {
                if !self.command_pane.has_sessions()
                    || self
                        .command_pane
                        .find_leaf(self.command_pane.focused_group)
                        .is_none()
                {
                    return;
                }
                self.command_pane.add_session_to_focused_group();
                self.focus_command_pane();
                self.scroll_focused_command_active_tab();
                self.persist_shell_layout_state();
                cx.notify();
            }
            ShellFocusTarget::AgentsPane(pane_id) if self.active_mode == TitlebarMode::Agents => {
                self.add_agents_placeholder_terminal_tab(pane_id, cx);
            }
            ShellFocusTarget::BrowserSurface
            | ShellFocusTarget::ProjectEditorSurface(_)
            | ShellFocusTarget::ProjectEditorCompanion(_)
            | ShellFocusTarget::AgentsPane(_) => {}
        }
    }

    fn split_focused_terminal_from_hotkey(
        &mut self,
        direction: FocusedTerminalSplitDirection,
        cx: &mut gpui::Context<Self>,
    ) {
        /*
        CDXC:GPUIFocusedSplits 2026-06-22-23:33:
        Cmd+D/Cmd+Shift+D use live shell focus instead of remembered workspace focus. Agents-pane focus in Agents mode reuses the right/below mounting split helpers because a new terminal runtime has not launched yet; command-pane focus creates a command-only horizontal split for both hotkeys, expands/focuses the command pane, persists, and scrolls active command tabs.
        */
        match self.shell_focus {
            ShellFocusTarget::CommandPane => {
                self.split_command_placeholder_terminal_from_hotkey(cx);
            }
            ShellFocusTarget::AgentsPane(pane_id) if self.active_mode == TitlebarMode::Agents => {
                match direction {
                    FocusedTerminalSplitDirection::Right => {
                        self.split_agents_placeholder_terminal_right(pane_id, cx);
                    }
                    FocusedTerminalSplitDirection::Down => {
                        self.split_agents_placeholder_terminal_below(pane_id, cx);
                    }
                }
            }
            ShellFocusTarget::BrowserSurface
            | ShellFocusTarget::ProjectEditorSurface(_)
            | ShellFocusTarget::ProjectEditorCompanion(_)
            | ShellFocusTarget::AgentsPane(_) => {}
        }
    }

    fn split_command_placeholder_terminal_from_hotkey(&mut self, cx: &mut gpui::Context<Self>) {
        let Some((group_id, _session_id)) =
            self.command_pane.split_session_to_right_of_focused_group()
        else {
            return;
        };

        self.focus_command_pane();
        self.command_drop_feedback = None;
        self.scroll_command_group_active_tab(group_id);
        self.scroll_focused_command_active_tab();
        self.persist_shell_layout_state();
        cx.notify();
    }

