    fn handle_command_pane_resize_rail_mouse_down(
        &mut self,
        event: &MouseDownEvent,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        window.prevent_default();
        cx.stop_propagation();

        if event.click_count >= 2 {
            self.command_pane
                .reset_height(command_pane_content_height(window));
            self.persist_shell_layout_state();
            cx.notify();
            return;
        }

        self.command_pane.resize_drag = Some(CommandPaneResizeDragState {
            start_y: event.position.y.as_f32(),
            start_height_ratio: self.command_pane.height_ratio,
            start_content_height: command_pane_content_height(window),
        });
        cx.notify();
    }

    fn handle_command_pane_resize_drag_move(
        &mut self,
        event: &MouseMoveEvent,
        window: &mut Window,
        cx: &mut gpui::Context<Self>,
    ) {
        let Some(drag) = self.command_pane.resize_drag else {
            return;
        };

        if !event.dragging() {
            self.finish_command_pane_resize_drag(cx);
            return;
        }

        window.prevent_default();
        cx.stop_propagation();

        let content_height = drag.start_content_height.max(1.0);
        let start_height = command_pane_height_for_ratio(drag.start_height_ratio, content_height);
        let delta = drag.start_y - event.position.y.as_f32();
        let next_ratio = command_pane_height_ratio((start_height + delta) / content_height);

        if (next_ratio - self.command_pane.height_ratio).abs() >= 0.001 {
            self.command_pane.height_ratio = next_ratio;
            cx.notify();
        }
    }

