    fn render_command_pane_controls(
        &self,
        group_id: Option<CommandPaneGroupId>,
        expanded_chrome: bool,
        cx: &mut gpui::Context<Self>,
    ) -> AnyElement {
        let pin_label = if self.command_pane.mode == CommandPaneMode::Pinned {
            "F"
        } else {
            "P"
        };
        let pin_tooltip = if self.command_pane.mode == CommandPaneMode::Pinned {
            "Float command pane"
        } else {
            "Pin command pane"
        };
        let expand_label = if self.command_pane.is_expanded() {
            "v"
        } else {
            "^"
        };
        let expand_tooltip = if self.command_pane.is_expanded() {
            "Collapse command pane"
        } else {
            "Expand command pane"
        };
        let controls_id = if expanded_chrome {
            match group_id {
                Some(group_id) => {
                    format!("ghostex-gpui-command-pane-titlebar-controls-{}", group_id.0)
                }
                None => "ghostex-gpui-command-pane-titlebar-controls".to_string(),
            }
        } else {
            "ghostex-gpui-command-pane-strip-controls".to_string()
        };

        /*
        CDXC:GPUICommandPaneControls 2026-06-24-07:33:
        Visible command-pane chrome copy should describe command actions instead of placeholder internals. This source-only control stays non-launching and private-detail-free: it creates only the existing command shell entry without terminal/CEF runtime work, command text, or output.
        */
        h_flex()
            .id(controls_id)
            .flex_shrink_0()
            .h_full()
            .items_center()
            .gap(px(4.0))
            .border_l_1()
            .border_color(command_pane_border_color())
            .px(px(6.0))
            .bg(command_pane_control_cluster_color())
            .child(self.render_command_pane_control_button(
                "new-command",
                "+",
                "New command",
                CommandPaneControlAction::NewCommandPlaceholder,
                group_id,
                cx,
            ))
            .child(self.render_command_pane_control_button(
                "pin",
                pin_label,
                pin_tooltip,
                CommandPaneControlAction::TogglePinned,
                group_id,
                cx,
            ))
            .child(self.render_command_pane_control_button(
                "expand",
                expand_label,
                expand_tooltip,
                CommandPaneControlAction::ToggleExpanded,
                group_id,
                cx,
            ))
            .when(expanded_chrome, |this| {
                this.child(self.render_command_pane_control_button(
                    "close-panel",
                    "x",
                    "Close command panel",
                    CommandPaneControlAction::ClosePanel,
                    group_id,
                    cx,
                ))
            })
            .into_any_element()
    }

    fn render_command_pane_control_button(
        &self,
        id: &'static str,
        label: &'static str,
        tooltip: &'static str,
        action: CommandPaneControlAction,
        group_id: Option<CommandPaneGroupId>,
        cx: &mut gpui::Context<Self>,
    ) -> AnyElement {
        let element_id = match group_id {
            Some(group_id) => format!("ghostex-gpui-command-pane-control-{id}-{}", group_id.0),
            None => format!("ghostex-gpui-command-pane-control-{id}"),
        };

        div()
            .id(element_id)
            .flex()
            .size(px(COMMAND_PANE_CONTROL_BUTTON_SIZE))
            .items_center()
            .justify_center()
            .rounded(px(4.0))
            .text_size(px(12.0))
            .font_weight(FontWeight::SEMIBOLD)
            .line_height(px(COMMAND_PANE_CONTROL_BUTTON_SIZE))
            .text_color(command_pane_control_text_color())
            .cursor_default()
            .hover(|this| this.bg(command_pane_control_hover_color()))
            .on_mouse_down(
                MouseButton::Left,
                cx.listener(move |this, _event: &MouseDownEvent, window, cx| {
                    window.prevent_default();
                    cx.stop_propagation();
                    if matches!(action, CommandPaneControlAction::NewCommandPlaceholder)
                        && let Some(group_id) = group_id
                    {
                        this.command_pane.focus_group(group_id);
                    }
                    this.handle_command_pane_control_action(action, cx);
                }),
            )
            .tooltip(move |window, cx| Tooltip::new(tooltip).build(window, cx))
            .child(label)
            .into_any_element()
    }

    fn render_agents_terminal_close_confirm_surface(
        &self,
        leaf: &WorkspaceLeaf,
        cx: &mut gpui::Context<Self>,
    ) -> Option<AnyElement> {
        #[cfg(target_os = "macos")]
        {
            let slot_id = self.agents_terminal_close_confirm_slot_for_leaf(leaf)?;
            let signature =
                terminal_close_confirm_surface_signature(TerminalCloseConfirmSurfaceFamily::Agents);
            let element_id = format!(
                "ghostex-gpui-terminal-close-confirm-agents-{}-{}",
                slot_id.pane_id.0, slot_id.session_id.0
            );

            Some(self.render_terminal_close_confirm_surface(
                signature,
                element_id,
                format!("agents-{}-{}", slot_id.pane_id.0, slot_id.session_id.0),
                move |this, _event, _window, cx| {
                    if this.cancel_pending_agents_terminal_close(slot_id) {
                        cx.notify();
                    }
                },
                move |this, _event, _window, cx| {
                    if this.confirm_pending_agents_terminal_close(slot_id) {
                        cx.notify();
                    }
                },
                cx,
            ))
        }

        #[cfg(not(target_os = "macos"))]
        {
            let _ = leaf;
            let _ = cx;
            None
        }
    }

    fn render_command_terminal_close_confirm_surface(
        &self,
        leaf: &CommandPaneLeaf,
        cx: &mut gpui::Context<Self>,
    ) -> Option<AnyElement> {
        #[cfg(target_os = "macos")]
        {
            let slot_id = self.command_terminal_close_confirm_slot_for_leaf(leaf)?;
            let signature = terminal_close_confirm_surface_signature(
                TerminalCloseConfirmSurfaceFamily::Command,
            );
            let element_id = format!(
                "ghostex-gpui-terminal-close-confirm-command-{}-{}",
                slot_id.group_id.0, slot_id.session_id.0
            );

            Some(self.render_terminal_close_confirm_surface(
                signature,
                element_id,
                format!("command-{}-{}", slot_id.group_id.0, slot_id.session_id.0),
                move |this, _event, _window, cx| {
                    if this.cancel_pending_command_terminal_close(slot_id) {
                        cx.notify();
                    }
                },
                move |this, _event, _window, cx| {
                    if this.confirm_pending_command_terminal_close(slot_id) {
                        cx.notify();
                    }
                },
                cx,
            ))
        }

        #[cfg(not(target_os = "macos"))]
        {
            let _ = leaf;
            let _ = cx;
            None
        }
    }

    #[cfg(target_os = "macos")]
    fn agents_terminal_close_confirm_slot_for_leaf(
        &self,
        leaf: &WorkspaceLeaf,
    ) -> Option<AgentsTerminalBodyMountSlotId> {
        let slot_id = self
            .agents_workspace
            .terminal_body_mount_candidate(leaf)
            .mount_slot_id()?;
        self.agents_terminal_close_confirms
            .exact_current_pending_slot(
                &self.agents_workspace,
                &self.agents_terminal_runtime_sessions,
                &self.agents_terminal_ghostty_surfaces,
                slot_id,
            )
    }

    #[cfg(target_os = "macos")]
    fn command_terminal_close_confirm_slot_for_leaf(
        &self,
        leaf: &CommandPaneLeaf,
    ) -> Option<CommandTerminalBodyMountSlotId> {
        let session_id = leaf.tab_group.active_session_id()?;
        let slot_id = CommandTerminalBodyMountSlotId {
            group_id: leaf.group_id,
            session_id,
        };
        self.command_terminal_close_confirms
            .exact_current_pending_slot(
                &self.command_pane,
                &self.command_terminal_ghostty_surfaces,
                slot_id,
            )
    }

    fn render_terminal_close_confirm_surface(
        &self,
        signature: TerminalCloseConfirmSurfaceSignature,
        element_id: String,
        element_id_suffix: String,
        keep_open: impl Fn(&mut Self, &MouseDownEvent, &mut Window, &mut gpui::Context<Self>) + 'static,
        confirm_close: impl Fn(&mut Self, &MouseDownEvent, &mut Window, &mut gpui::Context<Self>)
        + 'static,
        cx: &mut gpui::Context<Self>,
    ) -> AnyElement {
        /*
        CDXC:GPUITerminalCloseConfirm 2026-06-23-20:04:
        Render close-confirm prompts as visible normal-layout siblings above terminal content. The banner reduces the mounted Ghostty body region instead of overlapping it, keeps Agents and command state scoped to their own render branches, wires Keep Open to cancel, and wires the generic Close Terminal action to exact source-side model removal after `needs_confirm_quit` validation.
        */
        let family = signature.family;
        let confirm_action_enabled = signature.confirm_action_enabled;
        let badge_label = signature.badge_label;
        let title = signature.title;
        let message = signature.message;
        let keep_open_label = signature.keep_open_label;
        let confirm_action_label = signature.confirm_action_label;
        let confirm_action_tooltip = signature.confirm_action_tooltip;

        div()
            .id(element_id)
            .flex()
            .flex_shrink_0()
            .w_full()
            .items_center()
            .justify_center()
            .border_b_1()
            .border_color(terminal_close_confirm_surface_border_color(family))
            .bg(terminal_close_confirm_surface_outer_color(family))
            .px(px(10.0))
            .py(px(8.0))
            .child(
                v_flex()
                    .id(format!(
                        "ghostex-gpui-terminal-close-confirm-card-{element_id_suffix}"
                    ))
                    .w_full()
                    .max_w(px(TERMINAL_CLOSE_CONFIRM_SURFACE_MAX_WIDTH))
                    .min_w_0()
                    .rounded(px(6.0))
                    .border_1()
                    .border_color(terminal_close_confirm_surface_border_color(family))
                    .bg(terminal_close_confirm_surface_card_color(family))
                    .px(px(12.0))
                    .py(px(9.0))
                    .child(
                        h_flex()
                            .min_w_0()
                            .items_center()
                            .gap(px(8.0))
                            .child(
                                div()
                                    .flex_shrink_0()
                                    .rounded(px(4.0))
                                    .bg(terminal_close_confirm_surface_badge_color(family))
                                    .px(px(7.0))
                                    .py(px(2.0))
                                    .text_size(px(10.0))
                                    .font_weight(FontWeight::SEMIBOLD)
                                    .text_color(terminal_close_confirm_surface_badge_text_color(
                                        family,
                                    ))
                                    .child(badge_label),
                            )
                            .child(
                                div()
                                    .flex_shrink_0()
                                    .text_size(px(10.5))
                                    .font_weight(FontWeight::SEMIBOLD)
                                    .text_color(terminal_close_confirm_surface_message_color())
                                    .child(family.scope_label()),
                            )
                            .child(
                                div()
                                    .flex_1()
                                    .min_w_0()
                                    .overflow_hidden()
                                    .whitespace_nowrap()
                                    .text_ellipsis()
                                    .text_size(px(12.5))
                                    .font_weight(FontWeight::SEMIBOLD)
                                    .text_color(terminal_close_confirm_surface_title_color())
                                    .child(title),
                            ),
                    )
                    .child(
                        div()
                            .mt(px(5.0))
                            .min_w_0()
                            .overflow_hidden()
                            .whitespace_nowrap()
                            .text_ellipsis()
                            .text_size(px(11.5))
                            .line_height(px(16.0))
                            .text_color(terminal_close_confirm_surface_message_color())
                            .child(message),
                    )
                    .child(
                        h_flex()
                            .mt(px(8.0))
                            .items_center()
                            .gap(px(8.0))
                            .child(
                                div()
                                    .id(format!(
                                        "ghostex-gpui-terminal-close-confirm-keep-open-{element_id_suffix}"
                                    ))
                                    .flex()
                                    .h(px(26.0))
                                    .items_center()
                                    .justify_center()
                                    .rounded(px(5.0))
                                    .border_1()
                                    .border_color(
                                        terminal_close_confirm_surface_keep_open_border_color(
                                            family,
                                        ),
                                    )
                                    .bg(terminal_close_confirm_surface_keep_open_color(family))
                                    .px(px(11.0))
                                    .text_size(px(11.5))
                                    .font_weight(FontWeight::SEMIBOLD)
                                    .text_color(
                                        terminal_close_confirm_surface_keep_open_text_color(family),
                                    )
                                    .hover(|this| {
                                        this.bg(terminal_close_confirm_surface_keep_open_hover_color(
                                            family,
                                        ))
                                    })
                                    .on_mouse_down(
                                        MouseButton::Left,
                                        cx.listener(move |this, event: &MouseDownEvent, window, cx| {
                                            window.prevent_default();
                                            cx.stop_propagation();
                                            keep_open(this, event, window, cx);
                                        }),
                                    )
                                    .child(keep_open_label),
                            )
                            .child(
                                div()
                                    .id(format!(
                                        "ghostex-gpui-terminal-close-confirm-close-{element_id_suffix}"
                                    ))
                                    .flex()
                                    .h(px(26.0))
                                    .items_center()
                                    .justify_center()
                                    .rounded(px(5.0))
                                    .border_1()
                                    .border_color(
                                        terminal_close_confirm_surface_close_border_color(family),
                                    )
                                    .bg(terminal_close_confirm_surface_close_color(family))
                                    .px(px(10.0))
                                    .text_size(px(11.5))
                                    .font_weight(FontWeight::SEMIBOLD)
                                    .text_color(terminal_close_confirm_surface_close_text_color(
                                        family,
                                    ))
                                    .hover(|this| {
                                        this.bg(terminal_close_confirm_surface_close_hover_color(
                                            family,
                                        ))
                                    })
                                    .on_mouse_down(
                                        MouseButton::Left,
                                        cx.listener(
                                            move |this, event: &MouseDownEvent, window, cx| {
                                                window.prevent_default();
                                                cx.stop_propagation();
                                                if confirm_action_enabled {
                                                    confirm_close(this, event, window, cx);
                                                }
                                            },
                                        ),
                                    )
                                    .tooltip(move |window, cx| {
                                        Tooltip::new(confirm_action_tooltip).build(window, cx)
                                    })
                                    .child(confirm_action_label),
                            ),
                    ),
            )
            .into_any_element()
    }

    fn render_command_terminal_placeholder(
        &self,
        leaf: &CommandPaneLeaf,
        cx: &mut gpui::Context<Self>,
    ) -> AnyElement {
        let group_id = leaf.group_id;
        let active_session_id = leaf
            .tab_group
            .active_session_id()
            .unwrap_or(CommandSessionId(0));
        let mount_slot_id = self.command_pane.has_session(active_session_id).then_some(
            CommandTerminalBodyMountSlotId {
                group_id,
                session_id: active_session_id,
            },
        );

        /*
        CDXC:GPUICommandTerminalInputForwarding 2026-06-23-09:41:
        Mounted command terminal input uses the same command body div that already owns focus and drop behavior. Button press focuses the command group/pane before trying Ghostty forwarding, movement and button release pass GPUI modifiers to Ghostty input.Mods, and wheel events update pointer position with those mapped modifiers while keeping scroll mods precision-only.

        CDXC:GPUITerminalPressureForwarding 2026-06-23-09:51:
        Command terminal force-click pressure events are wired only for mounted command body slots. Forward pressure through the existing body element without default-stop so command focus and drop behavior keep their current ownership.

        CDXC:GPUICommandTerminalInputForwarding 2026-06-23-10:05:
        Mounted command bodies use GPUI element-level mouse-up-out only for capture-gated release parity. The handler does not route through the window, record outside positions, or synthesize coordinates.

        CDXC:GPUITerminalMouseButtons 2026-06-23-10:23:
        Mounted command bodies must forward right and middle down/up/up-out through the same body element as left. Right and middle down focus the mounted command terminal surface before forwarding the press, while placeholders keep their existing left-click-only focus behavior and no tab/chrome context menus are changed.

        CDXC:GPUITerminalSelectionDrag 2026-06-23-12:43:
        Mounted command selection drag does not need a command-pane-owned selection or drag-capture field. The command body already owns left press, body-relative move, in-body release, capture-gated up-out, typed command/workspace tab drag-over/drop handlers, and command focus handoff as normal sibling layout behavior; keep selection forwarding inside that body instead of adding overlays, hidden hit regions, stored coordinates, global capture, or root/window mouse routing.

        CDXC:GPUITerminalTextInput 2026-06-23-10:45:
        Mounted command terminal IME input is owned by the same body div that owns mouse focus and drop behavior. Track the shared terminal text focus handle and register GPUI's ElementInputHandler only from the body paint callback when this exact command mount slot is the focused terminal target; do not add overlays, hidden hit regions, root/window input routing, synthetic coordinates, logs, persistence, or raw preedit storage.
        */
        div()
            .id(format!(
                "ghostex-gpui-command-terminal-placeholder-{}-{}",
                group_id.0, active_session_id.0
            ))
            .relative()
            .flex_1()
            .min_w_0()
            .min_h_0()
            .w_full()
            .bg(command_terminal_placeholder_color())
            .when(
                mount_slot_id.is_some_and(|slot_id| {
                    self.terminal_text_input_should_track_command_slot(slot_id)
                }),
                |this| {
                    this.track_focus(&self.terminal_text_focus_handle)
                        .tab_stop(false)
                },
            )
            .on_mouse_down(
                MouseButton::Left,
                cx.listener(move |this, event: &MouseDownEvent, window, cx| {
                    window.prevent_default();
                    cx.stop_propagation();
                    if let Some(slot_id) = mount_slot_id {
                        this.focus_command_terminal_mount_slot(slot_id, window, cx);
                        let _ = this.forward_command_terminal_mount_slot_mouse_button(
                            slot_id,
                            event.position,
                            ghostty_kit::ffi::GHOSTTY_MOUSE_PRESS,
                            event.button,
                            event.modifiers,
                        );
                    } else {
                        this.command_pane.focus_group(group_id);
                        this.focus_command_pane();
                        cx.notify();
                    }
                }),
            )
            .on_drag_move::<DraggedCommandTab>(cx.listener(
                move |this, event: &gpui::DragMoveEvent<DraggedCommandTab>, _window, cx| {
                    this.update_command_pane_drag_feedback(event, group_id, cx);
                },
            ))
            .on_drag_move::<DraggedWorkspaceTab>(cx.listener(
                move |this, event: &gpui::DragMoveEvent<DraggedWorkspaceTab>, _window, cx| {
                    this.update_workspace_tab_over_command_pane_drag_feedback(event, group_id, cx);
                },
            ))
            .can_drop(|value, _window, _cx| {
                value.is::<DraggedCommandTab>() || value.is::<DraggedWorkspaceTab>()
            })
            .on_drop(
                cx.listener(move |this, dragged: &DraggedCommandTab, window, cx| {
                    this.handle_command_pane_body_drop(group_id, dragged, window, cx);
                }),
            )
            .on_drop(
                cx.listener(move |this, dragged: &DraggedWorkspaceTab, window, cx| {
                    this.handle_workspace_tab_command_pane_body_drop(group_id, dragged, window, cx);
                }),
            )
            .when_some(mount_slot_id, |this, slot_id| {
                let view = cx.entity().clone();
                this.on_mouse_down(
                    MouseButton::Right,
                    cx.listener(move |this, event: &MouseDownEvent, window, cx| {
                        window.prevent_default();
                        cx.stop_propagation();
                        this.focus_command_terminal_mount_slot(slot_id, window, cx);
                        let _ = this.forward_command_terminal_mount_slot_mouse_button(
                            slot_id,
                            event.position,
                            ghostty_kit::ffi::GHOSTTY_MOUSE_PRESS,
                            event.button,
                            event.modifiers,
                        );
                    }),
                )
                .on_mouse_down(
                    MouseButton::Middle,
                    cx.listener(move |this, event: &MouseDownEvent, window, cx| {
                        window.prevent_default();
                        cx.stop_propagation();
                        this.focus_command_terminal_mount_slot(slot_id, window, cx);
                        let _ = this.forward_command_terminal_mount_slot_mouse_button(
                            slot_id,
                            event.position,
                            ghostty_kit::ffi::GHOSTTY_MOUSE_PRESS,
                            event.button,
                            event.modifiers,
                        );
                    }),
                )
                .on_mouse_move(
                    cx.listener(move |this, event: &MouseMoveEvent, _window, _cx| {
                        let _ = this.forward_command_terminal_mount_slot_mouse_position(
                            slot_id,
                            event.position,
                            event.modifiers,
                        );
                    }),
                )
                .on_mouse_up(
                    MouseButton::Left,
                    cx.listener(move |this, event: &MouseUpEvent, _window, _cx| {
                        let _ = this.forward_command_terminal_mount_slot_mouse_button(
                            slot_id,
                            event.position,
                            ghostty_kit::ffi::GHOSTTY_MOUSE_RELEASE,
                            event.button,
                            event.modifiers,
                        );
                    }),
                )
                .on_mouse_up(
                    MouseButton::Right,
                    cx.listener(move |this, event: &MouseUpEvent, _window, _cx| {
                        let _ = this.forward_command_terminal_mount_slot_mouse_button(
                            slot_id,
                            event.position,
                            ghostty_kit::ffi::GHOSTTY_MOUSE_RELEASE,
                            event.button,
                            event.modifiers,
                        );
                    }),
                )
                .on_mouse_up(
                    MouseButton::Middle,
                    cx.listener(move |this, event: &MouseUpEvent, _window, _cx| {
                        let _ = this.forward_command_terminal_mount_slot_mouse_button(
                            slot_id,
                            event.position,
                            ghostty_kit::ffi::GHOSTTY_MOUSE_RELEASE,
                            event.button,
                            event.modifiers,
                        );
                    }),
                )
                .on_mouse_up_out(
                    MouseButton::Left,
                    cx.listener(move |this, event: &MouseUpEvent, _window, _cx| {
                        let _ = this.forward_command_terminal_mount_slot_mouse_release_outside(
                            slot_id,
                            event.button,
                            event.modifiers,
                        );
                    }),
                )
                .on_mouse_up_out(
                    MouseButton::Right,
                    cx.listener(move |this, event: &MouseUpEvent, _window, _cx| {
                        let _ = this.forward_command_terminal_mount_slot_mouse_release_outside(
                            slot_id,
                            event.button,
                            event.modifiers,
                        );
                    }),
                )
                .on_mouse_up_out(
                    MouseButton::Middle,
                    cx.listener(move |this, event: &MouseUpEvent, _window, _cx| {
                        let _ = this.forward_command_terminal_mount_slot_mouse_release_outside(
                            slot_id,
                            event.button,
                            event.modifiers,
                        );
                    }),
                )
                .on_mouse_pressure(cx.listener(
                    move |this, event: &MousePressureEvent, _window, _cx| {
                        let _ = this.forward_command_terminal_mount_slot_mouse_pressure(
                            slot_id,
                            event.position,
                            event.stage,
                            event.pressure,
                            event.modifiers,
                        );
                    },
                ))
                .on_scroll_wheel(
                    cx.listener(move |this, event: &ScrollWheelEvent, window, cx| {
                        if this.forward_command_terminal_mount_slot_mouse_scroll(
                            slot_id,
                            event.position,
                            event.delta,
                            event.modifiers,
                        ) {
                            window.prevent_default();
                            cx.stop_propagation();
                        }
                    }),
                )
                .child({
                    let bounds_view = view.clone();
                    let input_handler_view = view.clone();
                    canvas(
                        move |bounds, window, cx| {
                            let scale_factor = window.scale_factor();
                            let _ = bounds_view.update(cx, |this, cx| {
                                this.record_command_terminal_mount_slot_bounds(
                                    slot_id,
                                    bounds,
                                    scale_factor,
                                    cx,
                                );
                            });
                        },
                        move |bounds, _, window, cx| {
                            let input_view = input_handler_view.clone();
                            let _ = input_handler_view.update(cx, |this, cx| {
                                this.register_command_terminal_text_input_handler(
                                    slot_id, bounds, input_view, window, cx,
                                );
                            });
                        },
                    )
                    .absolute()
                    .size_full()
                })
            })
            .when_some(self.command_pane_drop_zone(group_id), |this, zone| {
                this.child(self.render_command_pane_drop_feedback(group_id, zone))
            })
            .into_any_element()
    }

    fn command_pane_drop_zone(&self, group_id: CommandPaneGroupId) -> Option<WorkspaceDropZone> {
        match self.command_drop_feedback {
            Some(CommandPaneDropFeedback {
                group_id: feedback_group_id,
                target: CommandPaneDropTarget::PaneBody(zone),
            }) if feedback_group_id == group_id => Some(zone),
            _ => None,
        }
    }

    fn render_command_pane_drop_feedback(
        &self,
        group_id: CommandPaneGroupId,
        zone: WorkspaceDropZone,
    ) -> AnyElement {
        let label = match zone {
            WorkspaceDropZone::Left => "Split left",
            WorkspaceDropZone::Right => "Split right",
            WorkspaceDropZone::Center | WorkspaceDropZone::Top | WorkspaceDropZone::Bottom => {
                "Group"
            }
        };

        let feedback = div()
            .id(format!(
                "ghostex-gpui-command-pane-drop-feedback-{}",
                group_id.0
            ))
            .absolute()
            .top_0()
            .left_0()
            .size_full();

        match zone {
            WorkspaceDropZone::Left => feedback
                .child(
                    self.render_command_drop_edge_band(label, zone)
                        .left_0()
                        .top_0()
                        .bottom_0(),
                )
                .into_any_element(),
            WorkspaceDropZone::Right => feedback
                .child(
                    self.render_command_drop_edge_band(label, zone)
                        .right_0()
                        .top_0()
                        .bottom_0(),
                )
                .into_any_element(),
            WorkspaceDropZone::Center | WorkspaceDropZone::Top | WorkspaceDropZone::Bottom => {
                feedback
                    .flex()
                    .items_center()
                    .justify_center()
                    .border_2()
                    .border_color(workspace_drop_feedback_border_color())
                    .bg(workspace_drop_group_feedback_color())
                    .child(
                        self.render_workspace_drop_feedback_label(label, WorkspaceDropZone::Center),
                    )
                    .into_any_element()
            }
        }
    }

    fn render_command_drop_edge_band(
        &self,
        label: &'static str,
        zone: WorkspaceDropZone,
    ) -> gpui::Div {
        div()
            .absolute()
            .flex()
            .h_full()
            .w(relative(0.28))
            .items_center()
            .justify_center()
            .border_2()
            .border_color(workspace_drop_feedback_border_color())
            .bg(workspace_drop_split_feedback_color())
            .child(self.render_workspace_drop_feedback_label(label, zone))
    }

    fn render_agents_workspace(&self, cx: &mut gpui::Context<Self>) -> AnyElement {
        /*
        CDXC:GPUIWorkspaceLayout 2026-06-22-05:11:
        Agents mode renders the workspace as GPUI native layout chrome: tab groups and split nodes own normal non-overlapping regions, every leaf keeps a tab bar even when it is the only pane, and Ghostty content is represented by black placeholder surfaces until libghostty integration lands.

        CDXC:GPUIWorkspaceLayout 2026-06-22-14:40:
        The Agents workspace root must be a vertical flex container, not only a flex-sized child of the command-pane wrapper. The rendered split or leaf tree uses flex_1 sizing, so it needs this parent layout context to fill the available height above the command pane instead of leaving a black shell gap below the terminal pane.
        */
        v_flex()
            .id("ghostex-gpui-agents-workspace")
            .flex_1()
            .min_w_0()
            .min_h_0()
            .overflow_hidden()
            .bg(workspace_background_color())
            .child(
                if let Some(pane_id) = self.agents_workspace.focus_mode_pane
                    && let Some(leaf) = self.agents_workspace.find_leaf(pane_id)
                {
                    self.render_workspace_leaf(leaf, cx)
                } else {
                    self.render_workspace_node(&self.agents_workspace.root, cx)
                },
            )
            .into_any_element()
    }

    fn render_workspace_node(
        &self,
        node: &WorkspaceNode,
        cx: &mut gpui::Context<Self>,
    ) -> AnyElement {
        match node {
            WorkspaceNode::Split(split) => self.render_workspace_split(split, cx),
            WorkspaceNode::Leaf(leaf) => self.render_workspace_leaf(leaf, cx),
        }
    }

    fn render_workspace_split(
        &self,
        split: &WorkspaceSplit,
        cx: &mut gpui::Context<Self>,
    ) -> AnyElement {
        let split_id = split.id;
        let axis = split.axis;
        let ratio = workspace_split_ratio(split.ratio);
        let first = div()
            .id(format!("ghostex-gpui-workspace-split-{}-first", split_id.0))
            .flex()
            .flex_col()
            .min_w_0()
            .min_h_0()
            .when(axis == WorkspaceSplitAxis::Horizontal, |this| this.h_full())
            .flex_grow(ratio)
            .flex_shrink_1()
            .flex_basis(relative(0.0))
            .child(self.render_workspace_node(&split.first, cx));
        let second = div()
            .id(format!(
                "ghostex-gpui-workspace-split-{}-second",
                split_id.0
            ))
            .flex()
            .flex_col()
            .min_w_0()
            .min_h_0()
            .when(axis == WorkspaceSplitAxis::Horizontal, |this| this.h_full())
            .flex_grow(1.0 - ratio)
            .flex_shrink_1()
            .flex_basis(relative(0.0))
            .child(self.render_workspace_node(&split.second, cx));

        /*
        CDXC:GPUIWorkspaceLayout 2026-06-22-05:11:
        Split handles are explicit layout siblings between split children. This keeps future resize hit regions in the normal tree while the current visual separator remains a non-interactive child, avoiding transparent overlays or overlapping terminal/web surfaces.

        CDXC:GPUIWorkspaceResize 2026-06-22-06:45:
        Workspace split containers report their first/handle/second child bounds from normal GPUI layout so resize drags can update the persisted split ratio for the exact rendered branch. The handle remains the only hit target; there is no invisible resize overlay or root-level hit-test redirection.
        */
        match split.axis {
            WorkspaceSplitAxis::Horizontal => {
                let view = cx.entity().clone();
                h_flex()
                    .on_children_prepainted(move |child_bounds, _window, cx| {
                        let _ = view.update(cx, |this, _cx| {
                            this.record_workspace_split_layout_metrics(
                                split_id,
                                axis,
                                &child_bounds,
                            );
                        });
                    })
                    .id(format!("ghostex-gpui-workspace-split-{}", split_id.0))
                    .flex_1()
                    .min_w_0()
                    .min_h_0()
                    .items_start()
                    .overflow_hidden()
                    .child(first)
                    .child(self.render_workspace_split_handle(split, cx))
                    .child(second)
                    .into_any_element()
            }
            WorkspaceSplitAxis::Vertical => {
                let view = cx.entity().clone();
                v_flex()
                    .on_children_prepainted(move |child_bounds, _window, cx| {
                        let _ = view.update(cx, |this, _cx| {
                            this.record_workspace_split_layout_metrics(
                                split_id,
                                axis,
                                &child_bounds,
                            );
                        });
                    })
                    .id(format!("ghostex-gpui-workspace-split-{}", split_id.0))
                    .flex_1()
                    .min_w_0()
                    .min_h_0()
                    .overflow_hidden()
                    .child(first)
                    .child(self.render_workspace_split_handle(split, cx))
                    .child(second)
                    .into_any_element()
            }
        }
    }

    fn render_workspace_split_handle(
        &self,
        split: &WorkspaceSplit,
        cx: &mut gpui::Context<Self>,
    ) -> AnyElement {
        let split_id = split.id;
        let axis = split.axis;
        match split.axis {
            WorkspaceSplitAxis::Horizontal => div()
                .id(format!(
                    "ghostex-gpui-workspace-split-handle-{}",
                    split_id.0
                ))
                .flex()
                .flex_shrink_0()
                .h_full()
                .w(px(WORKSPACE_SPLIT_HANDLE_THICKNESS))
                .items_center()
                .justify_center()
                .cursor_ew_resize()
                .bg(workspace_split_handle_color())
                .on_mouse_down(
                    MouseButton::Left,
                    cx.listener(move |this, event: &MouseDownEvent, window, cx| {
                        this.handle_workspace_split_handle_mouse_down(
                            split_id, axis, event, window, cx,
                        );
                    }),
                )
                .child(
                    div()
                        .h_full()
                        .w(px(WORKSPACE_SPLIT_SEPARATOR_THICKNESS))
                        .cursor_ew_resize()
                        .bg(workspace_split_separator_color()),
                )
                .into_any_element(),
            WorkspaceSplitAxis::Vertical => div()
                .id(format!(
                    "ghostex-gpui-workspace-split-handle-{}",
                    split_id.0
                ))
                .flex()
                .flex_shrink_0()
                .h(px(WORKSPACE_SPLIT_HANDLE_THICKNESS))
                .w_full()
                .items_center()
                .justify_center()
                .cursor_ns_resize()
                .bg(workspace_split_handle_color())
                .on_mouse_down(
                    MouseButton::Left,
                    cx.listener(move |this, event: &MouseDownEvent, window, cx| {
                        this.handle_workspace_split_handle_mouse_down(
                            split_id, axis, event, window, cx,
                        );
                    }),
                )
                .child(
                    div()
                        .h(px(WORKSPACE_SPLIT_SEPARATOR_THICKNESS))
                        .w_full()
                        .cursor_ns_resize()
                        .bg(workspace_split_separator_color()),
                )
                .into_any_element(),
        }
    }

    fn render_workspace_leaf(
        &self,
        leaf: &WorkspaceLeaf,
        cx: &mut gpui::Context<Self>,
    ) -> AnyElement {
        let pane_id = leaf.pane_id;
        let is_focused = self.agents_workspace.focused_pane == leaf.pane_id;
        let view = cx.entity().clone();

        v_flex()
            .on_children_prepainted(move |child_bounds, _window, cx| {
                let _ = view.update(cx, |this, _cx| {
                    this.record_workspace_leaf_layout_bounds(pane_id, &child_bounds);
                });
            })
            .id(format!("ghostex-gpui-workspace-pane-{}", pane_id.0))
            .flex_1()
            .min_w_0()
            .min_h_0()
            .overflow_hidden()
            .border_1()
            .border_color(if is_focused {
                workspace_focused_pane_border_color()
            } else {
                workspace_pane_border_color()
            })
            .bg(workspace_terminal_placeholder_color())
            .child(self.render_workspace_tab_bar(leaf, cx))
            .when_some(
                self.render_agents_terminal_close_confirm_surface(leaf, cx),
                |this, surface| this.child(surface),
            )
            .child(self.render_terminal_body_slot(leaf, cx))
            .into_any_element()
    }

    fn render_workspace_tab_bar(
        &self,
        leaf: &WorkspaceLeaf,
        cx: &mut gpui::Context<Self>,
    ) -> AnyElement {
        /*
        CDXC:GPUIWorkspaceTabs 2026-06-22-05:18:
        Agents terminal panes need native-style tab chrome before libghostty mounts: every pane keeps an always-visible tab bar, tab selection colors stay tied to active tab state instead of pane focus, horizontal overflow remains scrollable, and right-side pane actions stay in the tab chrome instead of overlapping terminal bodies.

        CDXC:GPUIAgentsPaneActions 2026-06-22-06:39:
        Agents pane action chrome owns shell-only behavior for creating Mounting terminal tabs and right-side horizontal splits when no runtime process has started yet. The far-right overflow is reserved for pane/layout actions rather than per-tab commands.

        CDXC:GPUIAgentsPaneActions 2026-06-22-07:48:
        Agents pane action chrome must expose explicit Split Below parity beside Split Right and New Terminal. The below action creates a selected Mounting terminal in a real vertical split under the clicked pane while preserving the pane/layout overflow-menu scope.

        CDXC:GPUIAgentsPaneActions 2026-06-22-10:04:
        The full-width bottom-row action is intentionally separate from pane-local Split Below. It appends a selected Mounting terminal under the entire Agents workspace tree through normal split-node layout, clears Focus mode for visibility, and preserves pane/layout menu plus real libghostty/process scope.

        CDXC:GPUIAgentsMergeAllTabs 2026-06-22-13:17:
        Merge All Tabs lives in the Agents pane overflow directly after Split Right/Split Below, matching the native pane titlebar ordering while keeping command terminals in the separate command-pane action set.
        */
        let scroll_handle = self.workspace_tab_scroll_handle(leaf.pane_id);

        h_flex()
            .id(format!("ghostex-gpui-workspace-tabbar-{}", leaf.pane_id.0))
            .flex_shrink_0()
            .h(px(WORKSPACE_TAB_BAR_HEIGHT))
            .w_full()
            .items_center()
            .overflow_hidden()
            .bg(workspace_tab_bar_color())
            .border_b_1()
            .border_color(workspace_tab_border_color())
            .child(
                h_flex()
                    .id(format!(
                        "ghostex-gpui-workspace-tabstrip-{}",
                        leaf.pane_id.0
                    ))
                    .flex_1()
                    .min_w_0()
                    .h_full()
                    .items_center()
                    .overflow_x_scroll()
                    .track_scroll(&scroll_handle)
                    .children(
                        leaf.tab_group
                            .tabs
                            .iter()
                            .enumerate()
                            .map(|(tab_index, tab)| {
                                self.render_workspace_tab(
                                    leaf.pane_id,
                                    &leaf.tab_group,
                                    tab_index,
                                    tab,
                                    cx,
                                )
                            }),
                    )
                    .child(self.render_workspace_tab_strip_end_drop_target(
                        leaf.pane_id,
                        leaf.tab_group.tabs.len(),
                        cx,
                    )),
            )
            .child(self.render_workspace_tab_edge_reveal(leaf.pane_id))
            .child(self.render_workspace_tab_action_cluster(leaf.pane_id, cx))
            .into_any_element()
    }

    fn render_workspace_tab(
        &self,
        pane_id: WorkspacePaneId,
        tab_group: &WorkspaceTabGroup,
        tab_index: usize,
        tab: &WorkspaceTab,
        cx: &mut gpui::Context<Self>,
    ) -> AnyElement {
        let session = self.agents_workspace.session(tab.session_id);
        let chrome_signature = workspace_tab_chrome_signature(tab_group, tab.session_id, session);
        let is_active = chrome_signature.active_in_tab_group;
        let presentation_state = chrome_signature.presentation_state;
        let tab_status = chrome_signature.tab_status;
        let visual_tone = chrome_signature.lifecycle_visual_tone;
        let title = session
            .map(|session| session.title.clone())
            .unwrap_or_else(|| "Terminal".to_string());
        let session_id = tab.session_id;
        let can_close = self.agents_workspace.can_close_tab(pane_id, session_id);
        let dragged_tab = DraggedWorkspaceTab {
            source_pane_id: pane_id,
            session_id,
            title: title.clone(),
            presentation_state,
            tab_status,
        };
        let show_insertion_marker = self.workspace_drop_feedback
            == Some(WorkspaceDropFeedback {
                pane_id,
                target: WorkspaceDropTarget::TabStrip(tab_index),
            });

        div()
            .id(format!(
                "ghostex-gpui-workspace-tab-{}-{}",
                pane_id.0, session_id.0
            ))
            .relative()
            .flex()
            .flex_shrink_0()
            .h_full()
            .w(px(WORKSPACE_TAB_WIDTH))
            .items_center()
            .overflow_hidden()
            .border_r_1()
            .border_color(workspace_tab_border_color())
            .pl(px(11.0))
            .pr(px(6.0))
            .text_size(px(12.5))
            .font_weight(if is_active {
                FontWeight::SEMIBOLD
            } else {
                FontWeight::NORMAL
            })
            .text_color(workspace_tab_text_color(visual_tone))
            .cursor_default()
            .when(visual_tone.uses_selected_treatment(), |this| {
                this.bg(workspace_tab_active_color())
            })
            .when(show_insertion_marker, |this| {
                this.child(self.render_workspace_tab_insertion_marker(pane_id, tab_index, "before"))
            })
            .hover(|this| {
                if visual_tone.uses_selected_treatment() {
                    this.bg(workspace_tab_active_color())
                } else {
                    this.bg(workspace_tab_hover_color())
                }
            })
            .on_mouse_down(
                MouseButton::Left,
                cx.listener(move |this, event: &MouseDownEvent, window, cx| {
                    window.prevent_default();
                    if event.click_count >= 2 {
                        this.double_click_agents_workspace_tab(pane_id, session_id, cx);
                    } else {
                        this.select_agents_tab(pane_id, session_id);
                        cx.notify();
                    }
                }),
            )
            .on_mouse_down(
                MouseButton::Right,
                cx.listener(move |this, event: &MouseDownEvent, window, cx| {
                    window.prevent_default();
                    cx.stop_propagation();
                    this.show_agents_tab_context_menu(
                        pane_id,
                        session_id,
                        event.position,
                        window,
                        cx,
                    );
                }),
            )
            .on_drag(dragged_tab, |dragged, _offset, _window, cx| {
                cx.new(|_| WorkspaceTabDragPreview {
                    title: dragged.title.clone(),
                    presentation_state: dragged.presentation_state,
                    tab_status: dragged.tab_status,
                })
            })
            .on_drag_move::<DraggedWorkspaceTab>(cx.listener(
                move |this, event: &gpui::DragMoveEvent<DraggedWorkspaceTab>, _window, cx| {
                    this.update_workspace_tab_drag_feedback(event, pane_id, tab_index, cx);
                },
            ))
            .on_drag_move::<DraggedCommandTab>(cx.listener(
                move |this, event: &gpui::DragMoveEvent<DraggedCommandTab>, _window, cx| {
                    this.update_command_tab_over_workspace_tab_drag_feedback(
                        event, pane_id, tab_index, cx,
                    );
                },
            ))
            .can_drop(move |value, _window, _cx| {
                value
                    .downcast_ref::<DraggedWorkspaceTab>()
                    .is_some_and(|dragged| dragged.source_pane_id == pane_id)
                    || value.is::<DraggedCommandTab>()
            })
            .on_drop(
                cx.listener(move |this, dragged: &DraggedWorkspaceTab, window, cx| {
                    this.handle_workspace_tab_strip_drop(pane_id, tab_index, dragged, window, cx);
                }),
            )
            .on_drop(
                cx.listener(move |this, dragged: &DraggedCommandTab, window, cx| {
                    this.handle_command_tab_workspace_tab_strip_drop(
                        pane_id, tab_index, dragged, window, cx,
                    );
                }),
            )
            .child(self.render_workspace_tab_status_icon(session_id, visual_tone))
            .child(
                div()
                    .id(format!(
                        "ghostex-gpui-workspace-tab-status-dot-{}-{}",
                        session_id.0,
                        tab_status.element_slug()
                    ))
                    .flex_shrink_0()
                    .size(px(6.0))
                    .ml(px(7.0))
                    .rounded_full()
                    .bg(workspace_tab_status_dot_color(visual_tone, tab_status)),
            )
            .child(
                div()
                    .flex_1()
                    .min_w_0()
                    .overflow_hidden()
                    .whitespace_nowrap()
                    .text_ellipsis()
                    .ml(px(8.0))
                    .child(title),
            )
            .when_some(presentation_state.tab_badge_label(), |this, label| {
                this.child(self.render_workspace_tab_state_badge(session_id, visual_tone, label))
            })
            .child(
                self.render_workspace_tab_close_button(
                    pane_id, session_id, can_close, is_active, cx,
                ),
            )
            .into_any_element()
    }

    fn render_workspace_tab_strip_end_drop_target(
        &self,
        pane_id: WorkspacePaneId,
        insertion_index: usize,
        cx: &mut gpui::Context<Self>,
    ) -> AnyElement {
        let show_insertion_marker = self.workspace_drop_feedback
            == Some(WorkspaceDropFeedback {
                pane_id,
                target: WorkspaceDropTarget::TabStrip(insertion_index),
            });

        div()
            .id(format!(
                "ghostex-gpui-workspace-tabstrip-end-drop-{}",
                pane_id.0
            ))
            .relative()
            .h_full()
            .flex_grow_1()
            .min_w(px(24.0))
            .when(show_insertion_marker, |this| {
                this.child(self.render_workspace_tab_insertion_marker(
                    pane_id,
                    insertion_index,
                    "end",
                ))
            })
            .on_drag_move::<DraggedWorkspaceTab>(cx.listener(
                move |this, event: &gpui::DragMoveEvent<DraggedWorkspaceTab>, _window, cx| {
                    this.update_workspace_tab_end_drag_feedback(
                        event,
                        pane_id,
                        insertion_index,
                        cx,
                    );
                },
            ))
            .on_drag_move::<DraggedCommandTab>(cx.listener(
                move |this, event: &gpui::DragMoveEvent<DraggedCommandTab>, _window, cx| {
                    this.update_command_tab_over_workspace_tab_end_drag_feedback(
                        event,
                        pane_id,
                        insertion_index,
                        cx,
                    );
                },
            ))
            .can_drop(move |value, _window, _cx| {
                value
                    .downcast_ref::<DraggedWorkspaceTab>()
                    .is_some_and(|dragged| dragged.source_pane_id == pane_id)
                    || value.is::<DraggedCommandTab>()
            })
            .on_drop(
                cx.listener(move |this, dragged: &DraggedWorkspaceTab, window, cx| {
                    this.handle_workspace_tab_strip_drop(
                        pane_id,
                        insertion_index,
                        dragged,
                        window,
                        cx,
                    );
                }),
            )
            .on_drop(
                cx.listener(move |this, dragged: &DraggedCommandTab, window, cx| {
                    this.handle_command_tab_workspace_tab_strip_drop(
                        pane_id,
                        insertion_index,
                        dragged,
                        window,
                        cx,
                    );
                }),
            )
            .into_any_element()
    }

