fn gpui_gte_homebrew_install_command() -> (&'static str, [&'static str; 2], Duration) {
    (
        "/bin/zsh",
        ["-lc", GPUI_GTE_HOMEBREW_INSTALL_SCRIPT],
        Duration::from_secs(5 * 60),
    )
}

fn gpui_install_gte_from_homebrew() -> GpuiGteInstallActionResult {
    /*
    CDXC:GtePromptEditing 2026-06-24-13:28:
    GPUI Settings must use the same fixed Homebrew resolution order and `maddada/tap/gte` install operation as the macOS Settings button, bounded to five minutes with stdout/stderr suppressed. Installing the binary is separate from selecting the promptEditorBackend, and failures must report generic copy instead of raw Homebrew output, paths, command output, URLs, tokens, or environment.
    */
    let (command, args, timeout) = gpui_gte_homebrew_install_command();
    let result = gpui_run_command_with_timeout(Path::new(command), &args, timeout);
    gpui_gte_install_result_from_command_result(result)
}

fn gpui_gte_install_result_from_command_result(
    result: Result<bool, String>,
) -> GpuiGteInstallActionResult {
    match result {
        Ok(true) => GpuiGteInstallActionResult {
            available: true,
            message: GPUI_GTE_INSTALL_SUCCESS_MESSAGE,
            toast_level: "success",
            toast_title: GPUI_GTE_INSTALL_SUCCESS_MESSAGE,
        },
        Ok(false) | Err(_) => GpuiGteInstallActionResult {
            available: false,
            message: GPUI_GTE_INSTALL_FAILURE_MESSAGE,
            toast_level: "warning",
            toast_title: "gte install failed",
        },
    }
}

fn gpui_install_cua_driver() -> Result<String, String> {
    /*
    CDXC:GPUIDesktopControlSettings 2026-06-24-13:14:
    GPUI installs Desktop Control through the same official trycua installer command used by native Settings, bounded to ten minutes with child output suppressed. After Cua Driver succeeds, install Ghostex Computer Use through the fixed Ghostex CLI helper; report driver-only partial setup honestly instead of hiding the failed skill step.
    */
    let installer_result = gpui_run_command_with_timeout(
        Path::new("/bin/bash"),
        &[
            "-lc",
            "curl -fsSL https://raw.githubusercontent.com/trycua/cua/main/libs/cua-driver/scripts/install.sh | /bin/bash",
        ],
        Duration::from_secs(10 * 60),
    );
    match installer_result {
        Ok(true) => {}
        Ok(false) => {
            return Err(
                "Desktop Control install failed. Current Desktop Control status was refreshed."
                    .to_string(),
            );
        }
        Err(_) => {
            return Err(
                "Desktop Control installer could not be started. Current Desktop Control status was refreshed."
                    .to_string(),
            );
        }
    }

    match gpui_install_bundled_ghostex_skill(
        &["computer-use", "install-skill"],
        "Ghostex Computer Use",
    ) {
        Ok(_) => Ok(
            "Desktop Control installed. Grant macOS Accessibility and Screen Recording permissions if needed."
                .to_string(),
        ),
        Err(message) => Err(format!(
            "Cua Driver installed, but Ghostex Computer Use skill could not be installed. {message}"
        )),
    }
}

fn gpui_repair_ghostex_cli_commands() -> Result<String, String> {
    /*
    CDXC:GPUISettingsCliInstall 2026-06-24-12:56:
    CLI repair is real only when GPUI is running from a packaged app that ships `Contents/Resources/CLI/ghostex-cli.mjs`. Development binaries must report unavailable status instead of synthesizing wrappers to a source checkout, while packaged repair writes public wrappers outside the app and replaces only marked Ghostex wrappers, app-owned CLI symlinks, or broken symlinks.
    */
    let cli_dir = gpui_bundled_ghostex_cli_resource_dir()?;
    let cli_script_path = cli_dir.join("ghostex-cli.mjs");
    let path_entries = gpui_cli_path_entries();
    let common_dirs = gpui_common_cli_install_dirs();
    let install_dirs = gpui_cli_install_dirs(&path_entries, &common_dirs, &cli_dir);

    let ghostex_result =
        gpui_install_ghostex_cli_command("ghostex", &cli_script_path, &cli_dir, &install_dirs);
    if !ghostex_result.installed() {
        return match ghostex_result {
            GpuiCliCommandInstallResult::Blocked => Err(
                "A ghostex command already exists in a writable install location, but GPUI could not prove it belongs to Ghostex. No unrelated command was overwritten."
                    .to_string(),
            ),
            _ => Err(
                "Ghostex could not create a writable PATH wrapper for the ghostex command. Current CLI status was refreshed without changing files."
                    .to_string(),
            ),
        };
    }

    let gx_result =
        gpui_install_ghostex_cli_command("gx", &cli_script_path, &cli_dir, &install_dirs);
    if gx_result == GpuiCliCommandInstallResult::Blocked {
        return Ok(
            "Ghostex CLI linked. The gx alias was not changed because another command already owns that name."
                .to_string(),
        );
    }
    if !gx_result.installed() {
        return Ok(
            "Ghostex CLI linked. The gx alias could not be linked because no writable install location was available."
                .to_string(),
        );
    }
    Ok(
        "Ghostex CLI linked. ghostex and gx now launch this GPUI app build where available."
            .to_string(),
    )
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum GpuiCliCommandInstallResult {
    Current,
    Repaired,
    Blocked,
    Unavailable,
}

impl GpuiCliCommandInstallResult {
    fn installed(self) -> bool {
        matches!(self, Self::Current | Self::Repaired)
    }
}

fn gpui_bundled_ghostex_cli_resource_dir() -> Result<PathBuf, String> {
    let executable = env::current_exe().map_err(|_| {
        "Packaged Ghostex CLI resources are unavailable in this GPUI build. Current integration status was refreshed without changing files."
            .to_string()
    })?;
    let Some(bundle_root) = find_app_bundle_root(&executable) else {
        return Err(
            "Packaged Ghostex CLI resources are unavailable in this GPUI build. Current integration status was refreshed without changing files."
                .to_string(),
        );
    };
    let cli_dir = bundle_root.join("Contents/Resources/CLI");
    if gpui_is_file(&cli_dir.join("ghostex-cli.mjs")) {
        Ok(cli_dir)
    } else {
        Err(
            "Packaged Ghostex CLI resources are unavailable in this GPUI build. Current integration status was refreshed without changing files."
                .to_string(),
        )
    }
}

fn gpui_install_ghostex_cli_command(
    command: &str,
    cli_script_path: &Path,
    cli_dir: &Path,
    install_dirs: &[PathBuf],
) -> GpuiCliCommandInstallResult {
    let wrapper = gpui_ghostex_cli_wrapper_content(cli_script_path);
    for directory in install_dirs {
        if !gpui_prepare_cli_install_directory(directory) {
            continue;
        }
        let link_path = directory.join(command);
        if gpui_path_exists_or_is_symlink(&link_path) {
            if !gpui_can_replace_existing_ghostex_command(command, &link_path, cli_dir) {
                return GpuiCliCommandInstallResult::Blocked;
            }
            if gpui_is_regular_file(&link_path)
                && fs::read_to_string(&link_path)
                    .map(|content| content == wrapper)
                    .unwrap_or(false)
            {
                let _ = gpui_set_executable_permissions(&link_path);
                gpui_clear_macos_execution_policy_xattrs(&link_path);
                return GpuiCliCommandInstallResult::Current;
            }
            if fs::remove_file(&link_path).is_err() {
                return GpuiCliCommandInstallResult::Unavailable;
            }
        }
        if gpui_write_executable_wrapper(&link_path, &wrapper).is_ok() {
            gpui_clear_macos_execution_policy_xattrs(&link_path);
            return GpuiCliCommandInstallResult::Repaired;
        }
    }
    GpuiCliCommandInstallResult::Unavailable
}

fn gpui_ghostex_cli_wrapper_content(cli_script_path: &Path) -> String {
    [
        "#!/bin/bash".to_string(),
        "set -euo pipefail".to_string(),
        format!("# {GPUI_GHOSTEX_CLI_WRAPPER_MARKER}: Public PATH commands live outside the app bundle so macOS does not directly execute app-bundled shell scripts during policy assessment."),
        format!(
            "exec /usr/bin/env node {} \"$@\"",
            gpui_shell_single_quote_path(cli_script_path)
        ),
        String::new(),
    ]
    .join("\n")
}

fn gpui_shell_single_quote_path(path: &Path) -> String {
    format!("'{}'", gpui_path_string(path).replace('\'', "'\\''"))
}

fn gpui_cli_path_entries() -> Vec<PathBuf> {
    gpui_unique_paths(
        env::var_os("PATH")
            .into_iter()
            .flat_map(|paths| env::split_paths(&paths).collect::<Vec<_>>())
            .filter(|path| !path.as_os_str().is_empty()),
    )
}

fn gpui_common_cli_install_dirs() -> Vec<PathBuf> {
    gpui_unique_paths([
        PathBuf::from("/opt/homebrew/bin"),
        PathBuf::from("/usr/local/bin"),
        gpui_home_dir().join(".local/bin"),
    ])
}

fn gpui_cli_install_dirs(
    path_entries: &[PathBuf],
    common_dirs: &[PathBuf],
    cli_dir: &Path,
) -> Vec<PathBuf> {
    let mut owned_dirs = Vec::new();
    for command in ["ghostex", "gx"] {
        for candidate in gpui_cli_command_path_candidates(command, path_entries, common_dirs) {
            if gpui_path_exists_or_is_symlink(&candidate)
                && gpui_is_ghostex_owned_command_path(command, &candidate, cli_dir)
            {
                if let Some(parent) = candidate.parent() {
                    owned_dirs.push(parent.to_path_buf());
                }
            }
        }
    }
    gpui_unique_paths(
        owned_dirs
            .into_iter()
            .chain(path_entries.iter().cloned())
            .chain(common_dirs.iter().cloned()),
    )
}

fn gpui_cli_command_path_candidates(
    command: &str,
    path_entries: &[PathBuf],
    common_dirs: &[PathBuf],
) -> Vec<PathBuf> {
    let found = gpui_which_command(command).into_iter();
    gpui_unique_paths(
        found
            .chain(path_entries.iter().map(|directory| directory.join(command)))
            .chain(common_dirs.iter().map(|directory| directory.join(command))),
    )
}

fn gpui_unique_paths(paths: impl IntoIterator<Item = PathBuf>) -> Vec<PathBuf> {
    let mut result = Vec::new();
    let mut seen = HashSet::new();
    for path in paths {
        if path.as_os_str().is_empty() {
            continue;
        }
        if seen.insert(path.clone()) {
            result.push(path);
        }
    }
    result
}

fn gpui_prepare_cli_install_directory(directory: &Path) -> bool {
    let user_bin = gpui_home_dir().join(".local/bin");
    if directory == user_bin.as_path() && fs::create_dir_all(directory).is_err() {
        return false;
    }
    if !gpui_is_dir(directory) {
        return false;
    }
    gpui_directory_accepts_temporary_write(directory)
}

fn gpui_directory_accepts_temporary_write(directory: &Path) -> bool {
    let probe_path = directory.join(format!(
        ".ghostex-gpui-cli-write-test-{}-{}",
        std::process::id(),
        system_time_epoch_millis_string(SystemTime::now())
    ));
    match std::fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&probe_path)
    {
        Ok(_) => {
            let _ = fs::remove_file(&probe_path);
            true
        }
        Err(_) => false,
    }
}

fn gpui_can_replace_existing_ghostex_command(command: &str, path: &Path, cli_dir: &Path) -> bool {
    gpui_is_ghostex_owned_command_path(command, path, cli_dir) || gpui_is_broken_symlink(path)
}

fn gpui_is_ghostex_owned_command_path(command: &str, path: &Path, cli_dir: &Path) -> bool {
    if gpui_file_contains_ghostex_cli_wrapper_marker(path) {
        return true;
    }
    let realpath = gpui_realpath_or_self(path);
    if gpui_path_is_relative_to(&realpath, cli_dir) {
        return true;
    }
    gpui_is_ghostex_app_owned_command_realpath(command, &realpath)
}

fn gpui_is_ghostex_app_owned_command_realpath(command: &str, realpath: &Path) -> bool {
    let normalized = gpui_path_string(realpath).to_lowercase();
    normalized.contains(&format!("/ghostex.app/contents/resources/cli/{command}"))
        || normalized.contains(&format!(
            "/ghostex.app/contents/resources/web/cli/{command}"
        ))
        || normalized.contains("/ghostex.app/contents/resources/cli/ghostex-cli.mjs")
        || (command == "ghostex" && normalized.contains("/ghostex.app/contents/macos/ghostex"))
}

fn gpui_is_marked_ghostex_wrapper_file(path: &Path) -> bool {
    if !gpui_is_regular_file(path) {
        return false;
    }
    let Ok(metadata) = fs::symlink_metadata(path) else {
        return false;
    };
    if metadata.len() > 128 * 1024 {
        return false;
    }
    fs::read_to_string(path)
        .map(|content| gpui_marked_ghostex_wrapper_content(&content))
        .unwrap_or(false)
}

fn gpui_is_regular_file(path: &Path) -> bool {
    fs::symlink_metadata(path)
        .map(|metadata| metadata.file_type().is_file())
        .unwrap_or(false)
}

fn gpui_path_exists_or_is_symlink(path: &Path) -> bool {
    fs::symlink_metadata(path).is_ok()
}

fn gpui_is_broken_symlink(path: &Path) -> bool {
    fs::symlink_metadata(path)
        .map(|metadata| metadata.file_type().is_symlink() && !path.exists())
        .unwrap_or(false)
}

fn gpui_realpath_or_self(path: &Path) -> PathBuf {
    fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf())
}

fn gpui_write_executable_wrapper(path: &Path, content: &str) -> std::io::Result<()> {
    fs::write(path, content.as_bytes())?;
    gpui_set_executable_permissions(path)
}

fn gpui_set_executable_permissions(path: &Path) -> std::io::Result<()> {
    #[cfg(unix)]
    {
        fs::set_permissions(path, fs::Permissions::from_mode(0o755))
    }
    #[cfg(not(unix))]
    {
        let _ = path;
        Ok(())
    }
}

fn gpui_clear_macos_execution_policy_xattrs(path: &Path) {
    /*
    CDXC:GPUISettingsCliInstall 2026-06-24-12:56:
    Repaired public CLI wrappers may inherit macOS execution-policy xattrs from a previous install location. Clear only the two known assessment attributes after wrapper writes/replacements, suppress command output, and keep repair success independent from xattr removal failures.
    */
    #[cfg(target_os = "macos")]
    {
        for attribute in ["com.apple.provenance", "com.apple.quarantine"] {
            let _ = std::process::Command::new("/usr/bin/xattr")
                .arg("-d")
                .arg(attribute)
                .arg(path)
                .stdin(std::process::Stdio::null())
                .stdout(std::process::Stdio::null())
                .stderr(std::process::Stdio::null())
                .status();
        }
    }
    #[cfg(not(target_os = "macos"))]
    {
        let _ = path;
    }
}

fn gpui_install_bundled_ghostex_skill_action(
    action: GpuiGhostexCliSettingsAction,
    args: &[&str],
    display_name: &str,
) -> GpuiGhostexCliActionResult {
    match gpui_install_bundled_ghostex_skill(args, display_name) {
        Ok(message) => GpuiGhostexCliActionResult::success(action, message),
        Err(message) => GpuiGhostexCliActionResult::failure(action, message),
    }
}

fn gpui_install_bundled_ghostex_skill(args: &[&str], display_name: &str) -> Result<String, String> {
    /*
    CDXC:GPUISettingsAgentSkills 2026-06-24-12:56:
    GPUI Settings installs bundled Ghostex skills by resolving the fixed `ghostex` command on PATH and running only the known `ghostex <namespace> install-skill` argv. Command text never comes from React, child stdout/stderr are suppressed, failures are reported generically, and status is refreshed from disk afterward.

    CDXC:GPUISettingsAgentSkills 2026-06-24-13:08:
    Executing a PATH `ghostex` command from Settings requires strict Ghostex ownership evidence: a repair marker plus `ghostex-cli.mjs`, or an app-owned realpath recognized by the CLI repair ownership helper. Broad read-only status strings are not sufficient for process execution.
    */
    let Some(ghostex_path) = gpui_which_command("ghostex") else {
        return Err(
            "Ghostex CLI was not found on PATH. Repair the Ghostex CLI before installing bundled skills."
                .to_string(),
        );
    };
    if !gpui_is_probably_ghostex_command(&ghostex_path, "ghostex") {
        return Err(
            "A ghostex command exists on PATH, but GPUI could not prove it belongs to Ghostex. Repair the Ghostex CLI before installing bundled skills."
                .to_string(),
        );
    }
    match gpui_run_command_with_timeout(&ghostex_path, args, Duration::from_secs(120)) {
        Ok(true) => Ok(format!("{display_name} installed.")),
        Ok(false) => Err(format!(
            "{display_name} install failed. Current integration status was refreshed."
        )),
        Err(_) => Err(format!(
            "{display_name} install could not be started. Current integration status was refreshed."
        )),
    }
}

fn gpui_run_command_with_timeout(
    command: &Path,
    args: &[&str],
    timeout: Duration,
) -> Result<bool, String> {
    let mut child = std::process::Command::new(command)
        .args(args)
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn()
        .map_err(|_| "process spawn failed".to_string())?;
    let started = Instant::now();
    loop {
        match child.try_wait() {
            Ok(Some(status)) => return Ok(status.success()),
            Ok(None) => {
                if started.elapsed() >= timeout {
                    let _ = child.kill();
                    let _ = child.wait();
                    return Ok(false);
                }
                std::thread::sleep(Duration::from_millis(100));
            }
            Err(_) => {
                let _ = child.kill();
                let _ = child.wait();
                return Ok(false);
            }
        }
    }
}

#[derive(Clone, Debug)]
struct GpuiCapturedCommandOutput {
    stderr: String,
    stdout: String,
    success: bool,
}

impl GpuiCapturedCommandOutput {
    fn combined_text(&self) -> String {
        if self.stderr.trim().is_empty() {
            return self.stdout.clone();
        }
        if self.stdout.trim().is_empty() {
            return self.stderr.clone();
        }
        format!("{}\n{}", self.stdout, self.stderr)
    }
}

fn gpui_run_command_with_captured_output_timeout(
    command: &Path,
    args: &[&str],
    timeout: Duration,
    max_capture_bytes: usize,
) -> Result<GpuiCapturedCommandOutput, String> {
    let mut child = std::process::Command::new(command)
        .args(args)
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .spawn()
        .map_err(|_| "process spawn failed".to_string())?;
    let stdout_reader = child
        .stdout
        .take()
        .map(|stream| gpui_capture_child_output_stream(stream, max_capture_bytes));
    let stderr_reader = child
        .stderr
        .take()
        .map(|stream| gpui_capture_child_output_stream(stream, max_capture_bytes));
    let started = Instant::now();
    let mut success = false;
    loop {
        match child.try_wait() {
            Ok(Some(status)) => {
                success = status.success();
                break;
            }
            Ok(None) => {
                if started.elapsed() >= timeout {
                    let _ = child.kill();
                    let _ = child.wait();
                    break;
                }
                std::thread::sleep(Duration::from_millis(100));
            }
            Err(_) => {
                let _ = child.kill();
                let _ = child.wait();
                break;
            }
        }
    }
    let stdout = gpui_join_captured_output(stdout_reader);
    let stderr = gpui_join_captured_output(stderr_reader);
    Ok(GpuiCapturedCommandOutput {
        stderr,
        stdout,
        success,
    })
}

fn gpui_capture_child_output_stream<R>(
    mut stream: R,
    max_capture_bytes: usize,
) -> std::thread::JoinHandle<Vec<u8>>
where
    R: Read + Send + 'static,
{
    std::thread::spawn(move || {
        let mut captured = Vec::new();
        let mut buffer = [0_u8; 4096];
        loop {
            match stream.read(&mut buffer) {
                Ok(0) => break,
                Ok(byte_count) => {
                    let remaining = max_capture_bytes.saturating_sub(captured.len());
                    if remaining > 0 {
                        captured.extend_from_slice(&buffer[..byte_count.min(remaining)]);
                    }
                }
                Err(_) => break,
            }
        }
        captured
    })
}

fn gpui_join_captured_output(reader: Option<std::thread::JoinHandle<Vec<u8>>>) -> String {
    reader
        .and_then(|reader| reader.join().ok())
        .map(|bytes| String::from_utf8_lossy(&bytes).into_owned())
        .unwrap_or_default()
}

fn gpui_uninstall_bundled_agent_skills() -> Result<String, String> {
    /*
    CDXC:GPUISettingsAgentSkills 2026-06-24-12:56:
    The bundled skill uninstall action is intentionally narrower than a generic skills cleanup. Remove only the four shared Ghostex skill names under `~/agents/skills`, handle missing folders as already-uninstalled state, and do not follow React-provided paths or delete other user/system skills.
    */
    let skills_root = gpui_home_dir().join("agents").join("skills");
    let mut removed_count = 0usize;
    for skill_name in GPUI_BUNDLED_GHOSTEX_AGENT_SKILL_NAMES {
        let skill_path = skills_root.join(skill_name);
        let metadata = match fs::symlink_metadata(&skill_path) {
            Ok(metadata) => metadata,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
            Err(_) => {
                return Err(
                    "Bundled Ghostex skill uninstall failed. Current integration status was refreshed."
                        .to_string(),
                );
            }
        };
        let remove_result = if metadata.file_type().is_symlink() || metadata.is_file() {
            fs::remove_file(&skill_path)
        } else if metadata.is_dir() {
            fs::remove_dir_all(&skill_path)
        } else {
            fs::remove_file(&skill_path)
        };
        if remove_result.is_err() {
            return Err(
                "Bundled Ghostex skill uninstall failed. Current integration status was refreshed."
                    .to_string(),
            );
        }
        removed_count += 1;
    }
    if removed_count == 0 {
        Ok("No bundled Ghostex agent skills were installed. Current integration status was refreshed.".to_string())
    } else {
        Ok(
            "Bundled Ghostex agent skills uninstalled. You can install them again from Settings."
                .to_string(),
        )
    }
}

fn gpui_agent_hook_status_message(
    endpoint: &str,
    requested_agent_ids: Option<HashSet<String>>,
    error_message: &str,
) -> serde_json::Value {
    /*
    CDXC:GPUISettingsStatusBridge 2026-06-24-11:40:
    Agent hook status/install/uninstall in GPUI is gxserver-owned, matching macOS Settings. Call the real hook endpoints and pass the daemon's `agentHookStatus` payload through; on transport/API failure, return an explicit empty error payload instead of local fixture rows or fake installed hooks.
    */
    let mut params = serde_json::Map::new();
    if let Some(agent_ids) = requested_agent_ids {
        params.insert(
            "agentIds".to_string(),
            serde_json::Value::Array(
                agent_ids
                    .into_iter()
                    .map(serde_json::Value::String)
                    .collect::<Vec<_>>(),
            ),
        );
    }

    if let Ok(result) = gpui_gxserver_rpc_result(
        endpoint,
        &serde_json::Value::Object(params),
        Duration::from_secs(45),
    ) {
        if result.get("type").and_then(serde_json::Value::as_str) == Some("agentHookStatus") {
            return result;
        }
    }
    serde_json::json!({
        "agents": [],
        "errorMessage": error_message,
        "generatedAt": gpui_status_generated_at(),
        "hookStateDirectory": "",
        "notifyHookPath": "",
        "type": "agentHookStatus",
    })
}

#[derive(Clone, Debug)]
enum GpuiProjectSettingsMetadataUpdate {
    WorktreeCommand {
        project_id: String,
        command: String,
    },
    BeadsDisplayKey {
        project_id: String,
        display_key: String,
    },
    BeadsDirectory {
        project_id: String,
        directory: String,
    },
    SidebarCommands {
        project_id: String,
        commands: Vec<GpuiStoredSidebarCommand>,
        command_order: Vec<String>,
        deleted_default_command_ids: Vec<String>,
    },
}

impl GpuiProjectSettingsMetadataUpdate {
    fn project_id(&self) -> &str {
        match self {
            Self::WorktreeCommand { project_id, .. }
            | Self::BeadsDisplayKey { project_id, .. }
            | Self::BeadsDirectory { project_id, .. }
            | Self::SidebarCommands { project_id, .. } => project_id,
        }
    }
}

fn gpui_project_settings_projects_from_gxserver() -> Vec<serde_json::Value> {
    /*
    CDXC:GPUISettingsProjectMetadata 2026-06-24-11:59:
    Settings project rows in GPUI must come from real local gxserver project domain data, falling back only to the presentation snapshot when `/api/listProjects` is unavailable or lacks usable rows. Do not synthesize paths, names, worktree metadata, or Beads settings from UI labels, session titles, terminal cwd, or local filesystem guesses.
    */
    let domain_projects = gpui_gxserver_domain_projects(Duration::from_secs(2));
    gpui_project_settings_projects_from_domain_projects_or_presentation(&domain_projects)
}

fn gpui_project_settings_projects_from_domain_projects_or_presentation(
    domain_projects: &[serde_json::Value],
) -> Vec<serde_json::Value> {
    let project_settings_projects = domain_projects
        .iter()
        .filter_map(gpui_project_settings_project_from_domain_project)
        .collect::<Vec<_>>();
    if !project_settings_projects.is_empty() {
        return project_settings_projects;
    }

    gpui_read_gxserver_presentation_snapshot()
        .ok()
        .and_then(|snapshot| {
            let snapshot = snapshot.as_object()?;
            Some(
                json_array_field(snapshot, "projects")
                    .into_iter()
                    .flatten()
                    .filter_map(gpui_project_settings_project_from_presentation_project)
                    .collect::<Vec<_>>(),
            )
        })
        .unwrap_or_default()
}

fn gpui_gxserver_domain_projects(timeout: Duration) -> Vec<serde_json::Value> {
    gpui_gxserver_domain_projects_result(timeout).unwrap_or_default()
}

fn gpui_gxserver_domain_projects_result(
    timeout: Duration,
) -> Result<Vec<serde_json::Value>, String> {
    let result = gpui_gxserver_rpc_result("/api/listProjects", &serde_json::json!({}), timeout)?;
    result
        .get("projects")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .ok_or_else(|| GPUI_SIDEBAR_METADATA_GENERIC_ERROR.to_string())
}

fn gpui_gxserver_recent_projects(timeout: Duration) -> Vec<serde_json::Value> {
    gpui_gxserver_rpc_result("/api/listRecentProjects", &serde_json::json!({}), timeout)
        .ok()
        .and_then(|result| {
            result
                .get("recentProjects")
                .and_then(serde_json::Value::as_array)
                .map(|projects| {
                    projects
                        .iter()
                        .filter_map(gpui_recent_project_from_gxserver)
                        .collect::<Vec<_>>()
                })
        })
        .unwrap_or_default()
}

fn gpui_recent_project_from_gxserver(project: &serde_json::Value) -> Option<serde_json::Value> {
    let project = project.as_object()?;
    let project_id = gpui_trimmed_json_string_field(project, "projectId")?;
    let title = gpui_trimmed_json_string_field(project, "title")?;
    let path = gpui_trimmed_json_string_field(project, "path")?;
    let session_count = project
        .get("sessionCount")
        .and_then(json_u64_value)
        .unwrap_or(0);

    let mut item = serde_json::Map::new();
    item.insert(
        "path".to_string(),
        serde_json::Value::String(path.to_string()),
    );
    item.insert(
        "projectId".to_string(),
        serde_json::Value::String(project_id.to_string()),
    );
    item.insert(
        "sessionCount".to_string(),
        serde_json::Value::Number(serde_json::Number::from(session_count)),
    );
    item.insert(
        "title".to_string(),
        serde_json::Value::String(title.to_string()),
    );
    gpui_insert_optional_nonempty_string(
        &mut item,
        "recentClosedAt",
        gpui_trimmed_json_string_field(project, "recentClosedAt"),
    );
    gpui_insert_optional_nonempty_string(
        &mut item,
        "iconDataUrl",
        gpui_trimmed_json_string_field(project, "iconDataUrl"),
    );
    gpui_insert_optional_nonempty_string(
        &mut item,
        "theme",
        gpui_trimmed_json_string_field(project, "theme"),
    );
    gpui_insert_optional_nonempty_string(
        &mut item,
        "themeColor",
        gpui_trimmed_json_string_field(project, "themeColor"),
    );
    if let Some(icon) = project.get("icon").filter(|value| value.is_object()) {
        item.insert("icon".to_string(), icon.clone());
    }
    Some(serde_json::Value::Object(item))
}

fn gpui_project_settings_project_from_domain_project(
    project: &serde_json::Value,
) -> Option<serde_json::Value> {
    let project = project.as_object()?;
    let project_id = gpui_trimmed_json_string_field(project, "projectId")?;
    let name = gpui_trimmed_json_string_field(project, "name")?;
    let path = gpui_trimmed_json_string_field(project, "path")?;
    let git_config = project
        .get("gitConfig")
        .and_then(serde_json::Value::as_object);
    let project_board_config = project
        .get("projectBoardConfig")
        .and_then(serde_json::Value::as_object);
    let worktree = project
        .get("worktree")
        .and_then(serde_json::Value::as_object);

    let mut item = serde_json::Map::new();
    item.insert(
        "name".to_string(),
        serde_json::Value::String(name.to_string()),
    );
    item.insert(
        "path".to_string(),
        serde_json::Value::String(path.to_string()),
    );
    item.insert(
        "projectId".to_string(),
        serde_json::Value::String(project_id.to_string()),
    );
    gpui_insert_optional_nonempty_string(
        &mut item,
        "worktreeParentProjectId",
        worktree.and_then(|worktree| gpui_trimmed_json_string_field(worktree, "parentProjectId")),
    );
    gpui_insert_optional_nonempty_string(
        &mut item,
        "worktreeCommand",
        git_config.and_then(|config| gpui_trimmed_json_string_field(config, "worktreeCommand")),
    );
    gpui_insert_optional_nonempty_string(
        &mut item,
        "beadsDisplayKey",
        project_board_config
            .and_then(|config| gpui_trimmed_json_string_field(config, "beadsDisplayKey"))
            .or_else(|| {
                git_config
                    .and_then(|config| gpui_trimmed_json_string_field(config, "beadsDisplayKey"))
            }),
    );
    gpui_insert_optional_nonempty_string(
        &mut item,
        "beadsDirectory",
        project_board_config
            .and_then(|config| gpui_trimmed_json_string_field(config, "beadsDirectory")),
    );
    Some(serde_json::Value::Object(item))
}

fn gpui_project_settings_project_from_presentation_project(
    project: &serde_json::Value,
) -> Option<serde_json::Value> {
    let project = project.as_object()?;
    let project_id = gpui_trimmed_json_string_field(project, "projectId")?;
    let name = gpui_trimmed_json_string_field(project, "title")?;
    let path = gpui_trimmed_json_string_field(project, "path")?;
    let mut item = serde_json::Map::new();
    item.insert(
        "name".to_string(),
        serde_json::Value::String(name.to_string()),
    );
    item.insert(
        "path".to_string(),
        serde_json::Value::String(path.to_string()),
    );
    item.insert(
        "projectId".to_string(),
        serde_json::Value::String(project_id.to_string()),
    );
    gpui_insert_optional_nonempty_string(
        &mut item,
        "worktreeParentProjectId",
        project
            .get("worktree")
            .and_then(serde_json::Value::as_object)
            .and_then(|worktree| gpui_trimmed_json_string_field(worktree, "parentProjectId")),
    );
    Some(serde_json::Value::Object(item))
}

fn gpui_update_project_settings_metadata(
    update: GpuiProjectSettingsMetadataUpdate,
) -> Result<(), String> {
    let project_id = gpui_trimmed_nonempty_str(Some(update.project_id()))
        .ok_or_else(|| "Missing gxserver project id.".to_string())?
        .to_string();
    let project = gpui_find_gxserver_project_by_id(&project_id)?;
    let mut params = serde_json::Map::new();
    params.insert(
        "projectId".to_string(),
        serde_json::Value::String(project_id),
    );

    match update {
        GpuiProjectSettingsMetadataUpdate::WorktreeCommand { command, .. } => {
            let mut git_config = gpui_clone_json_object_field(&project, "gitConfig");
            git_config.insert(
                "worktreeCommand".to_string(),
                gpui_settings_metadata_string_or_null(&command),
            );
            params.insert(
                "gitConfig".to_string(),
                serde_json::Value::Object(git_config),
            );
        }
        GpuiProjectSettingsMetadataUpdate::BeadsDisplayKey { display_key, .. } => {
            let display_key = gpui_settings_beads_display_key_or_null(&display_key);
            let mut git_config = gpui_clone_json_object_field(&project, "gitConfig");
            git_config.insert("beadsDisplayKey".to_string(), display_key.clone());
            params.insert(
                "gitConfig".to_string(),
                serde_json::Value::Object(git_config),
            );

            let mut project_board_config =
                gpui_clone_json_object_field(&project, "projectBoardConfig");
            project_board_config.insert("beadsDisplayKey".to_string(), display_key);
            params.insert(
                "projectBoardConfig".to_string(),
                serde_json::Value::Object(project_board_config),
            );
        }
        GpuiProjectSettingsMetadataUpdate::BeadsDirectory { directory, .. } => {
            let mut project_board_config =
                gpui_clone_json_object_field(&project, "projectBoardConfig");
            project_board_config.insert(
                "beadsDirectory".to_string(),
                gpui_settings_metadata_string_or_null(&directory),
            );
            params.insert(
                "projectBoardConfig".to_string(),
                serde_json::Value::Object(project_board_config),
            );
        }
        GpuiProjectSettingsMetadataUpdate::SidebarCommands {
            commands,
            command_order,
            deleted_default_command_ids,
            ..
        } => {
            params.insert(
                "customCommands".to_string(),
                gpui_stored_sidebar_commands_value(&commands),
            );
            params.insert(
                "customCommandOrder".to_string(),
                gpui_string_array_value(&command_order),
            );
            params.insert(
                "deletedDefaultCommandIds".to_string(),
                gpui_string_array_value(&deleted_default_command_ids),
            );
        }
    }

    let result = gpui_gxserver_rpc_result(
        "/api/updateProject",
        &serde_json::Value::Object(params),
        Duration::from_secs(10),
    )?;
    if result
        .get("project")
        .and_then(serde_json::Value::as_object)
        .is_some()
    {
        Ok(())
    } else {
        Err("gxserver returned an invalid project update result.".to_string())
    }
}

fn gpui_find_gxserver_project_by_id(
    project_id: &str,
) -> Result<serde_json::Map<String, serde_json::Value>, String> {
    let result = gpui_gxserver_rpc_result(
        "/api/listProjects",
        &serde_json::json!({}),
        Duration::from_secs(10),
    )?;
    let projects = result
        .get("projects")
        .and_then(serde_json::Value::as_array)
        .ok_or_else(|| "gxserver returned invalid project metadata.".to_string())?;
    projects
        .iter()
        .filter_map(serde_json::Value::as_object)
        .find(|project| gpui_trimmed_json_string_field(project, "projectId") == Some(project_id))
        .cloned()
        .ok_or_else(|| "gxserver project metadata was not found.".to_string())
}

fn gpui_clone_json_object_field(
    object: &serde_json::Map<String, serde_json::Value>,
    key: &str,
) -> serde_json::Map<String, serde_json::Value> {
    object
        .get(key)
        .and_then(serde_json::Value::as_object)
        .cloned()
        .unwrap_or_default()
}

fn gpui_settings_metadata_string_or_null(value: &str) -> serde_json::Value {
    match gpui_trimmed_nonempty_str(Some(value)) {
        Some(value) => serde_json::Value::String(value.to_string()),
        None => serde_json::Value::Null,
    }
}

fn gpui_settings_beads_display_key_or_null(value: &str) -> serde_json::Value {
    let display_key = value
        .trim()
        .chars()
        .flat_map(|ch| ch.to_uppercase())
        .filter(|ch| ch.is_ascii_alphanumeric())
        .take(3)
        .collect::<String>();
    if display_key.is_empty() {
        serde_json::Value::Null
    } else {
        serde_json::Value::String(display_key)
    }
}

fn gpui_insert_optional_nonempty_string(
    item: &mut serde_json::Map<String, serde_json::Value>,
    key: &str,
    value: Option<&str>,
) {
    if let Some(value) = gpui_trimmed_nonempty_str(value) {
        item.insert(
            key.to_string(),
            serde_json::Value::String(value.to_string()),
        );
    }
}

fn gpui_trimmed_json_string_field<'a>(
    object: &'a serde_json::Map<String, serde_json::Value>,
    key: &str,
) -> Option<&'a str> {
    gpui_trimmed_nonempty_str(json_string_field(object, key))
}

fn gpui_trimmed_nonempty_str(value: Option<&str>) -> Option<&str> {
    let value = value?.trim();
    (!value.is_empty()).then_some(value)
}

#[derive(Clone, Debug)]
struct GpuiPreviousSessionsRequest {
    limit: usize,
    query: Option<String>,
    request_id: String,
    session_tags: Option<Vec<String>>,
}

fn gpui_previous_sessions_request_from_command(
    command: &serde_json::Map<String, serde_json::Value>,
) -> GpuiPreviousSessionsRequest {
    let limit = command
        .get("limit")
        .and_then(serde_json::Value::as_u64)
        .map(|limit| limit.min(200).max(1) as usize)
        .unwrap_or(80);
    let query = command
        .get("query")
        .and_then(serde_json::Value::as_str)
        .map(str::to_string);
    let request_id = command
        .get("requestId")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("")
        .to_string();
    let session_tags = command
        .get("sessionTags")
        .and_then(serde_json::Value::as_array)
        .map(|tags| {
            tags.iter()
                .filter_map(serde_json::Value::as_str)
                .map(str::to_string)
                .collect::<Vec<_>>()
        });
    GpuiPreviousSessionsRequest {
        limit,
        query,
        request_id,
        session_tags,
    }
}

fn gpui_previous_sessions_result_message(
    request: GpuiPreviousSessionsRequest,
) -> serde_json::Value {
    /*
    CDXC:GPUIPreviousSessionsModal 2026-06-24-11:53:
    GPUI Previous Sessions loads real local gxserver history through `/api/listPreviousSessions` with the same bounded previous-only params as the TypeScript sidebar runtime. The response is a transient `previousSessionsResult` sidebarState payload so the shared modal clears loading without replacing the stored hydrate snapshot, and transport/token/network/parser failures return an empty contract-shaped result without logging private daemon data.
    */
    let previous_sessions = gpui_list_previous_sessions_from_gxserver(&request).unwrap_or_default();
    gpui_previous_sessions_result_payload(
        &request.request_id,
        request.query.as_deref(),
        previous_sessions,
    )
}

fn gpui_list_previous_sessions_from_gxserver(
    request: &GpuiPreviousSessionsRequest,
) -> Result<Vec<serde_json::Value>, String> {
    let mut params = serde_json::Map::new();
    params.insert("includeActive".to_string(), serde_json::Value::Bool(false));
    params.insert("includePrevious".to_string(), serde_json::Value::Bool(true));
    params.insert(
        "limit".to_string(),
        serde_json::Value::Number(serde_json::Number::from(request.limit as u64)),
    );
    if let Some(query) = request.query.as_ref() {
        params.insert(
            "query".to_string(),
            serde_json::Value::String(query.clone()),
        );
    }
    if let Some(session_tags) = request.session_tags.as_ref() {
        params.insert(
            "sessionTags".to_string(),
            serde_json::Value::Array(
                session_tags
                    .iter()
                    .map(|tag| serde_json::Value::String(tag.clone()))
                    .collect(),
            ),
        );
    }
    let result = gpui_gxserver_rpc_result(
        "/api/listPreviousSessions",
        &serde_json::Value::Object(params),
        Duration::from_secs(10),
    )?;
    let results = result
        .get("results")
        .and_then(serde_json::Value::as_array)
        .ok_or_else(|| "gxserver returned invalid previous-session results.".to_string())?;
    Ok(results
        .iter()
        .filter_map(gpui_gxserver_search_result_to_previous_session_item)
        .collect())
}

fn gpui_previous_sessions_result_payload(
    request_id: &str,
    query: Option<&str>,
    previous_sessions: Vec<serde_json::Value>,
) -> serde_json::Value {
    let mut payload = serde_json::Map::new();
    payload.insert(
        "previousSessions".to_string(),
        serde_json::Value::Array(previous_sessions),
    );
    if let Some(query) = query {
        payload.insert(
            "query".to_string(),
            serde_json::Value::String(query.to_string()),
        );
    }
    payload.insert(
        "requestId".to_string(),
        serde_json::Value::String(request_id.to_string()),
    );
    payload.insert(
        "type".to_string(),
        serde_json::Value::String("previousSessionsResult".to_string()),
    );
    serde_json::Value::Object(payload)
}

fn gpui_gxserver_search_result_to_previous_session_item(
    result: &serde_json::Value,
) -> Option<serde_json::Value> {
    /*
    CDXC:GPUIPreviousSessionsModal 2026-06-24-11:53:
    Previous-session rows returned to React must stay contract-shaped and metadata-only. Mirror the existing GPUI TypeScript projection from gxserver search results, including project/session restore identity and title/provider fields, but do not forward raw command text, stdout/stderr, workspace paths, URLs, tokens, gxserver responses, or archived session records.
    */
    let result = result.as_object()?;
    let title = json_string_field(result, "displayTitle")
        .or_else(|| json_string_field(result, "primaryTitle"))
        .or_else(|| json_string_field(result, "title"))
        .unwrap_or("Previous Session");
    let closed_at = json_string_field(result, "closedAt")
        .or_else(|| json_string_field(result, "updatedAt"))
        .or_else(|| json_string_field(result, "createdAt"))?;
    let project_id = json_string_field(result, "projectId")?;
    let session_id = json_string_field(result, "sessionId")?;
    let project_title = json_string_field(result, "projectTitle")?;
    let agent_name =
        json_string_field(result, "agentName").or_else(|| json_string_field(result, "agentId"));
    let agent_icon = json_string_field(result, "agentIcon").or(agent_name);
    let session_persistence_provider =
        json_string_field(result, "sessionPersistenceProvider").unwrap_or("zmx");
    let session_persistence_name = json_string_field(result, "sessionPersistenceName")
        .or_else(|| json_string_field(result, "zmxName"));

    let mut item = serde_json::Map::new();
    item.insert(
        "activity".to_string(),
        serde_json::Value::String("idle".to_string()),
    );
    if let Some(agent_icon) = gpui_sidebar_agent_icon(agent_icon) {
        item.insert(
            "agentIcon".to_string(),
            serde_json::Value::String(agent_icon.to_string()),
        );
    }
    gpui_insert_optional_string(
        &mut item,
        "agentSessionId",
        json_string_field(result, "agentSessionId"),
    );
    item.insert(
        "alias".to_string(),
        serde_json::Value::String(title.to_string()),
    );
    item.insert(
        "closedAt".to_string(),
        serde_json::Value::String(closed_at.to_string()),
    );
    item.insert("column".to_string(), serde_json::Value::Number(0.into()));
    gpui_insert_optional_string(
        &mut item,
        "displayTitle",
        json_string_field(result, "displayTitle"),
    );
    gpui_insert_optional_string(
        &mut item,
        "displayTitleTooltip",
        json_string_field(result, "displayTitleTooltip"),
    );
    item.insert(
        "historyId".to_string(),
        serde_json::Value::String(format!("gxserver:{project_id}:{session_id}")),
    );
    item.insert(
        "isFavorite".to_string(),
        serde_json::Value::Bool(json_bool_field(result, "isFavorite").unwrap_or(false)),
    );
    item.insert("isFocused".to_string(), serde_json::Value::Bool(false));
    item.insert(
        "isGeneratedName".to_string(),
        serde_json::Value::Bool(false),
    );
    item.insert(
        "isPinned".to_string(),
        serde_json::Value::Bool(json_bool_field(result, "isPinned").unwrap_or(false)),
    );
    item.insert(
        "isPrimaryTitleTerminalTitle".to_string(),
        serde_json::Value::Bool(
            json_bool_field(result, "isPrimaryTitleTerminalTitle").unwrap_or(false),
        ),
    );
    item.insert("isRestorable".to_string(), serde_json::Value::Bool(true));
    item.insert("isRunning".to_string(), serde_json::Value::Bool(false));
    item.insert("isVisible".to_string(), serde_json::Value::Bool(false));
    gpui_insert_optional_string(
        &mut item,
        "lastInteractionAt",
        json_string_field(result, "lastActiveAt"),
    );
    item.insert(
        "lifecycleState".to_string(),
        serde_json::Value::String("done".to_string()),
    );
    item.insert(
        "primaryTitle".to_string(),
        serde_json::Value::String(
            json_string_field(result, "primaryTitle")
                .unwrap_or(title)
                .to_string(),
        ),
    );
    item.insert(
        "projectId".to_string(),
        serde_json::Value::String(project_id.to_string()),
    );
    item.insert(
        "projectName".to_string(),
        serde_json::Value::String(project_title.to_string()),
    );
    item.insert("row".to_string(), serde_json::Value::Number(0.into()));
    item.insert(
        "sessionId".to_string(),
        serde_json::Value::String(session_id.to_string()),
    );
    item.insert(
        "sessionKind".to_string(),
        serde_json::Value::String("terminal".to_string()),
    );
    gpui_insert_optional_string(
        &mut item,
        "sessionPersistenceName",
        session_persistence_name,
    );
    item.insert(
        "sessionPersistenceProvider".to_string(),
        serde_json::Value::String(session_persistence_provider.to_string()),
    );
    gpui_insert_optional_string(
        &mut item,
        "sessionTag",
        json_string_field(result, "sessionTag"),
    );
    item.insert(
        "shortcutLabel".to_string(),
        serde_json::Value::String(String::new()),
    );
    gpui_insert_optional_string(
        &mut item,
        "terminalTitle",
        json_string_field(result, "terminalTitle"),
    );
    Some(serde_json::Value::Object(item))
}

fn gpui_insert_optional_string(
    item: &mut serde_json::Map<String, serde_json::Value>,
    key: &str,
    value: Option<&str>,
) {
    if let Some(value) = value {
        item.insert(
            key.to_string(),
            serde_json::Value::String(value.to_string()),
        );
    }
}

fn gpui_sidebar_agent_icon(value: Option<&str>) -> Option<&'static str> {
    let value = value?.trim().to_ascii_lowercase();
    match value.as_str() {
        "browser" => Some("browser"),
        "t3" | "t3 code" => Some("t3"),
        "codex" => Some("codex"),
        "claude" => Some("claude"),
        "cursor" | "cursor cli" | "cursor-cli" => Some("cursor-cli"),
        "pi" | "pi agent" => Some("pi"),
        "opencode" | "open code" => Some("opencode"),
        "gemini" => Some("gemini"),
        "copilot" => Some("copilot"),
        "droid" | "factory droid" | "factory-droid" => Some("factory-droid"),
        "grok" | "grok build" | "grok-build" => Some("grok-build"),
        "antigravity" | "antigravity cli" | "antigravity-cli" => Some("antigravity-cli"),
        "amp" | "amp cli" | "amp-cli" => Some("amp-cli"),
        "rovodev" | "rovo dev" | "rovo-dev" => Some("rovo-dev"),
        "hermes-agent" | "hermes agent" => Some("hermes-agent"),
        "codebuddy" => Some("codebuddy"),
        "qoder" => Some("qoder"),
        "kiro" | "kiro cli" => Some("kiro"),
        "omp" => Some("omp"),
        _ => None,
    }
}

fn gpui_previous_session_reference_from_history_id(history_id: &str) -> Option<(&str, &str)> {
    let payload = history_id.strip_prefix("gxserver:")?;
    payload.split_once(':')
}

fn gpui_delete_previous_session_from_history_id(history_id: &str) {
    let Some((project_id, session_id)) =
        gpui_previous_session_reference_from_history_id(history_id)
    else {
        return;
    };
    let _ = gpui_gxserver_rpc_result(
        "/api/removeSession",
        &serde_json::json!({
            "projectId": project_id,
            "reason": "deletePreviousSession",
            "sessionId": session_id,
        }),
        Duration::from_secs(10),
    );
}

fn gpui_restore_previous_session_from_history_id(history_id: &str) {
    /*
    CDXC:GPUIPreviousSessionsModal 2026-06-24-11:53:
    Restore/delete commands from the shared Previous Sessions modal are local gxserver mutations only when the modal row carries the canonical `gxserver:<projectId>:<sessionId>` identity created by this projection. Restore creates a replacement workspace terminal with `restoredFromSessionId`, then removes the stopped history row only after create succeeds; unavailable gxserver or malformed history ids remain silent no-ops rather than fake success.
    */
    let Some((project_id, session_id)) =
        gpui_previous_session_reference_from_history_id(history_id)
    else {
        return;
    };
    if gpui_gxserver_rpc_result(
        "/api/createSession",
        &serde_json::json!({
            "kind": "terminal",
            "lifecycleState": "running",
            "projectId": project_id,
            "restoredFromSessionId": session_id,
            "surface": "workspace",
        }),
        Duration::from_secs(30),
    )
    .is_ok()
    {
        let _ = gpui_gxserver_rpc_result(
            "/api/removeSession",
            &serde_json::json!({
                "projectId": project_id,
                "reason": "restorePreviousSession",
                "sessionId": session_id,
            }),
            Duration::from_secs(10),
        );
    }
}

fn gpui_close_daemon_session_and_refresh_state(
    project_id: Option<String>,
    session_id: Option<String>,
    active_project_id: Option<&str>,
) -> serde_json::Value {
    let error_message = match (project_id, session_id) {
        (Some(project_id), Some(session_id)) => {
            /*
            CDXC:GPUIDaemonSessionsModal 2026-06-24-12:00:
            Running Sessions can close only gxserver-owned rows whose modal payload carries both project/workspace id and session id. Use `/api/transitionSession` with `close` instead of `/api/removeSession` so gxserver owns provider shutdown and lifecycle history, while malformed ids or transport failures refresh the list with an honest error and no fake success.
            */
            if gpui_gxserver_rpc_result(
                "/api/transitionSession",
                &serde_json::json!({
                    "action": "close",
                    "projectId": project_id,
                    "reason": "gpuiRunningSessionsModal",
                    "sessionId": session_id,
                }),
                Duration::from_secs(30),
            )
            .is_ok()
            {
                None
            } else {
                Some("GPUI could not close that gxserver session. The Running Sessions list was refreshed without reporting fake success.".to_string())
            }
        }
        _ => Some(
            "GPUI could not identify that gxserver session. The Running Sessions list was refreshed without changing daemon state."
                .to_string(),
        ),
    };
    gpui_daemon_sessions_state_message(error_message, active_project_id)
}

fn gpui_daemon_sessions_state_message(
    error_message: Option<String>,
    active_project_id: Option<&str>,
) -> serde_json::Value {
    /*
    CDXC:GPUIDaemonSessionsModal 2026-06-24-12:00:
    GPUI Running Sessions state is built from real local gxserver health and `/api/readPresentationSnapshot` only. If gxserver, auth, health, or presentation is unavailable, return the shared daemonSessionsState shape with empty gxserver/T3 rows and an explicit error message; do not invent daemon pid/port, project paths, T3 server state, terminal text, commands, URLs, tokens, raw responses, or fallback sessions.
    */
    let daemon = gpui_daemon_info_from_gxserver_health().ok();
    let sessions = match gpui_read_gxserver_presentation_snapshot() {
        Ok(snapshot) => {
            gpui_daemon_session_items_from_presentation_snapshot(&snapshot, active_project_id)
        }
        Err(_) => {
            let unavailable_message = error_message.unwrap_or_else(|| {
                "Local gxserver is unavailable, so Running Sessions cannot load shared daemon sessions."
                    .to_string()
            });
            return gpui_daemon_sessions_state_payload(
                daemon,
                Vec::new(),
                Some(unavailable_message),
            );
        }
    };
    gpui_daemon_sessions_state_payload(daemon, sessions, error_message)
}

fn gpui_daemon_sessions_state_payload(
    daemon: Option<serde_json::Value>,
    sessions: Vec<serde_json::Value>,
    error_message: Option<String>,
) -> serde_json::Value {
    let mut payload = serde_json::Map::new();
    if let Some(daemon) = daemon {
        payload.insert("daemon".to_string(), daemon);
    }
    if let Some(error_message) = error_message {
        payload.insert(
            "errorMessage".to_string(),
            serde_json::Value::String(error_message),
        );
    }
    payload.insert("sessions".to_string(), serde_json::Value::Array(sessions));
    payload.insert(
        "t3Sessions".to_string(),
        serde_json::Value::Array(Vec::new()),
    );
    payload.insert(
        "type".to_string(),
        serde_json::Value::String("daemonSessionsState".to_string()),
    );
    serde_json::Value::Object(payload)
}

fn gpui_daemon_info_from_gxserver_health() -> Result<serde_json::Value, String> {
    let health = gpui_gxserver_server_health(Duration::from_secs(2))?;
    if health.get("ok").and_then(serde_json::Value::as_bool) != Some(true)
        || health.get("product").and_then(serde_json::Value::as_str) != Some(GPUI_GXSERVER_PRODUCT)
    {
        return Err("gxserver health was invalid.".to_string());
    }
    let pid = health
        .get("pid")
        .and_then(serde_json::Value::as_u64)
        .ok_or_else(|| "gxserver health omitted pid.".to_string())?;
    let port = health
        .get("port")
        .and_then(serde_json::Value::as_u64)
        .ok_or_else(|| "gxserver health omitted port.".to_string())?;
    let protocol_version = health
        .get("protocolVersion")
        .and_then(serde_json::Value::as_u64)
        .ok_or_else(|| "gxserver health omitted protocol version.".to_string())?;
    let started_at = health
        .get("startedAt")
        .and_then(serde_json::Value::as_str)
        .ok_or_else(|| "gxserver health omitted start time.".to_string())?;
    Ok(serde_json::json!({
        "pid": pid,
        "port": port,
        "protocolVersion": protocol_version,
        "startedAt": started_at,
    }))
}

fn gpui_read_gxserver_presentation_snapshot() -> Result<serde_json::Value, String> {
    let result = gpui_gxserver_rpc_result(
        "/api/readPresentationSnapshot",
        &serde_json::json!({}),
        Duration::from_secs(10),
    )?;
    result
        .get("snapshot")
        .and_then(serde_json::Value::as_object)
        .cloned()
        .map(serde_json::Value::Object)
        .ok_or_else(|| "gxserver returned an invalid presentation snapshot.".to_string())
}

fn gpui_daemon_session_items_from_presentation_snapshot(
    snapshot: &serde_json::Value,
    active_project_id: Option<&str>,
) -> Vec<serde_json::Value> {
    let Some(snapshot) = snapshot.as_object() else {
        return Vec::new();
    };
    let projects_by_id = json_array_field(snapshot, "projects")
        .into_iter()
        .flatten()
        .filter_map(|project| {
            let project = project.as_object()?;
            let project_id = json_string_field(project, "projectId")?;
            Some((project_id.to_string(), project.clone()))
        })
        .collect::<HashMap<_, _>>();
    json_array_field(snapshot, "sessions")
        .into_iter()
        .flatten()
        .filter_map(|session| {
            gpui_presentation_session_to_daemon_session_item(
                session,
                &projects_by_id,
                active_project_id,
            )
        })
        .collect()
}

fn gpui_presentation_session_to_daemon_session_item(
    session: &serde_json::Value,
    projects_by_id: &HashMap<String, serde_json::Map<String, serde_json::Value>>,
    active_project_id: Option<&str>,
) -> Option<serde_json::Value> {
    let session = session.as_object()?;
    let kind = json_string_field(session, "kind")?;
    let surface = json_string_field(session, "surface")?;
    if surface != "workspace" || !matches!(kind, "terminal" | "agent") {
        return None;
    }
    let project_id = json_string_field(session, "projectId")?;
    let session_id = json_string_field(session, "sessionId")?;
    let project = projects_by_id.get(project_id);
    let cwd = json_string_field(session, "cwd")
        .or_else(|| project.and_then(|project| json_string_field(project, "path")))
        .unwrap_or("");
    let title = json_string_field(session, "displayTitle")
        .or_else(|| json_string_field(session, "primaryTitle"))
        .or_else(|| json_string_field(session, "title"));
    let started_at = json_string_field(session, "createdAt")?;
    let shell = json_string_field(session, "sessionPersistenceProvider").unwrap_or("");
    let lifecycle_state = json_string_field(session, "lifecycleState").unwrap_or("unknown");
    let provider_state = json_string_field(session, "providerSessionState").unwrap_or("unknown");
    let status = gpui_daemon_session_status_from_gxserver(lifecycle_state, provider_state);
    let mut item = serde_json::Map::new();
    gpui_insert_optional_string(
        &mut item,
        "agentName",
        json_string_field(session, "agentName").or_else(|| json_string_field(session, "agentId")),
    );
    item.insert(
        "agentStatus".to_string(),
        serde_json::Value::String(
            gpui_daemon_agent_status(json_string_field(session, "activity")).to_string(),
        ),
    );
    /*
    CDXC:GPUIDaemonSessionsModal 2026-06-24-12:00:
    gxserver presentation does not currently expose terminal dimensions. Keep cols/rows as explicit zero values in GPUI Running Sessions until a real dimensions contract exists instead of inventing 80x24 or reading terminal/private process state.
    */
    item.insert("cols".to_string(), serde_json::Value::Number(0.into()));
    item.insert(
        "cwd".to_string(),
        serde_json::Value::String(cwd.to_string()),
    );
    item.insert(
        "isCurrentWorkspace".to_string(),
        serde_json::Value::Bool(active_project_id == Some(project_id)),
    );
    item.insert(
        "ownership".to_string(),
        serde_json::Value::String("gxserver".to_string()),
    );
    item.insert(
        "restoreState".to_string(),
        serde_json::Value::String("live".to_string()),
    );
    item.insert("rows".to_string(), serde_json::Value::Number(0.into()));
    item.insert(
        "sessionId".to_string(),
        serde_json::Value::String(session_id.to_string()),
    );
    item.insert(
        "shell".to_string(),
        serde_json::Value::String(shell.to_string()),
    );
    item.insert(
        "startedAt".to_string(),
        serde_json::Value::String(started_at.to_string()),
    );
    item.insert(
        "status".to_string(),
        serde_json::Value::String(status.to_string()),
    );
    gpui_insert_optional_string(&mut item, "title", title);
    item.insert(
        "workspaceId".to_string(),
        serde_json::Value::String(project_id.to_string()),
    );
    Some(serde_json::Value::Object(item))
}

fn gpui_daemon_agent_status(value: Option<&str>) -> &'static str {
    match value {
        Some("working") => "working",
        Some("attention") => "attention",
        _ => "idle",
    }
}

fn gpui_daemon_session_status_from_gxserver(
    lifecycle_state: &str,
    provider_state: &str,
) -> &'static str {
    match lifecycle_state {
        "running" if provider_state == "exists" || provider_state == "unknown" => "running",
        "running" => "disconnected",
        "stopped" => "exited",
        "sleeping" | "missing" | "unknown" => "disconnected",
        _ => "disconnected",
    }
}

const GPUI_OS_INTEGRATION_EDITOR_EXTENSIONS: &[&str] = &[
    "txt", "md", "markdown", "json", "jsonc", "yaml", "yml", "toml", "ini", "env", "xml", "csv",
    "html", "css", "scss", "js", "jsx", "ts", "tsx", "sh", "bash", "zsh", "fish", "py", "rb", "go",
    "rs", "swift", "java", "kt", "c", "h", "cpp", "hpp", "cs", "php", "lua", "sql",
];
const GPUI_OS_INTEGRATION_STATUS_EDITOR_EXTENSIONS: &[&str] =
    &["txt", "md", "json", "js", "ts", "sh"];
const GPUI_OS_INTEGRATION_SCRIPT_EXTENSIONS: &[&str] = &["command", "tool", "sh"];

fn gpui_set_os_integration_defaults_status_message(target: Option<&str>) -> serde_json::Value {
    let status_items = gpui_set_os_integration_defaults(target);
    let mut payload = gpui_os_integration_status_message();
    gpui_merge_os_integration_status_items(&mut payload, status_items);
    payload
}

#[cfg(target_os = "macos")]
fn gpui_set_os_integration_defaults(target: Option<&str>) -> Vec<serde_json::Value> {
    /*
    CDXC:GPUIOSIntegration 2026-06-24-15:02:
    GPUI Settings may mutate Launch Services defaults only from explicit OS Integration button clicks. Status refreshes and startup must stay read-only, while this path targets only the requested editor, ghostex:// terminal-link, script-runner, or all roles.

    CDXC:GPUIOSIntegration 2026-06-24-15:10:
    Default mutations must return privacy-safe status items for the reused Settings UI. Capture per-extension and per-scheme Launch Services failures as enum reasons only; never expose bundle paths, file paths, URLs, command text, environment values, stdout/stderr, daemon bodies, or raw OSStatus values.
    */
    let mut status_items = Vec::new();
    let Some(target) = target else {
        status_items.push(gpui_os_integration_status_item(
            "platform",
            "setDefault",
            "skipped",
            "invalidTarget",
            None,
            None,
        ));
        return status_items;
    };
    if !matches!(target, "editor" | "terminalLinks" | "scriptRunner" | "all") {
        status_items.push(gpui_os_integration_status_item(
            "platform",
            "setDefault",
            "skipped",
            "invalidTarget",
            None,
            None,
        ));
        return status_items;
    }
    let Some(bundle) = gpui_macos_os_integration_bundle_info() else {
        status_items.push(gpui_os_integration_status_item(
            "bundleRegistration",
            "setDefault",
            "failed",
            "bundleIdentifierMissing",
            None,
            None,
        ));
        return status_items;
    };

    match gpui_macos_register_os_integration_bundle(&bundle.bundle_root) {
        Some(status) if status == 0 => {}
        _ => status_items.push(gpui_os_integration_status_item(
            "bundleRegistration",
            "registerBundle",
            "failed",
            "bundleRegistrationFailed",
            None,
            None,
        )),
    }
    if target == "editor" || target == "all" {
        for file_extension in GPUI_OS_INTEGRATION_EDITOR_EXTENSIONS {
            let Some(content_type) = gpui_macos_content_type_for_extension(file_extension) else {
                status_items.push(gpui_os_integration_status_item(
                    "editor",
                    "setDefault",
                    "skipped",
                    "contentTypeUnavailable",
                    Some(file_extension),
                    None,
                ));
                continue;
            };
            let Some(bundle_identifier) = GpuiCfString::new(&bundle.bundle_identifier) else {
                status_items.push(gpui_os_integration_status_item(
                    "editor",
                    "setDefault",
                    "failed",
                    "bundleIdentifierMissing",
                    Some(file_extension),
                    None,
                ));
                continue;
            };
            let status = unsafe {
                LSSetDefaultRoleHandlerForContentType(
                    content_type.as_ref(),
                    K_LS_ROLES_EDITOR,
                    bundle_identifier.as_ref(),
                )
            };
            if status != 0 {
                status_items.push(gpui_os_integration_status_item(
                    "editor",
                    "setDefault",
                    "failed",
                    "launchServicesRejected",
                    Some(file_extension),
                    None,
                ));
            }
        }
    }
    if target == "terminalLinks" || target == "all" {
        if let (Some(scheme), Some(bundle_identifier)) = (
            GpuiCfString::new("ghostex"),
            GpuiCfString::new(&bundle.bundle_identifier),
        ) {
            let status = unsafe {
                LSSetDefaultHandlerForURLScheme(scheme.as_ref(), bundle_identifier.as_ref())
            };
            if status != 0 {
                status_items.push(gpui_os_integration_status_item(
                    "terminalLinks",
                    "setDefault",
                    "failed",
                    "launchServicesRejected",
                    None,
                    Some("ghostex"),
                ));
            }
        } else {
            status_items.push(gpui_os_integration_status_item(
                "terminalLinks",
                "setDefault",
                "failed",
                "bundleIdentifierMissing",
                None,
                Some("ghostex"),
            ));
        }
    }
    if target == "scriptRunner" || target == "all" {
        for file_extension in GPUI_OS_INTEGRATION_SCRIPT_EXTENSIONS {
            let Some(content_type) = gpui_macos_content_type_for_extension(file_extension) else {
                status_items.push(gpui_os_integration_status_item(
                    "scriptRunner",
                    "setDefault",
                    "skipped",
                    "contentTypeUnavailable",
                    Some(file_extension),
                    None,
                ));
                continue;
            };
            let Some(bundle_identifier) = GpuiCfString::new(&bundle.bundle_identifier) else {
                status_items.push(gpui_os_integration_status_item(
                    "scriptRunner",
                    "setDefault",
                    "failed",
                    "bundleIdentifierMissing",
                    Some(file_extension),
                    None,
                ));
                continue;
            };
            let status = unsafe {
                LSSetDefaultRoleHandlerForContentType(
                    content_type.as_ref(),
                    K_LS_ROLES_SHELL,
                    bundle_identifier.as_ref(),
                )
            };
            if status != 0 {
                status_items.push(gpui_os_integration_status_item(
                    "scriptRunner",
                    "setDefault",
                    "failed",
                    "launchServicesRejected",
                    Some(file_extension),
                    None,
                ));
            }
        }
    }
    status_items
}

#[cfg(not(target_os = "macos"))]
fn gpui_set_os_integration_defaults(target: Option<&str>) -> Vec<serde_json::Value> {
    if matches!(
        target,
        Some("editor") | Some("terminalLinks") | Some("scriptRunner") | Some("all")
    ) {
        return Vec::new();
    }
    vec![gpui_os_integration_status_item(
        "platform",
        "setDefault",
        "skipped",
        "invalidTarget",
        None,
        None,
    )]
}

fn gpui_os_integration_status_message() -> serde_json::Value {
    gpui_os_integration_status_payload()
}

fn gpui_merge_os_integration_status_items(
    payload: &mut serde_json::Value,
    status_items: Vec<serde_json::Value>,
) {
    if status_items.is_empty() {
        return;
    }
    let Some(object) = payload.as_object_mut() else {
        return;
    };
    match object.get_mut("statusItems") {
        Some(serde_json::Value::Array(existing_items)) => {
            existing_items.extend(status_items);
        }
        _ => {
            object.insert(
                "statusItems".to_string(),
                serde_json::Value::Array(status_items),
            );
        }
    }
}

fn gpui_os_integration_status_item(
    target: &str,
    operation: &str,
    status: &str,
    reason: &str,
    file_extension: Option<&str>,
    scheme: Option<&str>,
) -> serde_json::Value {
    let mut item = serde_json::Map::new();
    item.insert(
        "operation".to_string(),
        serde_json::Value::String(operation.to_string()),
    );
    item.insert(
        "reason".to_string(),
        serde_json::Value::String(reason.to_string()),
    );
    item.insert(
        "status".to_string(),
        serde_json::Value::String(status.to_string()),
    );
    item.insert(
        "target".to_string(),
        serde_json::Value::String(target.to_string()),
    );
    if let Some(file_extension) = file_extension {
        item.insert(
            "extension".to_string(),
            serde_json::Value::String(file_extension.to_string()),
        );
    }
    if let Some(scheme) = scheme {
        item.insert(
            "scheme".to_string(),
            serde_json::Value::String(scheme.to_string()),
        );
    }
    serde_json::Value::Object(item)
}

#[cfg(not(target_os = "macos"))]
fn gpui_os_integration_status_payload() -> serde_json::Value {
    /*
    CDXC:GPUIOSIntegration 2026-06-24-15:02:
    Non-macOS builds cannot inspect or mutate macOS Launch Services. Keep the shared status payload honest with unavailable registrations and no default handlers instead of inventing platform parity.
    */
    serde_json::json!({
        "bundleIdentifier": "com.madda.ghostex.gpui-unavailable",
        "editorDefaults": {},
        "generatedAt": gpui_status_generated_at(),
        "registeredEditableFiles": false,
        "registeredGhostexURLScheme": false,
        "registeredScriptRunner": false,
        "scriptDefaults": {},
        "statusItems": [
            gpui_os_integration_status_item(
                "platform",
                "readStatus",
                "unsupported",
                "unsupportedPlatform",
                None,
                None,
            )
        ],
        "terminalLinkDefaultBundleId": "GPUI Launch Services bridge unavailable",
        "type": "osIntegrationStatus",
    })
}

#[cfg(target_os = "macos")]
fn gpui_os_integration_status_payload() -> serde_json::Value {
    /*
    CDXC:GPUIOSIntegration 2026-06-24-15:02:
    Settings diagnostics should mirror the Swift host payload: app bundle id, Launch Services defaults for representative editor/script extensions, ghostex:// default handler, and Info.plist registration booleans. This function is read-only and must not set defaults or register the app on status requests.
    */
    let bundle = gpui_macos_os_integration_bundle_info();
    let bundle_identifier = bundle
        .as_ref()
        .map(|info| info.bundle_identifier.as_str())
        .unwrap_or("com.madda.ghostex.gpui-unavailable");
    let info_plist = bundle
        .as_ref()
        .map(|info| info.info_plist.as_str())
        .unwrap_or("");
    let mut payload = serde_json::json!({
        "bundleIdentifier": bundle_identifier,
        "editorDefaults": gpui_macos_default_role_handlers(
            GPUI_OS_INTEGRATION_STATUS_EDITOR_EXTENSIONS,
            K_LS_ROLES_EDITOR,
        ),
        "generatedAt": gpui_status_generated_at(),
        "registeredEditableFiles": gpui_os_integration_has_editable_registration(info_plist),
        "registeredGhostexURLScheme": gpui_os_integration_has_ghostex_url_registration(info_plist),
        "registeredScriptRunner": gpui_os_integration_has_script_registration(info_plist),
        "scriptDefaults": gpui_macos_default_role_handlers(
            GPUI_OS_INTEGRATION_SCRIPT_EXTENSIONS,
            K_LS_ROLES_SHELL,
        ),
        "type": "osIntegrationStatus",
    });
    if bundle.is_none() {
        gpui_merge_os_integration_status_items(
            &mut payload,
            vec![gpui_os_integration_status_item(
                "bundleRegistration",
                "readStatus",
                "failed",
                "bundleIdentifierMissing",
                None,
                None,
            )],
        );
    }
    if let Some(handler) = gpui_macos_default_url_scheme_handler("ghostex") {
        if let Some(object) = payload.as_object_mut() {
            object.insert(
                "terminalLinkDefaultBundleId".to_string(),
                serde_json::Value::String(handler),
            );
        }
    }
    payload
}

#[cfg(target_os = "macos")]
struct GpuiOSIntegrationBundleInfo {
    bundle_identifier: String,
    bundle_root: PathBuf,
    info_plist: String,
}

#[cfg(target_os = "macos")]
fn gpui_macos_os_integration_bundle_info() -> Option<GpuiOSIntegrationBundleInfo> {
    let executable = env::current_exe().ok()?;
    let bundle_root = find_app_bundle_root(&executable)?;
    let info_plist = fs::read_to_string(bundle_root.join("Contents/Info.plist")).ok()?;
    let bundle_identifier = gpui_plist_string_value(&info_plist, "CFBundleIdentifier")?;
    Some(GpuiOSIntegrationBundleInfo {
        bundle_identifier,
        bundle_root,
        info_plist,
    })
}

#[cfg(target_os = "macos")]
fn gpui_plist_string_value(plist: &str, key: &str) -> Option<String> {
    let key_marker = format!("<key>{key}</key>");
    let after_key = plist.split_once(&key_marker)?.1;
    let after_string = after_key.split_once("<string>")?.1;
    let value = after_string.split_once("</string>")?.0.trim();
    (!value.is_empty()).then(|| value.to_string())
}

#[cfg(target_os = "macos")]
fn gpui_os_integration_has_editable_registration(info_plist: &str) -> bool {
    info_plist.contains("<key>CFBundleDocumentTypes</key>")
        && info_plist.contains("<key>CFBundleTypeRole</key>")
        && info_plist.contains("<string>Editor</string>")
        && (info_plist.contains("<string>*</string>")
            || info_plist.contains("<string>public.text</string>")
            || info_plist.contains("<string>public.source-code</string>"))
}

#[cfg(target_os = "macos")]
fn gpui_os_integration_has_script_registration(info_plist: &str) -> bool {
    info_plist.contains("<key>CFBundleDocumentTypes</key>")
        && info_plist.contains("<key>CFBundleTypeRole</key>")
        && info_plist.contains("<string>Shell</string>")
        && GPUI_OS_INTEGRATION_SCRIPT_EXTENSIONS
            .iter()
            .all(|file_extension| {
                info_plist.contains(&format!("<string>{file_extension}</string>"))
            })
}

#[cfg(target_os = "macos")]
fn gpui_os_integration_has_ghostex_url_registration(info_plist: &str) -> bool {
    info_plist.contains("<key>CFBundleURLTypes</key>")
        && info_plist.contains("<key>CFBundleURLSchemes</key>")
        && info_plist.contains("<string>ghostex</string>")
}

#[cfg(target_os = "macos")]
fn gpui_macos_default_role_handlers(extensions: &[&str], role: u32) -> serde_json::Value {
    let handlers = extensions
        .iter()
        .filter_map(|file_extension| {
            let content_type = gpui_macos_content_type_for_extension(file_extension)?;
            let handler =
                unsafe { LSCopyDefaultRoleHandlerForContentType(content_type.as_ref(), role) };
            let handler = gpui_cf_string_to_string_and_release(handler)?;
            Some((
                (*file_extension).to_string(),
                serde_json::Value::String(handler),
            ))
        })
        .collect::<serde_json::Map<String, serde_json::Value>>();
    serde_json::Value::Object(handlers)
}

#[cfg(target_os = "macos")]
fn gpui_macos_default_url_scheme_handler(scheme: &str) -> Option<String> {
    let scheme = GpuiCfString::new(scheme)?;
    let handler = unsafe { LSCopyDefaultHandlerForURLScheme(scheme.as_ref()) };
    gpui_cf_string_to_string_and_release(handler)
}

#[cfg(target_os = "macos")]
fn gpui_macos_register_os_integration_bundle(bundle_root: &Path) -> Option<i32> {
    let path = GpuiCfString::new(&bundle_root.to_string_lossy())?;
    let url = unsafe {
        CFURLCreateWithFileSystemPath(
            std::ptr::null(),
            path.as_ref(),
            K_CF_URL_POSIX_PATH_STYLE,
            1,
        )
    };
    if url.is_null() {
        return None;
    }
    let status = unsafe { LSRegisterURL(url, 1) };
    unsafe {
        CFRelease(url);
    }
    Some(status)
}

#[cfg(target_os = "macos")]
fn gpui_macos_content_type_for_extension(file_extension: &str) -> Option<GpuiCfString> {
    let tag = GpuiCfString::new(file_extension)?;
    let content_type = unsafe {
        UTTypeCreatePreferredIdentifierForTag(
            kUTTagClassFilenameExtension,
            tag.as_ref(),
            std::ptr::null(),
        )
    };
    GpuiCfString::from_owned(content_type)
}

#[cfg(target_os = "macos")]
struct GpuiCfString(CFStringRef);

#[cfg(target_os = "macos")]
impl GpuiCfString {
    fn new(value: &str) -> Option<Self> {
        let c_value = std::ffi::CString::new(value).ok()?;
        let string = unsafe {
            CFStringCreateWithCString(
                std::ptr::null(),
                c_value.as_ptr(),
                K_CF_STRING_ENCODING_UTF8,
            )
        };
        Self::from_owned(string)
    }

    fn from_owned(value: CFStringRef) -> Option<Self> {
        (!value.is_null()).then_some(Self(value))
    }

    fn as_ref(&self) -> CFStringRef {
        self.0
    }
}

#[cfg(target_os = "macos")]
impl Drop for GpuiCfString {
    fn drop(&mut self) {
        unsafe {
            CFRelease(self.0);
        }
    }
}

#[cfg(target_os = "macos")]
fn gpui_cf_string_to_string_and_release(value: CFStringRef) -> Option<String> {
    if value.is_null() {
        return None;
    }
    let converted = gpui_cf_string_to_string(value);
    unsafe {
        CFRelease(value);
    }
    converted
}

#[cfg(target_os = "macos")]
fn gpui_cf_string_to_string(value: CFStringRef) -> Option<String> {
    let direct = unsafe { CFStringGetCStringPtr(value, K_CF_STRING_ENCODING_UTF8) };
    if !direct.is_null() {
        return unsafe { std::ffi::CStr::from_ptr(direct) }
            .to_str()
            .ok()
            .map(str::to_string);
    }

    let length = unsafe { CFStringGetLength(value) };
    let max_size = unsafe { CFStringGetMaximumSizeForEncoding(length, K_CF_STRING_ENCODING_UTF8) };
    if max_size < 0 {
        return None;
    }
    let mut buffer = vec![0i8; (max_size as usize).saturating_add(1)];
    let ok = unsafe {
        CFStringGetCString(
            value,
            buffer.as_mut_ptr(),
            buffer.len() as isize,
            K_CF_STRING_ENCODING_UTF8,
        )
    } != 0;
    if !ok {
        return None;
    }
    unsafe { std::ffi::CStr::from_ptr(buffer.as_ptr()) }
        .to_str()
        .ok()
        .map(str::to_string)
}

#[cfg(target_os = "macos")]
type CFStringRef = *const std::ffi::c_void;
#[cfg(target_os = "macos")]
type CFURLRef = *const std::ffi::c_void;

#[cfg(target_os = "macos")]
const K_CF_STRING_ENCODING_UTF8: u32 = 0x0800_0100;
#[cfg(target_os = "macos")]
const K_CF_URL_POSIX_PATH_STYLE: isize = 0;
#[cfg(target_os = "macos")]
const K_LS_ROLES_EDITOR: u32 = 0x0000_0004;
#[cfg(target_os = "macos")]
const K_LS_ROLES_SHELL: u32 = 0x0000_0008;

