fn append_url_query_params(mut url: String, params: &[(&str, String)]) -> String {
    if params.is_empty() {
        return url;
    }
    url.push(if url.contains('?') { '&' } else { '?' });
    for (index, (key, value)) in params.iter().enumerate() {
        if index > 0 {
            url.push('&');
        }
        url.push_str(&encode_search_query(key));
        url.push('=');
        url.push_str(&encode_search_query(value));
    }
    url
}

fn kanban_workarea_runtime_url_from_project_snapshot(
    snapshot: &GpuiProjectSnapshot,
) -> Option<ProjectWorkareaRealRuntimeUrl> {
    /*
    CDXC:GPUIProjectWorkareaRuntimeCefBundles 2026-06-24-11:03:
    Kanban runtime URL authority is the bundled first-party CEF page plus the explicit live sidebar project identity. The URL is passed directly to CefSurface creation and is not stored in shell state, logged, derived from .git/folders, or backed by WKWebView/WebKit.
    */
    if !snapshot.feature_availability.kanban || snapshot.is_quick_projectless {
        return None;
    }
    let active_project_id = snapshot.active_project_id.as_ref()?.0.clone();
    let project_path = snapshot
        .in_memory_project_path
        .as_ref()?
        .to_string_lossy()
        .to_string();
    let surface_id = snapshot.surface_ids.kanban_board_id.as_ref()?.clone();
    let base_url = gpui_cef_html_entry_url("GHOSTEX_GPUI_KANBAN_URL", "kanban.html").ok()?;
    ProjectWorkareaRealRuntimeUrl::from_authorized_runtime_url(append_url_query_params(
        base_url,
        &[
            ("projectName", snapshot.display_name.clone()),
            ("projectPath", project_path),
            ("projectId", active_project_id),
            ("projectEditorId", surface_id),
            ("beadsDisplayKey", snapshot.display_name.clone()),
        ],
    ))
}

fn manage_workarea_runtime_url_from_project_snapshot(
    snapshot: &GpuiProjectSnapshot,
) -> Option<ProjectWorkareaRealRuntimeUrl> {
    /*
    CDXC:GPUIProjectWorkareaRuntimeCefBundles 2026-06-24-11:03:
    Manage runtime URL authority is the bundled first-party CEF page plus explicit project/manage identity only. The project root stays in the Rust bridge from the in-memory sidebar snapshot, so the Manage page URL remains pathless while CEF replaces the old WKWebView runtime surface.
    */
    if !snapshot.feature_availability.manage || snapshot.is_quick_projectless {
        return None;
    }
    let active_project_id = snapshot.active_project_id.as_ref()?.0.clone();
    let surface_id = snapshot.surface_ids.manage_workspace_id.as_ref()?.clone();
    snapshot.in_memory_project_path.as_ref()?;
    let base_url = gpui_cef_html_entry_url("GHOSTEX_GPUI_MANAGE_URL", "manage.html").ok()?;
    ProjectWorkareaRealRuntimeUrl::from_authorized_runtime_url(append_url_query_params(
        base_url,
        &[
            ("projectId", active_project_id),
            ("projectEditorId", surface_id),
        ],
    ))
}

fn run_manage_files_bridge_request_for_project_snapshot(
    payload: &str,
    snapshot: Option<&GpuiProjectSnapshot>,
) -> serde_json::Value {
    let request = serde_json::from_str::<serde_json::Value>(payload).unwrap_or_default();
    let action = request
        .get("action")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("")
        .to_string();
    let request_id = request
        .get("requestId")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("")
        .to_string();

    let result = manage_files_bridge_result(&request, snapshot);
    match result {
        Ok(response) => response,
        Err(error) => manage_files_bridge_error_response(&action, &request_id, &error),
    }
}

fn manage_files_bridge_result(
    request: &serde_json::Value,
    snapshot: Option<&GpuiProjectSnapshot>,
) -> Result<serde_json::Value, String> {
    let action = manage_request_string(request, "action").unwrap_or_default();
    let request_id = manage_request_string(request, "requestId").unwrap_or_default();
    let snapshot = snapshot.ok_or_else(|| "No active project root is available.".to_string())?;
    let root = manage_project_root(snapshot)?;
    manage_validate_request_identity(request, snapshot)?;

    match action.as_str() {
        "list" => Ok(serde_json::json!({
            "action": action,
            "entries": manage_project_file_entries(&root)?,
            "requestId": request_id,
            "rootName": manage_root_name(&root),
        })),
        "read" => Ok(serde_json::json!({
            "action": action,
            "file": manage_project_file_preview(&root, manage_request_string(request, "path").as_deref())?,
            "requestId": request_id,
            "rootName": manage_root_name(&root),
        })),
        "save" => Ok(serde_json::json!({
            "action": action,
            "file": manage_save_project_file(
                &root,
                manage_request_string(request, "path").as_deref(),
                manage_request_string(request, "content").as_deref(),
            )?,
            "requestId": request_id,
            "rootName": manage_root_name(&root),
        })),
        _ => Err("Unsupported Manage file action.".to_string()),
    }
}

fn manage_request_string(request: &serde_json::Value, key: &str) -> Option<String> {
    request
        .get(key)
        .and_then(serde_json::Value::as_str)
        .map(str::to_string)
}

fn manage_validate_request_identity(
    request: &serde_json::Value,
    snapshot: &GpuiProjectSnapshot,
) -> Result<(), String> {
    let active_project_id = snapshot
        .active_project_id
        .as_ref()
        .map(|id| id.0.as_str())
        .unwrap_or("");
    let manage_surface_id = snapshot
        .surface_ids
        .manage_workspace_id
        .as_deref()
        .unwrap_or("");
    for key in ["projectId", "projectEditorId"] {
        let Some(value) = request
            .get(key)
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
        else {
            continue;
        };
        if value != active_project_id && value != manage_surface_id {
            return Err("Manage request was not sent by this project editor.".to_string());
        }
    }
    Ok(())
}

fn manage_project_root(snapshot: &GpuiProjectSnapshot) -> Result<PathBuf, String> {
    let path = snapshot
        .in_memory_project_path
        .as_ref()
        .ok_or_else(|| "No active project root is available.".to_string())?;
    let metadata =
        fs::metadata(path).map_err(|_| "The active project root is unavailable.".to_string())?;
    if !metadata.is_dir() {
        return Err("The active project root is unavailable.".to_string());
    }
    fs::canonicalize(path).map_err(|_| "The active project root is unavailable.".to_string())
}

fn manage_root_name(root: &Path) -> String {
    root.file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("Project")
        .to_string()
}

fn manage_files_bridge_error_response(
    action: &str,
    request_id: &str,
    error: &str,
) -> serde_json::Value {
    serde_json::json!({
        "action": action,
        "error": error,
        "requestId": request_id,
    })
}

fn manage_project_file_entries(root: &Path) -> Result<Vec<serde_json::Value>, String> {
    let mut entries = Vec::new();
    manage_append_project_file_entries(&mut entries, root, root, "", 0)?;
    Ok(entries)
}

fn manage_append_project_file_entries(
    entries: &mut Vec<serde_json::Value>,
    root: &Path,
    directory: &Path,
    relative_directory_path: &str,
    depth: usize,
) -> Result<(), String> {
    if entries.len() >= MANAGE_FILE_LIST_MAX_ENTRIES || depth > MANAGE_FILE_LIST_MAX_DEPTH {
        return Ok(());
    }
    let mut children = fs::read_dir(directory)
        .map_err(|_| "Could not list project files.".to_string())?
        .filter_map(Result::ok)
        .collect::<Vec<_>>();
    children.sort_by(|left, right| {
        let left_is_dir = left
            .metadata()
            .map(|metadata| metadata.is_dir())
            .unwrap_or(false);
        let right_is_dir = right
            .metadata()
            .map(|metadata| metadata.is_dir())
            .unwrap_or(false);
        right_is_dir
            .cmp(&left_is_dir)
            .then_with(|| left.file_name().cmp(&right.file_name()))
    });

    let mut directories = Vec::new();
    for child in children {
        if entries.len() >= MANAGE_FILE_LIST_MAX_ENTRIES {
            return Ok(());
        }
        let name = child.file_name().to_string_lossy().to_string();
        if name == ".DS_Store" {
            continue;
        }
        let metadata = match child.metadata() {
            Ok(metadata) => metadata,
            Err(_) => continue,
        };
        let is_directory = metadata.is_dir();
        if is_directory && MANAGE_IGNORED_DIRECTORY_NAMES.contains(&name.as_str()) {
            continue;
        }
        let resolved = match fs::canonicalize(child.path()) {
            Ok(resolved) => resolved,
            Err(_) => continue,
        };
        if !path_is_inside_or_equal(&resolved, root) {
            continue;
        }
        let relative_path = if relative_directory_path.is_empty() {
            name.clone()
        } else {
            format!("{relative_directory_path}/{name}")
        };
        entries.push(serde_json::json!({
            "depth": depth,
            "kind": if is_directory { "directory" } else { "file" },
            "modifiedAt": metadata.modified().ok().map(system_time_epoch_millis_string),
            "name": name,
            "path": relative_path,
            "size": if is_directory { None } else { Some(metadata.len()) },
        }));
        if is_directory
            && !child
                .file_type()
                .map(|file_type| file_type.is_symlink())
                .unwrap_or(false)
            && depth < MANAGE_FILE_LIST_MAX_DEPTH
        {
            directories.push((child.path(), relative_path));
        }
    }

    for (directory, relative_path) in directories {
        manage_append_project_file_entries(entries, root, &directory, &relative_path, depth + 1)?;
    }
    Ok(())
}

fn manage_project_file_preview(
    root: &Path,
    path: Option<&str>,
) -> Result<serde_json::Value, String> {
    let (target, relative_path) = manage_existing_url(root, path)?;
    if relative_path.is_empty() {
        return Err("Select a project file to preview.".to_string());
    }
    let metadata = fs::metadata(&target).map_err(|_| "Select a file to preview.".to_string())?;
    if metadata.is_dir() {
        return Err("Select a file to preview.".to_string());
    }
    let size = metadata.len();
    let name = target
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("")
        .to_string();
    if size > MANAGE_FILE_PREVIEW_MAX_BYTES {
        return Ok(manage_unsupported_file_preview(
            "File is too large to preview.",
            &name,
            &relative_path,
            size,
            &metadata,
        ));
    }
    let data = fs::read(&target).map_err(|_| "Could not read project file.".to_string())?;
    if data.contains(&0) {
        return Ok(manage_unsupported_file_preview(
            "Binary files are not previewed.",
            &name,
            &relative_path,
            size,
            &metadata,
        ));
    }
    let content =
        String::from_utf8(data).map_err(|_| "This file is not valid UTF-8 text.".to_string())?;
    Ok(serde_json::json!({
        "content": content,
        "kind": "text",
        "modifiedAt": metadata.modified().ok().map(system_time_epoch_millis_string),
        "name": name,
        "path": relative_path,
        "size": size,
    }))
}

fn manage_unsupported_file_preview(
    error: &str,
    name: &str,
    relative_path: &str,
    size: u64,
    metadata: &fs::Metadata,
) -> serde_json::Value {
    serde_json::json!({
        "error": error,
        "kind": "unsupported",
        "modifiedAt": metadata.modified().ok().map(system_time_epoch_millis_string),
        "name": name,
        "path": relative_path,
        "size": size,
    })
}

fn manage_save_project_file(
    root: &Path,
    path: Option<&str>,
    content: Option<&str>,
) -> Result<serde_json::Value, String> {
    let content = content.ok_or_else(|| "No file content was provided.".to_string())?;
    if content.len() > MANAGE_FILE_SAVE_MAX_BYTES {
        return Err("File is too large to save from Manage.".to_string());
    }
    let (target, relative_path) = manage_writable_url(root, path)?;
    if relative_path.is_empty() {
        return Err("Select a project file to save.".to_string());
    }
    if fs::metadata(&target)
        .map(|metadata| metadata.is_dir())
        .unwrap_or(false)
    {
        return Err("Select a file to save.".to_string());
    }
    let parent = target
        .parent()
        .ok_or_else(|| "Select a file to save.".to_string())?;
    fs::create_dir_all(parent).map_err(|_| "Could not save project file.".to_string())?;
    let temp = parent.join(format!(
        ".ghostex-gpui-manage-save-{}.tmp",
        system_time_epoch_millis_string(std::time::SystemTime::now())
    ));
    fs::write(&temp, content).map_err(|_| "Could not save project file.".to_string())?;
    fs::rename(&temp, &target).map_err(|_| "Could not save project file.".to_string())?;
    manage_project_file_preview(root, Some(&relative_path))
}

fn manage_existing_url(root: &Path, path: Option<&str>) -> Result<(PathBuf, String), String> {
    let relative_path = manage_normalized_relative_path(path)?;
    let target = if relative_path.is_empty() {
        root.to_path_buf()
    } else {
        root.join(PathBuf::from(&relative_path))
    };
    let resolved = fs::canonicalize(&target)
        .map_err(|_| "Manage paths must stay inside the project.".to_string())?;
    if !path_is_inside_or_equal(&resolved, root) {
        return Err("Manage paths must stay inside the project.".to_string());
    }
    Ok((resolved, relative_path))
}

fn manage_writable_url(root: &Path, path: Option<&str>) -> Result<(PathBuf, String), String> {
    let relative_path = manage_normalized_relative_path(path)?;
    let target = root.join(PathBuf::from(&relative_path));
    let parent = target
        .parent()
        .ok_or_else(|| "Select a project file to save.".to_string())?;
    let nearest_existing_parent = nearest_existing_ancestor(parent)
        .ok_or_else(|| "Manage paths must stay inside the project.".to_string())?;
    let resolved_parent = fs::canonicalize(nearest_existing_parent)
        .map_err(|_| "Manage paths must stay inside the project.".to_string())?;
    if !path_is_inside_or_equal(&resolved_parent, root) {
        return Err("Manage paths must stay inside the project.".to_string());
    }
    Ok((target, relative_path))
}

fn manage_normalized_relative_path(path: Option<&str>) -> Result<String, String> {
    let trimmed = path.unwrap_or("").trim();
    if trimmed.is_empty() {
        return Ok(String::new());
    }
    if trimmed.contains('\0') || trimmed.starts_with('/') {
        return Err("Manage paths must be project-relative.".to_string());
    }
    let components = trimmed
        .split('/')
        .filter(|component| !component.is_empty())
        .collect::<Vec<_>>();
    if components
        .iter()
        .any(|component| *component == "." || *component == "..")
    {
        return Err("Manage paths must stay inside the project.".to_string());
    }
    Ok(components.join("/"))
}

fn nearest_existing_ancestor(path: &Path) -> Option<&Path> {
    path.ancestors().find(|candidate| candidate.exists())
}

fn path_is_inside_or_equal(candidate: &Path, root: &Path) -> bool {
    candidate == root || candidate.starts_with(root)
}

fn system_time_epoch_millis_string(time: std::time::SystemTime) -> String {
    time.duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis().to_string())
        .unwrap_or_else(|_| "0".to_string())
}

#[derive(Clone, Debug)]
struct ProjectBoardBridgeRuntimeContext {
    project_id: Option<String>,
    project_path: String,
}

fn project_board_bridge_runtime_context_from_snapshot(
    snapshot: Option<&GpuiProjectSnapshot>,
) -> Option<ProjectBoardBridgeRuntimeContext> {
    /*
    CDXC:GPUIProjectWorkareaCefBridge 2026-06-24-11:03:
    Kanban CEF bridge execution may carry only explicit active-project identity from the live sidebar snapshot. The bridge sends gxserver the current project id/path pair for scoped Beads operations, never derives projects from .git/folders/URLs, never launches bd directly, and never logs or persists the private path.
    */
    let snapshot = snapshot?;
    if snapshot.is_quick_projectless || !snapshot.feature_availability.kanban {
        return None;
    }
    let project_path = snapshot
        .in_memory_project_path
        .as_ref()?
        .to_string_lossy()
        .trim()
        .to_string();
    if project_path.is_empty() {
        return None;
    }
    Some(ProjectBoardBridgeRuntimeContext {
        project_id: snapshot
            .active_project_id
            .as_ref()
            .map(|project_id| project_id.0.clone()),
        project_path,
    })
}

fn project_board_bridge_response_for_request_payload(
    payload: &str,
    snapshot: Option<&GpuiProjectSnapshot>,
) -> serde_json::Value {
    let request = serde_json::from_str::<serde_json::Value>(payload).unwrap_or_default();
    let request_id = manage_request_string(&request, "requestId").unwrap_or_default();
    let action = manage_request_string(&request, "action").unwrap_or_default();
    if action == "getState" || action == "projectEditorFocusOwnerChanged" {
        let project_id = snapshot
            .and_then(|snapshot| snapshot.active_project_id.as_ref())
            .map(|id| id.0.clone());
        return serde_json::json!({
            "ok": true,
            "payload": {
                "agents": [],
                "links": [],
                "projectId": project_id,
                "sessions": [],
            },
            "requestId": request_id,
        });
    }
    serde_json::json!({
        "error": "Project board conversation action is not handled by this GPUI runtime surface.",
        "ok": false,
        "requestId": request_id,
    })
}

fn run_project_beads_bridge_request_for_context(
    payload: &str,
    context: Option<&ProjectBoardBridgeRuntimeContext>,
) -> serde_json::Value {
    let request = serde_json::from_str::<serde_json::Value>(payload).unwrap_or_default();
    let request_id = manage_request_string(&request, "requestId").unwrap_or_default();
    match project_beads_bridge_result_for_request(&request, context) {
        Ok(response) => response,
        Err(error) => project_beads_bridge_error_response(&request_id, &error),
    }
}

fn project_beads_bridge_result_for_request(
    request: &serde_json::Value,
    context: Option<&ProjectBoardBridgeRuntimeContext>,
) -> Result<serde_json::Value, String> {
    let context = context.ok_or_else(|| "No active Kanban project is available.".to_string())?;
    let request_id = manage_request_string(request, "requestId").unwrap_or_default();
    let action = manage_request_string(request, "action").unwrap_or_default();
    if action == "generateTitle" {
        return Err(
            "Prompt-agent title generation is not handled by this GPUI runtime surface."
                .to_string(),
        );
    }

    let gxserver_action = project_beads_gxserver_action_for_board_action(&action)?;
    let mut params = serde_json::Map::new();
    params.insert(
        "action".to_string(),
        serde_json::Value::String(gxserver_action.to_string()),
    );
    params.insert(
        "projectBoardScope".to_string(),
        serde_json::Value::Bool(true),
    );
    params.insert(
        "projectPath".to_string(),
        serde_json::Value::String(context.project_path.clone()),
    );
    let request_project_id = manage_request_string(request, "projectId")
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    if let (Some(request_project_id), Some(active_project_id)) =
        (request_project_id.as_ref(), context.project_id.as_ref())
    {
        if request_project_id != active_project_id {
            return Err("Project board request was not sent by this active project.".to_string());
        }
    }
    if let Some(project_id) = request_project_id.or_else(|| context.project_id.clone()) {
        params.insert(
            "projectId".to_string(),
            serde_json::Value::String(project_id),
        );
    }

    for key in [
        "comment",
        "dependsOnId",
        "depType",
        "description",
        "issueId",
        "label",
        "priority",
        "query",
        "status",
        "title",
        "value",
    ] {
        if let Some(value) = manage_request_string(request, key) {
            params.insert(key.to_string(), serde_json::Value::String(value));
        }
    }
    if let Some(estimate) = request.get("estimate").filter(|value| value.is_number()) {
        params.insert("estimate".to_string(), estimate.clone());
    }
    if let Some(labels) = request.get("labels").and_then(serde_json::Value::as_array) {
        let labels = labels
            .iter()
            .filter_map(serde_json::Value::as_str)
            .map(|label| serde_json::Value::String(label.to_string()))
            .collect::<Vec<_>>();
        params.insert("labels".to_string(), serde_json::Value::Array(labels));
    }

    let (status_code, body) = gxserver_post_typed_operation(
        "/api/runBeadsAction",
        &serde_json::Value::Object(params),
        Duration::from_secs(60),
    )?;
    project_beads_bridge_response_from_gxserver(status_code, &body, &request_id)
}

fn project_beads_gxserver_action_for_board_action(action: &str) -> Result<&'static str, String> {
    match action {
        "addComment" => Ok("comment"),
        "addLabel" => Ok("addLabel"),
        "configGet" => Ok("configGet"),
        "configGetIssuePrefix" => Ok("configGetIssuePrefix"),
        "configSet" => Ok("configSet"),
        "create" => Ok("create"),
        "delete" => Ok("delete"),
        "depAdd" => Ok("depAdd"),
        "depRemove" => Ok("depRemove"),
        "list" => Ok("list"),
        "listIssues" => Ok("board"),
        "listAllLabels" => Ok("listAllLabels"),
        "renamePrefix" => Ok("renamePrefix"),
        "removeLabel" => Ok("removeLabel"),
        "search" => Ok("search"),
        "setLabels" => Ok("setLabels"),
        "show" => Ok("show"),
        "updateDescription" => Ok("updateDescription"),
        "updateEstimate" => Ok("updateEstimate"),
        "updatePriority" => Ok("updatePriority"),
        "updateStatus" => Ok("updateStatus"),
        "updateTitle" => Ok("updateTitle"),
        _ => Err(format!("Unsupported Beads action: {action}")),
    }
}

fn project_beads_bridge_response_from_gxserver(
    status_code: u16,
    body: &str,
    request_id: &str,
) -> Result<serde_json::Value, String> {
    if !(200..300).contains(&status_code) {
        let error = project_beads_gxserver_error_message(body, Some(status_code));
        return Ok(project_beads_bridge_error_response(request_id, &error));
    }
    let response = serde_json::from_str::<serde_json::Value>(body)
        .map_err(|_| "gxserver returned an invalid Beads response.".to_string())?;
    let result = response
        .get("result")
        .and_then(serde_json::Value::as_object)
        .ok_or_else(|| "gxserver did not return a Beads result.".to_string())?;
    let exit_code = result
        .get("exitCode")
        .and_then(serde_json::Value::as_i64)
        .unwrap_or(1);
    Ok(serde_json::json!({
        "error": null,
        "exitCode": exit_code,
        "requestId": request_id,
        "stderr": result.get("stderr").and_then(serde_json::Value::as_str).unwrap_or(""),
        "stdout": result.get("stdout").and_then(serde_json::Value::as_str).unwrap_or(""),
    }))
}

fn project_beads_gxserver_error_message(body: &str, status_code: Option<u16>) -> String {
    if let Ok(value) = serde_json::from_str::<serde_json::Value>(body) {
        if let Some(message) = value
            .get("error")
            .and_then(|error| error.get("message"))
            .and_then(serde_json::Value::as_str)
            .or_else(|| value.get("message").and_then(serde_json::Value::as_str))
        {
            return message.to_string();
        }
    }
    match status_code {
        Some(status_code) => format!("gxserver Beads request failed with HTTP {status_code}."),
        None => "gxserver Beads request failed.".to_string(),
    }
}

fn project_beads_bridge_error_response(request_id: &str, error: &str) -> serde_json::Value {
    serde_json::json!({
        "error": error,
        "exitCode": 127,
        "requestId": request_id,
        "stderr": error,
        "stdout": "",
    })
}

fn parse_gpui_gxserver_rpc_result(body: &str) -> Result<serde_json::Value, String> {
    let value = serde_json::from_str::<serde_json::Value>(body)
        .map_err(|_| "gxserver returned an invalid RPC response.".to_string())?;
    if value.get("ok").and_then(serde_json::Value::as_bool) != Some(true)
        || value.get("product").and_then(serde_json::Value::as_str) != Some(GPUI_GXSERVER_PRODUCT)
        || value
            .get("protocolVersion")
            .and_then(serde_json::Value::as_u64)
            != Some(GPUI_GXSERVER_PROTOCOL_VERSION)
    {
        return Err("gxserver returned an invalid RPC response.".to_string());
    }
    value
        .get("result")
        .and_then(serde_json::Value::as_object)
        .cloned()
        .map(serde_json::Value::Object)
        .ok_or_else(|| "gxserver returned an invalid RPC result.".to_string())
}

fn gxserver_post_typed_operation(
    path: &str,
    params: &serde_json::Value,
    timeout: Duration,
) -> Result<(u16, String), String> {
    /*
    CDXC:GPUIProjectBoardGxserverBridge 2026-06-24-11:03:
    GPUI Kanban CEF parity must use the existing gxserver typed-operation boundary for Beads work. Send the same protocol-version envelope and bearer token as the native bridge to localhost only, with no bd subprocess execution, remote fallback, raw request logging, response logging, URL/title inspection, or persisted board payloads.

    CDXC:GPUISettingsGxserverAgentPolicy 2026-06-24-11:39:
    Settings fan-out also uses this narrow local gxserver RPC helper so agent-policy saves share the existing bearer-token path and response-body parser. Keep callers endpoint-specific and privacy-safe; this helper must not log tokens, URLs, settings payloads, project paths, command text, stdout/stderr, or daemon responses.

    CDXC:GPUISettingsGxserverAgentPolicy 2026-06-24-12:14:
    Startup/open-time agent-policy hydration also uses this helper for `/api/readAgentSettings` so GPUI does not invent a second daemon client or bypass the same token, localhost, timeout, protocol-header, and response-sanitization boundary.

    CDXC:GPUISettingsStatusBridge 2026-06-24-11:40:
    Settings status/action parity reuses this helper for hook status/install/uninstall and Portless state updates. Keep the helper transport-only: callers own endpoint allowlists, result validation, explicit UI error messages, and no persistent logging.
    */
    if !path.starts_with("/api/") {
        return Err("Invalid gxserver API path.".to_string());
    }
    let token = read_gpui_gxserver_auth_token()?;
    let address = format!("{GPUI_GXSERVER_LOCAL_API_HOST}:{GPUI_GXSERVER_LOCAL_API_PORT}");
    let mut stream = TcpStream::connect(&address)
        .map_err(|_| "gxserver is not reachable on 127.0.0.1:58744.".to_string())?;
    stream
        .set_read_timeout(Some(timeout))
        .map_err(|_| "Could not configure gxserver read timeout.".to_string())?;
    stream
        .set_write_timeout(Some(timeout))
        .map_err(|_| "Could not configure gxserver write timeout.".to_string())?;

    let body = serde_json::json!({
        "protocolVersion": GPUI_GXSERVER_PROTOCOL_VERSION,
        "params": params,
    })
    .to_string();
    let request = format!(
        "POST {path} HTTP/1.1\r\nHost: {address}\r\nConnection: close\r\nAuthorization: Bearer {token}\r\nContent-Type: application/json\r\n{GPUI_GXSERVER_PROTOCOL_HEADER}: {GPUI_GXSERVER_PROTOCOL_VERSION}\r\nContent-Length: {}\r\n\r\n{body}",
        body.len()
    );
    stream
        .write_all(request.as_bytes())
        .map_err(|_| "Could not send gxserver request.".to_string())?;

    let mut response = String::new();
    stream
        .read_to_string(&mut response)
        .map_err(|_| "Could not read gxserver response.".to_string())?;
    let (headers, body) = response
        .split_once("\r\n\r\n")
        .ok_or_else(|| "gxserver returned an invalid HTTP response.".to_string())?;
    let status_code = headers
        .lines()
        .next()
        .and_then(|line| line.split_whitespace().nth(1))
        .and_then(|status| status.parse::<u16>().ok())
        .ok_or_else(|| "gxserver returned an invalid HTTP status.".to_string())?;
    Ok((status_code, gxserver_http_response_body(headers, body)?))
}

fn gpui_remote_gxserver_rpc_result(
    target: &GpuiRemoteGxserverRequestTarget,
    path: &str,
    params: &serde_json::Value,
    timeout: Duration,
) -> Result<serde_json::Value, String> {
    let (status_code, body) =
        gpui_remote_gxserver_post_typed_operation(target, path, params, timeout)?;
    if !(200..300).contains(&status_code) {
        return Err("Remote gxserver request failed.".to_string());
    }
    parse_gpui_gxserver_rpc_result(&body)
}

fn gpui_remote_gxserver_presentation_stream_loop(
    target: GpuiRemoteGxserverRequestTarget,
    cancel: Arc<AtomicBool>,
    tx: mpsc::UnboundedSender<GpuiRemoteGxserverPresentationStreamMessage>,
) {
    let mut last_revision: Option<u64> = None;
    for attempt in 0..GPUI_REMOTE_GXSERVER_PRESENTATION_STREAM_ATTEMPTS {
        if cancel.load(Ordering::SeqCst) {
            return;
        }
        let _ = gpui_remote_gxserver_presentation_stream_once(
            &target,
            cancel.as_ref(),
            &tx,
            &mut last_revision,
        );
        if cancel.load(Ordering::SeqCst) {
            return;
        }
        if attempt + 1 < GPUI_REMOTE_GXSERVER_PRESENTATION_STREAM_ATTEMPTS {
            thread::sleep(GPUI_REMOTE_GXSERVER_PRESENTATION_STREAM_RECONNECT_DELAY);
        }
    }
    if !cancel.load(Ordering::SeqCst) {
        let _ = tx.unbounded_send(GpuiRemoteGxserverPresentationStreamMessage::Failed);
    }
}

fn gpui_remote_gxserver_presentation_stream_once(
    target: &GpuiRemoteGxserverRequestTarget,
    cancel: &AtomicBool,
    tx: &mpsc::UnboundedSender<GpuiRemoteGxserverPresentationStreamMessage>,
    last_revision: &mut Option<u64>,
) -> Result<(), String> {
    /*
    CDXC:GPUIRemotePresentationStreaming 2026-06-24-19:54:
    The remote presentation stream uses gxserver's existing WebSocket protocol through the authenticated localhost tunnel. The only renderer-bound products of this helper are presentation snapshots and deltas already consumed by SidebarApp; eventStreamReady, server ids, auth details, raw response bodies, and transport failures stay native-only.
    */
    let mut stream = gpui_remote_gxserver_open_presentation_websocket(target, cancel)?;
    stream
        .set_read_timeout(Some(GPUI_REMOTE_GXSERVER_PRESENTATION_STREAM_READ_TIMEOUT))
        .map_err(|_| "Could not configure remote gxserver event read timeout.".to_string())?;
    let subscribe = gpui_remote_gxserver_presentation_subscribe_message(*last_revision);
    gpui_websocket_write_text_frame(&mut stream, subscribe.as_bytes())?;
    loop {
        if cancel.load(Ordering::SeqCst) {
            return Ok(());
        }
        let Some(frame) = gpui_websocket_read_frame(&mut stream, cancel)? else {
            return Ok(());
        };
        match frame {
            GpuiWebSocketFrame::Text(text) => {
                let Ok(event) = serde_json::from_str::<serde_json::Value>(text.trim()) else {
                    continue;
                };
                let Some((payload, revision)) =
                    gpui_remote_gxserver_presentation_event_payload(&event)
                else {
                    continue;
                };
                if let Some(revision) = revision {
                    *last_revision = Some(revision);
                }
                tx.unbounded_send(GpuiRemoteGxserverPresentationStreamMessage::Event(payload))
                    .map_err(|_| "Remote presentation receiver closed.".to_string())?;
            }
            GpuiWebSocketFrame::Ping(payload) => {
                gpui_websocket_write_control_frame(&mut stream, 0xA, &payload)?;
            }
            GpuiWebSocketFrame::Close => {
                return Err("Remote gxserver event stream closed.".to_string());
            }
            GpuiWebSocketFrame::Pong | GpuiWebSocketFrame::Other => {}
        }
    }
}

fn gpui_remote_gxserver_open_presentation_websocket(
    target: &GpuiRemoteGxserverRequestTarget,
    cancel: &AtomicBool,
) -> Result<TcpStream, String> {
    let address = format!("127.0.0.1:{}", target.local_port);
    let mut stream = TcpStream::connect(&address)
        .map_err(|_| "Remote gxserver event stream is not reachable.".to_string())?;
    stream
        .set_read_timeout(Some(GPUI_REMOTE_GXSERVER_PRESENTATION_STREAM_READ_TIMEOUT))
        .map_err(|_| "Could not configure remote gxserver event read timeout.".to_string())?;
    stream
        .set_write_timeout(Some(
            GPUI_REMOTE_GXSERVER_PRESENTATION_STREAM_HANDSHAKE_TIMEOUT,
        ))
        .map_err(|_| "Could not configure remote gxserver event write timeout.".to_string())?;
    let request = format!(
        "GET /api/events?protocolVersion={GPUI_GXSERVER_PROTOCOL_VERSION}&authToken={} HTTP/1.1\r\nHost: {address}\r\nConnection: Upgrade\r\nUpgrade: websocket\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n\r\n",
        target.token.as_str(),
    );
    stream
        .write_all(request.as_bytes())
        .map_err(|_| "Could not send remote gxserver event handshake.".to_string())?;
    let headers = gpui_read_websocket_handshake_headers(&mut stream, cancel)?;
    let status = headers
        .lines()
        .next()
        .and_then(|line| line.split_whitespace().nth(1))
        .and_then(|status| status.parse::<u16>().ok())
        .ok_or_else(|| "Remote gxserver returned an invalid event stream status.".to_string())?;
    if status != 101 {
        return Err("Remote gxserver did not accept the event stream.".to_string());
    }
    Ok(stream)
}

fn gpui_read_websocket_handshake_headers(
    stream: &mut TcpStream,
    cancel: &AtomicBool,
) -> Result<String, String> {
    let deadline = Instant::now() + GPUI_REMOTE_GXSERVER_PRESENTATION_STREAM_HANDSHAKE_TIMEOUT;
    let mut bytes = Vec::new();
    let mut byte = [0u8; 1];
    while Instant::now() < deadline {
        if cancel.load(Ordering::SeqCst) {
            return Err("Remote gxserver event stream was cancelled.".to_string());
        }
        match stream.read(&mut byte) {
            Ok(0) => return Err("Remote gxserver closed the event handshake.".to_string()),
            Ok(_) => {
                bytes.push(byte[0]);
                if bytes.ends_with(b"\r\n\r\n") {
                    return String::from_utf8(bytes)
                        .map_err(|_| "Remote gxserver event handshake was invalid.".to_string());
                }
                if bytes.len() > 16 * 1024 {
                    return Err("Remote gxserver event handshake was too large.".to_string());
                }
            }
            Err(error)
                if matches!(
                    error.kind(),
                    std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut
                ) =>
            {
                continue;
            }
            Err(_) => return Err("Could not read remote gxserver event handshake.".to_string()),
        }
    }
    Err("Remote gxserver event handshake timed out.".to_string())
}

fn gpui_remote_gxserver_presentation_subscribe_message(last_revision: Option<u64>) -> String {
    let mut payload = serde_json::Map::new();
    payload.insert(
        "clientId".to_string(),
        serde_json::json!(GPUI_SIDEBAR_GXSERVER_CLIENT_ID),
    );
    if let Some(last_revision) = last_revision {
        payload.insert("lastRevision".to_string(), serde_json::json!(last_revision));
    }
    payload.insert(
        "type".to_string(),
        serde_json::json!("subscribePresentation"),
    );
    serde_json::Value::Object(payload).to_string()
}

enum GpuiWebSocketFrame {
    Close,
    Other,
    Ping(Vec<u8>),
    Pong,
    Text(String),
}

fn gpui_websocket_read_frame(
    stream: &mut TcpStream,
    cancel: &AtomicBool,
) -> Result<Option<GpuiWebSocketFrame>, String> {
    let mut header = [0u8; 2];
    if !gpui_websocket_read_exact(stream, &mut header, cancel)? {
        return Ok(None);
    }
    let fin = header[0] & 0x80 != 0;
    let opcode = header[0] & 0x0F;
    if !fin {
        return Err("Remote gxserver sent a fragmented event frame.".to_string());
    }
    let masked = header[1] & 0x80 != 0;
    let mut payload_len = u64::from(header[1] & 0x7F);
    if payload_len == 126 {
        let mut extended = [0u8; 2];
        if !gpui_websocket_read_exact(stream, &mut extended, cancel)? {
            return Ok(None);
        }
        payload_len = u64::from(u16::from_be_bytes(extended));
    } else if payload_len == 127 {
        let mut extended = [0u8; 8];
        if !gpui_websocket_read_exact(stream, &mut extended, cancel)? {
            return Ok(None);
        }
        payload_len = u64::from_be_bytes(extended);
    }
    if payload_len as usize > GPUI_REMOTE_GXSERVER_PRESENTATION_STREAM_FRAME_MAX_BYTES {
        return Err("Remote gxserver event frame was too large.".to_string());
    }
    let mut mask = [0u8; 4];
    if masked && !gpui_websocket_read_exact(stream, &mut mask, cancel)? {
        return Ok(None);
    }
    let mut payload = vec![0u8; payload_len as usize];
    if !payload.is_empty() && !gpui_websocket_read_exact(stream, &mut payload, cancel)? {
        return Ok(None);
    }
    if masked {
        for (index, byte) in payload.iter_mut().enumerate() {
            *byte ^= mask[index % mask.len()];
        }
    }
    match opcode {
        0x1 => String::from_utf8(payload)
            .map(GpuiWebSocketFrame::Text)
            .map(Some)
            .map_err(|_| "Remote gxserver event frame was not UTF-8.".to_string()),
        0x8 => Ok(Some(GpuiWebSocketFrame::Close)),
        0x9 => Ok(Some(GpuiWebSocketFrame::Ping(payload))),
        0xA => Ok(Some(GpuiWebSocketFrame::Pong)),
        _ => Ok(Some(GpuiWebSocketFrame::Other)),
    }
}

fn gpui_websocket_read_exact(
    stream: &mut TcpStream,
    buffer: &mut [u8],
    cancel: &AtomicBool,
) -> Result<bool, String> {
    let mut offset = 0;
    while offset < buffer.len() {
        if cancel.load(Ordering::SeqCst) {
            return Ok(false);
        }
        match stream.read(&mut buffer[offset..]) {
            Ok(0) => return Err("Remote gxserver closed the event stream.".to_string()),
            Ok(read_count) => {
                offset += read_count;
            }
            Err(error)
                if matches!(
                    error.kind(),
                    std::io::ErrorKind::WouldBlock | std::io::ErrorKind::TimedOut
                ) =>
            {
                continue;
            }
            Err(_) => return Err("Could not read remote gxserver event stream.".to_string()),
        }
    }
    Ok(true)
}

fn gpui_websocket_write_text_frame(stream: &mut TcpStream, payload: &[u8]) -> Result<(), String> {
    gpui_websocket_write_frame(stream, 0x1, payload)
}

fn gpui_websocket_write_control_frame(
    stream: &mut TcpStream,
    opcode: u8,
    payload: &[u8],
) -> Result<(), String> {
    if payload.len() > 125 {
        return Err("Remote gxserver control frame was too large.".to_string());
    }
    gpui_websocket_write_frame(stream, opcode, payload)
}

fn gpui_websocket_write_frame(
    stream: &mut TcpStream,
    opcode: u8,
    payload: &[u8],
) -> Result<(), String> {
    let mask = gpui_websocket_mask();
    let mut frame = Vec::with_capacity(payload.len() + 14);
    frame.push(0x80 | (opcode & 0x0F));
    if payload.len() <= 125 {
        frame.push(0x80 | payload.len() as u8);
    } else if payload.len() <= u16::MAX as usize {
        frame.push(0x80 | 126);
        frame.extend_from_slice(&(payload.len() as u16).to_be_bytes());
    } else {
        frame.push(0x80 | 127);
        frame.extend_from_slice(&(payload.len() as u64).to_be_bytes());
    }
    frame.extend_from_slice(&mask);
    for (index, byte) in payload.iter().enumerate() {
        frame.push(*byte ^ mask[index % mask.len()]);
    }
    stream
        .write_all(&frame)
        .map_err(|_| "Could not write remote gxserver event frame.".to_string())
}

fn gpui_websocket_mask() -> [u8; 4] {
    (SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos() as u32)
        .wrapping_add(std::process::id())
        .to_be_bytes()
}

fn gpui_remote_gxserver_presentation_event_payload(
    event: &serde_json::Value,
) -> Option<(serde_json::Value, Option<u64>)> {
    let object = event.as_object()?;
    match object.get("type").and_then(serde_json::Value::as_str)? {
        "presentationSnapshot" => {
            let snapshot = object.get("snapshot")?;
            if !gpui_remote_gxserver_presentation_snapshot_allowed(snapshot) {
                return None;
            }
            let revision = gpui_json_revision(snapshot).or_else(|| gpui_json_revision(event));
            Some((
                serde_json::json!({
                    "snapshot": (*snapshot).clone(),
                    "type": "presentationSnapshot",
                }),
                revision,
            ))
        }
        "presentationDelta" => {
            let delta = object.get("delta")?;
            if !gpui_remote_gxserver_presentation_delta_allowed(delta) {
                return None;
            }
            let revision = gpui_json_revision(event)?;
            Some((
                serde_json::json!({
                    "delta": (*delta).clone(),
                    "revision": revision,
                    "type": "presentationDelta",
                }),
                Some(revision),
            ))
        }
        _ => None,
    }
}

fn gpui_remote_gxserver_presentation_snapshot_allowed(value: &serde_json::Value) -> bool {
    let Some(object) = value.as_object() else {
        return false;
    };
    object
        .get("groups")
        .and_then(serde_json::Value::as_array)
        .is_some()
        && object
            .get("projects")
            .and_then(serde_json::Value::as_array)
            .is_some()
        && object
            .get("sessions")
            .and_then(serde_json::Value::as_array)
            .is_some()
        && gpui_json_revision(value).is_some()
}

fn gpui_remote_gxserver_presentation_delta_allowed(value: &serde_json::Value) -> bool {
    value
        .as_object()
        .and_then(|object| object.get("type"))
        .and_then(serde_json::Value::as_str)
        .is_some()
}

fn gpui_json_revision(value: &serde_json::Value) -> Option<u64> {
    value.get("revision").and_then(|revision| {
        revision.as_u64().or_else(|| {
            revision
                .as_i64()
                .and_then(|value| u64::try_from(value).ok())
        })
    })
}

fn gpui_remote_gxserver_post_typed_operation(
    target: &GpuiRemoteGxserverRequestTarget,
    path: &str,
    params: &serde_json::Value,
    timeout: Duration,
) -> Result<(u16, String), String> {
    /*
    CDXC:GPUIRemoteMachines 2026-06-24-16:48:
    Remote gxserver RPCs use the live SSH tunnel target and in-memory token captured by Rust after Keychain storage. Keep this helper transport-only and response-unlogged: callers own endpoint allowlists and user-facing generic errors, while tokens, URLs, remote paths, params, stdout/stderr, and daemon bodies are never persisted or copied to renderer globals.
    */
    if !path.starts_with("/api/") {
        return Err("Invalid remote gxserver API path.".to_string());
    }
    let address = format!("127.0.0.1:{}", target.local_port);
    let mut stream = TcpStream::connect(&address)
        .map_err(|_| "Remote gxserver tunnel is not reachable.".to_string())?;
    stream
        .set_read_timeout(Some(timeout))
        .map_err(|_| "Could not configure remote gxserver read timeout.".to_string())?;
    stream
        .set_write_timeout(Some(timeout))
        .map_err(|_| "Could not configure remote gxserver write timeout.".to_string())?;

    let body = serde_json::json!({
        "protocolVersion": GPUI_GXSERVER_PROTOCOL_VERSION,
        "params": params,
    })
    .to_string();
    let request = format!(
        "POST {path} HTTP/1.1\r\nHost: {address}\r\nConnection: close\r\nAuthorization: Bearer {}\r\nContent-Type: application/json\r\n{GPUI_GXSERVER_PROTOCOL_HEADER}: {GPUI_GXSERVER_PROTOCOL_VERSION}\r\nContent-Length: {}\r\n\r\n{body}",
        target.token.as_str(),
        body.len()
    );
    stream
        .write_all(request.as_bytes())
        .map_err(|_| "Could not send remote gxserver request.".to_string())?;

    let mut response = String::new();
    stream
        .read_to_string(&mut response)
        .map_err(|_| "Could not read remote gxserver response.".to_string())?;
    let (headers, body) = response
        .split_once("\r\n\r\n")
        .ok_or_else(|| "Remote gxserver returned an invalid HTTP response.".to_string())?;
    let status_code = headers
        .lines()
        .next()
        .and_then(|line| line.split_whitespace().nth(1))
        .and_then(|status| status.parse::<u16>().ok())
        .ok_or_else(|| "Remote gxserver returned an invalid HTTP status.".to_string())?;
    Ok((status_code, gxserver_http_response_body(headers, body)?))
}

fn gxserver_get_typed_operation(path: &str, timeout: Duration) -> Result<(u16, String), String> {
    /*
    CDXC:GPUISettingsStatusBridge 2026-06-24-11:40:
    GPUI Settings reads gxserver health through the same localhost/token/protocol boundary as typed POST operations. Health reads must stay GET-only, short-timeout, response-unlogged, and limited to `/api/` paths so Portless HUD hydration does not introduce a second daemon client.
    */
    if !path.starts_with("/api/") {
        return Err("Invalid gxserver API path.".to_string());
    }
    let token = read_gpui_gxserver_auth_token()?;
    let address = format!("{GPUI_GXSERVER_LOCAL_API_HOST}:{GPUI_GXSERVER_LOCAL_API_PORT}");
    let mut stream = TcpStream::connect(&address)
        .map_err(|_| "gxserver is not reachable on 127.0.0.1:58744.".to_string())?;
    stream
        .set_read_timeout(Some(timeout))
        .map_err(|_| "Could not configure gxserver read timeout.".to_string())?;
    stream
        .set_write_timeout(Some(timeout))
        .map_err(|_| "Could not configure gxserver write timeout.".to_string())?;

    let request = format!(
        "GET {path} HTTP/1.1\r\nHost: {address}\r\nConnection: close\r\nAuthorization: Bearer {token}\r\n{GPUI_GXSERVER_PROTOCOL_HEADER}: {GPUI_GXSERVER_PROTOCOL_VERSION}\r\n\r\n",
    );
    stream
        .write_all(request.as_bytes())
        .map_err(|_| "Could not send gxserver health request.".to_string())?;

    let mut response = String::new();
    stream
        .read_to_string(&mut response)
        .map_err(|_| "Could not read gxserver health response.".to_string())?;
    let (headers, body) = response
        .split_once("\r\n\r\n")
        .ok_or_else(|| "gxserver returned an invalid HTTP response.".to_string())?;
    let status_code = headers
        .lines()
        .next()
        .and_then(|line| line.split_whitespace().nth(1))
        .and_then(|status| status.parse::<u16>().ok())
        .ok_or_else(|| "gxserver returned an invalid HTTP status.".to_string())?;
    Ok((status_code, gxserver_http_response_body(headers, body)?))
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct GpuiGxserverReadAgentSettingsResult {
    is_persisted: bool,
    settings: shared_settings::SharedGxserverAgentSettings,
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum GpuiGxserverAgentSettingsReconciliationAction {
    SeedLocal(shared_settings::SharedGxserverAgentSettings),
    ApplyCanonical(shared_settings::SharedGxserverAgentSettings),
    Noop,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct GpuiGxserverAgentSettingsHydrationResult {
    expected_local_settings: shared_settings::SharedGxserverAgentSettings,
    canonical_settings: shared_settings::SharedGxserverAgentSettings,
}

fn gpui_gxserver_agent_settings_reconciliation_action(
    local_settings: &shared_settings::SharedGxserverAgentSettings,
    daemon_result: &GpuiGxserverReadAgentSettingsResult,
) -> GpuiGxserverAgentSettingsReconciliationAction {
    if !daemon_result.is_persisted {
        return GpuiGxserverAgentSettingsReconciliationAction::SeedLocal(local_settings.clone());
    }
    if daemon_result.settings != *local_settings {
        return GpuiGxserverAgentSettingsReconciliationAction::ApplyCanonical(
            daemon_result.settings.clone(),
        );
    }
    GpuiGxserverAgentSettingsReconciliationAction::Noop
}

fn reconcile_gpui_gxserver_agent_settings_with_daemon()
-> Result<Option<GpuiGxserverAgentSettingsHydrationResult>, String> {
    let daemon_agent_settings = read_gpui_gxserver_agent_settings()?;
    let local_agent_settings =
        shared_settings::shared_sidebar_settings_snapshot().gxserver_agent_settings();
    match gpui_gxserver_agent_settings_reconciliation_action(
        &local_agent_settings,
        &daemon_agent_settings,
    ) {
        GpuiGxserverAgentSettingsReconciliationAction::SeedLocal(settings) => {
            let expected_local_settings = settings.clone();
            update_gpui_gxserver_agent_settings(&settings).map(|canonical_settings| {
                Some(GpuiGxserverAgentSettingsHydrationResult {
                    expected_local_settings,
                    canonical_settings,
                })
            })
        }
        GpuiGxserverAgentSettingsReconciliationAction::ApplyCanonical(settings) => {
            Ok(Some(GpuiGxserverAgentSettingsHydrationResult {
                expected_local_settings: local_agent_settings,
                canonical_settings: settings,
            }))
        }
        GpuiGxserverAgentSettingsReconciliationAction::Noop => Ok(None),
    }
}

fn read_gpui_gxserver_agent_settings() -> Result<GpuiGxserverReadAgentSettingsResult, String> {
    /*
    CDXC:GPUISettingsGxserverAgentPolicy 2026-06-24-12:14:
    Startup/open-time reconciliation reads the daemon's canonical agent-settings row through the same typed localhost RPC envelope as save-time sync. Parse only `isPersisted`, `agentAcceptAllEnabled`, and `defaultPromptAgentId`; failures remain local `Result` values and never create fallback daemon state or leak raw gxserver responses.
    */
    let (status_code, body) = gxserver_post_typed_operation(
        "/api/readAgentSettings",
        &serde_json::json!({}),
        Duration::from_secs(5),
    )?;
    if !(200..300).contains(&status_code) {
        return Err("gxserver agent settings read failed.".to_string());
    }
    parse_gpui_gxserver_read_agent_settings_response(&body)
}

fn update_gpui_gxserver_agent_settings(
    settings: &shared_settings::SharedGxserverAgentSettings,
) -> Result<shared_settings::SharedGxserverAgentSettings, String> {
    /*
    CDXC:GPUISettingsGxserverAgentPolicy 2026-06-24-11:39:
    GPUI Settings saves use the same local gxserver HTTP/token path as other GPUI gxserver calls. The request is the macOS-compatible `/api/updateAgentSettings` RPC envelope with only Accept All and Default Prompt Agent values; failures stay as local `Result` values so callers can silently preserve the render cache without private logs or fake daemon state.
    */
    let mut params = serde_json::Map::new();
    settings.write_to_settings_object(&mut params);
    let (status_code, body) = gxserver_post_typed_operation(
        "/api/updateAgentSettings",
        &serde_json::Value::Object(params),
        Duration::from_secs(5),
    )?;
    if !(200..300).contains(&status_code) {
        return Err("gxserver agent settings request failed.".to_string());
    }
    parse_gpui_gxserver_agent_settings_response(&body)
}

fn parse_gpui_gxserver_agent_settings_response(
    body: &str,
) -> Result<shared_settings::SharedGxserverAgentSettings, String> {
    let result = parse_gpui_gxserver_agent_settings_rpc_result(body)?;
    parse_gpui_gxserver_agent_settings_from_result(&result)
}

fn parse_gpui_gxserver_read_agent_settings_response(
    body: &str,
) -> Result<GpuiGxserverReadAgentSettingsResult, String> {
    let result = parse_gpui_gxserver_agent_settings_rpc_result(body)?;
    let is_persisted = result
        .get("isPersisted")
        .and_then(serde_json::Value::as_bool)
        .ok_or_else(|| "gxserver returned an invalid agent settings response.".to_string())?;
    let settings = parse_gpui_gxserver_agent_settings_from_result(&result)?;
    Ok(GpuiGxserverReadAgentSettingsResult {
        is_persisted,
        settings,
    })
}

fn parse_gpui_gxserver_agent_settings_rpc_result(
    body: &str,
) -> Result<serde_json::Map<String, serde_json::Value>, String> {
    let value = serde_json::from_str::<serde_json::Value>(body)
        .map_err(|_| "gxserver returned an invalid agent settings response.".to_string())?;
    if value.get("ok").and_then(serde_json::Value::as_bool) != Some(true)
        || value.get("product").and_then(serde_json::Value::as_str) != Some(GPUI_GXSERVER_PRODUCT)
        || value
            .get("protocolVersion")
            .and_then(serde_json::Value::as_u64)
            != Some(GPUI_GXSERVER_PROTOCOL_VERSION)
    {
        return Err("gxserver returned an invalid agent settings response.".to_string());
    }
    value
        .get("result")
        .and_then(serde_json::Value::as_object)
        .cloned()
        .ok_or_else(|| "gxserver returned an invalid agent settings response.".to_string())
}

fn parse_gpui_gxserver_agent_settings_from_result(
    result: &serde_json::Map<String, serde_json::Value>,
) -> Result<shared_settings::SharedGxserverAgentSettings, String> {
    let settings = result
        .get("settings")
        .and_then(serde_json::Value::as_object)
        .ok_or_else(|| "gxserver returned an invalid agent settings response.".to_string())?;
    let agent_accept_all_enabled = settings
        .get("agentAcceptAllEnabled")
        .and_then(serde_json::Value::as_bool)
        .ok_or_else(|| "gxserver returned an invalid agent settings response.".to_string())?;
    let default_prompt_agent_id = settings
        .get("defaultPromptAgentId")
        .and_then(serde_json::Value::as_str)
        .ok_or_else(|| "gxserver returned an invalid agent settings response.".to_string())?;
    Ok(shared_settings::SharedGxserverAgentSettings::new(
        agent_accept_all_enabled,
        default_prompt_agent_id,
    ))
}

fn gpui_sidebar_gxserver_bootstrap(
    latest_snapshot: Option<&GpuiProjectSnapshot>,
    focus_state: &GpuiGxserverPresentationFocusState,
) -> Option<cef::SidebarGxserverBootstrap> {
    /*
    CDXC:GPUISidebarGxserverBootstrap 2026-06-24-11:17:
    Build the GPUI sidebar bootstrap only from real local gxserver facts: the selected loopback API port, the existing auth-token helper, protocol version 1, a stable GPUI sidebar client id, and the explicit active project id already stored from the live sidebar snapshot. Do not infer optional session ids from project paths, titles, shell terminal ids, Browser tabs, fixtures, or fallback state.

    CDXC:GPUISidebarGxserverBootstrap 2026-06-24-13:34:
    `initialActiveProjectId` may be supplied only from the validated latest sidebar active-project snapshot. Quick/projectless or pre-snapshot startup bootstraps intentionally omit it, and this helper must not query gxserver project lists, persist ids, or log project identity.

    CDXC:GPUISidebarGxserverFocusState 2026-06-24-21:07:
    `focusedSessionId` and `visibleSessionIds` may be supplied only from the separate GPUI focus state that has already accepted real gxserver presentation ids. Local ids remain raw daemon session ids; remote ids remain machine-scoped sidebar ids so bootstrap replay is collision-safe.
    */
    Some(cef::SidebarGxserverBootstrap {
        base_url: format!("http://{GPUI_GXSERVER_LOCAL_API_HOST}:{GPUI_GXSERVER_LOCAL_API_PORT}"),
        auth_token: read_gpui_gxserver_auth_token().ok()?,
        protocol_version: GPUI_GXSERVER_PROTOCOL_VERSION as i32,
        client_id: GPUI_SIDEBAR_GXSERVER_CLIENT_ID.to_string(),
        initial_active_project_id: gpui_active_project_id_from_snapshot(latest_snapshot)
            .map(str::to_string),
        focused_session_id: focus_state.focused_session_id.clone(),
        visible_session_ids: focus_state.visible_session_ids.clone(),
    })
}

fn read_gpui_gxserver_auth_token() -> Result<String, String> {
    let token_path = home_dir()
        .join(".ghostex")
        .join("gxserver")
        .join("auth")
        .join("token");
    let token = fs::read_to_string(token_path)
        .map_err(|_| "gxserver auth token is unavailable.".to_string())?
        .trim()
        .to_string();
    if token.is_empty() {
        return Err("gxserver auth token is empty.".to_string());
    }
    Ok(token)
}

fn gxserver_http_response_body(headers: &str, body: &str) -> Result<String, String> {
    if !headers.lines().any(|line| {
        let Some((name, value)) = line.split_once(':') else {
            return false;
        };
        name.trim().eq_ignore_ascii_case("transfer-encoding")
            && value
                .split(',')
                .any(|part| part.trim().eq_ignore_ascii_case("chunked"))
    }) {
        return Ok(body.to_string());
    }
    gxserver_decode_chunked_http_body(body)
}

fn gxserver_decode_chunked_http_body(body: &str) -> Result<String, String> {
    let bytes = body.as_bytes();
    let mut index = 0;
    let mut output = Vec::new();
    loop {
        let line_end = gxserver_find_crlf(bytes, index)
            .ok_or_else(|| "Invalid chunked gxserver response.".to_string())?;
        let size_text = std::str::from_utf8(&bytes[index..line_end])
            .unwrap_or("")
            .split(';')
            .next()
            .unwrap_or("")
            .trim();
        let size = usize::from_str_radix(size_text, 16)
            .map_err(|_| "Invalid chunked gxserver response size.".to_string())?;
        index = line_end + 2;
        if size == 0 {
            return String::from_utf8(output)
                .map_err(|_| "Invalid UTF-8 in gxserver response.".to_string());
        }
        let chunk_end = index
            .checked_add(size)
            .filter(|end| *end <= bytes.len())
            .ok_or_else(|| "Invalid chunked gxserver response.".to_string())?;
        output.extend_from_slice(&bytes[index..chunk_end]);
        index = chunk_end;
        if bytes.get(index..index + 2) != Some(b"\r\n") {
            return Err("Invalid chunked gxserver response.".to_string());
        }
        index += 2;
    }
}

fn gxserver_find_crlf(bytes: &[u8], start: usize) -> Option<usize> {
    bytes
        .get(start..)?
        .windows(2)
        .position(|window| window == b"\r\n")
        .map(|offset| start + offset)
}

fn project_board_image_request_needs_clipboard(payload: &str) -> bool {
    serde_json::from_str::<serde_json::Value>(payload)
        .ok()
        .and_then(|request| manage_request_string(&request, "action"))
        .as_deref()
        == Some("pasteImage")
}

fn project_board_image_bridge_response_for_payload(
    payload: &str,
    clipboard_item: Option<ClipboardItem>,
) -> serde_json::Value {
    let request = serde_json::from_str::<serde_json::Value>(payload).unwrap_or_default();
    let request_id = manage_request_string(&request, "requestId").unwrap_or_default();
    let action = manage_request_string(&request, "action").unwrap_or_default();
    let result = match action.as_str() {
        "pasteImage" => {
            project_board_clipboard_image_path(clipboard_item.as_ref()).map(|image_path| {
                let request_id = request_id.clone();
                serde_json::json!({
                    "dataUrl": null,
                    "error": null,
                    "imagePath": image_path,
                    "path": null,
                    "requestId": request_id,
                })
            })
        }
        "loadPreview" => {
            let path = manage_request_string(&request, "path").unwrap_or_default();
            project_board_image_preview_data_url(&path).map(|data_url| {
                let request_id = request_id.clone();
                serde_json::json!({
                    "dataUrl": data_url,
                    "error": null,
                    "imagePath": null,
                    "path": path,
                    "requestId": request_id,
                })
            })
        }
        _ => Err(format!("Unsupported Project Board image action: {action}")),
    };
    result.unwrap_or_else(|error| {
        serde_json::json!({
            "dataUrl": null,
            "error": error,
            "imagePath": null,
            "path": request.get("path").and_then(serde_json::Value::as_str),
            "requestId": request_id,
        })
    })
}

fn project_board_clipboard_image_path(
    clipboard_item: Option<&ClipboardItem>,
) -> Result<String, String> {
    /*
    CDXC:GPUIProjectBoardImagePaste 2026-06-24-11:03:
    Kanban image paste through CEF should preserve the native Project Board contract: return a durable path reference, not base64 Markdown. Existing image file references stay as paths; GPUI image clipboard bytes are saved under ~/.ghostex/i with their declared image format and returned as the same display path convention.
    */
    let item = clipboard_item
        .ok_or_else(|| "Clipboard does not contain an image path or image data.".to_string())?;
    for entry in &item.entries {
        if let ClipboardEntry::ExternalPaths(paths) = entry {
            for path in paths.paths() {
                if is_project_board_image_file_path(path) {
                    return Ok(project_board_display_image_path_for_existing_path(path));
                }
            }
        }
    }
    for entry in &item.entries {
        if let ClipboardEntry::String(clipboard_string) = entry {
            if let Some(path) = project_board_image_path_from_reference(clipboard_string.text()) {
                if is_project_board_image_file_path(&path) {
                    return Ok(project_board_display_image_path_for_existing_path(&path));
                }
            }
        }
    }
    for entry in &item.entries {
        if let ClipboardEntry::Image(image) = entry {
            let bytes = image.bytes();
            if bytes.is_empty() || bytes.len() > PROJECT_BOARD_CLIPBOARD_IMAGE_MAX_BYTES {
                return Err("Clipboard image is too large to save.".to_string());
            }
            let path =
                unique_project_board_image_path(project_board_image_extension(image.format()))?;
            fs::write(&path, bytes).map_err(|_| "Could not save clipboard image.".to_string())?;
            return Ok(project_board_display_image_path_for_saved_path(&path));
        }
    }
    Err("Clipboard does not contain an image path or image data.".to_string())
}

fn project_board_image_preview_data_url(path: &str) -> Result<String, String> {
    let path = project_board_image_path_from_reference(path)
        .ok_or_else(|| "Image preview path does not point to a local image.".to_string())?;
    if !is_project_board_image_file_path(&path) {
        return Err("Image preview path does not point to a local image.".to_string());
    }
    let metadata = fs::metadata(&path)
        .map_err(|_| "Image preview path does not point to a local image.".to_string())?;
    if !metadata.is_file() || metadata.len() as usize > PROJECT_BOARD_IMAGE_PREVIEW_MAX_BYTES {
        return Err("Image preview data could not be decoded.".to_string());
    }
    let extension = path
        .extension()
        .and_then(|extension| extension.to_str())
        .unwrap_or("")
        .to_ascii_lowercase();
    let mime_type = project_board_image_mime_type_for_extension(&extension)
        .ok_or_else(|| "Image preview format is not supported by this CEF runtime.".to_string())?;
    let data =
        fs::read(&path).map_err(|_| "Image preview data could not be decoded.".to_string())?;
    Ok(format!(
        "data:{mime_type};base64,{}",
        project_board_base64_encode(&data)
    ))
}

fn project_board_image_path_from_reference(value: &str) -> Option<PathBuf> {
    let trimmed = value.trim();
    if trimmed.is_empty() || trimmed.contains('\0') {
        return None;
    }
    if trimmed.starts_with("file://") {
        let parsed = gpui::http_client::Url::parse(trimmed).ok()?;
        if parsed.scheme() == "file" {
            return parsed.to_file_path().ok();
        }
        return None;
    }
    if let Some(relative_path) = trimmed.strip_prefix("~/.ghostex/") {
        return Some(ghostex_shared_root_dir().join(relative_path));
    }
    if let Some(relative_path) = trimmed.strip_prefix("~/") {
        return Some(home_dir().join(relative_path));
    }
    if trimmed.starts_with('/') {
        return Some(PathBuf::from(trimmed));
    }
    None
}

fn is_project_board_image_file_path(path: &Path) -> bool {
    let extension = path
        .extension()
        .and_then(|extension| extension.to_str())
        .unwrap_or("")
        .to_ascii_lowercase();
    project_board_image_extension_is_allowed(&extension)
        && fs::metadata(path).map(|m| m.is_file()).unwrap_or(false)
}

fn project_board_image_extension_is_allowed(extension: &str) -> bool {
    matches!(
        extension,
        "avif"
            | "bmp"
            | "gif"
            | "heic"
            | "heif"
            | "ico"
            | "jpg"
            | "jpeg"
            | "png"
            | "svg"
            | "tif"
            | "tiff"
            | "webp"
    )
}

fn project_board_image_mime_type_for_extension(extension: &str) -> Option<&'static str> {
    match extension {
        "avif" => Some("image/avif"),
        "bmp" => Some("image/bmp"),
        "gif" => Some("image/gif"),
        "ico" => Some("image/x-icon"),
        "jpg" | "jpeg" => Some("image/jpeg"),
        "png" => Some("image/png"),
        "svg" => Some("image/svg+xml"),
        "webp" => Some("image/webp"),
        _ => None,
    }
}

fn project_board_image_extension(format: ImageFormat) -> &'static str {
    match format {
        ImageFormat::Png => "png",
        ImageFormat::Jpeg => "jpg",
        ImageFormat::Webp => "webp",
        ImageFormat::Gif => "gif",
        ImageFormat::Svg => "svg",
        ImageFormat::Bmp => "bmp",
        ImageFormat::Tiff => "tif",
        ImageFormat::Ico => "ico",
        ImageFormat::Pnm => "pnm",
    }
}

fn unique_project_board_image_path(extension: &str) -> Result<PathBuf, String> {
    let directory = ghostex_shared_root_dir().join("i");
    fs::create_dir_all(&directory).map_err(|_| "Could not create image directory.".to_string())?;
    let base_name = system_time_epoch_millis_string(std::time::SystemTime::now());
    let first = directory.join(format!("{base_name}.{extension}"));
    if !first.exists() {
        return Ok(first);
    }
    for index in 2..100 {
        let candidate = directory.join(format!("{base_name}-{index}.{extension}"));
        if !candidate.exists() {
            return Ok(candidate);
        }
    }
    Ok(directory.join(format!(
        "{}-{}.{}",
        base_name,
        std::process::id(),
        extension
    )))
}

fn project_board_display_image_path_for_saved_path(path: &Path) -> String {
    let file_name = path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("image.png");
    format!("~/.ghostex/i/{file_name}")
}

fn project_board_display_image_path_for_existing_path(path: &Path) -> String {
    let shared_root = ghostex_shared_root_dir();
    if let Ok(relative_path) = path.strip_prefix(&shared_root) {
        return format!("~/.ghostex/{}", relative_path.to_string_lossy());
    }
    path.to_string_lossy().to_string()
}

fn ghostex_shared_root_dir() -> PathBuf {
    home_dir().join(".ghostex")
}

fn home_dir() -> PathBuf {
    env::var_os("HOME")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("."))
}

fn project_board_base64_encode(bytes: &[u8]) -> String {
    const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut output = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for chunk in bytes.chunks(3) {
        let b0 = chunk[0];
        let b1 = *chunk.get(1).unwrap_or(&0);
        let b2 = *chunk.get(2).unwrap_or(&0);
        output.push(TABLE[(b0 >> 2) as usize] as char);
        output.push(TABLE[(((b0 & 0x03) << 4) | (b1 >> 4)) as usize] as char);
        if chunk.len() > 1 {
            output.push(TABLE[(((b1 & 0x0f) << 2) | (b2 >> 6)) as usize] as char);
        } else {
            output.push('=');
        }
        if chunk.len() > 2 {
            output.push(TABLE[(b2 & 0x3f) as usize] as char);
        } else {
            output.push('=');
        }
    }
    output
}

fn current_sidebar_max_width(window: &Window) -> f32 {
    let max_for_window =
        window.bounds().size.width.as_f32() - SIDEBAR_DIVIDER_WIDTH - WORKSPACE_MIN_WIDTH;
    SIDEBAR_MAX_WIDTH.min(max_for_window).max(SIDEBAR_MIN_WIDTH)
}

fn clamp_sidebar_width(width: f32, max_width: f32) -> f32 {
    width.clamp(SIDEBAR_MIN_WIDTH, max_width)
}

fn read_sidebar_width_setting() -> Option<f32> {
    read_json_number_field(&native_chrome_settings_path(), "sidebarWidth")
}

fn read_sidebar_default_width_setting() -> Option<f32> {
    shared_settings::shared_sidebar_settings_snapshot()
        .sidebar_default_width_px()
        .map(|width| width.clamp(SIDEBAR_MIN_WIDTH, SIDEBAR_MAX_WIDTH))
}

fn persist_sidebar_width_setting(width: f32) {
    /*
    CDXC:GPUIPrivacyAudit 2026-06-23-13:18:
    The GPUI settings write is limited to merging the finite numeric sidebarWidth into the existing native settings JSON object. Do not add project/session/browser/runtime fields here, and do not persist paths, names, command text, URLs, page titles, terminal content, tokens, cookies, secrets, stdout/stderr, or raw CEF/sidebar payloads from GPUI state.
    */
    let path = native_chrome_settings_path();
    let mut settings = read_json_object(&path).unwrap_or_default();
    settings.insert(
        "sidebarWidth".to_string(),
        serde_json::Value::Number(
            serde_json::Number::from_f64(width as f64)
                .expect("clamped sidebar width should be finite"),
        ),
    );

    if let Some(parent) = path.parent() {
        let _ = fs::create_dir_all(parent);
    }
    if let Ok(data) = serde_json::to_vec_pretty(&serde_json::Value::Object(settings)) {
        let _ = fs::write(path, data);
    }
}

fn read_json_number_field(path: &Path, key: &str) -> Option<f32> {
    let object = read_json_object(path)?;
    json_value_to_f32(object.get(key)?)
}

fn read_json_object(path: &Path) -> Option<serde_json::Map<String, serde_json::Value>> {
    let text = fs::read_to_string(path).ok()?;
    match serde_json::from_str::<serde_json::Value>(&text).ok()? {
        serde_json::Value::Object(object) => Some(object),
        _ => None,
    }
}

fn json_value_to_f32(value: &serde_json::Value) -> Option<f32> {
    let number = match value {
        serde_json::Value::Number(number) => number.as_f64()?,
        serde_json::Value::String(text) => text.parse::<f64>().ok()?,
        _ => return None,
    };
    number.is_finite().then_some(number as f32)
}

