    /*
    CDXC:GPUISidebarGit 2026-06-24-18:19:
    The changed-file allowlist must parse Git porcelain rename destinations without using reverse iteration over string-pattern splits, so `bun run gpui` keeps compiling while IDE-open validation still accepts only sanitized project-relative paths.
    */
    #[test]
    fn git_status_porcelain_paths_collect_rename_destination_with_forward_split() {
        let mut files = std::collections::HashSet::new();

        gpui_collect_git_status_porcelain_paths(
            "R  old folder/secret.txt -> src/renamed file.rs\n M src/lib.rs\n",
            &mut files,
        );

        assert!(files.contains("src/renamed file.rs"));
        assert!(files.contains("src/lib.rs"));
        assert!(!files.contains("old folder/secret.txt"));
    }

    /*
    CDXC:GPUIProjectSidebarBridge 2026-06-23-18:29:
    Sidebar workarea bridge routing tests are source-only evidence that the external sidebar-only CEF functions enter only the existing strict stores. They must not add Browser-page bridge exposure, invented Browser ids, URL/path/file/private payload acceptance, logging, persistence, mount creation, file I/O, validation, or placeholder replacement.
    */
    #[test]
    fn sidebar_workarea_bridge_events_route_to_strict_runtime_stores() {
        let mut snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::Project);
        snapshot.active_project_id = Some(GpuiProjectId("private_project_id".to_string()));
        snapshot.surface_ids.source_workarea_id = Some("source_private_surface".to_string());
        snapshot.surface_ids.kanban_board_id =
            Some("project-editor:private_project_id:tasks".to_string());
        snapshot.surface_ids.manage_workspace_id =
            Some("project-editor:private_project_id:manage".to_string());

        let mut source_runtime = SourceWorkareaRuntimeState::new();
        source_runtime.reconcile_active_project(Some(&snapshot));
        let mut browser_runtime = BrowserWorkareaRuntimeState::new();
        browser_runtime.reconcile_explicit_active_project_identity(
            Some(&snapshot),
            Some("browser_private_surface"),
        );
        let mut kanban_runtime =
            ProjectScopedRealSurfaceRuntimeState::new(ProjectScopedRealSurfaceKind::Kanban);
        kanban_runtime.reconcile_active_project(Some(&snapshot));
        let mut manage_runtime =
            ProjectScopedRealSurfaceRuntimeState::new(ProjectScopedRealSurfaceKind::Manage);
        manage_runtime.reconcile_active_project(Some(&snapshot));

        assert!(store_sidebar_workarea_bridge_event(
            &mut source_runtime,
            &mut browser_runtime,
            &mut kanban_runtime,
            &mut manage_runtime,
            cef::SidebarBridgeEvent::SourceWorkareaReadiness(
                source_readiness_contract_payload_text_for_test(
                    "private_project_id",
                    "source_private_surface",
                    "loading",
                ),
            ),
        ));
        assert!(source_runtime.readiness_bridge == SourceWorkareaReadinessBridgeState::Loading);

        assert!(store_sidebar_workarea_bridge_event(
            &mut source_runtime,
            &mut browser_runtime,
            &mut kanban_runtime,
            &mut manage_runtime,
            cef::SidebarBridgeEvent::BrowserWorkareaReadiness(
                browser_workarea_readiness_contract_payload_text_for_test(
                    "private_project_id",
                    "browser_private_surface",
                    "ready",
                ),
            ),
        ));
        assert!(browser_runtime.readiness_bridge == BrowserWorkareaReadinessBridgeState::Ready);

        assert!(store_sidebar_workarea_bridge_event(
            &mut source_runtime,
            &mut browser_runtime,
            &mut kanban_runtime,
            &mut manage_runtime,
            cef::SidebarBridgeEvent::ProjectWorkareaReadiness(
                project_workarea_readiness_contract_payload_text_for_test(
                    "kanban",
                    "private_project_id",
                    "project-editor:private_project_id:tasks",
                    "mounting",
                ),
            ),
        ));
        assert!(
            kanban_runtime.lifecycle_bridge
                == ProjectScopedRealSurfaceLifecycleBridgeState::Mounting
        );
        assert!(
            manage_runtime.lifecycle_bridge
                == ProjectScopedRealSurfaceLifecycleBridgeState::MissingExplicitBridge
        );

        assert!(store_sidebar_workarea_bridge_event(
            &mut source_runtime,
            &mut browser_runtime,
            &mut kanban_runtime,
            &mut manage_runtime,
            cef::SidebarBridgeEvent::ProjectWorkareaReadiness(
                project_workarea_readiness_contract_payload_text_for_test(
                    "manage",
                    "private_project_id",
                    "project-editor:private_project_id:manage",
                    "loadFailed",
                ),
            ),
        ));
        assert!(
            manage_runtime.lifecycle_bridge
                == ProjectScopedRealSurfaceLifecycleBridgeState::LoadFailed
        );

        assert!(store_sidebar_workarea_bridge_event(
            &mut source_runtime,
            &mut browser_runtime,
            &mut kanban_runtime,
            &mut manage_runtime,
            cef::SidebarBridgeEvent::ManageFileWorkareaOperationRequest(
                manage_file_workarea_operation_request_payload_text_for_test(
                    "private_project_id",
                    "project-editor:private_project_id:manage",
                    "readTextFile",
                ),
            ),
        ));
        assert!(
            manage_runtime.manage_file_workarea_operation_decision
                == Some(ManageFileWorkareaBridgeOperationPolicyDecision::Accepted(
                    ManageFileWorkareaBridgeOperationKind::ReadTextFile
                ))
        );
    }

    #[test]
    fn sidebar_workarea_bridge_events_noop_private_or_missing_identity_payloads() {
        let mut snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::Project);
        snapshot.active_project_id = Some(GpuiProjectId("private_project_id".to_string()));
        snapshot.surface_ids.source_workarea_id = Some("source_private_surface".to_string());
        snapshot.surface_ids.kanban_board_id =
            Some("project-editor:private_project_id:tasks".to_string());
        snapshot.surface_ids.manage_workspace_id =
            Some("project-editor:private_project_id:manage".to_string());

        let mut source_runtime = SourceWorkareaRuntimeState::new();
        source_runtime.reconcile_active_project(Some(&snapshot));
        source_runtime.readiness_bridge = SourceWorkareaReadinessBridgeState::Loading;
        let mut browser_runtime = BrowserWorkareaRuntimeState::new();
        browser_runtime.reconcile_explicit_active_project_identity(Some(&snapshot), None);
        let mut kanban_runtime =
            ProjectScopedRealSurfaceRuntimeState::new(ProjectScopedRealSurfaceKind::Kanban);
        kanban_runtime.reconcile_active_project(Some(&snapshot));
        kanban_runtime.lifecycle_bridge = ProjectScopedRealSurfaceLifecycleBridgeState::Mounting;
        let mut manage_runtime =
            ProjectScopedRealSurfaceRuntimeState::new(ProjectScopedRealSurfaceKind::Manage);
        manage_runtime.reconcile_active_project(Some(&snapshot));
        store_manage_file_workarea_operation_request_from_contract_json(
            &mut manage_runtime,
            &manage_file_workarea_operation_request_payload_text_for_test(
                "private_project_id",
                "project-editor:private_project_id:manage",
                "readTextFile",
            ),
        )
        .unwrap();
        let prior_manage_decision = manage_runtime.manage_file_workarea_operation_decision;

        let private_source = serde_json::json!({
            "version": GPUI_SOURCE_READINESS_MESSAGE_VERSION,
            "type": GPUI_SOURCE_READINESS_MESSAGE_TYPE,
            "activeProjectId": "private_project_id",
            "sourceWorkareaId": "source_private_surface",
            "state": "ready",
            "codeServerUrl": "http://127.0.0.1:3000/?token=secret",
        })
        .to_string();
        assert!(!store_sidebar_workarea_bridge_event(
            &mut source_runtime,
            &mut browser_runtime,
            &mut kanban_runtime,
            &mut manage_runtime,
            cef::SidebarBridgeEvent::SourceWorkareaReadiness(private_source),
        ));
        assert!(source_runtime.readiness_bridge == SourceWorkareaReadinessBridgeState::Loading);

        assert!(!store_sidebar_workarea_bridge_event(
            &mut source_runtime,
            &mut browser_runtime,
            &mut kanban_runtime,
            &mut manage_runtime,
            cef::SidebarBridgeEvent::BrowserWorkareaReadiness(
                browser_workarea_readiness_contract_payload_text_for_test(
                    "private_project_id",
                    "browser_private_surface",
                    "ready",
                ),
            ),
        ));
        assert!(browser_runtime.active_identity.is_none());
        assert!(
            browser_runtime.readiness_bridge
                == BrowserWorkareaReadinessBridgeState::MissingExplicitBridge
        );

        let private_project = serde_json::json!({
            "version": GPUI_PROJECT_WORKAREA_READINESS_MESSAGE_VERSION,
            "type": GPUI_PROJECT_WORKAREA_READINESS_MESSAGE_TYPE,
            "surface": "kanban",
            "activeProjectId": "private_project_id",
            "surfaceId": "project-editor:private_project_id:tasks",
            "state": "ready",
            "path": "/Users/madda/private/project",
        })
        .to_string();
        assert!(!store_sidebar_workarea_bridge_event(
            &mut source_runtime,
            &mut browser_runtime,
            &mut kanban_runtime,
            &mut manage_runtime,
            cef::SidebarBridgeEvent::ProjectWorkareaReadiness(private_project),
        ));
        assert!(
            kanban_runtime.lifecycle_bridge
                == ProjectScopedRealSurfaceLifecycleBridgeState::Mounting
        );

        let private_manage = serde_json::json!({
            "version": GPUI_MANAGE_FILE_WORKAREA_OPERATION_REQUEST_MESSAGE_VERSION,
            "type": GPUI_MANAGE_FILE_WORKAREA_OPERATION_REQUEST_MESSAGE_TYPE,
            "activeProjectId": "private_project_id",
            "manageWorkspaceId": "project-editor:private_project_id:manage",
            "operation": "readTextFile",
            "fileContents": "private file body",
        })
        .to_string();
        assert!(!store_sidebar_workarea_bridge_event(
            &mut source_runtime,
            &mut browser_runtime,
            &mut kanban_runtime,
            &mut manage_runtime,
            cef::SidebarBridgeEvent::ManageFileWorkareaOperationRequest(private_manage),
        ));
        assert!(manage_runtime.manage_file_workarea_operation_decision == prior_manage_decision);
    }

