    #[test]
    fn sidebar_snapshot_store_accepts_duplicate_valid_payload_without_replacement() {
        let project_payload = gpui_project_contract_payload_text_for_test(
            Some("project_for_duplicate_test"),
            "Project",
            GpuiProjectContext::Project,
        );
        let mut latest_snapshot = None;

        assert_eq!(
            store_latest_gpui_project_snapshot_from_sidebar_contract_json(
                &mut latest_snapshot,
                &project_payload,
            ),
            Ok(GpuiProjectSnapshotStoreResult::Changed)
        );
        let snapshot_before_duplicate_payload = latest_snapshot.clone();
        let display_name_ptr_before_duplicate_payload = latest_snapshot
            .as_ref()
            .map(|snapshot| snapshot.display_name.as_ptr());
        let active_project_id_ptr_before_duplicate_payload = latest_snapshot
            .as_ref()
            .and_then(|snapshot| snapshot.active_project_id.as_ref())
            .map(|project_id| project_id.0.as_ptr());

        assert_eq!(
            store_latest_gpui_project_snapshot_from_sidebar_contract_json(
                &mut latest_snapshot,
                &project_payload,
            ),
            Ok(GpuiProjectSnapshotStoreResult::Unchanged)
        );

        assert!(latest_snapshot == snapshot_before_duplicate_payload);
        assert_eq!(
            latest_snapshot
                .as_ref()
                .map(|snapshot| snapshot.display_name.as_ptr()),
            display_name_ptr_before_duplicate_payload
        );
        assert_eq!(
            latest_snapshot
                .as_ref()
                .and_then(|snapshot| snapshot.active_project_id.as_ref())
                .map(|project_id| project_id.0.as_ptr()),
            active_project_id_ptr_before_duplicate_payload
        );
    }

    #[test]
    fn malformed_sidebar_payload_preserves_titlebar_project_label() {
        let project_payload = serde_json::json!({
            "version": 1,
            "type": GPUI_SIDEBAR_PROJECT_CONTEXT_MESSAGE_TYPE,
            "activeProject": {
                "activeProjectId": "project_for_titlebar_test",
                "displayName": "Stored Snapshot Label",
                "projectPath": null,
                "isQuickProjectless": false,
                "workareaAvailability": {
                    "source": true,
                    "browser": true,
                    "kanban": true,
                    "manage": true,
                },
                "surfaceIds": {},
            },
        })
        .to_string();
        let mut latest_snapshot = None;
        assert_eq!(
            titlebar_project_label_from_latest_sidebar_snapshot(latest_snapshot.as_ref()),
            TITLEBAR_PROJECT_LABEL_FALLBACK
        );

        assert_eq!(
            store_latest_gpui_project_snapshot_from_sidebar_contract_json(
                &mut latest_snapshot,
                &project_payload,
            ),
            Ok(GpuiProjectSnapshotStoreResult::Changed)
        );
        let label_before_malformed_payload =
            titlebar_project_label_from_latest_sidebar_snapshot(latest_snapshot.as_ref());
        assert_eq!(label_before_malformed_payload, "Stored Snapshot Label");

        let snapshot_before_malformed_payload = latest_snapshot.clone();
        assert!(matches!(
            store_latest_gpui_project_snapshot_from_sidebar_contract_json(
                &mut latest_snapshot,
                "{",
            ),
            Err(GpuiProjectSnapshotContractError::MalformedJson)
        ));

        assert!(latest_snapshot == snapshot_before_malformed_payload);
        assert_eq!(
            titlebar_project_label_from_latest_sidebar_snapshot(latest_snapshot.as_ref()),
            label_before_malformed_payload
        );
    }

    fn shell_layout_state_object_for_focus_test(
        active_mode: TitlebarMode,
        shell_focus: ShellFocusTarget,
        previous_non_command_focus: Option<ShellFocusTarget>,
        agents_workspace: &WorkspaceModel,
        command_pane: &CommandPaneModel,
        project_editor_shell: &ProjectEditorShellModel,
    ) -> serde_json::Map<String, serde_json::Value> {
        let browser_profiles = BrowserProfileModel::shell_default();
        let browser_tabs = browser_model_with_single_loaded_tab();
        json_object(serde_json::json!({
            "version": GPUI_WORKSPACE_SHELL_STATE_VERSION,
            "activeMode": active_mode.element_slug(),
            "shellFocus": shell_focus_to_shell_state_json(shell_focus),
            "previousNonCommandFocus": previous_non_command_focus.map(shell_focus_to_shell_state_json),
            "agentsWorkspace": workspace_model_to_shell_state_json(agents_workspace),
            "commandPane": command_pane_model_to_shell_state_json(command_pane),
            "browserProfiles": browser_profile_model_to_shell_state_json(&browser_profiles),
            "browserTabs": browser_tab_model_to_shell_state_json(&browser_tabs),
            "projectEditorShell": project_editor_shell_to_shell_state_json(project_editor_shell),
        }))
    }

    fn browser_model_with_single_loaded_tab() -> BrowserTabModel {
        let tab_id = BrowserTabId(10);
        let pane_id = BrowserPaneId(1);
        let url = "https://example.com/start".to_string();

        BrowserTabModel {
            tabs: vec![BrowserTab {
                id: tab_id,
                profile_id: BrowserProfileId::default_profile(),
                title: browser_tab_title_for_url(&url),
                runtime_page_title: None,
                runtime_favicon_url: None,
                runtime_favicon_image: None,
                runtime_favicon_fetch: None,
                url: url.clone(),
                state: BrowserTabState::Loaded,
                navigation_history: BrowserNavigationHistory::loaded(&url),
            }],
            root: BrowserNode::Leaf(BrowserLeaf {
                pane_id,
                tab_group: BrowserTabGroup {
                    tabs: vec![BrowserPaneTab { tab_id }],
                    active_tab: tab_id,
                },
            }),
            focused_pane: pane_id,
            active_tab: tab_id,
            next_pane_id: 2,
            next_split_id: 1,
            next_tab_id: 11,
        }
    }

    #[test]
    fn gpui_shell_state_migrates_original_unversioned_layout_shape() {
        let agents_workspace = WorkspaceModel::first_slice_default();
        let mut command_pane = CommandPaneModel::shell_default(1_000.0);
        command_pane.mode = CommandPaneMode::Pinned;
        let mut project_editor_shell = ProjectEditorShellModel::shell_default();
        project_editor_shell.left_companion_visible = false;
        project_editor_shell.left_companion_width_ratio = 0.42;

        let legacy_state = json_object(serde_json::json!({
            "activeMode": "browser",
            "shellFocus": shell_focus_to_shell_state_json(ShellFocusTarget::BrowserSurface),
            "agentsWorkspace": workspace_model_to_shell_state_json(&agents_workspace),
            "commandPane": command_pane_model_to_shell_state_json(&command_pane),
            "browserTabs": {
                "activeTabId": 7,
                "focusedPaneId": 1,
                "nextPaneId": 2,
                "nextSplitId": 1,
                "nextTabId": 8,
                "tabs": [
                    {
                        "id": 7,
                        "state": "loaded",
                        "url": "https://secret_user:secret_pass@example.com/docs?token=secret#frag",
                        "runtimePageTitle": "Private Runtime Page Title",
                        "profileId": 99
                    }
                ]
            },
            "projectEditorShell": project_editor_shell_to_shell_state_json(&project_editor_shell),
            "projectPath": "/Users/madda/private-project",
            "commandText": "deploy --token private_secret",
            "stdout": "private command output"
        }));

        let restored = GpuiShellLayoutState::from_json_object(
            &legacy_state,
            1_000.0,
            ProjectScopedWorkareaAvailability::new(GpuiProjectContext::Project, true),
        )
        .expect("original unversioned shell-state shape should migrate");

        assert!(restored.active_mode == TitlebarMode::Browser);
        assert_shell_focus(restored.shell_focus, ShellFocusTarget::BrowserSurface);
        assert_eq!(
            restored.browser_profiles.profile_ids().collect::<Vec<_>>(),
            vec![BrowserProfileId::default_profile()]
        );
        assert_eq!(
            restored.browser_profiles.active_profile_id(),
            BrowserProfileId::default_profile()
        );
        assert_eq!(restored.browser_tabs.focused_pane.0, 1);
        assert_eq!(restored.browser_tabs.active_tab.0, 7);
        assert_eq!(
            browser_leaf_tab_ids(&restored.browser_tabs, BrowserPaneId(1)),
            vec![7]
        );

        let restored_tab = restored.browser_tabs.tab(BrowserTabId(7)).unwrap();
        assert!(restored_tab.state == BrowserTabState::Loaded);
        assert_eq!(restored_tab.profile_id, BrowserProfileId::default_profile());
        assert_eq!(restored_tab.url, "https://example.com/docs");
        assert_eq!(restored_tab.title, "example.com");
        assert!(restored_tab.runtime_page_title.is_none());

        let migrated_shell_text = shell_state_text(&serde_json::json!({
            "version": GPUI_WORKSPACE_SHELL_STATE_VERSION,
            "activeMode": restored.active_mode.element_slug(),
            "shellFocus": shell_focus_to_shell_state_json(restored.shell_focus),
            "previousNonCommandFocus": restored
                .previous_non_command_focus
                .map(shell_focus_to_shell_state_json),
            "agentsWorkspace": workspace_model_to_shell_state_json(&restored.agents_workspace),
            "commandPane": command_pane_model_to_shell_state_json(&restored.command_pane),
            "browserProfiles": browser_profile_model_to_shell_state_json(&restored.browser_profiles),
            "browserTabs": browser_tab_model_to_shell_state_json(&restored.browser_tabs),
            "projectEditorShell": project_editor_shell_to_shell_state_json(&restored.project_editor_shell),
        }));
        assert_text_omits(
            &migrated_shell_text,
            &[
                "secret_user",
                "secret_pass",
                "token",
                "frag",
                "Private Runtime Page Title",
                "profileId",
                "Profile 99",
                "/Users/madda/private-project",
                "private_secret",
                "private command output",
                "?",
                "#",
                "@",
            ],
        );
    }

    #[test]
    fn gpui_shell_state_rejects_unknown_versions_and_unknown_unversioned_shapes() {
        let agents_workspace = WorkspaceModel::first_slice_default();
        let command_pane = CommandPaneModel::shell_default(1_000.0);
        let project_editor_shell = ProjectEditorShellModel::shell_default();
        let availability =
            ProjectScopedWorkareaAvailability::new(GpuiProjectContext::Project, true);

        let mut future_state = shell_layout_state_object_for_focus_test(
            TitlebarMode::Agents,
            ShellFocusTarget::AgentsPane(agents_workspace.focused_pane),
            None,
            &agents_workspace,
            &command_pane,
            &project_editor_shell,
        );
        future_state.insert(
            "version".to_string(),
            serde_json::json!(GPUI_WORKSPACE_SHELL_STATE_VERSION + 1),
        );
        assert!(
            GpuiShellLayoutState::from_json_object(&future_state, 1_000.0, availability).is_none()
        );

        future_state.insert("version".to_string(), serde_json::json!("not-a-version"));
        assert!(
            GpuiShellLayoutState::from_json_object(&future_state, 1_000.0, availability).is_none()
        );

        let unknown_unversioned_state = json_object(serde_json::json!({
            "activeMode": "browser",
            "browserTabs": {},
            "projectPath": "/Users/madda/private-project"
        }));
        assert!(
            GpuiShellLayoutState::from_json_object(
                &unknown_unversioned_state,
                1_000.0,
                availability
            )
            .is_none()
        );

        let invalid_known_legacy_state = json_object(serde_json::json!({
            "activeMode": "browser",
            "shellFocus": shell_focus_to_shell_state_json(ShellFocusTarget::BrowserSurface),
            "agentsWorkspace": {},
            "commandPane": command_pane_model_to_shell_state_json(&command_pane),
            "browserTabs": browser_tab_model_to_shell_state_json(&browser_model_with_single_loaded_tab()),
            "projectEditorShell": project_editor_shell_to_shell_state_json(&project_editor_shell),
        }));
        assert!(
            GpuiShellLayoutState::from_json_object(
                &invalid_known_legacy_state,
                1_000.0,
                availability
            )
            .is_none()
        );
    }

    #[test]
    fn gpui_shell_state_current_version_requires_current_writer_schema() {
        let agents_workspace = WorkspaceModel::first_slice_default();
        let command_pane = CommandPaneModel::shell_default(1_000.0);
        let project_editor_shell = ProjectEditorShellModel::shell_default();
        let availability =
            ProjectScopedWorkareaAvailability::new(GpuiProjectContext::Project, true);
        let valid_state = shell_layout_state_object_for_focus_test(
            TitlebarMode::Agents,
            ShellFocusTarget::AgentsPane(agents_workspace.focused_pane),
            None,
            &agents_workspace,
            &command_pane,
            &project_editor_shell,
        );

        assert!(
            GpuiShellLayoutState::from_json_object(&valid_state, 1_000.0, availability).is_some()
        );

        for missing_key in [
            "activeMode",
            "shellFocus",
            "previousNonCommandFocus",
            "agentsWorkspace",
            "commandPane",
            "browserProfiles",
            "browserTabs",
            "projectEditorShell",
        ] {
            let mut state = valid_state.clone();
            state.remove(missing_key);
            assert!(
                GpuiShellLayoutState::from_json_object(&state, 1_000.0, availability).is_none(),
                "current shell state restored without required key {missing_key}"
            );
        }

        for (key, value) in [
            ("version", serde_json::json!("1")),
            ("activeMode", serde_json::json!("unknown-mode")),
            ("shellFocus", serde_json::json!({ "type": "unknown-focus" })),
            (
                "previousNonCommandFocus",
                serde_json::json!("browser-surface"),
            ),
            ("agentsWorkspace", serde_json::json!({})),
            ("commandPane", serde_json::json!({})),
            ("browserProfiles", serde_json::json!({})),
            ("browserTabs", serde_json::json!({})),
            ("projectEditorShell", serde_json::json!("bad")),
        ] {
            let mut state = valid_state.clone();
            state.insert(key.to_string(), value);
            assert!(
                GpuiShellLayoutState::from_json_object(&state, 1_000.0, availability).is_none(),
                "current shell state restored with malformed required field {key}"
            );
        }

        let mut stale_focus_state = valid_state.clone();
        stale_focus_state.insert(
            "shellFocus".to_string(),
            shell_focus_to_shell_state_json(ShellFocusTarget::AgentsPane(WorkspacePaneId(99))),
        );
        let restored_stale_focus =
            GpuiShellLayoutState::from_json_object(&stale_focus_state, 1_000.0, availability)
                .expect("typed stale focus should still restore through normal validation");
        assert_shell_focus(
            restored_stale_focus.shell_focus,
            ShellFocusTarget::AgentsPane(agents_workspace.focused_pane),
        );

        let mut private_extra_state = valid_state.clone();
        private_extra_state.insert(
            "projectPath".to_string(),
            serde_json::json!("/Users/madda/private-current-schema"),
        );
        private_extra_state.insert(
            "rawUrl".to_string(),
            serde_json::json!("https://secret_user:secret_pass@example.com/path?token=secret#frag"),
        );
        private_extra_state.insert(
            "terminalContent".to_string(),
            serde_json::json!("private terminal content"),
        );
        let restored_with_private_extras =
            GpuiShellLayoutState::from_json_object(&private_extra_state, 1_000.0, availability)
                .expect("current shell state should ignore unknown private extras");
        let restored_text = shell_state_text(&serde_json::json!({
            "version": GPUI_WORKSPACE_SHELL_STATE_VERSION,
            "activeMode": restored_with_private_extras.active_mode.element_slug(),
            "shellFocus": shell_focus_to_shell_state_json(restored_with_private_extras.shell_focus),
            "previousNonCommandFocus": restored_with_private_extras
                .previous_non_command_focus
                .map(shell_focus_to_shell_state_json),
            "agentsWorkspace": workspace_model_to_shell_state_json(&restored_with_private_extras.agents_workspace),
            "commandPane": command_pane_model_to_shell_state_json(&restored_with_private_extras.command_pane),
            "browserProfiles": browser_profile_model_to_shell_state_json(&restored_with_private_extras.browser_profiles),
            "browserTabs": browser_tab_model_to_shell_state_json(&restored_with_private_extras.browser_tabs),
            "projectEditorShell": project_editor_shell_to_shell_state_json(&restored_with_private_extras.project_editor_shell),
        }));
        assert_text_omits(
            &restored_text,
            &[
                "/Users/madda/private-current-schema",
                "secret_user",
                "secret_pass",
                "token",
                "frag",
                "private terminal content",
                "rawUrl",
                "terminalContent",
                "?",
                "#",
                "@",
            ],
        );
    }

    #[test]
    fn gpui_phase10_persistent_writer_boundary_omits_private_runtime_data() {
        let agents_workspace = WorkspaceModel::first_slice_default();
        let command_pane = CommandPaneModel::shell_default(1_000.0);
        let project_editor_shell = ProjectEditorShellModel::shell_default();
        let browser_profiles = BrowserProfileModel {
            profiles: vec![
                BrowserProfileId::default_profile(),
                BrowserProfileId(BROWSER_PROFILE_FIRST_GENERATED_ID),
            ],
            active_profile: BrowserProfileId(BROWSER_PROFILE_FIRST_GENERATED_ID),
            next_profile_id: BROWSER_PROFILE_FIRST_GENERATED_ID + 1,
        };
        let private_url =
            "https://private_user:private_pass@example.com/docs?token=private_token#private_frag";
        let tab_id = BrowserTabId(44);
        let pane_id = BrowserPaneId(9);
        let browser_tabs = BrowserTabModel {
            tabs: vec![BrowserTab {
                id: tab_id,
                profile_id: BrowserProfileId(BROWSER_PROFILE_FIRST_GENERATED_ID),
                title: "Private Runtime Fallback Title".to_string(),
                runtime_page_title: Some("Private Runtime Page Title".to_string()),
                runtime_favicon_url: Some(
                    "https://icons.example/favicon.ico?token=secret_favicon_token".to_string(),
                ),
                runtime_favicon_image: None,
                runtime_favicon_fetch: Some(BrowserFaviconFetchSource {
                    url: "https://icons.example/fetch.ico?token=secret_fetch_token".to_string(),
                }),
                url: private_url.to_string(),
                state: BrowserTabState::Loaded,
                navigation_history: BrowserNavigationHistory {
                    entries: vec![
                        "https://history_user:history_pass@example.com/start?token=history_token#history_frag".to_string(),
                        private_url.to_string(),
                    ],
                    current_index: Some(1),
                },
            }],
            root: BrowserNode::Leaf(BrowserLeaf {
                pane_id,
                tab_group: BrowserTabGroup {
                    tabs: vec![BrowserPaneTab { tab_id }],
                    active_tab: tab_id,
                },
            }),
            focused_pane: pane_id,
            active_tab: tab_id,
            next_pane_id: 10,
            next_split_id: 1,
            next_tab_id: 45,
        };

        let persisted = shell_state_text(&serde_json::json!({
            "version": GPUI_WORKSPACE_SHELL_STATE_VERSION,
            "activeMode": TitlebarMode::Browser.element_slug(),
            "shellFocus": shell_focus_to_shell_state_json(ShellFocusTarget::BrowserSurface),
            "previousNonCommandFocus": serde_json::Value::Null,
            "agentsWorkspace": workspace_model_to_shell_state_json(&agents_workspace),
            "commandPane": command_pane_model_to_shell_state_json(&command_pane),
            "browserProfiles": browser_profile_model_to_shell_state_json(&browser_profiles),
            "browserTabs": browser_tab_model_to_shell_state_json(&browser_tabs),
            "projectEditorShell": project_editor_shell_to_shell_state_json(&project_editor_shell),
        }));

        assert!(persisted.contains("\"activeMode\":\"browser\""));
        assert!(persisted.contains("\"browserProfiles\""));
        assert!(persisted.contains("https://example.com/docs"));
        assert_text_omits(
            &persisted,
            &[
                "private_user",
                "private_pass",
                "private_token",
                "private_frag",
                "history_user",
                "history_pass",
                "history_token",
                "history_frag",
                "Private Runtime Fallback Title",
                "Private Runtime Page Title",
                "secret_favicon_token",
                "secret_fetch_token",
                "profileId",
                "cache_path",
                "persist_session_cookies",
                "/Users/madda/private-project",
                "deploy --token secret",
                "private stdout",
                "private terminal content",
                "support-bundle",
                "?",
                "#",
                "@",
            ],
        );
    }

    fn browser_leaf_tab_ids(model: &BrowserTabModel, pane_id: BrowserPaneId) -> Vec<u64> {
        model
            .find_leaf(pane_id)
            .map(|leaf| leaf.tab_group.tabs.iter().map(|tab| tab.tab_id.0).collect())
            .unwrap_or_default()
    }

    fn browser_tab_metadata_snapshot(
        model: &BrowserTabModel,
    ) -> Vec<(
        u64,
        String,
        String,
        &'static str,
        Option<String>,
        Option<String>,
        Option<String>,
        Vec<String>,
        Option<usize>,
    )> {
        model
            .tabs
            .iter()
            .map(|tab| {
                (
                    tab.id.0,
                    tab.title.clone(),
                    tab.url.clone(),
                    tab.state.element_slug(),
                    tab.runtime_page_title.clone(),
                    tab.runtime_favicon_url.clone(),
                    tab.runtime_favicon_fetch
                        .as_ref()
                        .map(|source| source.url.clone()),
                    tab.navigation_history.entries.clone(),
                    tab.navigation_history.current_index,
                )
            })
            .collect()
    }

