    fn sync_startup_coordinator_and_launch_plans(
        coordinator: &mut AgentsTerminalStartupCoordinator,
        agents_workspace_visible: bool,
        model: &WorkspaceModel,
        runtime_registry: &mut AgentsTerminalRuntimeSessionRegistry,
        geometries: &HashMap<AgentsTerminalStartupBodySlotId, AgentsTerminalStartupBodyGeometry>,
    ) {
        coordinator.sync_visible_mounting_startup_candidates(
            agents_workspace_visible,
            model,
            runtime_registry,
            geometries,
        );
        coordinator.sync_startup_launch_plans(
            agents_workspace_visible,
            model,
            runtime_registry,
            geometries,
        );
    }

    fn startup_launch_plan_state_for(
        model: &WorkspaceModel,
        bounds: Bounds<Pixels>,
        scale_factor: f32,
    ) -> (
        AgentsTerminalRuntimeSessionRegistry,
        AgentsTerminalStartupCoordinator,
        HashMap<AgentsTerminalStartupBodySlotId, AgentsTerminalStartupBodyGeometry>,
        AgentsTerminalRuntimeSessionId,
        AgentsTerminalStartupBodySlotId,
    ) {
        let mut runtime_registry = AgentsTerminalRuntimeSessionRegistry::new();
        runtime_registry.reconcile_with_workspace(model);
        let startup_body_slot_id = model.rendered_terminal_startup_body_slots()[0];
        let runtime_session_id = runtime_registry
            .runtime_session_id_for_shell_session(startup_body_slot_id.session_id)
            .unwrap();
        let geometries = startup_body_geometry_map(startup_body_slot_id, bounds, scale_factor);
        let mut coordinator = AgentsTerminalStartupCoordinator::new();
        sync_startup_coordinator_and_launch_plans(
            &mut coordinator,
            true,
            model,
            &mut runtime_registry,
            &geometries,
        );
        assert_eq!(coordinator.startup_launch_plan_count(), 1);

        (
            runtime_registry,
            coordinator,
            geometries,
            runtime_session_id,
            startup_body_slot_id,
        )
    }

    fn startup_completion_intent_for(
        coordinator: &AgentsTerminalStartupCoordinator,
        runtime_session_id: AgentsTerminalRuntimeSessionId,
    ) -> AgentsTerminalStartupCompletionIntent {
        coordinator
            .startup_completion_intent_for_runtime_session(runtime_session_id)
            .expect("startup completion intent should be available for current Mounting session")
    }

