    fn workspace_session_state_slugs(model: &WorkspaceModel) -> Vec<(u64, &'static str)> {
        model
            .terminal_sessions
            .iter()
            .map(|session| (session.id.0, session.presentation_state.element_slug()))
            .collect()
    }

    fn workspace_session_status_slugs(
        model: &WorkspaceModel,
    ) -> Vec<(u64, &'static str, bool, &'static str)> {
        model
            .terminal_sessions
            .iter()
            .map(|session| {
                (
                    session.id.0,
                    session.activity.element_slug(),
                    session.delayed_send_active,
                    session.tab_status().element_slug(),
                )
            })
            .collect()
    }

    fn command_session_status_slugs(
        model: &CommandPaneModel,
    ) -> Vec<(u64, &'static str, bool, &'static str)> {
        model
            .terminal_sessions
            .iter()
            .map(|session| {
                (
                    session.id.0,
                    session.activity.element_slug(),
                    session.delayed_send_active,
                    session.tab_status().element_slug(),
                )
            })
            .collect()
    }

    fn project_editor_lifecycle_slugs(
        model: &ProjectEditorShellModel,
    ) -> Vec<(&'static str, &'static str, u64)> {
        project_editor_modes()
            .into_iter()
            .map(|mode| {
                let lifecycle = model.lifecycle(mode).unwrap();
                (
                    mode.element_slug(),
                    lifecycle.state.element_slug(),
                    lifecycle.recency,
                )
            })
            .collect()
    }

    fn awake_project_editor_mode_slugs(model: &ProjectEditorShellModel) -> Vec<&'static str> {
        project_editor_modes()
            .into_iter()
            .filter(|mode| model.is_mode_awake(*mode))
            .map(TitlebarMode::element_slug)
            .collect()
    }

    fn command_group_active_session_id(
        model: &CommandPaneModel,
        group_id: CommandPaneGroupId,
    ) -> Option<u64> {
        model
            .find_leaf(group_id)
            .and_then(|leaf| leaf.tab_group.active_session_id())
            .map(|session_id| session_id.0)
    }

    fn single_tab_workspace_model(
        pane_id: WorkspacePaneId,
        session_id: TerminalSessionId,
        presentation_state: TerminalSessionPresentationState,
    ) -> WorkspaceModel {
        WorkspaceModel {
            terminal_sessions: vec![TerminalSession::placeholder(
                session_id,
                "Solo".to_string(),
                presentation_state,
            )],
            root: WorkspaceNode::Leaf(WorkspaceLeaf {
                pane_id,
                tab_group: WorkspaceTabGroup {
                    tabs: vec![WorkspaceTab { session_id }],
                    active_tab: session_id,
                },
            }),
            focused_pane: pane_id,
            focus_mode_pane: None,
            next_pane_id: pane_id.0 + 1,
            next_split_id: 1,
            next_session_id: session_id.0 + 1,
        }
    }

    fn single_tab_command_model(
        group_id: CommandPaneGroupId,
        session_id: CommandSessionId,
        title: &str,
    ) -> CommandPaneModel {
        CommandPaneModel {
            terminal_sessions: vec![CommandTerminalSession::placeholder(
                session_id,
                title.to_string(),
            )],
            root: CommandPaneNode::Leaf(CommandPaneLeaf {
                group_id,
                tab_group: CommandPaneTabGroup {
                    tabs: vec![CommandPaneTab { session_id }],
                    active_session: session_id,
                },
            }),
            focused_group: group_id,
            mode: CommandPaneMode::Pinned,
            last_expanded_mode: CommandPaneMode::Pinned,
            height_ratio: command_pane_default_height_ratio(1_000.0),
            resize_drag: None,
            next_group_id: group_id.0 + 1,
            next_split_id: 1,
            next_session_id: session_id.0 + 1,
        }
    }

    #[test]
    fn browser_tab_chrome_status_distinguishes_surface_restored_and_address_only_tabs() {
        assert!(
            BrowserTabChromeStatus::from_state(BrowserTabState::Loaded, true)
                == BrowserTabChromeStatus::LoadedSurface
        );
        assert!(
            BrowserTabChromeStatus::from_state(BrowserTabState::Loaded, false)
                == BrowserTabChromeStatus::RestoredPlaceholder
        );
        assert!(
            BrowserTabChromeStatus::from_state(BrowserTabState::AddressOnly, true)
                == BrowserTabChromeStatus::AddressOnly
        );
        assert!(
            BrowserTabChromeStatus::from_state(BrowserTabState::AddressOnly, false)
                == BrowserTabChromeStatus::AddressOnly
        );
    }

    #[test]
    fn browser_tab_chrome_status_colors_and_favicon_gate_match_placeholder_parity() {
        assert_eq!(
            browser_tab_chrome_status_color(BrowserTabChromeStatus::LoadedSurface),
            0x58b7ff
        );
        assert_eq!(
            browser_tab_chrome_status_color(BrowserTabChromeStatus::RestoredPlaceholder),
            0x41d7b5
        );
        assert_eq!(
            browser_tab_chrome_status_color(BrowserTabChromeStatus::AddressOnly),
            0xffffff
        );
        assert_ne!(
            browser_tab_chrome_status_color(BrowserTabChromeStatus::LoadedSurface),
            browser_tab_chrome_status_color(BrowserTabChromeStatus::RestoredPlaceholder)
        );
        assert_ne!(
            browser_tab_chrome_status_color(BrowserTabChromeStatus::RestoredPlaceholder),
            browser_tab_chrome_status_color(BrowserTabChromeStatus::AddressOnly)
        );

        assert!(BrowserTabChromeStatus::LoadedSurface.allows_runtime_favicon());
        assert!(!BrowserTabChromeStatus::RestoredPlaceholder.allows_runtime_favicon());
        assert!(!BrowserTabChromeStatus::AddressOnly.allows_runtime_favicon());
    }

    #[test]
    fn browser_runtime_lifecycle_policy_hides_and_holds_for_sleep_modes_and_drags() {
        /*
        CDXC:GPUIBrowserLifecycle 2026-06-23-14:30:
        Source-only lifecycle coverage must keep HiddenHold as a visibility-only result. Sleep, non-Browser mode, Browser tab drag, and command-tab drag may hide existing CEF child views, but they must not imply CEF teardown, suspend, recreation, restored-surface materialization, import, popup transfer, or shell-state mutation.
        */
        let model = browser_model_with_single_loaded_tab();
        let loaded_surface_tab_id = BrowserTabId(10);

        for lifecycle in [
            BrowserRuntimeLifecycleInput {
                active_mode: TitlebarMode::Agents,
                browser_awake: true,
                browser_tab_drag_active: false,
                command_tab_drag_active: false,
            },
            BrowserRuntimeLifecycleInput {
                active_mode: TitlebarMode::Browser,
                browser_awake: false,
                browser_tab_drag_active: false,
                command_tab_drag_active: false,
            },
            BrowserRuntimeLifecycleInput {
                active_mode: TitlebarMode::Browser,
                browser_awake: true,
                browser_tab_drag_active: true,
                command_tab_drag_active: false,
            },
            BrowserRuntimeLifecycleInput {
                active_mode: TitlebarMode::Browser,
                browser_awake: true,
                browser_tab_drag_active: false,
                command_tab_drag_active: true,
            },
        ] {
            assert!(!lifecycle.allows_cef_child_views());
            let policy = BrowserRuntimeSurfacePolicy::for_tab(
                lifecycle,
                Some(BrowserTabState::Loaded),
                true,
                true,
            );
            assert!(policy == BrowserRuntimeSurfacePolicy::HiddenHold);
            assert!(!policy.shows_cef_child_view());
            assert!(
                browser_runtime_visible_surface_tab_ids(lifecycle, &model, [loaded_surface_tab_id])
                    .is_empty()
            );
        }
    }

