    #[test]
    fn browser_runtime_restored_placeholder_requires_active_awake_browser_leaf() {
        /*
        CDXC:GPUIBrowserLifecycle 2026-06-23-14:30:
        RestoredPlaceholder is render-only proof that an active rendered loaded Browser tab has no CEF entity while Browser is active, awake, and not dragging. It must not show, create, suspend, or tear down a CEF child view, and inactive loaded tabs or address-only tabs must stay HiddenHold instead of becoming visible or materialized.
        */
        let visible_lifecycle = BrowserRuntimeLifecycleInput {
            active_mode: TitlebarMode::Browser,
            browser_awake: true,
            browser_tab_drag_active: false,
            command_tab_drag_active: false,
        };
        let restored_policy = BrowserRuntimeSurfacePolicy::for_tab(
            visible_lifecycle,
            Some(BrowserTabState::Loaded),
            true,
            false,
        );
        assert!(restored_policy == BrowserRuntimeSurfacePolicy::RestoredPlaceholder);
        assert!(!restored_policy.shows_cef_child_view());

        for lifecycle in [
            BrowserRuntimeLifecycleInput {
                active_mode: TitlebarMode::Agents,
                browser_awake: true,
                browser_tab_drag_active: false,
                command_tab_drag_active: false,
            },
            BrowserRuntimeLifecycleInput {
                active_mode: TitlebarMode::Browser,
                browser_awake: false,
                browser_tab_drag_active: false,
                command_tab_drag_active: false,
            },
            BrowserRuntimeLifecycleInput {
                active_mode: TitlebarMode::Browser,
                browser_awake: true,
                browser_tab_drag_active: true,
                command_tab_drag_active: false,
            },
            BrowserRuntimeLifecycleInput {
                active_mode: TitlebarMode::Browser,
                browser_awake: true,
                browser_tab_drag_active: false,
                command_tab_drag_active: true,
            },
        ] {
            let policy = BrowserRuntimeSurfacePolicy::for_tab(
                lifecycle,
                Some(BrowserTabState::Loaded),
                true,
                false,
            );
            assert!(policy == BrowserRuntimeSurfacePolicy::HiddenHold);
            assert!(!policy.shows_cef_child_view());
        }

        for policy in [
            BrowserRuntimeSurfacePolicy::for_tab(
                visible_lifecycle,
                Some(BrowserTabState::Loaded),
                false,
                false,
            ),
            BrowserRuntimeSurfacePolicy::for_tab(
                visible_lifecycle,
                Some(BrowserTabState::AddressOnly),
                true,
                false,
            ),
            BrowserRuntimeSurfacePolicy::for_tab(
                visible_lifecycle,
                Some(BrowserTabState::AddressOnly),
                true,
                true,
            ),
            BrowserRuntimeSurfacePolicy::for_tab(visible_lifecycle, None, true, true),
        ] {
            assert!(policy == BrowserRuntimeSurfacePolicy::HiddenHold);
            assert!(!policy.shows_cef_child_view());
        }
    }

    #[test]
    fn browser_runtime_source_policies_block_imports_and_blank_popup_transfer() {
        /*
        CDXC:GPUIBrowserRuntimePolicy 2026-06-23-12:48:
        Source-only Phase 8 policy coverage must prove Browser import and blank-popup transfer remain explicit no-op contracts at helper boundaries: no import may proceed without a compatible importer requirement, and no blank popup may synthesize page-content transfer or address-only tab fallback behavior.

        CDXC:GPUIBrowserRuntimePolicy 2026-06-23-14:13:
        The unsupported import notification is intentionally fixed category text. It must not expose profile paths, browser-store filenames, raw URLs, tokens, importer diagnostics, or failure details while the real import flow remains a deferred product decision.

        CDXC:GPUIBrowserRuntimePolicy 2026-06-23-14:30:
        Empty popup targets and unsupported import are separate blockers. Empty targets must no-op without address-only fallback, notification, import, CEF surface creation, shell-state writes, or page-content copy; non-empty targets are trimmed only at the target boundary.
        */
        assert!(matches!(
            BrowserPopupTargetPolicy::for_target_url(""),
            BrowserPopupTargetPolicy::IgnoreWithoutTransfer
        ));
        assert!(matches!(
            BrowserPopupTargetPolicy::for_target_url(" \n\t "),
            BrowserPopupTargetPolicy::IgnoreWithoutTransfer
        ));
        assert!(browser_loaded_popup_target_url("").is_none());
        assert!(browser_loaded_popup_target_url(" \n\t ").is_none());
        assert!(matches!(
            BrowserPopupTargetPolicy::for_target_url("  https://popup.example/path  "),
            BrowserPopupTargetPolicy::OpenLoadedTab
        ));
        assert_eq!(
            browser_loaded_popup_target_url("  https://popup.example/path  ").as_deref(),
            Some("https://popup.example/path")
        );

        assert!(
            BrowserDataImportPolicy::for_profile_action_available(false)
                .notification()
                .is_none()
        );
        assert_eq!(
            BrowserDataImportPolicy::for_profile_action_available(true).notification(),
            Some(BROWSER_IMPORT_UNSUPPORTED_NOTIFICATION)
        );
        let import_notification = BrowserDataImportPolicy::for_profile_action_available(true)
            .notification()
            .expect("available import policy should show the fixed unsupported notice");
        assert_text_omits(
            import_notification,
            &[
                "/Users/",
                "Library/Application Support",
                "Chrome",
                "Firefox",
                "Safari",
                "cookies.sqlite",
                "Login Data",
                "History.db",
                "profile-",
                "http://",
                "https://",
                "token=",
                "password",
                "secret",
                "path=",
                "failed",
                "error",
            ],
        );
    }

