    #[test]
    fn browser_runtime_lifecycle_restored_loaded_tabs_do_not_materialize_from_visibility() {
        let mut model = browser_model_with_single_loaded_tab();
        let restored_url = "https://restored.example/start";
        model.tabs.push(BrowserTab {
            id: BrowserTabId(20),
            profile_id: BrowserProfileId::default_profile(),
            title: browser_tab_title_for_url(restored_url),
            runtime_page_title: None,
            runtime_favicon_url: None,
            runtime_favicon_image: None,
            runtime_favicon_fetch: None,
            url: restored_url.to_string(),
            state: BrowserTabState::Loaded,
            navigation_history: BrowserNavigationHistory::loaded(restored_url),
        });
        let original_root = std::mem::replace(&mut model.root, browser_dummy_node());
        model.root = BrowserNode::Split(BrowserSplit {
            id: BrowserSplitId(1),
            axis: WorkspaceSplitAxis::Horizontal,
            ratio: 0.5,
            first: Box::new(original_root),
            second: Box::new(BrowserNode::Leaf(BrowserLeaf {
                pane_id: BrowserPaneId(2),
                tab_group: BrowserTabGroup {
                    tabs: vec![BrowserPaneTab {
                        tab_id: BrowserTabId(20),
                    }],
                    active_tab: BrowserTabId(20),
                },
            })),
        });
        model.next_pane_id = 3;
        model.next_split_id = 2;
        model.next_tab_id = 21;

        let lifecycle = BrowserRuntimeLifecycleInput {
            active_mode: TitlebarMode::Browser,
            browser_awake: true,
            browser_tab_drag_active: false,
            command_tab_drag_active: false,
        };
        let visible =
            browser_runtime_visible_surface_tab_ids(lifecycle, &model, [BrowserTabId(10)]);

        assert!(visible.len() == 1);
        assert!(visible.contains(&BrowserTabId(10)));
        assert!(!visible.contains(&BrowserTabId(20)));
        let restored_policy = BrowserRuntimeSurfacePolicy::for_tab(
            lifecycle,
            Some(BrowserTabState::Loaded),
            model
                .rendered_active_loaded_tab_ids()
                .contains(&BrowserTabId(20)),
            false,
        );
        assert!(restored_policy == BrowserRuntimeSurfacePolicy::RestoredPlaceholder);
        assert!(!restored_policy.shows_cef_child_view());
    }

    #[test]
    fn browser_tab_chrome_signature_ignores_focused_pane_changes() {
        let left_url = "https://left.example/start";
        let right_url = "https://right.example/start";
        let mut model = BrowserTabModel {
            tabs: vec![
                BrowserTab {
                    id: BrowserTabId(10),
                    profile_id: BrowserProfileId(9),
                    title: browser_tab_title_for_url(left_url),
                    runtime_page_title: None,
                    runtime_favicon_url: None,
                    runtime_favicon_image: None,
                    runtime_favicon_fetch: None,
                    url: left_url.to_string(),
                    state: BrowserTabState::Loaded,
                    navigation_history: BrowserNavigationHistory::loaded(left_url),
                },
                BrowserTab {
                    id: BrowserTabId(20),
                    profile_id: BrowserProfileId(10),
                    title: browser_tab_title_for_url(right_url),
                    runtime_page_title: None,
                    runtime_favicon_url: None,
                    runtime_favicon_image: None,
                    runtime_favicon_fetch: None,
                    url: right_url.to_string(),
                    state: BrowserTabState::Loaded,
                    navigation_history: BrowserNavigationHistory::loaded(right_url),
                },
            ],
            root: BrowserNode::Split(BrowserSplit {
                id: BrowserSplitId(1),
                axis: WorkspaceSplitAxis::Horizontal,
                ratio: 0.5,
                first: Box::new(BrowserNode::Leaf(BrowserLeaf {
                    pane_id: BrowserPaneId(1),
                    tab_group: BrowserTabGroup {
                        tabs: vec![BrowserPaneTab {
                            tab_id: BrowserTabId(10),
                        }],
                        active_tab: BrowserTabId(10),
                    },
                })),
                second: Box::new(BrowserNode::Leaf(BrowserLeaf {
                    pane_id: BrowserPaneId(2),
                    tab_group: BrowserTabGroup {
                        tabs: vec![BrowserPaneTab {
                            tab_id: BrowserTabId(20),
                        }],
                        active_tab: BrowserTabId(20),
                    },
                })),
            }),
            focused_pane: BrowserPaneId(1),
            active_tab: BrowserTabId(10),
            next_pane_id: 3,
            next_split_id: 2,
            next_tab_id: 21,
        };

        let left_signature_before = model
            .tab_chrome_signature(BrowserPaneId(1), BrowserTabId(10), true)
            .unwrap();
        let right_signature_before = model
            .tab_chrome_signature(BrowserPaneId(2), BrowserTabId(20), false)
            .unwrap();

        model.focused_pane = BrowserPaneId(2);

        let left_signature_after = model
            .tab_chrome_signature(BrowserPaneId(1), BrowserTabId(10), true)
            .unwrap();
        let right_signature_after = model
            .tab_chrome_signature(BrowserPaneId(2), BrowserTabId(20), false)
            .unwrap();

        assert!(left_signature_after == left_signature_before);
        assert!(right_signature_after == right_signature_before);
        assert!(left_signature_after.active_in_tab_group);
        assert!(right_signature_after.active_in_tab_group);
        assert!(left_signature_after.chrome_status == BrowserTabChromeStatus::LoadedSurface);
        assert!(right_signature_after.chrome_status == BrowserTabChromeStatus::RestoredPlaceholder);

        model.focused_pane = BrowserPaneId(1);

        assert!(
            model
                .tab_chrome_signature(BrowserPaneId(1), BrowserTabId(10), true)
                .unwrap()
                == left_signature_before
        );
        assert!(
            model
                .tab_chrome_signature(BrowserPaneId(2), BrowserTabId(20), false)
                .unwrap()
                == right_signature_before
        );
    }

    #[test]
    fn browser_tab_chrome_signature_keeps_active_membership_distinct() {
        let active_url = "https://active.example/start";
        let inactive_url = "https://inactive.example/start";
        let model = BrowserTabModel {
            tabs: vec![
                BrowserTab {
                    id: BrowserTabId(30),
                    profile_id: BrowserProfileId::default_profile(),
                    title: browser_tab_title_for_url(active_url),
                    runtime_page_title: None,
                    runtime_favicon_url: None,
                    runtime_favicon_image: None,
                    runtime_favicon_fetch: None,
                    url: active_url.to_string(),
                    state: BrowserTabState::Loaded,
                    navigation_history: BrowserNavigationHistory::loaded(active_url),
                },
                BrowserTab {
                    id: BrowserTabId(31),
                    profile_id: BrowserProfileId::default_profile(),
                    title: browser_tab_title_for_url(inactive_url),
                    runtime_page_title: None,
                    runtime_favicon_url: None,
                    runtime_favicon_image: None,
                    runtime_favicon_fetch: None,
                    url: inactive_url.to_string(),
                    state: BrowserTabState::Loaded,
                    navigation_history: BrowserNavigationHistory::loaded(inactive_url),
                },
            ],
            root: BrowserNode::Leaf(BrowserLeaf {
                pane_id: BrowserPaneId(3),
                tab_group: BrowserTabGroup {
                    tabs: vec![
                        BrowserPaneTab {
                            tab_id: BrowserTabId(30),
                        },
                        BrowserPaneTab {
                            tab_id: BrowserTabId(31),
                        },
                    ],
                    active_tab: BrowserTabId(30),
                },
            }),
            focused_pane: BrowserPaneId(3),
            active_tab: BrowserTabId(30),
            next_pane_id: 4,
            next_split_id: 1,
            next_tab_id: 32,
        };

        let active = model
            .tab_chrome_signature(BrowserPaneId(3), BrowserTabId(30), true)
            .unwrap();
        let inactive = model
            .tab_chrome_signature(BrowserPaneId(3), BrowserTabId(31), true)
            .unwrap();

        assert!(active != inactive);
        assert!(active.active_in_tab_group);
        assert!(!inactive.active_in_tab_group);
        assert!(active.state == inactive.state);
        assert!(active.chrome_status == inactive.chrome_status);
    }

    #[test]
    fn browser_tab_chrome_signature_preserves_surface_status_inputs() {
        let tab_id = BrowserTabId(40);
        let tab_group = BrowserTabGroup {
            tabs: vec![BrowserPaneTab { tab_id }],
            active_tab: tab_id,
        };

        let loaded_surface =
            browser_tab_chrome_signature(&tab_group, tab_id, BrowserTabState::Loaded, true);
        let restored_placeholder =
            browser_tab_chrome_signature(&tab_group, tab_id, BrowserTabState::Loaded, false);
        let address_only =
            browser_tab_chrome_signature(&tab_group, tab_id, BrowserTabState::AddressOnly, false);

        assert!(loaded_surface.state == BrowserTabState::Loaded);
        assert!(loaded_surface.chrome_status == BrowserTabChromeStatus::LoadedSurface);
        assert!(restored_placeholder.state == BrowserTabState::Loaded);
        assert!(restored_placeholder.chrome_status == BrowserTabChromeStatus::RestoredPlaceholder);
        assert!(address_only.state == BrowserTabState::AddressOnly);
        assert!(address_only.chrome_status == BrowserTabChromeStatus::AddressOnly);
        assert!(loaded_surface.active_in_tab_group);
        assert!(restored_placeholder.active_in_tab_group);
        assert!(address_only.active_in_tab_group);
        assert!(loaded_surface != restored_placeholder);
        assert!(loaded_surface != address_only);
        assert!(restored_placeholder != address_only);
    }

    #[test]
    fn agent_terminal_tab_status_prioritizes_delayed_send_and_maps_sidebar_colors() {
        assert!(
            agent_terminal_tab_status(AgentTerminalActivity::Idle, false)
                == AgentTerminalTabStatus::Idle
        );
        assert!(
            agent_terminal_tab_status(AgentTerminalActivity::Working, false)
                == AgentTerminalTabStatus::Working
        );
        assert!(
            agent_terminal_tab_status(AgentTerminalActivity::Attention, false)
                == AgentTerminalTabStatus::Attention
        );
        assert!(
            agent_terminal_tab_status(AgentTerminalActivity::Idle, true)
                == AgentTerminalTabStatus::DelayedSend
        );
        assert!(
            agent_terminal_tab_status(AgentTerminalActivity::Working, true)
                == AgentTerminalTabStatus::DelayedSend
        );
        assert!(
            agent_terminal_tab_status(AgentTerminalActivity::Attention, true)
                == AgentTerminalTabStatus::DelayedSend
        );

        assert_eq!(
            agent_terminal_tab_status_color(AgentTerminalTabStatus::Idle),
            0x67d886
        );
        assert_eq!(
            agent_terminal_tab_status_color(AgentTerminalTabStatus::Working),
            0xff9f43
        );
        assert_eq!(
            agent_terminal_tab_status_color(AgentTerminalTabStatus::Attention),
            0x95d7f6
        );
        assert_eq!(
            agent_terminal_tab_status_color(AgentTerminalTabStatus::DelayedSend),
            0xffcf5a
        );
        assert!(agent_terminal_tab_status_inactive_opacity(AgentTerminalTabStatus::Idle) < 1.0);
        assert!(agent_terminal_tab_status_inactive_opacity(AgentTerminalTabStatus::Working) < 1.0);
        assert!(
            agent_terminal_tab_status_inactive_opacity(AgentTerminalTabStatus::Attention) < 1.0
        );
        assert!(
            agent_terminal_tab_status_inactive_opacity(AgentTerminalTabStatus::DelayedSend) < 1.0
        );
    }

