    #[test]
    fn agents_is_not_a_project_editor_lifecycle_mode() {
        let mut model = ProjectEditorShellModel::shell_default();
        let before = project_editor_lifecycle_slugs(&model);
        let next_recency_before = model.next_lifecycle_recency;

        assert!(model.lifecycle(TitlebarMode::Agents).is_none());
        assert!(!model.is_mode_awake(TitlebarMode::Agents));
        assert_eq!(
            project_editor_modes()
                .into_iter()
                .map(TitlebarMode::element_slug)
                .collect::<Vec<_>>(),
            vec!["source", "browser", "kanban", "manage"]
        );

        assert!(!model.mark_mode_awake(TitlebarMode::Agents));
        assert_eq!(project_editor_lifecycle_slugs(&model), before);
        assert_eq!(model.next_lifecycle_recency, next_recency_before);

        assert!(!model.mark_mode_sleeping(TitlebarMode::Agents));
        assert_eq!(project_editor_lifecycle_slugs(&model), before);
        assert_eq!(model.next_lifecycle_recency, next_recency_before);
    }

    #[test]
    fn selected_sleeping_project_editor_modes_remain_focusable_without_waking() {
        let agents_workspace = WorkspaceModel::first_slice_default();
        let command_pane = CommandPaneModel::shell_default(1_000.0);

        for active_mode in project_editor_modes() {
            let mut model = ProjectEditorShellModel::shell_default();
            for (index, mode) in project_editor_modes().into_iter().enumerate() {
                let lifecycle = model.lifecycle_mut(mode).unwrap();
                lifecycle.state = ProjectEditorLifecycleState::Sleeping;
                lifecycle.recency = 10 + index as u64;
            }
            model.next_lifecycle_recency = 40;
            let before = project_editor_lifecycle_slugs(&model);

            let requested_focus = match active_mode {
                TitlebarMode::Browser => ShellFocusTarget::BrowserSurface,
                TitlebarMode::Source | TitlebarMode::Kanban | TitlebarMode::Manage => {
                    ShellFocusTarget::ProjectEditorSurface(active_mode)
                }
                TitlebarMode::Agents => unreachable!("Agents is not a project-editor mode"),
            };
            let focus = valid_shell_focus_or_default(
                requested_focus,
                active_mode,
                &agents_workspace,
                &command_pane,
                &model,
            );

            assert!(focus == requested_focus);
            assert!(!model.is_mode_awake(active_mode));
            assert_eq!(project_editor_lifecycle_slugs(&model), before);
            assert_eq!(model.next_lifecycle_recency, 40);
        }
    }

    #[test]
    fn browser_pane_menu_split_creates_address_only_focused_pane() {
        let mut model = browser_model_with_single_loaded_tab();
        let original_pane_id = BrowserPaneId(1);
        let original_tab_id = BrowserTabId(10);

        assert!(model.split_new_address_placeholder_tab_to_pane(
            original_pane_id,
            WorkspaceDropZone::Right,
            BrowserProfileId(3),
        ));

        let pane_order = model
            .rendered_leaf_order()
            .into_iter()
            .map(|pane_id| pane_id.0)
            .collect::<Vec<_>>();
        assert_eq!(pane_order, vec![1, 2]);
        assert_eq!(browser_leaf_tab_ids(&model, original_pane_id), vec![10]);

        let original_leaf = model.find_leaf(original_pane_id).unwrap();
        assert_eq!(original_leaf.tab_group.active_tab.0, original_tab_id.0);
        assert_eq!(model.focused_pane.0, 2);
        assert_eq!(model.active_tab.0, 11);
        assert_eq!(browser_leaf_tab_ids(&model, model.focused_pane), vec![11]);

        let new_leaf = model.find_leaf(model.focused_pane).unwrap();
        assert_eq!(new_leaf.tab_group.active_tab.0, 11);
        let new_tab = model.tab(model.active_tab).unwrap();
        assert!(new_tab.state == BrowserTabState::AddressOnly);
        assert_eq!(new_tab.profile_id, BrowserProfileId(3));
        assert!(new_tab.url.is_empty());
        assert!(new_tab.navigation_history.entries.is_empty());
        assert!(new_tab.navigation_history.current_index.is_none());

        let loaded_tab_ids = model.rendered_active_loaded_tab_ids();
        assert!(loaded_tab_ids.contains(&original_tab_id));
        assert!(!loaded_tab_ids.contains(&model.active_tab));

        let placeholder = BrowserBodyPlaceholder::from_tab(new_tab, false);
        assert!(placeholder.state == BrowserTabState::AddressOnly);
        assert!(placeholder.safe_title.is_none());
        assert!(placeholder.safe_url.is_none());
        assert!(!placeholder.has_cef_surface);
    }

