        let mut command = single_tab_command_model(
            CommandPaneGroupId(4),
            CommandSessionId(8),
            "Visible Command",
        );

        let (inserted_pane_id, inserted_session_id) =
            transfer_command_placeholder_to_workspace_tab_strip(
                &mut agents,
                &mut command,
                CommandPaneGroupId(4),
                CommandSessionId(8),
                WorkspacePaneId(1),
                1,
            )
            .unwrap();

        assert_eq!(inserted_pane_id.0, 1);
        assert_eq!(
            workspace_leaf_session_ids(&agents, WorkspacePaneId(1)),
            vec![10, inserted_session_id.0, 11, 12]
        );
