    #[test]
    fn agents_placeholder_activation_moves_to_mounting_without_fake_running() {
        for (session_id, presentation_state) in [
            (
                TerminalSessionId(21),
                TerminalSessionPresentationState::Sleeping,
            ),
            (
                TerminalSessionId(22),
                TerminalSessionPresentationState::RestoredUnmounted,
            ),
            (
                TerminalSessionId(23),
                TerminalSessionPresentationState::PoppedOutPlaceholder,
            ),
            (
                TerminalSessionId(24),
                TerminalSessionPresentationState::StartupFailed,
            ),
        ] {
            let mut model =
                single_tab_workspace_model(WorkspacePaneId(2), session_id, presentation_state);

            assert!(model.activate_terminal_placeholder_session(WorkspacePaneId(2), session_id));
            assert_eq!(
                workspace_pane_active_session_id(&model, WorkspacePaneId(2)),
                Some(session_id.0)
            );
            assert!(
                model
                    .session(session_id)
                    .is_some_and(|session| session.presentation_state
                        == TerminalSessionPresentationState::Mounting)
            );
            assert_eq!(agents_mount_slot_tuples(&model), Vec::<(u64, u64)>::new());
        }

        let mut mounting_model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(30, TerminalSessionPresentationState::Running),
                workspace_session(31, TerminalSessionPresentationState::Mounting),
            ],
            root: workspace_leaf_node(3, &[30, 31], 30),
            focused_pane: WorkspacePaneId(3),
            focus_mode_pane: None,
            next_pane_id: 4,
            next_split_id: 1,
            next_session_id: 32,
        };
        assert!(
            mounting_model
                .activate_terminal_placeholder_session(WorkspacePaneId(3), TerminalSessionId(31))
        );
        assert!(
            mounting_model
                .session(TerminalSessionId(31))
                .is_some_and(|session| {
                    session.presentation_state == TerminalSessionPresentationState::Mounting
                })
        );
        assert_eq!(
            workspace_pane_active_session_id(&mounting_model, WorkspacePaneId(3)),
            Some(31)
        );
        assert_eq!(
            agents_mount_slot_tuples(&mounting_model),
            Vec::<(u64, u64)>::new()
        );

        let mut running_model = single_tab_workspace_model(
            WorkspacePaneId(4),
            TerminalSessionId(40),
            TerminalSessionPresentationState::Running,
        );
        assert!(
            !running_model
                .activate_terminal_placeholder_session(WorkspacePaneId(4), TerminalSessionId(40))
        );
        assert!(
            running_model
                .session(TerminalSessionId(40))
                .is_some_and(|session| {
                    session.presentation_state == TerminalSessionPresentationState::Running
                })
        );
        assert_eq!(agents_mount_slot_tuples(&running_model), vec![(4, 40)]);
    }

    #[test]
    fn agents_placeholder_activation_splits_materialization_startup_from_blocked_wake_reattach() {
        /*
        CDXC:GPUITerminalRestoredMaterialization 2026-06-23-19:26:
        Explicit restored-unmounted activation is the source-side materialization contract and may feed the existing startup candidate/body-slot path. Sleeping wake and popped-out reattach still show Mounting pending UI without startup maps; their parked-owner contract is separate and does not create launch plans or hidden startup hosts.

        CDXC:GPUTerminalParkedOwnerReattach 2026-06-23-19:41:
        Sleeping wake and popped-out reattach may expose a non-startup parked-owner body slot for runtime reattach geometry, but activation alone must not mark Running or create startup candidates.
        */
        for (session_id, presentation_state) in [
            (
                TerminalSessionId(51),
                TerminalSessionPresentationState::Sleeping,
            ),
            (
                TerminalSessionId(53),
                TerminalSessionPresentationState::PoppedOutPlaceholder,
            ),
        ] {
            let mut model =
                single_tab_workspace_model(WorkspacePaneId(5), session_id, presentation_state);

            assert!(model.activate_terminal_placeholder_session(WorkspacePaneId(5), session_id));
            assert!(
                model
                    .session(session_id)
                    .is_some_and(|session| session.presentation_state
                        == TerminalSessionPresentationState::Mounting)
            );
            assert!(
                model
                    .visible_selected_mounting_startup_candidates()
                    .is_empty()
            );
            assert!(model.rendered_terminal_startup_body_slots().is_empty());
            assert_eq!(
                agents_parked_owner_body_slot_tuples(&model),
                vec![(5, session_id.0)]
            );
        }

        let restored_session_id = TerminalSessionId(52);
        let mut restored_model = single_tab_workspace_model(
            WorkspacePaneId(5),
            restored_session_id,
            TerminalSessionPresentationState::RestoredUnmounted,
        );

        assert!(
            restored_model
                .activate_terminal_placeholder_session(WorkspacePaneId(5), restored_session_id)
        );
        let restored_session = restored_model.session(restored_session_id).unwrap();
        assert!(restored_session.presentation_state == TerminalSessionPresentationState::Mounting);
        assert!(restored_session.can_enter_startup_pipeline());
        let restored_candidates = restored_model.visible_selected_mounting_startup_candidates();
        assert_eq!(restored_candidates.len(), 1);
        assert!(restored_candidates[0].pane_id == WorkspacePaneId(5));
        assert!(restored_candidates[0].shell_session_id == restored_session_id);
        assert!(
            restored_model.rendered_terminal_startup_body_slots()
                == vec![AgentsTerminalStartupBodySlotId {
                    pane_id: WorkspacePaneId(5),
                    session_id: restored_session_id,
                }]
        );

        let retry_session_id = TerminalSessionId(54);
        let mut retry_model = single_tab_workspace_model(
            WorkspacePaneId(6),
            retry_session_id,
            TerminalSessionPresentationState::StartupFailed,
        );

        assert!(
            retry_model.activate_terminal_placeholder_session(WorkspacePaneId(6), retry_session_id)
        );
        let retry_candidates = retry_model.visible_selected_mounting_startup_candidates();
        assert_eq!(retry_candidates.len(), 1);
        assert!(retry_candidates[0].pane_id == WorkspacePaneId(6));
        assert!(retry_candidates[0].shell_session_id == retry_session_id);
        assert_eq!(retry_model.rendered_terminal_startup_body_slots().len(), 1);
    }

    #[test]
    fn agents_failed_startup_retry_rotates_runtime_attempt_before_startup_sync() {
        /*
        CDXC:GPUITerminalStartupRetryIdentity 2026-06-23-18:19:
        Source coverage must prove retry activation gets a fresh runtime attempt identity before the startup coordinator creates the next candidate launch plan or completion intent. The durable shell id, title, tab, and Mounting presentation flow stay unchanged.
        */
        let retry_session_id = TerminalSessionId(64);
        let mut model = single_tab_workspace_model(
            WorkspacePaneId(6),
            retry_session_id,
            TerminalSessionPresentationState::StartupFailed,
        );
        let original_title = model.session(retry_session_id).unwrap().title.clone();
        let mut runtime_registry = AgentsTerminalRuntimeSessionRegistry::new();
        runtime_registry.reconcile_with_workspace(&model);
        let previous_runtime_id = runtime_registry
            .runtime_session_id_for_shell_session(retry_session_id)
            .unwrap();

        assert!(
            activate_agents_terminal_placeholder_with_runtime_attempt_identity(
                &mut model,
                &mut runtime_registry,
                WorkspacePaneId(6),
                retry_session_id,
            )
        );
        let retry_session = model.session(retry_session_id).unwrap();
        assert!(retry_session.id == retry_session_id);
        assert_eq!(retry_session.title, original_title);
        assert!(retry_session.can_enter_startup_pipeline());
        assert_eq!(
            workspace_pane_active_session_id(&model, WorkspacePaneId(6)),
            Some(retry_session_id.0)
        );
        let retry_runtime_id = runtime_registry
            .runtime_session_id_for_shell_session(retry_session_id)
            .unwrap();
        assert!(retry_runtime_id != previous_runtime_id);
        assert_eq!(runtime_registry.runtime_session_count(), 1);
        let shell_state_after_rotation = workspace_model_to_shell_state_json(&model);
        let session_object = shell_state_after_rotation
            .get("terminalSessions")
            .and_then(serde_json::Value::as_array)
            .and_then(|sessions| sessions.first())
            .and_then(serde_json::Value::as_object)
            .unwrap();
        assert_eq!(
            session_object.get("id").and_then(serde_json::Value::as_u64),
            Some(retry_session_id.0)
        );
        assert!(session_object.get("runtimeSessionId").is_none());
        assert!(session_object.get("runtime_session_id").is_none());

        let startup_body_slot_id = model.rendered_terminal_startup_body_slots()[0];
        let geometries = startup_body_geometry_map(
            startup_body_slot_id,
            focus_test_bounds(18.0, 28.0, 318.0, 218.0),
            2.0,
        );
        let mut startup_coordinator = AgentsTerminalStartupCoordinator::new();
        sync_startup_coordinator_and_launch_plans(
            &mut startup_coordinator,
            true,
            &model,
            &mut runtime_registry,
            &geometries,
        );

        assert_eq!(startup_coordinator.pending_startup_count(), 1);
        assert_eq!(startup_coordinator.startup_launch_plan_count(), 1);
        assert_eq!(startup_coordinator.startup_completion_intent_count(), 1);
        assert!(
            startup_coordinator
                .startup_launch_plan_for_runtime_session(previous_runtime_id)
                .is_none()
        );
        assert!(
            startup_coordinator
                .startup_completion_intent_for_runtime_session(previous_runtime_id)
                .is_none()
        );
        let launch_plan = startup_coordinator
            .startup_launch_plan_for_runtime_session(retry_runtime_id)
            .unwrap();
        assert!(launch_plan.runtime_session_id == retry_runtime_id);
        assert!(launch_plan.shell_session_id == retry_session_id);
        assert!(launch_plan.startup_body_slot_id == startup_body_slot_id);
        let completion_intent =
            startup_completion_intent_for(&startup_coordinator, retry_runtime_id);
        assert!(completion_intent.runtime_session_id == retry_runtime_id);
        assert!(completion_intent.shell_session_id == retry_session_id);
        assert!(completion_intent.startup_body_slot_id == startup_body_slot_id);
    }

    #[test]
    fn agents_restored_unmounted_materialization_preserves_runtime_attempt_and_creates_startup_intent()
     {
        /*
        CDXC:GPUITerminalRestoredMaterialization 2026-06-23-19:26:
        Restored-unmounted materialization uses the existing startup pipeline but is not a failed-startup retry. Preserve the process-local runtime id already associated with the durable shell session, then create startup launch-plan and completion-intent state only after current startup body geometry exists.
        */
        let session_id = TerminalSessionId(72);
        let mut model = single_tab_workspace_model(
            WorkspacePaneId(7),
            session_id,
            TerminalSessionPresentationState::RestoredUnmounted,
        );
        let mut runtime_registry = AgentsTerminalRuntimeSessionRegistry::new();
        runtime_registry.reconcile_with_workspace(&model);
        let original_runtime_id = runtime_registry
            .runtime_session_id_for_shell_session(session_id)
            .unwrap();

        assert!(
            activate_agents_terminal_placeholder_with_runtime_attempt_identity(
                &mut model,
                &mut runtime_registry,
                WorkspacePaneId(7),
                session_id,
            )
        );
        assert!(
            runtime_registry.runtime_session_id_for_shell_session(session_id)
                == Some(original_runtime_id)
        );
        assert_eq!(runtime_registry.runtime_session_count(), 1);
        let session = model.session(session_id).unwrap();
        assert!(session.presentation_state == TerminalSessionPresentationState::Mounting);
        assert!(session.can_enter_startup_pipeline());
        assert_eq!(
            model.visible_selected_mounting_startup_candidates().len(),
            1
        );
        let startup_body_slot_id = model.rendered_terminal_startup_body_slots()[0];
        let geometries = startup_body_geometry_map(
            startup_body_slot_id,
            focus_test_bounds(27.0, 37.0, 327.0, 227.0),
            2.0,
        );
        let mut startup_coordinator = AgentsTerminalStartupCoordinator::new();
        sync_startup_coordinator_and_launch_plans(
            &mut startup_coordinator,
            true,
            &model,
            &mut runtime_registry,
            &geometries,
        );

        assert_eq!(startup_coordinator.pending_startup_count(), 1);
        assert_eq!(startup_coordinator.startup_launch_plan_count(), 1);
        assert_eq!(startup_coordinator.startup_completion_intent_count(), 1);
        let launch_plan = startup_coordinator
            .startup_launch_plan_for_runtime_session(original_runtime_id)
            .unwrap();
        assert!(launch_plan.runtime_session_id == original_runtime_id);
        assert!(launch_plan.shell_session_id == session_id);
        assert!(launch_plan.startup_body_slot_id == startup_body_slot_id);
        let completion_intent =
            startup_completion_intent_for(&startup_coordinator, original_runtime_id);
        assert!(completion_intent.runtime_session_id == original_runtime_id);
        assert!(completion_intent.shell_session_id == session_id);
        assert!(completion_intent.startup_body_slot_id == startup_body_slot_id);

        let shell_state_after_materialization = workspace_model_to_shell_state_json(&model);
        let session_object = shell_state_after_materialization
            .get("terminalSessions")
            .and_then(serde_json::Value::as_array)
            .and_then(|sessions| sessions.first())
            .and_then(serde_json::Value::as_object)
            .unwrap();
        assert!(session_object.get("runtimeSessionId").is_none());
        assert!(session_object.get("runtime_session_id").is_none());
    }

