    #[test]
    fn agents_terminal_startup_coordinator_tracks_visible_selected_mounting_candidates() {
        let model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(101, TerminalSessionPresentationState::Running),
                workspace_session(102, TerminalSessionPresentationState::Mounting),
                workspace_session(201, TerminalSessionPresentationState::Mounting),
            ],
            root: WorkspaceNode::Split(WorkspaceSplit {
                id: WorkspaceSplitId(1),
                axis: WorkspaceSplitAxis::Horizontal,
                ratio: 0.5,
                first: Box::new(workspace_leaf_node(10, &[101, 102], 102)),
                second: Box::new(workspace_leaf_node(20, &[201], 201)),
            }),
            focused_pane: WorkspacePaneId(10),
            focus_mode_pane: Some(WorkspacePaneId(10)),
            next_pane_id: 21,
            next_split_id: 2,
            next_session_id: 202,
        };
        let mut runtime_registry = AgentsTerminalRuntimeSessionRegistry::new();
        runtime_registry.reconcile_with_workspace(&model);
        let visible_runtime_id = runtime_registry
            .runtime_session_id_for_shell_session(TerminalSessionId(102))
            .unwrap();
        let hidden_runtime_id = runtime_registry
            .runtime_session_id_for_shell_session(TerminalSessionId(201))
            .unwrap();
        let mut startup_coordinator = AgentsTerminalStartupCoordinator::new();

        startup_coordinator.sync_visible_mounting_startup_candidates(
            false,
            &model,
            &mut runtime_registry,
            &HashMap::new(),
        );
        assert_eq!(startup_coordinator.pending_startup_count(), 0);

        startup_coordinator.sync_visible_mounting_startup_candidates(
            true,
            &model,
            &mut runtime_registry,
            &HashMap::new(),
        );

        assert_eq!(startup_coordinator.pending_startup_count(), 1);
        assert!(
            startup_coordinator.pending_startup_for_runtime_session(visible_runtime_id)
                == Some(AgentsTerminalStartupRecord {
                    pane_id: WorkspacePaneId(10),
                    shell_session_id: TerminalSessionId(102),
                    startup_body_geometry_available: false,
                })
        );
        assert!(
            startup_coordinator
                .pending_startup_for_runtime_session(hidden_runtime_id)
                .is_none()
        );
    }

    #[test]
    fn agents_terminal_startup_coordinator_records_geometry_availability_without_changing_results()
    {
        let mut ready_model = single_tab_workspace_model(
            WorkspacePaneId(140),
            TerminalSessionId(1401),
            TerminalSessionPresentationState::Mounting,
        );
        let mut ready_runtime_registry = AgentsTerminalRuntimeSessionRegistry::new();
        ready_runtime_registry.reconcile_with_workspace(&ready_model);
        let ready_runtime_session_id = ready_runtime_registry
            .runtime_session_id_for_shell_session(TerminalSessionId(1401))
            .unwrap();
        let ready_slot = ready_model.rendered_terminal_startup_body_slots()[0];
        let ready_geometries =
            startup_body_geometry_map(ready_slot, focus_test_bounds(31.0, 41.0, 310.0, 210.0), 2.0);
        let mut ready_coordinator = AgentsTerminalStartupCoordinator::new();

        ready_coordinator.sync_visible_mounting_startup_candidates(
            true,
            &ready_model,
            &mut ready_runtime_registry,
            &ready_geometries,
        );

        assert!(
            ready_coordinator
                .pending_startup_for_runtime_session(ready_runtime_session_id)
                .is_some_and(|record| record.startup_body_geometry_available)
        );
        let ready_completion_intent =
            startup_completion_intent_for(&ready_coordinator, ready_runtime_session_id);
        assert!(ready_coordinator.apply_startup_result(
            &mut ready_model,
            &ready_runtime_registry,
            startup_ready_result(ready_completion_intent),
        ));
        assert_eq!(ready_coordinator.pending_startup_count(), 0);
        assert_eq!(ready_coordinator.startup_completion_intent_count(), 0);
        assert_eq!(agents_mount_slot_tuples(&ready_model), vec![(140, 1401)]);
        assert!(
            ready_model
                .session(TerminalSessionId(1401))
                .is_some_and(|session| {
                    session.presentation_state == TerminalSessionPresentationState::Running
                })
        );

        let mut failed_model = single_tab_workspace_model(
            WorkspacePaneId(150),
            TerminalSessionId(1501),
            TerminalSessionPresentationState::Mounting,
        );
        let mut failed_runtime_registry = AgentsTerminalRuntimeSessionRegistry::new();
        failed_runtime_registry.reconcile_with_workspace(&failed_model);
        let failed_runtime_session_id = failed_runtime_registry
            .runtime_session_id_for_shell_session(TerminalSessionId(1501))
            .unwrap();
        let failed_slot = failed_model.rendered_terminal_startup_body_slots()[0];
        let failed_geometries = startup_body_geometry_map(
            failed_slot,
            focus_test_bounds(32.0, 42.0, 320.0, 220.0),
            2.5,
        );
        let mut failed_coordinator = AgentsTerminalStartupCoordinator::new();

        failed_coordinator.sync_visible_mounting_startup_candidates(
            true,
            &failed_model,
            &mut failed_runtime_registry,
            &failed_geometries,
        );

        assert!(
            failed_coordinator
                .pending_startup_for_runtime_session(failed_runtime_session_id)
                .is_some_and(|record| record.startup_body_geometry_available)
        );
        let failed_completion_intent =
            startup_completion_intent_for(&failed_coordinator, failed_runtime_session_id);
        assert!(failed_coordinator.apply_startup_result(
            &mut failed_model,
            &failed_runtime_registry,
            startup_failed_result(failed_completion_intent),
        ));
        assert_eq!(failed_coordinator.pending_startup_count(), 0);
        assert_eq!(failed_coordinator.startup_completion_intent_count(), 0);
        assert_eq!(
            agents_mount_slot_tuples(&failed_model),
            Vec::<(u64, u64)>::new()
        );
        assert!(
            failed_model
                .session(TerminalSessionId(1501))
                .is_some_and(|session| {
                    session.presentation_state == TerminalSessionPresentationState::StartupFailed
                })
        );
    }

    #[test]
    fn agents_terminal_startup_launch_plan_requires_geometry_and_preserves_runtime_facts() {
        let model = single_tab_workspace_model(
            WorkspacePaneId(160),
            TerminalSessionId(1601),
            TerminalSessionPresentationState::Mounting,
        );
        let mut runtime_registry = AgentsTerminalRuntimeSessionRegistry::new();
        runtime_registry.reconcile_with_workspace(&model);
        let runtime_session_id = runtime_registry
            .runtime_session_id_for_shell_session(TerminalSessionId(1601))
            .unwrap();
        let startup_body_slot_id = model.rendered_terminal_startup_body_slots()[0];
        let bounds = focus_test_bounds(44.5, 55.25, 640.5, 360.25);
        let mut startup_coordinator = AgentsTerminalStartupCoordinator::new();

        sync_startup_coordinator_and_launch_plans(
            &mut startup_coordinator,
            true,
            &model,
            &mut runtime_registry,
            &HashMap::new(),
        );

        assert_eq!(startup_coordinator.pending_startup_count(), 1);
        assert_eq!(startup_coordinator.startup_launch_plan_count(), 0);

        let geometries = startup_body_geometry_map(startup_body_slot_id, bounds, 2.25);
        sync_startup_coordinator_and_launch_plans(
            &mut startup_coordinator,
            true,
            &model,
            &mut runtime_registry,
            &geometries,
        );

        let record = startup_coordinator
            .pending_startup_for_runtime_session(runtime_session_id)
            .unwrap();
        let plan = startup_coordinator
            .startup_launch_plan_for_runtime_session(runtime_session_id)
            .unwrap();
        assert!(record.startup_body_geometry_available);
        assert!(plan.runtime_session_id == runtime_session_id);
        assert!(plan.shell_session_id == TerminalSessionId(1601));
        assert!(plan.pane_id == WorkspacePaneId(160));
        assert!(plan.startup_body_slot_id == startup_body_slot_id);
        assert!(plan.bounds == bounds);
        assert_f32_close(plan.scale_factor, 2.25);
    }

    #[test]
    fn agents_terminal_startup_launch_plans_prune_when_visibility_state_or_identity_changes() {
        let model = single_tab_workspace_model(
            WorkspacePaneId(170),
            TerminalSessionId(1701),
            TerminalSessionPresentationState::Mounting,
        );
        let (mut runtime_registry, mut startup_coordinator, geometries, _, _) =
            startup_launch_plan_state_for(&model, focus_test_bounds(10.0, 20.0, 300.0, 200.0), 2.0);
        sync_startup_coordinator_and_launch_plans(
            &mut startup_coordinator,
            false,
            &model,
            &mut runtime_registry,
            &geometries,
        );
        assert_eq!(startup_coordinator.startup_launch_plan_count(), 0);

        let mut running_model = single_tab_workspace_model(
            WorkspacePaneId(171),
            TerminalSessionId(1711),
            TerminalSessionPresentationState::Mounting,
        );
        let (mut runtime_registry, mut startup_coordinator, geometries, _, _) =
            startup_launch_plan_state_for(
                &running_model,
                focus_test_bounds(11.0, 21.0, 301.0, 201.0),
                2.0,
            );
        running_model.transition_terminal_session_presentation_state(
            TerminalSessionId(1711),
            TerminalSessionPresentationState::Mounting,
            TerminalSessionPresentationState::Running,
        );
        runtime_registry.reconcile_with_workspace(&running_model);
        sync_startup_coordinator_and_launch_plans(
            &mut startup_coordinator,
            true,
            &running_model,
            &mut runtime_registry,
            &geometries,
        );
        assert_eq!(startup_coordinator.startup_launch_plan_count(), 0);

        let mut selection_model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(1721, TerminalSessionPresentationState::Mounting),
                workspace_session(1722, TerminalSessionPresentationState::Running),
            ],
            root: workspace_leaf_node(172, &[1721, 1722], 1721),
            focused_pane: WorkspacePaneId(172),
            focus_mode_pane: None,
            next_pane_id: 173,
            next_split_id: 1,
            next_session_id: 1723,
        };
        let (mut runtime_registry, mut startup_coordinator, geometries, _, _) =
            startup_launch_plan_state_for(
                &selection_model,
                focus_test_bounds(12.0, 22.0, 302.0, 202.0),
                2.0,
            );
        selection_model.select_tab(WorkspacePaneId(172), TerminalSessionId(1722));
        runtime_registry.reconcile_with_workspace(&selection_model);
        sync_startup_coordinator_and_launch_plans(
            &mut startup_coordinator,
            true,
            &selection_model,
            &mut runtime_registry,
            &geometries,
        );
        assert_eq!(startup_coordinator.startup_launch_plan_count(), 0);

        let mut hidden_focus_model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(1731, TerminalSessionPresentationState::Mounting),
                workspace_session(1732, TerminalSessionPresentationState::Running),
            ],
            root: WorkspaceNode::Split(WorkspaceSplit {
                id: WorkspaceSplitId(1),
                axis: WorkspaceSplitAxis::Horizontal,
                ratio: 0.5,
                first: Box::new(workspace_leaf_node(173, &[1731], 1731)),
                second: Box::new(workspace_leaf_node(174, &[1732], 1732)),
            }),
            focused_pane: WorkspacePaneId(173),
            focus_mode_pane: None,
            next_pane_id: 175,
            next_split_id: 2,
            next_session_id: 1733,
        };
        let (mut runtime_registry, mut startup_coordinator, geometries, _, _) =
            startup_launch_plan_state_for(
                &hidden_focus_model,
                focus_test_bounds(13.0, 23.0, 303.0, 203.0),
                2.0,
            );
        hidden_focus_model.focus_pane(WorkspacePaneId(174));
        hidden_focus_model.focus_mode_pane = Some(WorkspacePaneId(174));
        runtime_registry.reconcile_with_workspace(&hidden_focus_model);
        sync_startup_coordinator_and_launch_plans(
            &mut startup_coordinator,
            true,
            &hidden_focus_model,
            &mut runtime_registry,
            &geometries,
        );
        assert_eq!(startup_coordinator.startup_launch_plan_count(), 0);

        let mut removed_model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(1751, TerminalSessionPresentationState::Mounting),
                workspace_session(1752, TerminalSessionPresentationState::Running),
            ],
            root: workspace_leaf_node(175, &[1751, 1752], 1751),
            focused_pane: WorkspacePaneId(175),
            focus_mode_pane: None,
            next_pane_id: 176,
            next_split_id: 1,
            next_session_id: 1753,
        };
        let (mut runtime_registry, mut startup_coordinator, geometries, _, _) =
            startup_launch_plan_state_for(
                &removed_model,
                focus_test_bounds(14.0, 24.0, 304.0, 204.0),
                2.0,
            );
        assert!(removed_model.close_tab(WorkspacePaneId(175), TerminalSessionId(1751)));
        runtime_registry.reconcile_with_workspace(&removed_model);
        sync_startup_coordinator_and_launch_plans(
            &mut startup_coordinator,
            true,
            &removed_model,
            &mut runtime_registry,
            &geometries,
        );
        assert_eq!(startup_coordinator.startup_launch_plan_count(), 0);

        let runtime_mismatch_model = single_tab_workspace_model(
            WorkspacePaneId(176),
            TerminalSessionId(1761),
            TerminalSessionPresentationState::Mounting,
        );
        let (
            mut runtime_registry,
            mut startup_coordinator,
            geometries,
            runtime_session_id,
            startup_body_slot_id,
        ) = startup_launch_plan_state_for(
            &runtime_mismatch_model,
            focus_test_bounds(15.0, 25.0, 305.0, 205.0),
            2.0,
        );
        runtime_registry.runtime_ids_by_shell_session.insert(
            startup_body_slot_id.session_id,
            AgentsTerminalRuntimeSessionId(runtime_session_id.0 + 100),
        );
        startup_coordinator.sync_startup_launch_plans(
            true,
            &runtime_mismatch_model,
            &runtime_registry,
            &geometries,
        );
        assert!(
            startup_coordinator
                .startup_launch_plan_for_runtime_session(runtime_session_id)
                .is_none()
        );
        assert_eq!(startup_coordinator.startup_launch_plan_count(), 0);
    }

