    #[cfg(target_os = "macos")]
    #[test]
    fn agents_terminal_startup_host_config_requires_launch_plan() {
        let create_attempts = Arc::new(AtomicUsize::new(0));
        let destroy_count = Arc::new(AtomicUsize::new(0));
        let destroyed_pointer = Arc::new(AtomicUsize::new(0));
        let mut startup_host_native_views = HashMap::new();
        let mut startup_config_requests = HashMap::new();

        reconcile_startup_hosts_for_test(
            &mut startup_host_native_views,
            &mut startup_config_requests,
            &[],
            create_attempts.clone(),
            destroy_count.clone(),
            destroyed_pointer,
        );

        assert!(startup_host_native_views.is_empty());
        assert!(startup_config_requests.is_empty());
        assert_eq!(create_attempts.load(Ordering::SeqCst), 0);
        assert_eq!(destroy_count.load(Ordering::SeqCst), 0);
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn agents_terminal_startup_host_config_uses_launch_plan_bounds_and_scale() {
        let model = single_tab_workspace_model(
            WorkspacePaneId(181),
            TerminalSessionId(1811),
            TerminalSessionPresentationState::Mounting,
        );
        let bounds = focus_test_bounds(44.25, 55.5, 640.75, 360.5);
        let (_, coordinator, _, runtime_session_id, startup_body_slot_id) =
            startup_launch_plan_state_for(&model, bounds, 2.25);
        let startup_launch_plans = coordinator.startup_launch_plans();
        let create_attempts = Arc::new(AtomicUsize::new(0));
        let destroy_count = Arc::new(AtomicUsize::new(0));
        let destroyed_pointer = Arc::new(AtomicUsize::new(0));
        let mut startup_host_native_views = HashMap::new();
        let mut startup_config_requests = HashMap::new();

        reconcile_startup_hosts_for_test(
            &mut startup_host_native_views,
            &mut startup_config_requests,
            &startup_launch_plans,
            create_attempts.clone(),
            destroy_count.clone(),
            destroyed_pointer,
        );

        assert_eq!(create_attempts.load(Ordering::SeqCst), 1);
        assert_eq!(startup_host_native_views.len(), 1);
        assert_eq!(startup_config_requests.len(), 1);
        let host_view = startup_host_native_views
            .get(&startup_body_slot_id)
            .expect("current startup slot should own a hidden host view");
        let host_plan = host_view.startup_launch_plan();
        assert!(host_plan.runtime_session_id == runtime_session_id);
        assert!(host_plan.startup_body_slot_id == startup_body_slot_id);
        assert!(host_plan.bounds == bounds);
        assert_f32_close(host_plan.scale_factor, 2.25);

        let config = startup_config_requests
            .get(&startup_body_slot_id)
            .expect("current startup host should prepare a config request")
            .to_ffi_config();
        assert_eq!(
            unsafe { config.platform.macos }.nsview,
            startup_test_native_view_pointer().as_ptr()
        );
        assert_eq!(config.userdata, startup_test_native_view_pointer().as_ptr());
        assert_eq!(config.scale_factor, 2.25);
        assert!(config.working_directory.is_null());
        assert!(config.command.is_null());
        assert!(config.env_vars.is_null());
        assert_eq!(config.env_var_count, 0);
        assert!(config.initial_input.is_null());
        assert!(!config.wait_after_command);
    }

