    #[cfg(target_os = "macos")]
    #[test]
    fn agents_startup_launch_payload_source_matches_only_exact_runtime_key() {
        let model = single_tab_workspace_model(
            WorkspacePaneId(219),
            TerminalSessionId(2191),
            TerminalSessionPresentationState::Mounting,
        );
        let bounds = focus_test_bounds(46.25, 57.5, 642.75, 362.5);
        let (_, coordinator, _, _runtime_session_id, startup_body_slot_id) =
            startup_launch_plan_state_for(&model, bounds, 2.75);
        let startup_launch_plans = coordinator.startup_launch_plans();
        let plan = startup_launch_plans[0];
        let source = AgentsTerminalStartupLaunchPayloadSource::new_empty()
            .with_explicit_payload_for_test(plan, startup_explicit_launch_payload_for_test());

        assert!(source.payload_for_launch_plan(plan).unwrap().is_some());
        assert!(
            source
                .payload_for_launch_plan(AgentsTerminalStartupLaunchPlan {
                    runtime_session_id: AgentsTerminalRuntimeSessionId(
                        plan.runtime_session_id.0 + 100,
                    ),
                    ..plan
                })
                .unwrap()
                .is_none()
        );
        assert!(
            source
                .payload_for_launch_plan(AgentsTerminalStartupLaunchPlan {
                    shell_session_id: TerminalSessionId(plan.shell_session_id.0 + 100),
                    ..plan
                })
                .unwrap()
                .is_none()
        );
        assert!(
            source
                .payload_for_launch_plan(AgentsTerminalStartupLaunchPlan {
                    startup_body_slot_id: AgentsTerminalStartupBodySlotId {
                        pane_id: WorkspacePaneId(plan.pane_id.0 + 100),
                        session_id: plan.shell_session_id,
                    },
                    ..plan
                })
                .unwrap()
                .is_none()
        );

        let create_attempts = Arc::new(AtomicUsize::new(0));
        let destroy_count = Arc::new(AtomicUsize::new(0));
        let destroyed_pointer = Arc::new(AtomicUsize::new(0));
        let mut startup_host_native_views = HashMap::new();
        let mut startup_config_requests = HashMap::new();
        reconcile_startup_hosts_with_preservation_for_test(
            &mut startup_host_native_views,
            &mut startup_config_requests,
            &startup_launch_plans,
            &[],
            startup_test_parent_ns_view(),
            &source,
            create_attempts,
            destroy_count,
            destroyed_pointer,
        );

        let request = startup_config_requests
            .get(&startup_body_slot_id)
            .expect("exact explicit source should attach a launch payload");
        let request_debug = format!("{request:?}");
        assert!(request_debug.contains("has_launch_payload: true"));
        assert!(request_debug.contains("launch_env_var_count: 1"));
        assert_text_omits(
            &request_debug,
            &[
                "/Users/madda/private-explicit-startup",
                "private-explicit-command",
                "SECRET_EXPLICIT_TOKEN",
                "SECRET_EXPLICIT_ENV",
                "private-explicit-env-value",
                "private-explicit-initial-input",
            ],
        );

        let wrong_source = AgentsTerminalStartupLaunchPayloadSource::new_empty()
            .with_explicit_payload_for_test(
                AgentsTerminalStartupLaunchPlan {
                    runtime_session_id: AgentsTerminalRuntimeSessionId(
                        plan.runtime_session_id.0 + 1,
                    ),
                    ..plan
                },
                startup_explicit_launch_payload_for_test(),
            );
        let mut wrong_source_hosts = HashMap::new();
        let mut wrong_source_requests = HashMap::new();
        reconcile_startup_hosts_with_preservation_for_test(
            &mut wrong_source_hosts,
            &mut wrong_source_requests,
            &startup_launch_plans,
            &[],
            startup_test_parent_ns_view(),
            &wrong_source,
            Arc::new(AtomicUsize::new(0)),
            Arc::new(AtomicUsize::new(0)),
            Arc::new(AtomicUsize::new(0)),
        );
        let config = wrong_source_requests
            .get(&startup_body_slot_id)
            .expect("mismatched explicit source should leave a default request")
            .to_ffi_config();
        assert!(config.working_directory.is_null());
        assert!(config.command.is_null());
        assert!(config.env_vars.is_null());
        assert_eq!(config.env_var_count, 0);
        assert!(config.initial_input.is_null());
        assert!(!config.wait_after_command);
        assert!(model.rendered_terminal_body_mount_slots().is_empty());
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn agents_startup_launch_payload_source_invalid_payload_prunes_without_raw_leak() {
        let model = single_tab_workspace_model(
            WorkspacePaneId(220),
            TerminalSessionId(2201),
            TerminalSessionPresentationState::Mounting,
        );
        let bounds = focus_test_bounds(47.25, 58.5, 643.75, 363.5);
        let (_, coordinator, _, _runtime_session_id, _startup_body_slot_id) =
            startup_launch_plan_state_for(&model, bounds, 3.0);
        let startup_launch_plans = coordinator.startup_launch_plans();
        let plan = startup_launch_plans[0];
        let source = AgentsTerminalStartupLaunchPayloadSource::new_empty()
            .with_explicit_payload_for_test(
                plan,
                AgentsTerminalStartupExplicitLaunchPayload {
                    working_directory: Some("/Users/madda/private-invalid\0startup".to_string()),
                    command: Some(
                        "private-invalid-command --token SECRET_INVALID_TOKEN".to_string(),
                    ),
                    env_vars: vec![(
                        "SECRET_INVALID_ENV".to_string(),
                        "private-invalid-env-value".to_string(),
                    )],
                    initial_input: Some("private-invalid-initial-input".to_string()),
                    wait_after_command: true,
                },
            );
        let error = source
            .payload_for_launch_plan(plan)
            .expect_err("interior NUL should reject the explicit startup launch payload");
        assert!(matches!(
            error,
            terminal_ghostty_surface::GhosttySurfaceConfigRequestError::LaunchPayloadContainsInteriorNul {
                field: terminal_ghostty_surface::GhosttySurfaceLaunchPayloadField::WorkingDirectory,
            }
        ));
        let error_debug = format!("{error:?}");
        assert_text_omits(
            &error_debug,
            &[
                "/Users/madda/private-invalid",
                "private-invalid-command",
                "SECRET_INVALID_TOKEN",
                "SECRET_INVALID_ENV",
                "private-invalid-env-value",
                "private-invalid-initial-input",
            ],
        );

        let create_attempts = Arc::new(AtomicUsize::new(0));
        let destroy_count = Arc::new(AtomicUsize::new(0));
        let destroyed_pointer = Arc::new(AtomicUsize::new(0));
        let mut startup_host_native_views = HashMap::new();
        let mut startup_config_requests = HashMap::new();
        reconcile_startup_hosts_with_preservation_for_test(
            &mut startup_host_native_views,
            &mut startup_config_requests,
            &startup_launch_plans,
            &[],
            startup_test_parent_ns_view(),
            &source,
            create_attempts.clone(),
            destroy_count.clone(),
            destroyed_pointer,
        );

        assert_eq!(create_attempts.load(Ordering::SeqCst), 1);
        assert!(startup_host_native_views.is_empty());
        assert!(startup_config_requests.is_empty());
        assert_eq!(destroy_count.load(Ordering::SeqCst), 1);

        let persisted = shell_state_text(&workspace_model_to_shell_state_json(&model));
        assert_text_omits(
            &persisted,
            &[
                "/Users/madda/private-invalid",
                "private-invalid-command",
                "SECRET_INVALID_TOKEN",
                "SECRET_INVALID_ENV",
                "private-invalid-env-value",
                "private-invalid-initial-input",
                "LaunchPayloadContainsInteriorNul",
                "AgentsTerminalStartupLaunchPayloadSource",
                "explicit_payloads_by_startup_key",
            ],
        );
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn agents_terminal_startup_host_config_preserves_through_geometry_gap() {
        let model = single_tab_workspace_model(
            WorkspacePaneId(192),
            TerminalSessionId(1921),
            TerminalSessionPresentationState::Mounting,
        );
        let bounds = focus_test_bounds(70.25, 80.5, 500.75, 260.5);
        let (
            mut runtime_registry,
            mut coordinator,
            _geometries,
            runtime_session_id,
            startup_body_slot_id,
        ) = startup_launch_plan_state_for(&model, bounds, 2.75);
        let create_attempts = Arc::new(AtomicUsize::new(0));
        let destroy_count = Arc::new(AtomicUsize::new(0));
        let destroyed_pointer = Arc::new(AtomicUsize::new(0));
        let mut startup_host_native_views = HashMap::new();
        let mut startup_config_requests = HashMap::new();

        reconcile_startup_hosts_with_preservation_for_test(
            &mut startup_host_native_views,
            &mut startup_config_requests,
            &coordinator.startup_launch_plans(),
            &coordinator.startup_host_preservation_keys(true, &model, &runtime_registry),
            startup_test_parent_ns_view(),
            &AgentsTerminalStartupLaunchPayloadSource::new_empty(),
            create_attempts.clone(),
            destroy_count.clone(),
            destroyed_pointer.clone(),
        );

        assert_eq!(create_attempts.load(Ordering::SeqCst), 1);
        assert_eq!(startup_host_native_views.len(), 1);
        assert_eq!(startup_config_requests.len(), 1);

        sync_startup_coordinator_and_launch_plans(
            &mut coordinator,
            true,
            &model,
            &mut runtime_registry,
            &HashMap::new(),
        );
        assert_eq!(coordinator.startup_launch_plan_count(), 0);
        assert!(
            coordinator
                .pending_startup_for_runtime_session(runtime_session_id)
                .is_some_and(|record| !record.startup_body_geometry_available)
        );

        reconcile_startup_hosts_with_preservation_for_test(
            &mut startup_host_native_views,
            &mut startup_config_requests,
            &coordinator.startup_launch_plans(),
            &coordinator.startup_host_preservation_keys(true, &model, &runtime_registry),
            startup_test_parent_ns_view(),
            &AgentsTerminalStartupLaunchPayloadSource::new_empty(),
            create_attempts.clone(),
            destroy_count.clone(),
            destroyed_pointer,
        );

        assert_eq!(create_attempts.load(Ordering::SeqCst), 1);
        assert_eq!(destroy_count.load(Ordering::SeqCst), 0);
        assert_eq!(startup_host_native_views.len(), 1);
        assert_eq!(startup_config_requests.len(), 1);
        let host_plan = startup_host_native_views
            .get(&startup_body_slot_id)
            .expect("preserved startup host should remain keyed by startup slot")
            .startup_launch_plan();
        assert!(host_plan.runtime_session_id == runtime_session_id);
        assert!(host_plan.startup_body_slot_id == startup_body_slot_id);
        assert!(host_plan.bounds == bounds);
        assert_f32_close(host_plan.scale_factor, 2.75);

        let config = startup_config_requests
            .get(&startup_body_slot_id)
            .expect("preserved startup host should keep an empty config request")
            .to_ffi_config();
        assert_eq!(
            unsafe { config.platform.macos }.nsview,
            startup_test_native_view_pointer().as_ptr()
        );
        assert_eq!(config.userdata, startup_test_native_view_pointer().as_ptr());
        assert_eq!(config.scale_factor, 2.75);
        assert!(model.rendered_terminal_body_mount_slots().is_empty());
    }

