    #[cfg(target_os = "macos")]
    #[test]
    fn agents_terminal_startup_host_config_prunes_when_launch_plan_becomes_stale() {
        let create_attempts = Arc::new(AtomicUsize::new(0));
        let destroy_count = Arc::new(AtomicUsize::new(0));
        let destroyed_pointer = Arc::new(AtomicUsize::new(0));

        let assert_prunes = |mut model: WorkspaceModel,
                             bounds: Bounds<Pixels>,
                             mutate: &mut dyn FnMut(
            &mut WorkspaceModel,
            &mut AgentsTerminalRuntimeSessionRegistry,
            &mut AgentsTerminalStartupCoordinator,
            &HashMap<AgentsTerminalStartupBodySlotId, AgentsTerminalStartupBodyGeometry>,
            AgentsTerminalRuntimeSessionId,
            AgentsTerminalStartupBodySlotId,
        ),
                             agents_visible_after: bool| {
            let (
                mut runtime_registry,
                mut coordinator,
                geometries,
                runtime_session_id,
                startup_body_slot_id,
            ) = startup_launch_plan_state_for(&model, bounds, 2.0);
            let mut startup_host_native_views = HashMap::new();
            let mut startup_config_requests = HashMap::new();
            reconcile_startup_hosts_for_test(
                &mut startup_host_native_views,
                &mut startup_config_requests,
                &coordinator.startup_launch_plans(),
                create_attempts.clone(),
                destroy_count.clone(),
                destroyed_pointer.clone(),
            );
            assert_eq!(startup_host_native_views.len(), 1);
            assert_eq!(startup_config_requests.len(), 1);

            mutate(
                &mut model,
                &mut runtime_registry,
                &mut coordinator,
                &geometries,
                runtime_session_id,
                startup_body_slot_id,
            );
            runtime_registry.reconcile_with_workspace(&model);
            sync_startup_coordinator_and_launch_plans(
                &mut coordinator,
                agents_visible_after,
                &model,
                &mut runtime_registry,
                &geometries,
            );
            reconcile_startup_hosts_for_test(
                &mut startup_host_native_views,
                &mut startup_config_requests,
                &coordinator.startup_launch_plans(),
                create_attempts.clone(),
                destroy_count.clone(),
                destroyed_pointer.clone(),
            );

            assert!(startup_host_native_views.is_empty());
            assert!(startup_config_requests.is_empty());
        };

        let hidden_agents_model = single_tab_workspace_model(
            WorkspacePaneId(182),
            TerminalSessionId(1821),
            TerminalSessionPresentationState::Mounting,
        );
        assert_prunes(
            hidden_agents_model,
            focus_test_bounds(10.0, 20.0, 300.0, 200.0),
            &mut |_, _, _, _, _, _| {},
            false,
        );

        let running_model = single_tab_workspace_model(
            WorkspacePaneId(183),
            TerminalSessionId(1831),
            TerminalSessionPresentationState::Mounting,
        );
        assert_prunes(
            running_model,
            focus_test_bounds(11.0, 21.0, 301.0, 201.0),
            &mut |model, _, _, _, _, _| {
                model.transition_terminal_session_presentation_state(
                    TerminalSessionId(1831),
                    TerminalSessionPresentationState::Mounting,
                    TerminalSessionPresentationState::Running,
                );
            },
            true,
        );

        let failed_model = single_tab_workspace_model(
            WorkspacePaneId(184),
            TerminalSessionId(1841),
            TerminalSessionPresentationState::Mounting,
        );
        assert_prunes(
            failed_model,
            focus_test_bounds(12.0, 22.0, 302.0, 202.0),
            &mut |model, _, _, _, _, _| {
                model.transition_terminal_session_presentation_state(
                    TerminalSessionId(1841),
                    TerminalSessionPresentationState::Mounting,
                    TerminalSessionPresentationState::StartupFailed,
                );
            },
            true,
        );

        let selection_model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(1851, TerminalSessionPresentationState::Mounting),
                workspace_session(1852, TerminalSessionPresentationState::Running),
            ],
            root: workspace_leaf_node(185, &[1851, 1852], 1851),
            focused_pane: WorkspacePaneId(185),
            focus_mode_pane: None,
            next_pane_id: 186,
            next_split_id: 1,
            next_session_id: 1853,
        };
        assert_prunes(
            selection_model,
            focus_test_bounds(13.0, 23.0, 303.0, 203.0),
            &mut |model, _, _, _, _, _| {
                model.select_tab(WorkspacePaneId(185), TerminalSessionId(1852));
            },
            true,
        );

        let focus_hidden_model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(1861, TerminalSessionPresentationState::Mounting),
                workspace_session(1862, TerminalSessionPresentationState::Running),
            ],
            root: WorkspaceNode::Split(WorkspaceSplit {
                id: WorkspaceSplitId(1),
                axis: WorkspaceSplitAxis::Horizontal,
                ratio: 0.5,
                first: Box::new(workspace_leaf_node(186, &[1861], 1861)),
                second: Box::new(workspace_leaf_node(187, &[1862], 1862)),
            }),
            focused_pane: WorkspacePaneId(186),
            focus_mode_pane: None,
            next_pane_id: 188,
            next_split_id: 2,
            next_session_id: 1863,
        };
        assert_prunes(
            focus_hidden_model,
            focus_test_bounds(14.0, 24.0, 304.0, 204.0),
            &mut |model, _, _, _, _, _| {
                model.focus_pane(WorkspacePaneId(187));
                model.focus_mode_pane = Some(WorkspacePaneId(187));
            },
            true,
        );

        let removed_model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(1881, TerminalSessionPresentationState::Mounting),
                workspace_session(1882, TerminalSessionPresentationState::Running),
            ],
            root: workspace_leaf_node(188, &[1881, 1882], 1881),
            focused_pane: WorkspacePaneId(188),
            focus_mode_pane: None,
            next_pane_id: 189,
            next_split_id: 1,
            next_session_id: 1883,
        };
        assert_prunes(
            removed_model,
            focus_test_bounds(15.0, 25.0, 305.0, 205.0),
            &mut |model, _, _, _, _, _| {
                assert!(model.close_tab(WorkspacePaneId(188), TerminalSessionId(1881)));
            },
            true,
        );

        let runtime_mismatch_model = single_tab_workspace_model(
            WorkspacePaneId(189),
            TerminalSessionId(1891),
            TerminalSessionPresentationState::Mounting,
        );
        let (
            mut runtime_registry,
            mut coordinator,
            geometries,
            runtime_session_id,
            startup_body_slot_id,
        ) = startup_launch_plan_state_for(
            &runtime_mismatch_model,
            focus_test_bounds(16.0, 26.0, 306.0, 206.0),
            2.0,
        );
        let mut startup_host_native_views = HashMap::new();
        let mut startup_config_requests = HashMap::new();
        reconcile_startup_hosts_for_test(
            &mut startup_host_native_views,
            &mut startup_config_requests,
            &coordinator.startup_launch_plans(),
            create_attempts.clone(),
            destroy_count.clone(),
            destroyed_pointer.clone(),
        );
        assert_eq!(startup_host_native_views.len(), 1);
        assert_eq!(startup_config_requests.len(), 1);

        runtime_registry.runtime_ids_by_shell_session.insert(
            startup_body_slot_id.session_id,
            AgentsTerminalRuntimeSessionId(runtime_session_id.0 + 100),
        );
        coordinator.sync_startup_launch_plans(
            true,
            &runtime_mismatch_model,
            &runtime_registry,
            &geometries,
        );
        reconcile_startup_hosts_for_test(
            &mut startup_host_native_views,
            &mut startup_config_requests,
            &coordinator.startup_launch_plans(),
            create_attempts.clone(),
            destroy_count.clone(),
            destroyed_pointer.clone(),
        );
        assert!(startup_host_native_views.is_empty());
        assert!(startup_config_requests.is_empty());

        assert_eq!(create_attempts.load(Ordering::SeqCst), 7);
        assert_eq!(destroy_count.load(Ordering::SeqCst), 7);
        assert_eq!(
            destroyed_pointer.load(Ordering::SeqCst),
            startup_test_native_view_pointer().as_ptr() as usize
        );
    }

