    #[cfg(target_os = "macos")]
    #[test]
    fn agents_terminal_startup_ghostty_surface_requires_matching_config_and_plan() {
        let _guard = startup_fake_ghostty_test_lock();
        reset_startup_fake_ghostty_state();
        let model = single_tab_workspace_model(
            WorkspacePaneId(204),
            TerminalSessionId(2041),
            TerminalSessionPresentationState::Mounting,
        );
        let bounds = focus_test_bounds(44.25, 55.5, 640.75, 360.5);
        let (runtime_registry, coordinator, _, runtime_session_id, startup_body_slot_id) =
            startup_launch_plan_state_for(&model, bounds, 2.25);
        let startup_launch_plans = coordinator.startup_launch_plans();
        let preservation_keys =
            coordinator.startup_host_preservation_keys(true, &model, &runtime_registry);
        let mut startup_surface_owners = HashMap::new();
        let mut ghostty_app = None;

        reconcile_startup_ghostty_surfaces_for_test(
            &mut startup_surface_owners,
            &mut ghostty_app,
            &HashMap::new(),
            &startup_launch_plans,
            &preservation_keys,
        );
        assert!(startup_surface_owners.is_empty());
        assert!(ghostty_app.is_none());
        assert!(
            startup_fake_ghostty_state()
                .lock()
                .unwrap()
                .calls
                .is_empty()
        );

        let startup_config_requests =
            startup_surface_config_request_map(startup_body_slot_id, 2.25);
        reconcile_startup_ghostty_surfaces_for_test(
            &mut startup_surface_owners,
            &mut ghostty_app,
            &startup_config_requests,
            &[],
            &preservation_keys,
        );
        assert!(startup_surface_owners.is_empty());
        assert!(ghostty_app.is_none());
        assert!(
            startup_fake_ghostty_state()
                .lock()
                .unwrap()
                .calls
                .is_empty()
        );

        reconcile_startup_ghostty_surfaces_for_test(
            &mut startup_surface_owners,
            &mut ghostty_app,
            &startup_config_requests,
            &startup_launch_plans,
            &preservation_keys,
        );

        assert!(ghostty_app.is_some());
        assert_eq!(startup_surface_owners.len(), 1);
        let owner = startup_surface_owners
            .get(&startup_body_slot_id)
            .expect("matching startup config and launch plan should create an owner");
        assert!(owner.startup_body_slot_id() == startup_body_slot_id);
        assert!(owner.runtime_session_id() == runtime_session_id);

        let state = startup_fake_ghostty_state().lock().unwrap();
        assert_eq!(
            state.last_surface_config_nsview,
            startup_test_native_view_pointer().as_ptr() as usize
        );
        assert_eq!(state.last_surface_config_scale, Some(2.25));
        assert_eq!(state.last_content_scale, Some((2.25, 2.25)));
        assert_eq!(state.last_size, Some((1441, 811)));
        assert!(!state.calls.contains(&"ghostty_app_set_focus"));
        assert!(!state.calls.contains(&"ghostty_surface_set_focus"));
    }

