    #[cfg(target_os = "macos")]
    #[test]
    fn agents_terminal_startup_ghostty_surface_prunes_stale_boundaries_and_missing_config() {
        let _guard = startup_fake_ghostty_test_lock();
        reset_startup_fake_ghostty_state();

        let assert_prunes = |case_label: &str,
                             mut model: WorkspaceModel,
                             bounds: Bounds<Pixels>,
                             mutate: &mut dyn FnMut(
            &mut WorkspaceModel,
            &mut AgentsTerminalRuntimeSessionRegistry,
            AgentsTerminalRuntimeSessionId,
            AgentsTerminalStartupBodySlotId,
        ),
                             agents_visible_after: bool| {
            let (
                mut runtime_registry,
                mut coordinator,
                geometries,
                runtime_session_id,
                startup_body_slot_id,
            ) = startup_launch_plan_state_for(&model, bounds, 2.0);
            let startup_config_requests =
                startup_surface_config_request_map(startup_body_slot_id, 2.0);
            let mut startup_surface_owners = HashMap::new();
            let mut ghostty_app = None;
            reconcile_startup_ghostty_surfaces_for_test(
                &mut startup_surface_owners,
                &mut ghostty_app,
                &startup_config_requests,
                &coordinator.startup_launch_plans(),
                &coordinator.startup_host_preservation_keys(true, &model, &runtime_registry),
            );
            assert_eq!(startup_surface_owners.len(), 1);

            mutate(
                &mut model,
                &mut runtime_registry,
                runtime_session_id,
                startup_body_slot_id,
            );
            runtime_registry.reconcile_with_workspace(&model);
            sync_startup_coordinator_and_launch_plans(
                &mut coordinator,
                agents_visible_after,
                &model,
                &mut runtime_registry,
                &geometries,
            );
            reconcile_startup_ghostty_surfaces_for_test(
                &mut startup_surface_owners,
                &mut ghostty_app,
                &startup_config_requests,
                &coordinator.startup_launch_plans(),
                &coordinator.startup_host_preservation_keys(
                    agents_visible_after,
                    &model,
                    &runtime_registry,
                ),
            );

            assert!(
                startup_surface_owners.is_empty(),
                "startup surface should prune for {case_label}"
            );
        };

        assert_prunes(
            "hidden agents",
            single_tab_workspace_model(
                WorkspacePaneId(206),
                TerminalSessionId(2061),
                TerminalSessionPresentationState::Mounting,
            ),
            focus_test_bounds(10.0, 20.0, 300.0, 200.0),
            &mut |_, _, _, _| {},
            false,
        );

        assert_prunes(
            "running state",
            single_tab_workspace_model(
                WorkspacePaneId(207),
                TerminalSessionId(2071),
                TerminalSessionPresentationState::Mounting,
            ),
            focus_test_bounds(11.0, 21.0, 301.0, 201.0),
            &mut |model, _, _, _| {
                model.transition_terminal_session_presentation_state(
                    TerminalSessionId(2071),
                    TerminalSessionPresentationState::Mounting,
                    TerminalSessionPresentationState::Running,
                );
            },
            true,
        );

        assert_prunes(
            "selection change",
            WorkspaceModel {
                terminal_sessions: vec![
                    workspace_session(2081, TerminalSessionPresentationState::Mounting),
                    workspace_session(2082, TerminalSessionPresentationState::Running),
                ],
                root: workspace_leaf_node(208, &[2081, 2082], 2081),
                focused_pane: WorkspacePaneId(208),
                focus_mode_pane: None,
                next_pane_id: 209,
                next_split_id: 1,
                next_session_id: 2083,
            },
            focus_test_bounds(12.0, 22.0, 302.0, 202.0),
            &mut |model, _, _, _| {
                model.select_tab(WorkspacePaneId(208), TerminalSessionId(2082));
            },
            true,
        );

        assert_prunes(
            "focus-hidden pane",
            WorkspaceModel {
                terminal_sessions: vec![
                    workspace_session(2091, TerminalSessionPresentationState::Mounting),
                    workspace_session(2092, TerminalSessionPresentationState::Running),
                ],
                root: WorkspaceNode::Split(WorkspaceSplit {
                    id: WorkspaceSplitId(1),
                    axis: WorkspaceSplitAxis::Horizontal,
                    ratio: 0.5,
                    first: Box::new(workspace_leaf_node(209, &[2091], 2091)),
                    second: Box::new(workspace_leaf_node(210, &[2092], 2092)),
                }),
                focused_pane: WorkspacePaneId(209),
                focus_mode_pane: None,
                next_pane_id: 211,
                next_split_id: 2,
                next_session_id: 2093,
            },
            focus_test_bounds(13.0, 23.0, 303.0, 203.0),
            &mut |model, _, _, _| {
                model.focus_pane(WorkspacePaneId(210));
                model.focus_mode_pane = Some(WorkspacePaneId(210));
            },
            true,
        );

        assert_prunes(
            "removed session",
            WorkspaceModel {
                terminal_sessions: vec![
                    workspace_session(2111, TerminalSessionPresentationState::Mounting),
                    workspace_session(2112, TerminalSessionPresentationState::Running),
                ],
                root: workspace_leaf_node(211, &[2111, 2112], 2111),
                focused_pane: WorkspacePaneId(211),
                focus_mode_pane: None,
                next_pane_id: 212,
                next_split_id: 1,
                next_session_id: 2113,
            },
            focus_test_bounds(14.0, 24.0, 304.0, 204.0),
            &mut |model, _, _, _| {
                assert!(model.close_tab(WorkspacePaneId(211), TerminalSessionId(2111)));
            },
            true,
        );

        let runtime_mismatch_model = single_tab_workspace_model(
            WorkspacePaneId(212),
            TerminalSessionId(2121),
            TerminalSessionPresentationState::Mounting,
        );
        let (
            mut runtime_registry,
            mut coordinator,
            geometries,
            runtime_session_id,
            startup_body_slot_id,
        ) = startup_launch_plan_state_for(
            &runtime_mismatch_model,
            focus_test_bounds(15.0, 25.0, 305.0, 205.0),
            2.0,
        );
        let startup_config_requests = startup_surface_config_request_map(startup_body_slot_id, 2.0);
        let mut startup_surface_owners = HashMap::new();
        let mut ghostty_app = None;
        reconcile_startup_ghostty_surfaces_for_test(
            &mut startup_surface_owners,
            &mut ghostty_app,
            &startup_config_requests,
            &coordinator.startup_launch_plans(),
            &coordinator.startup_host_preservation_keys(
                true,
                &runtime_mismatch_model,
                &runtime_registry,
            ),
        );
        assert_eq!(startup_surface_owners.len(), 1);

        let replacement_runtime_session_id =
            AgentsTerminalRuntimeSessionId(runtime_session_id.0 + 100);
        runtime_registry.runtime_ids_by_shell_session.insert(
            startup_body_slot_id.session_id,
            replacement_runtime_session_id,
        );
        sync_startup_coordinator_and_launch_plans(
            &mut coordinator,
            true,
            &runtime_mismatch_model,
            &mut runtime_registry,
            &geometries,
        );
        reconcile_startup_ghostty_surfaces_for_test(
            &mut startup_surface_owners,
            &mut ghostty_app,
            &startup_config_requests,
            &coordinator.startup_launch_plans(),
            &coordinator.startup_host_preservation_keys(
                true,
                &runtime_mismatch_model,
                &runtime_registry,
            ),
        );
        assert_eq!(startup_surface_owners.len(), 1);
        assert!(
            startup_surface_owners
                .get(&startup_body_slot_id)
                .is_some_and(|owner| owner.runtime_session_id() == replacement_runtime_session_id)
        );
        assert_eq!(
            startup_fake_ghostty_state()
                .lock()
                .unwrap()
                .calls
                .iter()
                .filter(|call| **call == "ghostty_surface_new")
                .count(),
            7
        );

        let model = single_tab_workspace_model(
            WorkspacePaneId(213),
            TerminalSessionId(2131),
            TerminalSessionPresentationState::Mounting,
        );
        let (runtime_registry, coordinator, _, _runtime_session_id, startup_body_slot_id) =
            startup_launch_plan_state_for(&model, focus_test_bounds(16.0, 26.0, 306.0, 206.0), 2.0);
        let startup_config_requests = startup_surface_config_request_map(startup_body_slot_id, 2.0);
        let mut startup_surface_owners = HashMap::new();
        let mut ghostty_app = None;
        reconcile_startup_ghostty_surfaces_for_test(
            &mut startup_surface_owners,
            &mut ghostty_app,
            &startup_config_requests,
            &coordinator.startup_launch_plans(),
            &coordinator.startup_host_preservation_keys(true, &model, &runtime_registry),
        );
        assert_eq!(startup_surface_owners.len(), 1);
        reconcile_startup_ghostty_surfaces_for_test(
            &mut startup_surface_owners,
            &mut ghostty_app,
            &HashMap::new(),
            &coordinator.startup_launch_plans(),
            &coordinator.startup_host_preservation_keys(true, &model, &runtime_registry),
        );
        assert!(startup_surface_owners.is_empty());
        assert!(
            startup_fake_ghostty_state()
                .lock()
                .unwrap()
                .calls
                .iter()
                .filter(|call| **call == "ghostty_surface_free")
                .count()
                >= 7
        );
    }

