    #[cfg(target_os = "macos")]
    #[test]
    fn agents_terminal_startup_readiness_preparation_observes_surface_metadata_without_promotion() {
        let _guard = startup_fake_ghostty_test_lock();
        reset_startup_fake_ghostty_state();
        {
            let mut state = startup_fake_ghostty_state().lock().unwrap();
            state.foreground_pid = STARTUP_FAKE_FOREGROUND_PROCESS_ID;
            state.tty_name = Some(STARTUP_FAKE_TTY_NAME);
        }

        let model = single_tab_workspace_model(
            WorkspacePaneId(219),
            TerminalSessionId(2191),
            TerminalSessionPresentationState::Mounting,
        );
        let (
            runtime_registry,
            mut coordinator,
            _geometries,
            runtime_session_id,
            startup_body_slot_id,
        ) = startup_launch_plan_state_for(&model, focus_test_bounds(20.0, 30.0, 310.0, 210.0), 2.0);
        let startup_config_requests = startup_surface_config_request_map(startup_body_slot_id, 2.0);
        let mut startup_surface_owners = HashMap::new();
        let mut ghostty_app = None;
        let running_surface_owners: HashMap<
            AgentsTerminalBodyMountSlotId,
            terminal_ghostty_surface::GhosttySurfaceOwner,
        > = HashMap::new();

        reconcile_startup_ghostty_surfaces_for_test(
            &mut startup_surface_owners,
            &mut ghostty_app,
            &startup_config_requests,
            &coordinator.startup_launch_plans(),
            &coordinator.startup_host_preservation_keys(true, &model, &runtime_registry),
        );
        sync_agents_terminal_startup_readiness_signal_preparations(
            &mut coordinator,
            agents_terminal_startup_surface_metadata_snapshots(&startup_surface_owners),
        );

        assert_eq!(startup_surface_owners.len(), 1);
        assert_eq!(coordinator.startup_readiness_signal_preparation_count(), 1);
        let preparation = coordinator
            .startup_readiness_signal_preparation_for_runtime_session(runtime_session_id)
            .expect("real startup surface metadata should prepare a runtime handoff signal");
        assert!(preparation.surface_metadata.foreground_process_id_present());
        assert!(preparation.surface_metadata.tty_name_present());
        assert!(!preparation.surface_metadata.process_exited());
        assert_eq!(agents_mount_slot_tuples(&model), Vec::<(u64, u64)>::new());
        assert_eq!(agents_startup_body_slot_tuples(&model), vec![(219, 2191)]);
        assert!(running_surface_owners.is_empty());
        assert!(
            model
                .session(TerminalSessionId(2191))
                .is_some_and(|session| {
                    session.presentation_state == TerminalSessionPresentationState::Mounting
                })
        );
        let state = startup_fake_ghostty_state().lock().unwrap();
        assert_eq!(state.tty_string_free_count, 1);
        assert!(state.calls.contains(&"ghostty_surface_process_exited"));
        assert!(state.calls.contains(&"ghostty_surface_foreground_pid"));
        assert!(state.calls.contains(&"ghostty_surface_tty_name"));
        assert!(!state.calls.contains(&"ghostty_surface_set_focus"));
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn agents_terminal_startup_readiness_handoff_transfers_host_and_surface_without_recreate() {
        let _guard = startup_fake_ghostty_test_lock();
        reset_startup_fake_ghostty_state();
        {
            let mut state = startup_fake_ghostty_state().lock().unwrap();
            state.foreground_pid = STARTUP_FAKE_FOREGROUND_PROCESS_ID;
            state.tty_name = Some(STARTUP_FAKE_TTY_NAME);
        }

        let mut model = single_tab_workspace_model(
            WorkspacePaneId(220),
            TerminalSessionId(2201),
            TerminalSessionPresentationState::Mounting,
        );
        let (
            runtime_registry,
            mut coordinator,
            mut startup_body_geometries,
            runtime_session_id,
            startup_body_slot_id,
        ) = startup_launch_plan_state_for(&model, focus_test_bounds(21.0, 31.0, 311.0, 211.0), 2.0);
        let create_attempts = Arc::new(AtomicUsize::new(0));
        let destroy_count = Arc::new(AtomicUsize::new(0));
        let destroyed_pointer = Arc::new(AtomicUsize::new(0));
        let mut startup_host_native_views = HashMap::new();
        let mut startup_config_requests = HashMap::new();
        reconcile_startup_hosts_for_test(
            &mut startup_host_native_views,
            &mut startup_config_requests,
            &coordinator.startup_launch_plans(),
            create_attempts,
            destroy_count.clone(),
            destroyed_pointer,
        );
        let mut startup_surface_owners = HashMap::new();
        let mut ghostty_app = None;
        reconcile_startup_ghostty_surfaces_for_test(
            &mut startup_surface_owners,
            &mut ghostty_app,
            &startup_config_requests,
            &coordinator.startup_launch_plans(),
            &coordinator.startup_host_preservation_keys(true, &model, &runtime_registry),
        );
        sync_agents_terminal_startup_readiness_signal_preparations(
            &mut coordinator,
            agents_terminal_startup_surface_metadata_snapshots(&startup_surface_owners),
        );
        let handoff_plan = coordinator
            .startup_readiness_handoff_plans(true, &model, &runtime_registry)
            .into_iter()
            .next()
            .expect("ready metadata should produce an exact handoff plan");
        let mount_slot_id = handoff_plan.mount_slot_id;
        let mut running_mount_slot_bounds = HashMap::new();
        let mut running_host_native_views = HashMap::new();
        let mut running_surface_owners = HashMap::new();
        let running_config_requests = HashMap::new();

        assert!(transfer_ready_agents_terminal_startup_handoff(
            &mut coordinator,
            &mut model,
            &runtime_registry,
            &mut startup_body_geometries,
            &mut startup_host_native_views,
            &mut startup_surface_owners,
            &mut startup_config_requests,
            &mut running_mount_slot_bounds,
            &mut running_host_native_views,
            &mut running_surface_owners,
            &running_config_requests,
            handoff_plan,
        ));

        assert!(startup_body_geometries.is_empty());
        assert!(startup_host_native_views.is_empty());
        assert!(startup_surface_owners.is_empty());
        assert!(startup_config_requests.is_empty());
        assert_eq!(coordinator.pending_startup_count(), 0);
        assert_eq!(coordinator.startup_completion_intent_count(), 0);
        assert_eq!(coordinator.startup_readiness_signal_preparation_count(), 0);
        assert_eq!(
            agents_startup_body_slot_tuples(&model),
            Vec::<(u64, u64)>::new()
        );
        assert_eq!(agents_mount_slot_tuples(&model), vec![(220, 2201)]);
        assert!(
            running_mount_slot_bounds.get(&mount_slot_id).copied()
                == Some(handoff_plan.startup_launch_plan.bounds)
        );
        assert_eq!(running_host_native_views.len(), 1);
        assert!(
            running_host_native_views
                .get(&mount_slot_id)
                .map(|host_view| host_view.attachment_plan())
                == Some(agents_terminal_attachment_plan_for_startup_handoff(
                    handoff_plan
                ))
        );
        assert_eq!(running_surface_owners.len(), 1);
        assert!(
            running_surface_owners
                .get(&mount_slot_id)
                .is_some_and(|surface| {
                    surface.mount_slot_id() == mount_slot_id
                        && surface.runtime_session_id() == runtime_session_id
                })
        );
        assert_eq!(destroy_count.load(Ordering::SeqCst), 0);
        let state = startup_fake_ghostty_state().lock().unwrap();
        assert_eq!(
            state
                .calls
                .iter()
                .filter(|call| **call == "ghostty_surface_new")
                .count(),
            1
        );
        assert!(!state.calls.contains(&"ghostty_surface_free"));
        assert!(!state.calls.contains(&"ghostty_surface_set_focus"));
        assert_eq!(state.tty_string_free_count, 1);
        assert!(startup_body_slot_id == handoff_plan.startup_body_slot_id());
    }

