    #[test]
    fn agents_terminal_startup_stale_results_are_ignored() {
        let mut model = single_tab_workspace_model(
            WorkspacePaneId(90),
            TerminalSessionId(901),
            TerminalSessionPresentationState::Mounting,
        );
        let mut runtime_registry = AgentsTerminalRuntimeSessionRegistry::new();
        runtime_registry.reconcile_with_workspace(&model);
        let runtime_session_id = runtime_registry
            .runtime_session_id_for_shell_session(TerminalSessionId(901))
            .unwrap();
        let mut startup_coordinator = AgentsTerminalStartupCoordinator::new();
        startup_coordinator.sync_visible_mounting_startup_candidates(
            true,
            &model,
            &mut runtime_registry,
            &HashMap::new(),
        );
        let completion_intent =
            startup_completion_intent_for(&startup_coordinator, runtime_session_id);

        for stale_intent in [
            AgentsTerminalStartupCompletionIntent {
                runtime_session_id: AgentsTerminalRuntimeSessionId(runtime_session_id.0 + 100),
                ..completion_intent
            },
            AgentsTerminalStartupCompletionIntent {
                shell_session_id: TerminalSessionId(902),
                ..completion_intent
            },
            AgentsTerminalStartupCompletionIntent {
                startup_body_slot_id: AgentsTerminalStartupBodySlotId {
                    pane_id: WorkspacePaneId(91),
                    session_id: TerminalSessionId(901),
                },
                ..completion_intent
            },
        ] {
            assert!(
                startup_coordinator
                    .produce_startup_result_from_runtime_signal(Some(startup_ready_signal(
                        stale_intent
                    )))
                    .is_none()
            );
            assert!(!startup_coordinator.apply_startup_result(
                &mut model,
                &runtime_registry,
                startup_ready_result(stale_intent),
            ));
        }
        assert_eq!(startup_coordinator.pending_startup_count(), 1);
        assert_eq!(startup_coordinator.startup_completion_intent_count(), 1);
        assert!(
            model
                .session(TerminalSessionId(901))
                .is_some_and(|session| {
                    session.presentation_state == TerminalSessionPresentationState::Mounting
                })
        );

        model.transition_terminal_session_presentation_state(
            TerminalSessionId(901),
            TerminalSessionPresentationState::Mounting,
            TerminalSessionPresentationState::Sleeping,
        );
        assert!(!startup_coordinator.apply_startup_result(
            &mut model,
            &runtime_registry,
            startup_ready_result(completion_intent),
        ));
        assert_eq!(startup_coordinator.pending_startup_count(), 0);
        assert_eq!(startup_coordinator.startup_completion_intent_count(), 0);
        assert!(
            model
                .session(TerminalSessionId(901))
                .is_some_and(|session| {
                    session.presentation_state == TerminalSessionPresentationState::Sleeping
                })
        );

        let mut removed_model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(911, TerminalSessionPresentationState::Mounting),
                workspace_session(912, TerminalSessionPresentationState::Running),
            ],
            root: workspace_leaf_node(91, &[911, 912], 911),
            focused_pane: WorkspacePaneId(91),
            focus_mode_pane: None,
            next_pane_id: 92,
            next_split_id: 1,
            next_session_id: 913,
        };
        runtime_registry.reconcile_with_workspace(&removed_model);
        startup_coordinator.sync_visible_mounting_startup_candidates(
            true,
            &removed_model,
            &mut runtime_registry,
            &HashMap::new(),
        );
        let removed_runtime_session_id = runtime_registry
            .runtime_session_id_for_shell_session(TerminalSessionId(911))
            .unwrap();
        let removed_completion_intent =
            startup_completion_intent_for(&startup_coordinator, removed_runtime_session_id);
        assert!(removed_model.close_tab(WorkspacePaneId(91), TerminalSessionId(911)));
        runtime_registry.reconcile_with_workspace(&removed_model);

        assert!(!startup_coordinator.apply_startup_result(
            &mut removed_model,
            &runtime_registry,
            startup_failed_result(removed_completion_intent),
        ));
        assert_eq!(startup_coordinator.pending_startup_count(), 0);
        assert_eq!(startup_coordinator.startup_completion_intent_count(), 0);
        assert!(removed_model.session(TerminalSessionId(911)).is_none());
        assert_eq!(
            workspace_leaf_session_ids(&removed_model, WorkspacePaneId(91)),
            vec![912]
        );
    }

    #[test]
    fn agents_shell_terminal_session_ids_survive_reorder_grouping_edge_split_and_restore() {
        let mut model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(101, TerminalSessionPresentationState::Running),
                workspace_session(102, TerminalSessionPresentationState::Running),
                workspace_session(201, TerminalSessionPresentationState::Running),
            ],
            root: WorkspaceNode::Split(WorkspaceSplit {
                id: WorkspaceSplitId(1),
                axis: WorkspaceSplitAxis::Horizontal,
                ratio: 0.5,
                first: Box::new(workspace_leaf_node(10, &[101, 102], 101)),
                second: Box::new(workspace_leaf_node(20, &[201], 201)),
            }),
            focused_pane: WorkspacePaneId(10),
            focus_mode_pane: None,
            next_pane_id: 30,
            next_split_id: 2,
            next_session_id: 300,
        };

        assert!(model.reorder_tab_within_pane(WorkspacePaneId(10), TerminalSessionId(102), 0,));
        assert_eq!(
            workspace_leaf_session_ids(&model, WorkspacePaneId(10)),
            vec![102, 101]
        );
        assert_eq!(workspace_terminal_session_ids(&model), vec![101, 102, 201]);

        assert!(model.group_tab_into_pane(
            WorkspacePaneId(20),
            WorkspacePaneId(10),
            TerminalSessionId(201),
        ));
        assert_eq!(
            workspace_leaf_session_ids(&model, WorkspacePaneId(10)),
            vec![102, 101, 201]
        );
        assert!(model.find_leaf(WorkspacePaneId(20)).is_none());
        assert_eq!(workspace_terminal_session_ids(&model), vec![101, 102, 201]);

        assert!(model.split_tab_to_pane(
            WorkspacePaneId(10),
            WorkspacePaneId(10),
            TerminalSessionId(102),
            WorkspaceDropZone::Right,
        ));
        assert_eq!(
            workspace_leaf_session_ids(&model, WorkspacePaneId(10)),
            vec![101, 201]
        );
        assert_eq!(
            workspace_leaf_session_ids(&model, WorkspacePaneId(30)),
            vec![102]
        );
        assert_eq!(
            workspace_pane_active_session_id(&model, WorkspacePaneId(30)),
            Some(102)
        );
        assert_eq!(workspace_terminal_session_ids(&model), vec![101, 102, 201]);

        let restored =
            workspace_model_from_shell_state(&workspace_model_to_shell_state_json(&model))
                .expect("shell state should restore after layout moves");
        assert_eq!(
            workspace_leaf_session_ids(&restored, WorkspacePaneId(10)),
            vec![101, 201]
        );
        assert_eq!(
            workspace_leaf_session_ids(&restored, WorkspacePaneId(30)),
            vec![102]
        );
        assert_eq!(
            workspace_terminal_session_ids(&restored),
            vec![101, 102, 201]
        );
    }

    #[test]
    fn agents_terminal_runtime_registry_preserves_ids_across_layout_moves_and_focus_changes() {
        let mut model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(101, TerminalSessionPresentationState::Running),
                workspace_session(102, TerminalSessionPresentationState::Running),
                workspace_session(201, TerminalSessionPresentationState::Running),
            ],
            root: WorkspaceNode::Split(WorkspaceSplit {
                id: WorkspaceSplitId(1),
                axis: WorkspaceSplitAxis::Horizontal,
                ratio: 0.5,
                first: Box::new(workspace_leaf_node(10, &[101, 102], 101)),
                second: Box::new(workspace_leaf_node(20, &[201], 201)),
            }),
            focused_pane: WorkspacePaneId(10),
            focus_mode_pane: None,
            next_pane_id: 30,
            next_split_id: 2,
            next_session_id: 300,
        };
        let mut registry = AgentsTerminalRuntimeSessionRegistry::new();
        registry.reconcile_with_workspace(&model);
        let runtime_102 = registry
            .runtime_session_id_for_shell_session(TerminalSessionId(102))
            .unwrap();
        let runtime_201 = registry
            .runtime_session_id_for_shell_session(TerminalSessionId(201))
            .unwrap();

        assert!(model.reorder_tab_within_pane(WorkspacePaneId(10), TerminalSessionId(102), 0,));
        registry.reconcile_with_workspace(&model);
        assert!(
            registry.runtime_session_id_for_shell_session(TerminalSessionId(102))
                == Some(runtime_102)
        );

        assert!(model.group_tab_into_pane(
            WorkspacePaneId(20),
            WorkspacePaneId(10),
            TerminalSessionId(201),
        ));
        registry.reconcile_with_workspace(&model);
        assert!(
            registry.runtime_session_id_for_shell_session(TerminalSessionId(201))
                == Some(runtime_201)
        );

        assert!(model.split_tab_to_pane(
            WorkspacePaneId(10),
            WorkspacePaneId(10),
            TerminalSessionId(102),
            WorkspaceDropZone::Bottom,
        ));
        registry.reconcile_with_workspace(&model);
        assert!(
            registry.runtime_session_id_for_shell_session(TerminalSessionId(102))
                == Some(runtime_102)
        );

        model.focus_pane(WorkspacePaneId(30));
        model.select_tab(WorkspacePaneId(10), TerminalSessionId(201));
        model.toggle_focus_mode();
        registry.reconcile_with_workspace(&model);
        assert!(
            registry.runtime_session_id_for_shell_session(TerminalSessionId(102))
                == Some(runtime_102)
        );
        assert!(
            registry.runtime_session_id_for_shell_session(TerminalSessionId(201))
                == Some(runtime_201)
        );
    }

