    #[test]
    fn restored_agents_shell_state_keeps_shell_ids_but_not_runtime_ids() {
        let model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(401, TerminalSessionPresentationState::Running),
                workspace_session(402, TerminalSessionPresentationState::Sleeping),
            ],
            root: workspace_leaf_node(40, &[401, 402], 401),
            focused_pane: WorkspacePaneId(40),
            focus_mode_pane: None,
            next_pane_id: 41,
            next_split_id: 1,
            next_session_id: 403,
        };
        let mut first_registry = AgentsTerminalRuntimeSessionRegistry::new();
        first_registry.ensure_runtime_session_id(TerminalSessionId(999));
        first_registry.reconcile_with_workspace(&model);
        let original_runtime_401 = first_registry
            .runtime_session_id_for_shell_session(TerminalSessionId(401))
            .unwrap();

        let shell_state = workspace_model_to_shell_state_json(&model);
        let persisted = shell_state_text(&shell_state);
        assert!(persisted.contains("\"id\":401"));
        assert_text_omits(
            &persisted,
            &[
                "AgentsTerminalRuntimeSessionId",
                "AgentsTerminalRuntimeSessionRegistry",
                "agents_terminal_runtime_sessions",
                "agentsTerminalRuntimeSessions",
                "runtime_ids_by_shell_session",
                "runtimeIdsByShellSession",
                "next_runtime_session_id",
                "nextRuntimeSessionId",
                "runtime_session_id_for_shell_session",
                "runtimeSessionIdForShellSession",
                "ensure_runtime_session_id",
                "ensureRuntimeSessionId",
                "rotate_runtime_session_id_for_shell_session",
                "rotateRuntimeSessionIdForShellSession",
                "allocate_runtime_session_id",
                "allocateRuntimeSessionId",
                "activate_agents_terminal_placeholder_with_runtime_attempt_identity",
                "activateAgentsTerminalPlaceholderWithRuntimeAttemptIdentity",
                "GPUITerminalRuntimeIdentity",
            ],
        );

        let restored = workspace_model_from_shell_state(&shell_state)
            .expect("shell state should restore without runtime ids");
        assert_eq!(workspace_terminal_session_ids(&restored), vec![401, 402]);

        let mut fresh_registry = AgentsTerminalRuntimeSessionRegistry::new();
        fresh_registry.reconcile_with_workspace(&restored);
        let fresh_runtime_401 = fresh_registry
            .runtime_session_id_for_shell_session(TerminalSessionId(401))
            .unwrap();

        assert!(fresh_runtime_401 != original_runtime_401);
        assert!(fresh_runtime_401 == AgentsTerminalRuntimeSessionId(1));
    }

    #[test]
    fn workspace_to_command_tab_strip_transfer_inserts_at_requested_index_and_closes_source() {
        let mut agents = WorkspaceModel {
            terminal_sessions: vec![
                TerminalSession::placeholder(
                    TerminalSessionId(10),
                    "Keep Agent".to_string(),
                    TerminalSessionPresentationState::Running,
                ),
                TerminalSession::placeholder(
                    TerminalSessionId(11),
                    "Visible Agent Title".to_string(),
                    TerminalSessionPresentationState::Sleeping,
                ),
                TerminalSession::placeholder(
                    TerminalSessionId(12),
                    "Trailing Agent".to_string(),
                    TerminalSessionPresentationState::RestoredUnmounted,
                ),
            ],
            root: workspace_leaf_node(1, &[10, 11, 12], 10),
            focused_pane: WorkspacePaneId(1),
            focus_mode_pane: None,
            next_pane_id: 2,
            next_split_id: 1,
            next_session_id: 13,
        };
        let mut command = CommandPaneModel {
            terminal_sessions: vec![
                CommandTerminalSession::placeholder(CommandSessionId(1), "Command 1".to_string()),
                CommandTerminalSession::placeholder(CommandSessionId(2), "Command 2".to_string()),
                CommandTerminalSession::placeholder(CommandSessionId(3), "Command 3".to_string()),
            ],
            root: CommandPaneNode::Split(CommandPaneSplit {
                id: CommandPaneSplitId(1),
                ratio: 0.5,
                first: Box::new(CommandPaneNode::Leaf(CommandPaneLeaf {
                    group_id: CommandPaneGroupId(1),
                    tab_group: CommandPaneTabGroup {
                        tabs: vec![
                            CommandPaneTab {
                                session_id: CommandSessionId(1),
                            },
                            CommandPaneTab {
                                session_id: CommandSessionId(2),
                            },
                        ],
                        active_session: CommandSessionId(1),
                    },
                })),
                second: Box::new(CommandPaneNode::Leaf(CommandPaneLeaf {
                    group_id: CommandPaneGroupId(2),
                    tab_group: CommandPaneTabGroup {
                        tabs: vec![CommandPaneTab {
                            session_id: CommandSessionId(3),
                        }],
                        active_session: CommandSessionId(3),
                    },
                })),
            }),
            focused_group: CommandPaneGroupId(2),
            mode: CommandPaneMode::Collapsed,
            last_expanded_mode: CommandPaneMode::Floating,
            height_ratio: command_pane_default_height_ratio(1_000.0),
            resize_drag: None,
            next_group_id: 3,
            next_split_id: 2,
            next_session_id: 4,
        };

        let (inserted_group_id, inserted_session_id) =
            transfer_workspace_placeholder_to_command_tab_strip(
                &mut agents,
                &mut command,
                WorkspacePaneId(1),
                TerminalSessionId(11),
                CommandPaneGroupId(1),
                1,
            )
            .unwrap();

        assert_eq!(inserted_group_id.0, 1);
        assert_eq!(
            command_group_session_ids(&command, CommandPaneGroupId(1)),
            vec![1, inserted_session_id.0, 2]
        );
        assert_eq!(
            command_group_active_session_id(&command, CommandPaneGroupId(1)),
            Some(inserted_session_id.0)
        );
        assert_eq!(command.focused_group.0, 1);
        assert!(command.is_expanded());
        assert!(
            command
                .session(inserted_session_id)
                .is_some_and(|session| session.title == "Visible Agent Title")
        );
        assert_eq!(
            workspace_leaf_session_ids(&agents, WorkspacePaneId(1)),
            vec![10, 12]
        );
        assert!(agents.session(TerminalSessionId(11)).is_none());
        assert_eq!(
            workspace_pane_active_session_id(&agents, WorkspacePaneId(1)),
            Some(10)
        );
    }

    #[test]
    fn workspace_to_command_tab_strip_transfer_appends_at_end_and_preserves_final_root_source() {
        let mut agents = WorkspaceModel {
            terminal_sessions: vec![
                TerminalSession::placeholder(
                    TerminalSessionId(40),
                    "End Agent Title".to_string(),
                    TerminalSessionPresentationState::Running,
                ),
                workspace_session(41, TerminalSessionPresentationState::Sleeping),
            ],
            root: workspace_leaf_node(1, &[40, 41], 40),
            focused_pane: WorkspacePaneId(1),
            focus_mode_pane: None,
            next_pane_id: 2,
            next_split_id: 1,
            next_session_id: 42,
        };
        let mut command = CommandPaneModel::shell_default(1_000.0);
        let end_index = command
            .find_leaf(CommandPaneGroupId(1))
            .map(|leaf| leaf.tab_group.tabs.len())
            .unwrap();

        let (_inserted_group_id, inserted_session_id) =
            transfer_workspace_placeholder_to_command_tab_strip(
                &mut agents,
                &mut command,
                WorkspacePaneId(1),
                TerminalSessionId(40),
                CommandPaneGroupId(1),
                end_index,
            )
            .unwrap();

        assert_eq!(
            command_group_session_ids(&command, CommandPaneGroupId(1)),
            vec![1, 2, inserted_session_id.0]
        );
        assert_eq!(
            command_group_active_session_id(&command, CommandPaneGroupId(1)),
            Some(inserted_session_id.0)
        );
        assert_eq!(command.focused_group.0, 1);
        assert!(
            command
                .session(inserted_session_id)
                .is_some_and(|session| session.title == "End Agent Title")
        );
        assert_eq!(
            workspace_leaf_session_ids(&agents, WorkspacePaneId(1)),
            vec![41]
        );
        assert!(agents.session(TerminalSessionId(40)).is_none());

        let mut final_root_agents = single_tab_workspace_model(
            WorkspacePaneId(9),
            TerminalSessionId(90),
            TerminalSessionPresentationState::Running,
        );
        let mut guarded_command = CommandPaneModel::shell_default(1_000.0);

        assert!(
            transfer_workspace_placeholder_to_command_tab_strip(
                &mut final_root_agents,
                &mut guarded_command,
                WorkspacePaneId(9),
                TerminalSessionId(90),
                CommandPaneGroupId(1),
                1,
            )
            .is_none()
        );
        assert_eq!(
            workspace_leaf_session_ids(&final_root_agents, WorkspacePaneId(9)),
            vec![90]
        );
        assert!(final_root_agents.session(TerminalSessionId(90)).is_some());
        assert_eq!(
            command_group_session_ids(&guarded_command, CommandPaneGroupId(1)),
            vec![1, 2]
        );
        assert!(
            !guarded_command
                .terminal_sessions
                .iter()
                .any(|session| session.title == "Solo")
        );
    }

    #[test]
    fn workspace_to_command_tab_strip_transfer_preserves_source_on_insert_failure_and_rolls_back() {
        let mut failed_insert_agents = WorkspaceModel {
            terminal_sessions: vec![
                TerminalSession::placeholder(
                    TerminalSessionId(60),
                    "Preserve Insert Source".to_string(),
                    TerminalSessionPresentationState::Running,
                ),
                workspace_session(61, TerminalSessionPresentationState::Running),
            ],
            root: workspace_leaf_node(1, &[60, 61], 60),
            focused_pane: WorkspacePaneId(1),
            focus_mode_pane: None,
            next_pane_id: 2,
            next_split_id: 1,
            next_session_id: 62,
        };
        let mut failed_insert_command = CommandPaneModel::shell_default(1_000.0);

        assert!(
            transfer_workspace_placeholder_to_command_tab_strip(
                &mut failed_insert_agents,
                &mut failed_insert_command,
                WorkspacePaneId(1),
                TerminalSessionId(60),
                CommandPaneGroupId(99),
                0,
            )
            .is_none()
        );
        assert_eq!(
            workspace_leaf_session_ids(&failed_insert_agents, WorkspacePaneId(1)),
            vec![60, 61]
        );
        assert!(
            failed_insert_agents
                .session(TerminalSessionId(60))
                .is_some_and(|session| session.title == "Preserve Insert Source")
        );
        assert_eq!(
            command_group_session_ids(&failed_insert_command, CommandPaneGroupId(1)),
            vec![1, 2]
        );

        let mut rollback_agents = WorkspaceModel {
            terminal_sessions: vec![
                TerminalSession::placeholder(
                    TerminalSessionId(70),
                    "Rollback Agent Title".to_string(),
                    TerminalSessionPresentationState::Running,
                ),
                workspace_session(71, TerminalSessionPresentationState::Running),
            ],
            root: workspace_leaf_node(1, &[70, 71], 70),
            focused_pane: WorkspacePaneId(1),
            focus_mode_pane: None,
            next_pane_id: 2,
            next_split_id: 1,
            next_session_id: 72,
        };
        let mut rollback_command = CommandPaneModel::shell_default(1_000.0);

        assert!(
            transfer_workspace_placeholder_to_command_tab_strip_with_source_close(
                &mut rollback_agents,
                &mut rollback_command,
                WorkspacePaneId(1),
                TerminalSessionId(70),
                CommandPaneGroupId(1),
                1,
                |_workspace, _pane_id, _session_id| false,
            )
            .is_none()
        );
        assert_eq!(
            workspace_leaf_session_ids(&rollback_agents, WorkspacePaneId(1)),
            vec![70, 71]
        );
        assert!(
            rollback_agents
                .session(TerminalSessionId(70))
                .is_some_and(|session| session.title == "Rollback Agent Title")
        );
        assert_eq!(
            command_group_session_ids(&rollback_command, CommandPaneGroupId(1)),
            vec![1, 2]
        );
        assert!(
            !rollback_command
                .terminal_sessions
                .iter()
                .any(|session| session.title == "Rollback Agent Title")
        );
    }

    #[test]
    fn agents_close_selects_neighbor_and_visual_sibling_after_split_collapse() {
        let mut tab_model = WorkspaceModel::first_slice_default();
        tab_model.select_tab(WorkspacePaneId(1), TerminalSessionId(3));

        assert!(tab_model.close_active_tab());

        assert_eq!(
            workspace_leaf_session_ids(&tab_model, WorkspacePaneId(1)),
            vec![1, 2, 4, 5, 6, 7, 8]
        );
        assert_eq!(
            workspace_pane_active_session_id(&tab_model, WorkspacePaneId(1)),
            Some(4)
        );
        assert_eq!(tab_model.focused_pane.0, 1);
        assert!(tab_model.session(TerminalSessionId(3)).is_none());

        let mut split_model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(11, TerminalSessionPresentationState::Running),
                workspace_session(12, TerminalSessionPresentationState::Running),
                workspace_session(13, TerminalSessionPresentationState::Running),
                workspace_session(14, TerminalSessionPresentationState::Running),
            ],
            root: WorkspaceNode::Split(WorkspaceSplit {
                id: WorkspaceSplitId(1),
                axis: WorkspaceSplitAxis::Horizontal,
                ratio: 0.5,
                first: Box::new(WorkspaceNode::Split(WorkspaceSplit {
                    id: WorkspaceSplitId(2),
                    axis: WorkspaceSplitAxis::Vertical,
                    ratio: 0.5,
                    first: Box::new(workspace_leaf_node(1, &[11], 11)),
                    second: Box::new(workspace_leaf_node(2, &[12], 12)),
                })),
                second: Box::new(WorkspaceNode::Split(WorkspaceSplit {
                    id: WorkspaceSplitId(3),
                    axis: WorkspaceSplitAxis::Vertical,
                    ratio: 0.5,
                    first: Box::new(workspace_leaf_node(3, &[13], 13)),
                    second: Box::new(workspace_leaf_node(4, &[14], 14)),
                })),
            }),
            focused_pane: WorkspacePaneId(4),
            focus_mode_pane: None,
            next_pane_id: 5,
            next_split_id: 4,
            next_session_id: 15,
        };

        assert_eq!(
            split_model
                .leaf_order()
                .into_iter()
                .map(|pane_id| pane_id.0)
                .collect::<Vec<_>>(),
            vec![1, 2, 3, 4]
        );

        assert!(split_model.close_active_tab());

        assert_eq!(
            split_model
                .leaf_order()
                .into_iter()
                .map(|pane_id| pane_id.0)
                .collect::<Vec<_>>(),
            vec![1, 2, 3]
        );
        assert_eq!(split_model.focused_pane.0, 3);
        assert!(split_model.find_leaf(WorkspacePaneId(4)).is_none());
        assert!(split_model.session(TerminalSessionId(14)).is_none());
        assert_eq!(
            workspace_pane_active_session_id(&split_model, WorkspacePaneId(3)),
            Some(13)
        );
    }

