    #[test]
    fn command_terminal_body_bounds_create_host_plans_without_group_or_titlebar_bounds() {
        let model =
            single_tab_command_model(CommandPaneGroupId(10), CommandSessionId(101), "build");
        let slot_id = model.rendered_terminal_body_mount_slots()[0];
        let group_bounds = focus_test_bounds(10.0, 20.0, 700.0, 360.0);
        let body_bounds = focus_test_bounds(10.0, 46.0, 700.0, 334.0);
        let mut host = NativeTerminalSurfaceHost::<CommandTerminalBodyMountSlotId>::new();
        let recorded_body_bounds = HashMap::from([(slot_id, body_bounds)]);

        let commands = host.sync_visible_command_slots(
            model.is_expanded(),
            &model.rendered_terminal_body_mount_slots(),
            &recorded_body_bounds,
        );
        let plan = host.active_plan_for(slot_id).unwrap();

        assert!(matches!(
            commands.as_slice(),
            [terminal_surface_host::NativeTerminalSurfaceHostCommand::AttachOrShow {
                plan: command_plan
            }] if *command_plan == plan
        ));
        assert!(plan.bounds == body_bounds);
        assert!(plan.bounds != group_bounds);
        assert_f32_close(plan.bounds.origin.y.as_f32(), 46.0);
        assert_f32_close(plan.bounds.size.height.as_f32(), 334.0);
    }

