    #[test]
    fn command_host_lifecycle_prunes_on_close_and_collapse_without_touching_agents_host() {
        let mut command =
            single_tab_command_model(CommandPaneGroupId(10), CommandSessionId(101), "cmd");
        let command_slot = command.rendered_terminal_body_mount_slots()[0];
        let command_bounds = focus_test_bounds(10.0, 46.0, 700.0, 334.0);
        let mut command_host = NativeTerminalSurfaceHost::<CommandTerminalBodyMountSlotId>::new();
        let mut command_lifecycle = terminal_surface_lifecycle::NativeTerminalSurfaceLifecycleState::<
            CommandTerminalBodyMountSlotId,
        >::new();
        let attach_commands = command_host.sync_visible_command_slots(
            true,
            &[command_slot],
            &HashMap::from([(command_slot, command_bounds)]),
        );
        command_lifecycle.reconcile_host_commands(&attach_commands);

        let agents = single_tab_workspace_model(
            WorkspacePaneId(20),
            TerminalSessionId(201),
            TerminalSessionPresentationState::Running,
        );
        let agents_slot = agents.rendered_terminal_body_mount_slots()[0];
        let agents_bounds = focus_test_bounds(20.0, 60.0, 800.0, 500.0);
        let mut agents_host = NativeTerminalSurfaceHost::new();
        agents_host.sync_visible_agents_slots(
            true,
            &[agents_slot],
            &HashMap::from([(agents_slot, agents_bounds)]),
        );

        assert!(command.close_session(CommandPaneGroupId(10), CommandSessionId(101)));
        let close_commands = command_host.sync_visible_command_slots(
            command.is_expanded(),
            &command.rendered_terminal_body_mount_slots(),
            &HashMap::new(),
        );
        command_lifecycle.reconcile_host_commands(&close_commands);

        assert!(matches!(
            close_commands.as_slice(),
            [terminal_surface_host::NativeTerminalSurfaceHostCommand::HideAndDetach { plan }]
                if plan.slot_id == command_slot
        ));
        assert!(command_host.active_plan().is_none());
        assert!(command_lifecycle.active_plan().is_none());
        assert!(agents_host.active_plan_for(agents_slot).is_some());

        let mut collapsed_command =
            single_tab_command_model(CommandPaneGroupId(30), CommandSessionId(301), "collapsed");
        let collapsed_slot = collapsed_command.rendered_terminal_body_mount_slots()[0];
        let mut collapsed_host = NativeTerminalSurfaceHost::<CommandTerminalBodyMountSlotId>::new();
        collapsed_host.sync_visible_command_slots(
            true,
            &[collapsed_slot],
            &HashMap::from([(collapsed_slot, focus_test_bounds(1.0, 2.0, 3.0, 4.0))]),
        );
        collapsed_command.collapse();
        let collapse_commands = collapsed_host.sync_visible_command_slots(
            collapsed_command.is_expanded(),
            &collapsed_command.rendered_terminal_body_mount_slots(),
            &HashMap::new(),
        );

        assert!(matches!(
            collapse_commands.as_slice(),
            [terminal_surface_host::NativeTerminalSurfaceHostCommand::HideAndDetach { plan }]
                if plan.slot_id == collapsed_slot
        ));
        assert!(collapsed_host.active_plan().is_none());
    }

    #[test]
    fn command_terminal_focus_targets_only_mounted_focused_command_surface() {
        let mut command = CommandPaneModel {
            terminal_sessions: vec![
                CommandTerminalSession::placeholder(CommandSessionId(101), "left".into()),
                CommandTerminalSession::placeholder(CommandSessionId(201), "right".into()),
            ],
            root: CommandPaneNode::Split(CommandPaneSplit {
                id: CommandPaneSplitId(1),
                ratio: 0.5,
                first: Box::new(CommandPaneNode::Leaf(CommandPaneLeaf {
                    group_id: CommandPaneGroupId(10),
                    tab_group: CommandPaneTabGroup {
                        tabs: vec![CommandPaneTab {
                            session_id: CommandSessionId(101),
                        }],
                        active_session: CommandSessionId(101),
                    },
                })),
                second: Box::new(CommandPaneNode::Leaf(CommandPaneLeaf {
                    group_id: CommandPaneGroupId(20),
                    tab_group: CommandPaneTabGroup {
                        tabs: vec![CommandPaneTab {
                            session_id: CommandSessionId(201),
                        }],
                        active_session: CommandSessionId(201),
                    },
                })),
            }),
            focused_group: CommandPaneGroupId(20),
            mode: CommandPaneMode::Pinned,
            last_expanded_mode: CommandPaneMode::Pinned,
            height_ratio: command_pane_default_height_ratio(1_000.0),
            resize_drag: None,
            next_group_id: 21,
            next_split_id: 2,
            next_session_id: 202,
        };
        let mounted_slot_ids = command.rendered_terminal_body_mount_slots();

        assert_eq!(
            command_terminal_surface_focus_states_for_slots(
                ShellFocusTarget::CommandPane,
                &command,
                &mounted_slot_ids,
            )
            .into_iter()
            .map(|(slot_id, focused)| (slot_id.group_id.0, slot_id.session_id.0, focused))
            .collect::<Vec<_>>(),
            vec![(10, 101, false), (20, 201, true)]
        );

        assert!(
            command_terminal_surface_focus_states_for_slots(
                ShellFocusTarget::AgentsPane(WorkspacePaneId(1)),
                &command,
                &mounted_slot_ids,
            )
            .into_iter()
            .all(|(_slot_id, focused)| !focused)
        );
        assert!(
            command_terminal_surface_focus_states_for_slots(
                ShellFocusTarget::BrowserSurface,
                &command,
                &mounted_slot_ids,
            )
            .into_iter()
            .all(|(_slot_id, focused)| !focused)
        );

        command.mode = CommandPaneMode::Collapsed;
        assert!(
            focused_command_terminal_surface_mount_slot(ShellFocusTarget::CommandPane, &command)
                .is_none()
        );
    }

    #[test]
    fn terminal_close_confirm_surface_signatures_are_generic_family_scoped_and_honest() {
        /*
        CDXC:GPUITerminalCloseConfirm 2026-06-23-20:04:
        Close-confirm UI signatures are source-only contract evidence for the enabled generic close action backed by GhosttyKit `needs_confirm_quit`. They must prove Agents and command prompts are family-scoped and privacy-safe without adding app validation, synthetic callbacks, broad fallback removal, logs, persistence, command text, paths, stdout/stderr, terminal content, raw ids, URLs, tokens, or runtime payloads.
        */
        let agents =
            terminal_close_confirm_surface_signature(TerminalCloseConfirmSurfaceFamily::Agents);
        let command =
            terminal_close_confirm_surface_signature(TerminalCloseConfirmSurfaceFamily::Command);

        assert!(agents.family == TerminalCloseConfirmSurfaceFamily::Agents);
        assert!(command.family == TerminalCloseConfirmSurfaceFamily::Command);
        assert!(agents.message != command.message);

        for signature in [agents, command] {
            assert_eq!(signature.badge_label, "Close confirmation");
            assert_eq!(signature.title, "Terminal close requested");
            assert_eq!(signature.keep_open_label, "Keep Open");
            assert_eq!(signature.confirm_action_label, "Close Terminal");
            assert!(signature.confirm_action_enabled);
            assert!(signature.confirm_action_tooltip.contains("terminal"));

            let visible_text = format!(
                "{} {} {} {} {} {} {}",
                signature.family.scope_label(),
                signature.badge_label,
                signature.title,
                signature.message,
                signature.keep_open_label,
                signature.confirm_action_label,
                signature.confirm_action_tooltip,
            );
            assert_text_omits(
                &visible_text,
                &[
                    "private_project_id",
                    "source_private_surface",
                    "session_id",
                    "runtime_session_id",
                    "/Users/madda/private",
                    "https://private.example",
                    "token=secret",
                    "GHOSTEX_SECRET",
                    "rm -rf",
                    "stdout",
                    "stderr",
                    "terminal content",
                ],
            );
        }
    }

