    #[cfg(target_os = "macos")]
    #[test]
    fn command_ghostty_request_close_calls_once_and_keeps_session_pending() {
        let _guard = startup_fake_ghostty_test_lock();
        reset_startup_fake_ghostty_state();
        let mut command = single_tab_command_model(
            CommandPaneGroupId(10),
            CommandSessionId(101),
            "private command",
        );
        let slot_id = command.rendered_terminal_body_mount_slots()[0];
        let ghostty_app = startup_fake_ghostty_app_owner().unwrap();
        let surface = terminal_ghostty_surface::GhosttySurfaceOwner::new(
            &ghostty_app,
            slot_id,
            command_terminal_runtime_session_id(slot_id),
            &startup_surface_config_request_for_test(2.0),
        )
        .unwrap();
        let mut command_surface_owners = HashMap::from([(slot_id, surface)]);
        let mut empty_command_surface_owners = HashMap::new();

        assert!(!request_close_command_terminal_ghostty_surface_if_mounted(
            &command,
            &mut empty_command_surface_owners,
            slot_id,
        ));
        assert!(request_close_command_terminal_ghostty_surface_if_mounted(
            &command,
            &mut command_surface_owners,
            slot_id,
        ));
        assert!(request_close_command_terminal_ghostty_surface_if_mounted(
            &command,
            &mut command_surface_owners,
            slot_id,
        ));
        assert!(!request_close_command_terminal_ghostty_surface_if_mounted(
            &command,
            &mut command_surface_owners,
            CommandTerminalBodyMountSlotId {
                group_id: CommandPaneGroupId(99),
                session_id: CommandSessionId(9901),
            },
        ));

        let mut collapsed_command = single_tab_command_model(
            CommandPaneGroupId(10),
            CommandSessionId(101),
            "collapsed private command",
        );
        collapsed_command.collapse();
        assert!(!request_close_command_terminal_ghostty_surface_if_mounted(
            &collapsed_command,
            &mut command_surface_owners,
            slot_id,
        ));

        assert_eq!(
            startup_fake_ghostty_call_count("ghostty_surface_request_close"),
            1
        );
        assert!(command.session(CommandSessionId(101)).is_some());
        let mut close_confirms = CommandTerminalCloseConfirmState::new();
        assert!(!consume_confirmed_command_terminal_ghostty_surface_closes(
            &mut command,
            &mut close_confirms,
            &command_surface_owners,
        ));
        assert!(command.session(CommandSessionId(101)).is_some());
    }

