    #[cfg(target_os = "macos")]
    #[test]
    fn command_ghostty_close_confirm_state_tracks_exact_current_slot_and_waits_for_callback() {
        let _guard = startup_fake_ghostty_test_lock();
        reset_startup_fake_ghostty_state();
        let mut command = single_tab_command_model(
            CommandPaneGroupId(10),
            CommandSessionId(101),
            "confirm command",
        );
        let slot_id = command.rendered_terminal_body_mount_slots()[0];
        let ghostty_app = startup_fake_ghostty_app_owner().unwrap();
        let surface = terminal_ghostty_surface::GhosttySurfaceOwner::new(
            &ghostty_app,
            slot_id,
            command_terminal_runtime_session_id(slot_id),
            &startup_surface_config_request_for_test(2.0),
        )
        .unwrap();
        surface.simulate_runtime_close_callback_for_test(true);
        let command_surface_owners = HashMap::from([(slot_id, surface)]);
        let mut close_confirms = CommandTerminalCloseConfirmState::new();

        assert!(
            close_confirms
                .sync_from_confirmation_needed_callbacks(&command, &command_surface_owners,)
        );
        assert!(close_confirms.has_pending(slot_id));
        assert_eq!(close_confirms.pending_count(), 1);
        assert!(
            pending_command_terminal_close_confirm_for_slot(
                &command,
                &command_surface_owners,
                slot_id,
            )
            .is_some()
        );
        assert!(
            !command_surface_owners
                .get(&slot_id)
                .unwrap()
                .confirmation_needed_close_pending_for_test()
        );

        assert!(close_confirms.confirm(&mut command, &command_surface_owners, slot_id));
        assert!(command.session(CommandSessionId(101)).is_none());
        assert!(!close_confirms.has_pending(slot_id));
        assert_eq!(
            startup_fake_ghostty_call_count("ghostty_surface_needs_confirm_quit"),
            3
        );
    }

