    #[cfg(target_os = "macos")]
    #[test]
    fn command_ghostty_confirmed_close_removes_only_matching_command_session() {
        let _guard = startup_fake_ghostty_test_lock();
        reset_startup_fake_ghostty_state();
        let mut command =
            single_tab_command_model(CommandPaneGroupId(10), CommandSessionId(101), "left");
        let (right_group_id, right_session_id) =
            command.split_session_to_right_of_focused_group().unwrap();
        let left_slot_id = CommandTerminalBodyMountSlotId {
            group_id: CommandPaneGroupId(10),
            session_id: CommandSessionId(101),
        };
        let right_slot_id = CommandTerminalBodyMountSlotId {
            group_id: right_group_id,
            session_id: right_session_id,
        };
        let command_mount_slot_bounds =
            HashMap::from([(right_slot_id, focus_test_bounds(20.0, 40.0, 600.0, 300.0))]);
        let startup_body_slot_id = AgentsTerminalStartupBodySlotId {
            pane_id: WorkspacePaneId(99),
            session_id: TerminalSessionId(9901),
        };
        let startup_body_geometries = HashMap::from([(
            startup_body_slot_id,
            AgentsTerminalStartupBodyGeometry {
                bounds: focus_test_bounds(1.0, 2.0, 3.0, 4.0),
                scale_factor: 2.0,
            },
        )]);
        let agents_model = single_tab_workspace_model(
            WorkspacePaneId(20),
            TerminalSessionId(201),
            TerminalSessionPresentationState::Running,
        );
        let agents_slot_id = agents_model.rendered_terminal_body_mount_slots()[0];
        let ghostty_app = startup_fake_ghostty_app_owner().unwrap();
        let left_surface = terminal_ghostty_surface::GhosttySurfaceOwner::new(
            &ghostty_app,
            left_slot_id,
            command_terminal_runtime_session_id(left_slot_id),
            &startup_surface_config_request_for_test(2.0),
        )
        .unwrap();
        let right_surface = terminal_ghostty_surface::GhosttySurfaceOwner::new(
            &ghostty_app,
            right_slot_id,
            command_terminal_runtime_session_id(right_slot_id),
            &startup_surface_config_request_for_test(2.0),
        )
        .unwrap();
        let agents_surface = terminal_ghostty_surface::GhosttySurfaceOwner::new(
            &ghostty_app,
            agents_slot_id,
            AgentsTerminalRuntimeSessionId(42),
            &startup_surface_config_request_for_test(2.0),
        )
        .unwrap();
        left_surface.simulate_runtime_close_callback_for_test(false);
        let command_surface_owners =
            HashMap::from([(left_slot_id, left_surface), (right_slot_id, right_surface)]);
        let agents_surface_owners = HashMap::from([(agents_slot_id, agents_surface)]);

        let mut close_confirms = CommandTerminalCloseConfirmState::new();
        assert!(consume_confirmed_command_terminal_ghostty_surface_closes(
            &mut command,
            &mut close_confirms,
            &command_surface_owners,
        ));

        assert!(command.session(CommandSessionId(101)).is_none());
        assert!(command.session(right_session_id).is_some());
        assert_eq!(
            command_mount_slot_tuples(&command),
            vec![(right_group_id.0, right_session_id.0)]
        );
        assert_eq!(command_surface_owners.len(), 2);
        assert!(command_surface_owners.contains_key(&right_slot_id));
        assert!(command_mount_slot_bounds.contains_key(&right_slot_id));
        assert!(agents_model.session(TerminalSessionId(201)).is_some());
        assert!(agents_surface_owners.contains_key(&agents_slot_id));
        assert!(startup_body_geometries.contains_key(&startup_body_slot_id));
    }

