    fn terminal_text_input_keystroke(key_char: Option<&str>, modifiers: Modifiers) -> Keystroke {
        Keystroke {
            modifiers,
            key: "physical-key-must-not-forward".to_string(),
            key_char: key_char.map(ToOwned::to_owned),
        }
    }

