        let missing = terminal_text_input_keystroke(None, Modifiers::none());
        assert!(committed_terminal_text_from_keystroke(&missing).is_none());

        let empty = terminal_text_input_keystroke(Some(""), Modifiers::none());
        assert!(committed_terminal_text_from_keystroke(&empty).is_none());

