    #[test]
    fn terminal_committed_text_event_helper_does_not_fall_back_to_key() {
        let committed_text = "\u{00e9}";
        let committed_event = KeyDownEvent {
            keystroke: terminal_text_input_keystroke(Some(committed_text), Modifiers::none()),
            is_held: false,
            prefer_character_input: false,
        };
        assert_eq!(
            committed_terminal_text_from_key_down_event(&committed_event),
            Some(committed_text)
        );

        let physical_only_event = KeyDownEvent {
            keystroke: terminal_text_input_keystroke(None, Modifiers::none()),
            is_held: false,
            prefer_character_input: true,
        };
        assert!(committed_terminal_text_from_key_down_event(&physical_only_event).is_none());

        let platform_physical_only_event = KeyDownEvent {
            keystroke: terminal_text_input_keystroke(
                None,
                Modifiers {
                    platform: true,
                    ..Default::default()
                },
            ),
            is_held: false,
            prefer_character_input: false,
        };
        assert!(
            committed_terminal_text_from_key_down_event(&platform_physical_only_event).is_none()
        );

        let control_physical_only_event = KeyDownEvent {
            keystroke: terminal_text_input_keystroke(
                None,
                Modifiers {
                    control: true,
                    ..Default::default()
                },
            ),
            is_held: false,
            prefer_character_input: false,
        };
        assert!(
            committed_terminal_text_from_key_down_event(&control_physical_only_event).is_none()
        );
    }

