    #[test]
    fn agents_terminal_surface_focus_states_move_between_two_mounted_surfaces_without_dropping_slots()
     {
        let model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(101, TerminalSessionPresentationState::Running),
                workspace_session(201, TerminalSessionPresentationState::Running),
            ],
            root: WorkspaceNode::Split(WorkspaceSplit {
                id: WorkspaceSplitId(1),
                axis: WorkspaceSplitAxis::Horizontal,
                ratio: 0.5,
                first: Box::new(workspace_leaf_node(10, &[101], 101)),
                second: Box::new(workspace_leaf_node(20, &[201], 201)),
            }),
            focused_pane: WorkspacePaneId(10),
            focus_mode_pane: None,
            next_pane_id: 21,
            next_split_id: 2,
            next_session_id: 202,
        };
        let mounted_slot_ids = model.rendered_terminal_body_mount_slots();

        assert_eq!(
            agents_surface_focus_state_tuples(
                &model,
                TitlebarMode::Agents,
                ShellFocusTarget::AgentsPane(WorkspacePaneId(10)),
                &mounted_slot_ids,
            ),
            vec![(10, 101, true), (20, 201, false)]
        );
        assert_eq!(
            agents_surface_focus_state_tuples(
                &model,
                TitlebarMode::Agents,
                ShellFocusTarget::AgentsPane(WorkspacePaneId(20)),
                &mounted_slot_ids,
            ),
            vec![(10, 101, false), (20, 201, true)]
        );
        assert_eq!(
            mounted_slot_ids
                .iter()
                .map(|slot_id| (slot_id.pane_id.0, slot_id.session_id.0))
                .collect::<Vec<_>>(),
            vec![(10, 101), (20, 201)]
        );
    }

