    #[cfg(target_os = "macos")]
    #[test]
    fn agents_ghostty_close_confirm_state_tracks_exact_current_slot_and_waits_for_callback() {
        let _guard = startup_fake_ghostty_test_lock();
        reset_startup_fake_ghostty_state();
        let mut model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(101, TerminalSessionPresentationState::Running),
                workspace_session(102, TerminalSessionPresentationState::Running),
            ],
            root: workspace_leaf_node(10, &[101, 102], 101),
            focused_pane: WorkspacePaneId(10),
            focus_mode_pane: None,
            next_pane_id: 11,
            next_split_id: 1,
            next_session_id: 103,
        };
        let mut runtime_registry = AgentsTerminalRuntimeSessionRegistry::new();
        runtime_registry.reconcile_with_workspace(&model);
        let slot_id = model.rendered_terminal_body_mount_slots()[0];
        let runtime_session_id = runtime_registry
            .runtime_session_id_for_shell_session(slot_id.session_id)
            .unwrap();
        let ghostty_app = startup_fake_ghostty_app_owner().unwrap();
        let surface = terminal_ghostty_surface::GhosttySurfaceOwner::new(
            &ghostty_app,
            slot_id,
            runtime_session_id,
            &startup_surface_config_request_for_test(2.0),
        )
        .unwrap();
        surface.simulate_runtime_close_callback_for_test(true);
        let running_surface_owners = HashMap::from([(slot_id, surface)]);
        let mut close_confirms = AgentsTerminalCloseConfirmState::new();

        assert!(close_confirms.sync_from_confirmation_needed_callbacks(
            &model,
            &runtime_registry,
            &running_surface_owners,
        ));
        assert!(close_confirms.has_pending(slot_id));
        assert_eq!(close_confirms.pending_count(), 1);
        assert!(
            pending_agents_terminal_close_confirm_for_slot(
                &model,
                &runtime_registry,
                &running_surface_owners,
                slot_id,
            )
            .is_some()
        );
        assert!(
            !running_surface_owners
                .get(&slot_id)
                .unwrap()
                .confirmation_needed_close_pending_for_test()
        );

        assert!(close_confirms.confirm(
            &mut model,
            &runtime_registry,
            &running_surface_owners,
            slot_id,
        ));
        assert!(model.session(TerminalSessionId(101)).is_none());
        assert!(!close_confirms.has_pending(slot_id));
        assert_eq!(
            workspace_leaf_session_ids(&model, WorkspacePaneId(10)),
            vec![102]
        );
        assert_eq!(
            startup_fake_ghostty_call_count("ghostty_surface_needs_confirm_quit"),
            3
        );
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn agents_ghostty_close_confirm_cancel_clears_pending_without_closing_session() {
        let _guard = startup_fake_ghostty_test_lock();
        reset_startup_fake_ghostty_state();
        let model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(101, TerminalSessionPresentationState::Running),
                workspace_session(102, TerminalSessionPresentationState::Running),
            ],
            root: workspace_leaf_node(10, &[101, 102], 101),
            focused_pane: WorkspacePaneId(10),
            focus_mode_pane: None,
            next_pane_id: 11,
            next_split_id: 1,
            next_session_id: 103,
        };
        let mut runtime_registry = AgentsTerminalRuntimeSessionRegistry::new();
        runtime_registry.reconcile_with_workspace(&model);
        let slot_id = model.rendered_terminal_body_mount_slots()[0];
        let runtime_session_id = runtime_registry
            .runtime_session_id_for_shell_session(slot_id.session_id)
            .unwrap();
        let ghostty_app = startup_fake_ghostty_app_owner().unwrap();
        let mut surface = terminal_ghostty_surface::GhosttySurfaceOwner::new(
            &ghostty_app,
            slot_id,
            runtime_session_id,
            &startup_surface_config_request_for_test(2.0),
        )
        .unwrap();
        assert!(surface.request_close());
        surface.simulate_runtime_close_callback_for_test(true);
        let mut running_surface_owners = HashMap::from([(slot_id, surface)]);
        let mut close_confirms = AgentsTerminalCloseConfirmState::new();
        assert!(close_confirms.sync_from_confirmation_needed_callbacks(
            &model,
            &runtime_registry,
            &running_surface_owners,
        ));

        assert!(close_confirms.cancel(
            &model,
            &runtime_registry,
            &mut running_surface_owners,
            slot_id,
        ));
        assert!(
            running_surface_owners
                .get_mut(&slot_id)
                .unwrap()
                .request_close()
        );

        assert!(!close_confirms.has_pending(slot_id));
        assert_eq!(close_confirms.pending_count(), 0);
        assert!(model.session(TerminalSessionId(101)).is_some());
        assert_eq!(
            workspace_leaf_session_ids(&model, WorkspacePaneId(10)),
            vec![101, 102]
        );
        assert_eq!(agents_mount_slot_tuples(&model), vec![(10, 101)]);
        assert_eq!(
            startup_fake_ghostty_call_count("ghostty_surface_request_close"),
            2
        );
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn agents_ghostty_close_confirm_ignores_stale_inactive_mismatched_and_final_root_surfaces() {
        let _guard = startup_fake_ghostty_test_lock();
        reset_startup_fake_ghostty_state();
        let model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(101, TerminalSessionPresentationState::Running),
                workspace_session(102, TerminalSessionPresentationState::Running),
            ],
            root: workspace_leaf_node(10, &[101, 102], 101),
            focused_pane: WorkspacePaneId(10),
            focus_mode_pane: None,
            next_pane_id: 11,
            next_split_id: 1,
            next_session_id: 103,
        };
        let mut runtime_registry = AgentsTerminalRuntimeSessionRegistry::new();
        runtime_registry.reconcile_with_workspace(&model);
        let current_slot_id = AgentsTerminalBodyMountSlotId {
            pane_id: WorkspacePaneId(10),
            session_id: TerminalSessionId(101),
        };
        let inactive_slot_id = AgentsTerminalBodyMountSlotId {
            pane_id: WorkspacePaneId(10),
            session_id: TerminalSessionId(102),
        };
        let stale_slot_id = AgentsTerminalBodyMountSlotId {
            pane_id: WorkspacePaneId(99),
            session_id: TerminalSessionId(9901),
        };
        let ghostty_app = startup_fake_ghostty_app_owner().unwrap();
        let wrong_current_surface = terminal_ghostty_surface::GhosttySurfaceOwner::new(
            &ghostty_app,
            inactive_slot_id,
            runtime_registry
                .runtime_session_id_for_shell_session(inactive_slot_id.session_id)
                .unwrap(),
            &startup_surface_config_request_for_test(2.0),
        )
        .unwrap();
        wrong_current_surface.simulate_runtime_close_callback_for_test(true);
        let inactive_surface = terminal_ghostty_surface::GhosttySurfaceOwner::new(
            &ghostty_app,
            inactive_slot_id,
            runtime_registry
                .runtime_session_id_for_shell_session(inactive_slot_id.session_id)
                .unwrap(),
            &startup_surface_config_request_for_test(2.0),
        )
        .unwrap();
        inactive_surface.simulate_runtime_close_callback_for_test(true);
        let stale_surface = terminal_ghostty_surface::GhosttySurfaceOwner::new(
            &ghostty_app,
            stale_slot_id,
            AgentsTerminalRuntimeSessionId(9901),
            &startup_surface_config_request_for_test(2.0),
        )
        .unwrap();
        stale_surface.simulate_runtime_close_callback_for_test(true);
        let running_surface_owners = HashMap::from([
            (current_slot_id, wrong_current_surface),
            (inactive_slot_id, inactive_surface),
            (stale_slot_id, stale_surface),
        ]);
        let mut close_confirms = AgentsTerminalCloseConfirmState::new();

        assert!(!close_confirms.sync_from_confirmation_needed_callbacks(
            &model,
            &runtime_registry,
            &running_surface_owners,
        ));

        assert_eq!(close_confirms.pending_count(), 0);
        assert!(model.session(TerminalSessionId(101)).is_some());
        assert!(model.session(TerminalSessionId(102)).is_some());
        assert_eq!(agents_mount_slot_tuples(&model), vec![(10, 101)]);

        let final_root_model = single_tab_workspace_model(
            WorkspacePaneId(20),
            TerminalSessionId(201),
            TerminalSessionPresentationState::Running,
        );
        let mut final_root_registry = AgentsTerminalRuntimeSessionRegistry::new();
        final_root_registry.reconcile_with_workspace(&final_root_model);
        let final_root_slot_id = final_root_model.rendered_terminal_body_mount_slots()[0];
        let final_root_surface = terminal_ghostty_surface::GhosttySurfaceOwner::new(
            &ghostty_app,
            final_root_slot_id,
            final_root_registry
                .runtime_session_id_for_shell_session(final_root_slot_id.session_id)
                .unwrap(),
            &startup_surface_config_request_for_test(2.0),
        )
        .unwrap();
        final_root_surface.simulate_runtime_close_callback_for_test(true);
        let final_root_surfaces = HashMap::from([(final_root_slot_id, final_root_surface)]);
        assert!(!close_confirms.sync_from_confirmation_needed_callbacks(
            &final_root_model,
            &final_root_registry,
            &final_root_surfaces,
        ));
        assert_eq!(close_confirms.pending_count(), 0);
        assert!(final_root_model.session(TerminalSessionId(201)).is_some());
    }

