    #[test]
    fn agents_native_terminal_surface_host_plans_all_visible_running_slots_exact_bounds() {
        let model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(101, TerminalSessionPresentationState::Running),
                workspace_session(201, TerminalSessionPresentationState::Running),
            ],
            root: WorkspaceNode::Split(WorkspaceSplit {
                id: WorkspaceSplitId(1),
                axis: WorkspaceSplitAxis::Horizontal,
                ratio: 0.5,
                first: Box::new(workspace_leaf_node(10, &[101], 101)),
                second: Box::new(workspace_leaf_node(20, &[201], 201)),
            }),
            focused_pane: WorkspacePaneId(10),
            focus_mode_pane: None,
            next_pane_id: 21,
            next_split_id: 2,
            next_session_id: 202,
        };
        let current_slots = model.rendered_terminal_body_mount_slots();
        let left_slot_id = current_slots[0];
        let right_slot_id = current_slots[1];
        let left_bounds = focus_test_bounds(12.0, 24.0, 640.0, 360.0);
        let right_bounds = focus_test_bounds(700.0, 24.0, 640.0, 360.0);
        let recorded_bounds =
            HashMap::from([(left_slot_id, left_bounds), (right_slot_id, right_bounds)]);
        let mut host = NativeTerminalSurfaceHost::new();

        let commands = host.sync_visible_agents_slots(true, &current_slots, &recorded_bounds);
        let left_plan = host.active_plan_for(left_slot_id).unwrap();
        let right_plan = host.active_plan_for(right_slot_id).unwrap();

        assert!(left_plan.slot_id == left_slot_id);
        assert!(
            left_plan.host_id
                == terminal_surface_host::NativeTerminalSurfaceHostId::from_slot_id(left_slot_id)
        );
        assert!(left_plan.bounds == left_bounds);
        assert!(right_plan.slot_id == right_slot_id);
        assert!(
            right_plan.host_id
                == terminal_surface_host::NativeTerminalSurfaceHostId::from_slot_id(right_slot_id)
        );
        assert!(right_plan.bounds == right_bounds);
        assert!(host.active_plans() == vec![left_plan, right_plan]);
        assert!(commands.len() == 2);
        assert!(matches!(
            commands[0],
            terminal_surface_host::NativeTerminalSurfaceHostCommand::AttachOrShow {
                plan: command_plan
            } if command_plan == left_plan
        ));
        assert!(matches!(
            commands[1],
            terminal_surface_host::NativeTerminalSurfaceHostCommand::AttachOrShow {
                plan: command_plan
            } if command_plan == right_plan
        ));
    }

    #[test]
    fn agents_native_terminal_surface_host_clears_stale_state_for_sleeping_or_missing_focus() {
        let running_model = single_tab_workspace_model(
            WorkspacePaneId(40),
            TerminalSessionId(401),
            TerminalSessionPresentationState::Running,
        );
        let running_slots = running_model.rendered_terminal_body_mount_slots();
        let stale_slot_id = running_slots[0];
        let stale_bounds =
            terminal_mount_bounds_map(stale_slot_id, focus_test_bounds(10.0, 20.0, 300.0, 200.0));
        let mut host = NativeTerminalSurfaceHost::new();
        let attach_commands = host.sync_visible_agents_slots(true, &running_slots, &stale_bounds);
        let stale_plan = host.active_plan().unwrap();
        let mut lifecycle = terminal_surface_lifecycle::NativeTerminalSurfaceLifecycleState::new();
        lifecycle.reconcile_host_commands(&attach_commands);

        let sleeping_model = single_tab_workspace_model(
            WorkspacePaneId(40),
            TerminalSessionId(401),
            TerminalSessionPresentationState::Sleeping,
        );
        let sleeping_commands = host.sync_visible_agents_slots(
            true,
            &sleeping_model.rendered_terminal_body_mount_slots(),
            &stale_bounds,
        );
        assert!(sleeping_commands.len() == 1);
        assert!(matches!(
            sleeping_commands[0],
            terminal_surface_host::NativeTerminalSurfaceHostCommand::HideAndDetach { plan }
                if plan == stale_plan
        ));
        assert!(host.active_plan().is_none());
        let sleeping_decisions = lifecycle.reconcile_host_commands(&sleeping_commands);
        assert!(sleeping_decisions.is_empty());
        assert!(lifecycle.active_plan().is_none());

        let missing_model = WorkspaceModel {
            terminal_sessions: Vec::new(),
            root: workspace_leaf_node(50, &[501], 501),
            focused_pane: WorkspacePaneId(50),
            focus_mode_pane: None,
            next_pane_id: 51,
            next_split_id: 1,
            next_session_id: 502,
        };
        assert!(
            host.sync_visible_agents_slots(
                true,
                &missing_model.rendered_terminal_body_mount_slots(),
                &stale_bounds,
            )
            .is_empty()
        );
        assert!(host.active_plan().is_none());

        let mut missing_host = NativeTerminalSurfaceHost::new();
        let mut missing_lifecycle =
            terminal_surface_lifecycle::NativeTerminalSurfaceLifecycleState::new();
        let missing_attach_commands =
            missing_host.sync_visible_agents_slots(true, &running_slots, &stale_bounds);
        missing_lifecycle.reconcile_host_commands(&missing_attach_commands);
        let missing_commands = missing_host.sync_visible_agents_slots(
            true,
            &missing_model.rendered_terminal_body_mount_slots(),
            &stale_bounds,
        );
        let missing_decisions = missing_lifecycle.reconcile_host_commands(&missing_commands);

        assert!(matches!(
            missing_commands.as_slice(),
            [terminal_surface_host::NativeTerminalSurfaceHostCommand::HideAndDetach { plan }]
                if *plan == stale_plan
        ));
        assert!(missing_decisions.is_empty());
        assert!(missing_lifecycle.active_plan().is_none());

        let no_slot_model = WorkspaceModel {
            terminal_sessions: vec![workspace_session(
                701,
                TerminalSessionPresentationState::Running,
            )],
            root: workspace_leaf_node(70, &[701], 701),
            focused_pane: WorkspacePaneId(999),
            focus_mode_pane: None,
            next_pane_id: 71,
            next_split_id: 1,
            next_session_id: 702,
        };
        let mut no_slot_host = NativeTerminalSurfaceHost::new();
        let mut no_slot_lifecycle =
            terminal_surface_lifecycle::NativeTerminalSurfaceLifecycleState::new();
        let no_slot_attach_commands =
            no_slot_host.sync_visible_agents_slots(true, &running_slots, &stale_bounds);
        no_slot_lifecycle.reconcile_host_commands(&no_slot_attach_commands);
        let no_slot_commands = no_slot_host.sync_visible_agents_slots(
            true,
            &no_slot_model.rendered_terminal_body_mount_slots(),
            &stale_bounds,
        );
        let no_slot_decisions = no_slot_lifecycle.reconcile_host_commands(&no_slot_commands);

        assert!(matches!(
            no_slot_commands.as_slice(),
            [terminal_surface_host::NativeTerminalSurfaceHostCommand::HideAndDetach { plan }]
                if *plan == stale_plan
        ));
        assert!(no_slot_decisions.is_empty());
        assert!(no_slot_lifecycle.active_plan().is_none());
    }

    #[test]
    fn agents_native_terminal_surface_host_clears_stale_lifecycle_when_active_mode_is_not_agents() {
        let running_model = single_tab_workspace_model(
            WorkspacePaneId(60),
            TerminalSessionId(601),
            TerminalSessionPresentationState::Running,
        );
        let running_slots = running_model.rendered_terminal_body_mount_slots();
        let slot_id = running_slots[0];
        let bounds =
            terminal_mount_bounds_map(slot_id, focus_test_bounds(40.0, 50.0, 500.0, 260.0));
        let mut host = NativeTerminalSurfaceHost::new();
        let mut lifecycle = terminal_surface_lifecycle::NativeTerminalSurfaceLifecycleState::new();
        let attach_commands = host.sync_visible_agents_slots(true, &running_slots, &bounds);
        lifecycle.reconcile_host_commands(&attach_commands);
        let stale_plan = host.active_plan().unwrap();
        let active_mode = TitlebarMode::Browser;

        let hidden_commands = host.sync_visible_agents_slots(
            active_mode == TitlebarMode::Agents,
            &running_slots,
            &HashMap::new(),
        );
        let hidden_decisions = lifecycle.reconcile_host_commands(&hidden_commands);

        assert!(matches!(
            hidden_commands.as_slice(),
            [terminal_surface_host::NativeTerminalSurfaceHostCommand::HideAndDetach { plan }]
                if *plan == stale_plan
        ));
        assert!(hidden_decisions.is_empty());
        assert!(host.active_plan().is_none());
        assert!(lifecycle.active_plan().is_none());
    }

    #[test]
    fn agents_native_terminal_surface_host_identity_changes_with_selected_running_tab_and_adds_visible_slot()
     {
        let mut model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(101, TerminalSessionPresentationState::Running),
                workspace_session(102, TerminalSessionPresentationState::Running),
                workspace_session(201, TerminalSessionPresentationState::Running),
            ],
            root: WorkspaceNode::Split(WorkspaceSplit {
                id: WorkspaceSplitId(1),
                axis: WorkspaceSplitAxis::Horizontal,
                ratio: 0.5,
                first: Box::new(workspace_leaf_node(10, &[101, 102], 101)),
                second: Box::new(workspace_leaf_node(20, &[201], 201)),
            }),
            focused_pane: WorkspacePaneId(10),
            focus_mode_pane: None,
            next_pane_id: 21,
            next_split_id: 2,
            next_session_id: 202,
        };
        let mut host = NativeTerminalSurfaceHost::new();
        let mut recorded_bounds = HashMap::new();

        let first_slot = model.rendered_terminal_body_mount_slots()[0];
        recorded_bounds.insert(first_slot, focus_test_bounds(0.0, 0.0, 400.0, 300.0));
        host.sync_visible_agents_slots(
            true,
            &model.rendered_terminal_body_mount_slots(),
            &recorded_bounds,
        );
        let first_plan = host.active_plan().unwrap();

        model.select_tab(WorkspacePaneId(10), TerminalSessionId(102));
        let selected_tab_slot = model.rendered_terminal_body_mount_slots()[0];
        recorded_bounds.insert(selected_tab_slot, focus_test_bounds(0.0, 0.0, 400.0, 300.0));
        let selected_tab_commands = host.sync_visible_agents_slots(
            true,
            &model.rendered_terminal_body_mount_slots(),
            &recorded_bounds,
        );
        let selected_tab_plan = host.active_plan().unwrap();
        assert!(selected_tab_commands.len() == 2);
        assert!(matches!(
            selected_tab_commands[0],
            terminal_surface_host::NativeTerminalSurfaceHostCommand::HideAndDetach { plan }
                if plan == first_plan
        ));
        assert!(matches!(
            selected_tab_commands[1],
            terminal_surface_host::NativeTerminalSurfaceHostCommand::AttachOrShow { plan }
                if plan == selected_tab_plan
        ));
        assert!(selected_tab_plan.host_id != first_plan.host_id);
        assert!(selected_tab_plan.slot_id == selected_tab_slot);

        let right_slot = model.rendered_terminal_body_mount_slots()[1];
        recorded_bounds.insert(right_slot, focus_test_bounds(420.0, 0.0, 400.0, 300.0));
        let visible_slot_commands = host.sync_visible_agents_slots(
            true,
            &model.rendered_terminal_body_mount_slots(),
            &recorded_bounds,
        );
        let right_plan = host.active_plan_for(right_slot).unwrap();
        assert!(visible_slot_commands.len() == 2);
        assert!(matches!(
            visible_slot_commands[0],
            terminal_surface_host::NativeTerminalSurfaceHostCommand::NoOp { plan }
                if plan == selected_tab_plan
        ));
        assert!(matches!(
            visible_slot_commands[1],
            terminal_surface_host::NativeTerminalSurfaceHostCommand::AttachOrShow { plan }
                if plan == right_plan
        ));
        assert!(right_plan.host_id != selected_tab_plan.host_id);
        assert!(right_plan.slot_id == right_slot);
        assert!(host.active_plans() == vec![selected_tab_plan, right_plan]);
    }

    #[test]
    fn agents_native_terminal_surface_host_includes_non_focused_visible_running_leaves() {
        let model = WorkspaceModel {
            terminal_sessions: vec![
                workspace_session(101, TerminalSessionPresentationState::Running),
                workspace_session(201, TerminalSessionPresentationState::Running),
            ],
            root: WorkspaceNode::Split(WorkspaceSplit {
                id: WorkspaceSplitId(1),
                axis: WorkspaceSplitAxis::Horizontal,
                ratio: 0.5,
                first: Box::new(workspace_leaf_node(10, &[101], 101)),
                second: Box::new(workspace_leaf_node(20, &[201], 201)),
            }),
            focused_pane: WorkspacePaneId(10),
            focus_mode_pane: None,
            next_pane_id: 21,
            next_split_id: 2,
            next_session_id: 202,
        };
        let focused_slot = model.rendered_terminal_body_mount_slots()[0];
        let non_focused_slot = AgentsTerminalBodyMountSlotId {
            pane_id: WorkspacePaneId(20),
            session_id: TerminalSessionId(201),
        };
        let mut recorded_bounds = HashMap::from([(
            non_focused_slot,
            focus_test_bounds(500.0, 0.0, 400.0, 300.0),
        )]);
        let mut host = NativeTerminalSurfaceHost::new();

        let non_focused_commands = host.sync_visible_agents_slots(
            true,
            &model.rendered_terminal_body_mount_slots(),
            &recorded_bounds,
        );
        let non_focused_plan = host.active_plan_for(non_focused_slot).unwrap();
        assert!(matches!(
            non_focused_commands.as_slice(),
            [terminal_surface_host::NativeTerminalSurfaceHostCommand::AttachOrShow { plan }]
                if *plan == non_focused_plan
        ));

        recorded_bounds.insert(focused_slot, focus_test_bounds(0.0, 0.0, 400.0, 300.0));
        let commands = host.sync_visible_agents_slots(
            true,
            &model.rendered_terminal_body_mount_slots(),
            &recorded_bounds,
        );
        let focused_plan = host.active_plan_for(focused_slot).unwrap();
        assert!(matches!(
            commands.as_slice(),
            [
                terminal_surface_host::NativeTerminalSurfaceHostCommand::AttachOrShow { plan: left_plan },
                terminal_surface_host::NativeTerminalSurfaceHostCommand::NoOp { plan: right_plan },
            ] if *left_plan == focused_plan && *right_plan == non_focused_plan
        ));
        assert!(host.active_plans() == vec![focused_plan, non_focused_plan]);
    }

