    #[test]
    fn command_close_selects_neighbors_collapses_empty_branch_and_final_panel() {
        let mut model = CommandPaneModel::shell_default(1_000.0);

        assert_eq!(
            command_group_active_session_id(&model, CommandPaneGroupId(1)),
            Some(1)
        );
        assert!(model.close_session(CommandPaneGroupId(1), CommandSessionId(1)));
        assert_eq!(
            command_group_session_ids(&model, CommandPaneGroupId(1)),
            vec![2]
        );
        assert_eq!(
            command_group_active_session_id(&model, CommandPaneGroupId(1)),
            Some(2)
        );
        assert_eq!(model.focused_group.0, 1);
        assert!(model.has_sessions());
        assert!(model.is_expanded());

        let (split_group, split_session) = model.split_session_to_right_of_focused_group().unwrap();
        assert_eq!(split_group.0, 2);
        assert_eq!(split_session.0, 3);
        assert_eq!(command_group_order_ids(&model), vec![1, 2]);
        assert_eq!(model.focused_group.0, 2);

        assert!(model.close_session(split_group, split_session));
        assert_eq!(command_group_order_ids(&model), vec![1]);
        assert_eq!(model.focused_group.0, 1);
        assert!(matches!(&model.root, CommandPaneNode::Leaf(_)));
        assert!(model.is_expanded());

        assert!(model.close_active_session());
        assert!(!model.has_sessions());
        assert!(!model.is_expanded());
        assert!(matches!(model.mode, CommandPaneMode::Collapsed));
        assert_eq!(model.focused_group.0, 0);
        assert!(matches!(
            &model.root,
            CommandPaneNode::Leaf(leaf)
                if leaf.group_id.0 == 0 && leaf.tab_group.tabs.is_empty()
        ));
    }

    #[test]
    fn agents_workspace_shell_state_round_trip_preserves_layout_without_terminal_content() {
        let model = WorkspaceModel {
            terminal_sessions: vec![
                TerminalSession::placeholder(
                    TerminalSessionId(41),
                    "Private deploy terminal /Users/madda/private".to_string(),
                    TerminalSessionPresentationState::Running,
                )
                .with_activity(AgentTerminalActivity::Working),
                TerminalSession::placeholder(
                    TerminalSessionId(42),
                    "stderr: secret build output".to_string(),
                    TerminalSessionPresentationState::Sleeping,
                )
                .with_activity(AgentTerminalActivity::Attention),
                TerminalSession::placeholder(
                    TerminalSessionId(43),
                    "cat /Users/madda/project/private.txt".to_string(),
                    TerminalSessionPresentationState::RestoredUnmounted,
                )
                .with_delayed_send_active(true),
                TerminalSession::placeholder(
                    TerminalSessionId(44),
                    "launch --cwd /Users/madda/private-app".to_string(),
                    TerminalSessionPresentationState::Mounting,
                ),
            ],
            root: WorkspaceNode::Split(WorkspaceSplit {
                id: WorkspaceSplitId(7),
                axis: WorkspaceSplitAxis::Vertical,
                ratio: 0.37,
                first: Box::new(WorkspaceNode::Leaf(WorkspaceLeaf {
                    pane_id: WorkspacePaneId(21),
                    tab_group: WorkspaceTabGroup {
                        tabs: vec![
                            WorkspaceTab {
                                session_id: TerminalSessionId(41),
                            },
                            WorkspaceTab {
                                session_id: TerminalSessionId(42),
                            },
                        ],
                        active_tab: TerminalSessionId(42),
                    },
                })),
                second: Box::new(WorkspaceNode::Leaf(WorkspaceLeaf {
                    pane_id: WorkspacePaneId(22),
                    tab_group: WorkspaceTabGroup {
                        tabs: vec![
                            WorkspaceTab {
                                session_id: TerminalSessionId(43),
                            },
                            WorkspaceTab {
                                session_id: TerminalSessionId(44),
                            },
                        ],
                        active_tab: TerminalSessionId(44),
                    },
                })),
            }),
            focused_pane: WorkspacePaneId(22),
            focus_mode_pane: Some(WorkspacePaneId(22)),
            next_pane_id: 30,
            next_split_id: 11,
            next_session_id: 50,
        };

        let state = workspace_model_to_shell_state_json(&model);
        let persisted = shell_state_text(&state);
        assert!(persisted.contains("\"activity\":\"working\""));
        assert!(persisted.contains("\"activity\":\"attention\""));
        assert!(persisted.contains("\"delayedSendActive\":true"));
        assert!(persisted.contains("\"presentationState\":\"mounting\""));
        assert_text_omits(
            &persisted,
            &[
                "Private deploy terminal",
                "stderr: secret build output",
                "cat /Users/madda/project/private.txt",
                "launch --cwd /Users/madda/private-app",
                "/Users/madda",
                "stdout",
                "stderr",
                "commandText",
                "workingDirectory",
                "envVars",
                "initialInput",
                "processId",
                "runtimeSessionId",
                "ghosttySurfaceConfig",
                "GhosttySurfaceConfigRequest",
                "GhosttySurfaceLaunchPayload",
                "GhosttySurfaceLaunchEnvVar",
                "GhosttySurfaceLaunchPayloadField",
                "GhosttySurfacePreparedConfig",
                "ghostty_surface_config_s",
                "launch_payload",
                "launchPayload",
                "launch_env_var_count",
                "launchEnvVarCount",
                "content",
                "title",
            ],
        );

        let decoded: serde_json::Value = serde_json::from_str(&persisted).unwrap();
        let restored = workspace_model_from_shell_state(&decoded).unwrap();

        assert_eq!(
            restored
                .leaf_order()
                .into_iter()
                .map(|pane_id| pane_id.0)
                .collect::<Vec<_>>(),
            vec![21, 22]
        );
        assert_eq!(
            restored
                .rendered_leaf_order()
                .into_iter()
                .map(|pane_id| pane_id.0)
                .collect::<Vec<_>>(),
            vec![22]
        );
        let WorkspaceNode::Split(split) = &restored.root else {
            panic!("expected restored Agents workspace split root");
        };
        assert_eq!(split.id.0, 7);
        assert!(matches!(split.axis, WorkspaceSplitAxis::Vertical));
        assert_f32_close(split.ratio, 0.37);
        assert_eq!(restored.focused_pane.0, 22);
        assert_eq!(restored.focus_mode_pane.map(|pane_id| pane_id.0), Some(22));
        assert_eq!(restored.next_pane_id, 30);
        assert_eq!(restored.next_split_id, 11);
        assert_eq!(restored.next_session_id, 50);

        let left = restored.find_leaf(WorkspacePaneId(21)).unwrap();
        assert_eq!(left.tab_group.active_tab.0, 42);
        assert_eq!(
            workspace_leaf_session_ids(&restored, WorkspacePaneId(21)),
            vec![41, 42]
        );
        let right = restored.find_leaf(WorkspacePaneId(22)).unwrap();
        assert_eq!(right.tab_group.active_tab.0, 44);
        assert_eq!(
            workspace_leaf_session_ids(&restored, WorkspacePaneId(22)),
            vec![43, 44]
        );

        for (
            session_id,
            expected_title,
            expected_state,
            expected_activity,
            expected_delayed_send_active,
            expected_tab_status,
        ) in [
            (
                TerminalSessionId(41),
                "Terminal 41",
                TerminalSessionPresentationState::Running,
                AgentTerminalActivity::Working,
                false,
                AgentTerminalTabStatus::Working,
            ),
            (
                TerminalSessionId(42),
                "Terminal 42",
                TerminalSessionPresentationState::Sleeping,
                AgentTerminalActivity::Attention,
                false,
                AgentTerminalTabStatus::Attention,
            ),
            (
                TerminalSessionId(43),
                "Terminal 43",
                TerminalSessionPresentationState::RestoredUnmounted,
                AgentTerminalActivity::Idle,
                true,
                AgentTerminalTabStatus::DelayedSend,
            ),
            (
                TerminalSessionId(44),
                "Terminal 44",
                TerminalSessionPresentationState::Mounting,
                AgentTerminalActivity::Idle,
                false,
                AgentTerminalTabStatus::Idle,
            ),
        ] {
            let session = restored.session(session_id).unwrap();
            assert_eq!(session.title, expected_title);
            assert!(session.presentation_state == expected_state);
            assert!(session.activity == expected_activity);
            assert_eq!(session.delayed_send_active, expected_delayed_send_active);
            assert!(session.tab_status() == expected_tab_status);
        }
        /*
        CDXC:GPUITerminalActivationRuntimeGuard 2026-06-23-18:00:
        Restored shell-state Mounting is presentation only because startup eligibility and parked owner ownership are runtime-only. A persisted wake/reattach state must not become a new startup candidate or claim a parked owner after app restart.

        CDXC:GPUITerminalActivationRuntimeGuard 2026-06-23-18:12:
        Slice 229 asserts the restored-Mounting edge directly in the round-trip privacy test so persisted shell presentation cannot be confused with a new terminal startup or an in-process failed-startup retry.
        */
        assert!(
            restored
                .visible_selected_mounting_startup_candidates()
                .is_empty()
        );
        assert!(restored.rendered_terminal_startup_body_slots().is_empty());
    }

