    #[test]
    fn browser_shell_state_round_trip_sanitizes_urls_history_and_runtime_metadata() {
        let loaded_url =
            "https://sensitive_user:sensitive_pass@example.com/docs?private_token=abc#private_frag";
        let blocked_url = "file:///Users/madda/private-project/index.html?token=local#frag";
        let favicon_data_url = concat!(
            "data:image/png;base64,",
            "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/p9sAAAAASUVORK5CYII="
        );
        let favicon_fetch_url = "https://cdn.example.test/icon.png?secret_favicon_token=1#icon";
        let model = BrowserTabModel {
            tabs: vec![
                BrowserTab {
                    id: BrowserTabId(100),
                    profile_id: BrowserProfileId(9),
                    title: "Runtime fallback should be regenerated".to_string(),
                    runtime_page_title: Some("Private account dashboard title".to_string()),
                    runtime_favicon_url: Some(favicon_fetch_url.to_string()),
                    runtime_favicon_image: browser_favicon_image_from_data_url(favicon_data_url),
                    runtime_favicon_fetch: Some(BrowserFaviconFetchSource {
                        url: favicon_fetch_url.to_string(),
                    }),
                    url: loaded_url.to_string(),
                    state: BrowserTabState::Loaded,
                    navigation_history: BrowserNavigationHistory {
                        entries: vec![
                            "https://history_user:history_pass@alpha.example/start?history_token=1#history_frag"
                                .to_string(),
                            loaded_url.to_string(),
                        ],
                        current_index: Some(1),
                    },
                },
                BrowserTab {
                    id: BrowserTabId(101),
                    profile_id: BrowserProfileId(10),
                    title: "Local file title".to_string(),
                    runtime_page_title: Some("Local private page".to_string()),
                    runtime_favicon_url: Some("custom-scheme://icon/private".to_string()),
                    runtime_favicon_image: None,
                    runtime_favicon_fetch: Some(BrowserFaviconFetchSource {
                        url: "custom-scheme://icon/private".to_string(),
                    }),
                    url: blocked_url.to_string(),
                    state: BrowserTabState::Loaded,
                    navigation_history: BrowserNavigationHistory::loaded(blocked_url),
                },
            ],
            root: BrowserNode::Leaf(BrowserLeaf {
                pane_id: BrowserPaneId(5),
                tab_group: BrowserTabGroup {
                    tabs: vec![
                        BrowserPaneTab {
                            tab_id: BrowserTabId(100),
                        },
                        BrowserPaneTab {
                            tab_id: BrowserTabId(101),
                        },
                    ],
                    active_tab: BrowserTabId(100),
                },
            }),
            focused_pane: BrowserPaneId(5),
            active_tab: BrowserTabId(100),
            next_pane_id: 6,
            next_split_id: 3,
            next_tab_id: 102,
        };

        let persisted = shell_state_text(&browser_tab_model_to_shell_state_json(&model));
        assert_text_omits(
            &persisted,
            &[
                "sensitive_user",
                "sensitive_pass",
                "private_token",
                "private_frag",
                "history_user",
                "history_pass",
                "history_token",
                "history_frag",
                "Private account dashboard title",
                "Runtime fallback should be regenerated",
                "Local private page",
                "secret_favicon_token",
                "favicon",
                "file://",
                "custom-scheme",
                "/Users/madda/private-project",
                "profileId",
                "Profile 9",
                "Profile 10",
                "?",
                "#",
                "@",
            ],
        );

        let decoded: serde_json::Value = serde_json::from_str(&persisted).unwrap();
        let restored = browser_tab_model_from_shell_state(&decoded, BrowserProfileId(3)).unwrap();
        assert_eq!(restored.focused_pane.0, 5);
        assert_eq!(restored.active_tab.0, 100);
        assert_eq!(
            browser_leaf_tab_ids(&restored, BrowserPaneId(5)),
            vec![100, 101]
        );

        let restored_loaded = restored.tab(BrowserTabId(100)).unwrap();
        assert!(restored_loaded.state == BrowserTabState::Loaded);
        assert_eq!(restored_loaded.profile_id, BrowserProfileId(3));
        assert_eq!(restored_loaded.url, "https://example.com/docs");
        assert_eq!(restored_loaded.title, "example.com");
        assert!(restored_loaded.runtime_page_title.is_none());
        assert!(restored_loaded.runtime_favicon_url.is_none());
        assert!(restored_loaded.runtime_favicon_image.is_none());
        assert!(restored_loaded.runtime_favicon_fetch.is_none());
        assert_eq!(
            restored_loaded.navigation_history.entries,
            vec![
                "https://alpha.example/start".to_string(),
                "https://example.com/docs".to_string()
            ]
        );
        assert_eq!(restored_loaded.navigation_history.current_index, Some(1));

        let restored_blocked = restored.tab(BrowserTabId(101)).unwrap();
        assert!(restored_blocked.state == BrowserTabState::AddressOnly);
        assert_eq!(restored_blocked.profile_id, BrowserProfileId(3));
        assert!(restored_blocked.url.is_empty());
        assert!(restored_blocked.runtime_page_title.is_none());
        assert!(restored_blocked.runtime_favicon_url.is_none());
        assert!(restored_blocked.runtime_favicon_image.is_none());
        assert!(restored_blocked.runtime_favicon_fetch.is_none());
        assert!(restored_blocked.navigation_history.entries.is_empty());
        assert!(restored_blocked.navigation_history.current_index.is_none());
    }

    #[test]
    fn command_pane_shell_state_round_trip_preserves_layout_without_command_content() {
        let model = CommandPaneModel {
            terminal_sessions: vec![
                CommandTerminalSession::placeholder(
                    CommandSessionId(30),
                    "deploy --token api_secret /Users/madda/private".to_string(),
                )
                .with_activity(CommandTerminalActivity::Working),
                CommandTerminalSession::placeholder(
                    CommandSessionId(31),
                    "stdout: private command output".to_string(),
                )
                .with_activity(CommandTerminalActivity::Attention),
                CommandTerminalSession::placeholder(
                    CommandSessionId(32),
                    "stderr: private failure".to_string(),
                )
                .with_activity(CommandTerminalActivity::Working)
                .with_delayed_send_active(true),
            ],
            root: CommandPaneNode::Split(CommandPaneSplit {
                id: CommandPaneSplitId(4),
                ratio: 0.64,
                first: Box::new(CommandPaneNode::Leaf(CommandPaneLeaf {
                    group_id: CommandPaneGroupId(7),
                    tab_group: CommandPaneTabGroup {
                        tabs: vec![
                            CommandPaneTab {
                                session_id: CommandSessionId(30),
                            },
                            CommandPaneTab {
                                session_id: CommandSessionId(31),
                            },
                        ],
                        active_session: CommandSessionId(31),
                    },
                })),
                second: Box::new(CommandPaneNode::Leaf(CommandPaneLeaf {
                    group_id: CommandPaneGroupId(8),
                    tab_group: CommandPaneTabGroup {
                        tabs: vec![CommandPaneTab {
                            session_id: CommandSessionId(32),
                        }],
                        active_session: CommandSessionId(32),
                    },
                })),
            }),
            focused_group: CommandPaneGroupId(8),
            mode: CommandPaneMode::Collapsed,
            last_expanded_mode: CommandPaneMode::Floating,
            height_ratio: 0.42,
            resize_drag: None,
            next_group_id: 9,
            next_split_id: 5,
            next_session_id: 33,
        };

        let persisted = shell_state_text(&command_pane_model_to_shell_state_json(&model));
        assert!(persisted.contains("\"activity\":\"working\""));
        assert!(persisted.contains("\"activity\":\"attention\""));
        assert!(persisted.contains("\"delayedSendActive\":true"));
        assert_text_omits(
            &persisted,
            &[
                "deploy --token",
                "api_secret",
                "/Users/madda/private",
                "private command output",
                "private failure",
                "stdout",
                "stderr",
                "commandText",
                "content",
                "title",
                "deadline",
                "countdown",
            ],
        );

        let decoded: serde_json::Value = serde_json::from_str(&persisted).unwrap();
        let restored = command_pane_model_from_shell_state(&decoded, 1_000.0).unwrap();

        assert!(matches!(restored.mode, CommandPaneMode::Collapsed));
        assert!(matches!(
            restored.last_expanded_mode,
            CommandPaneMode::Floating
        ));
        assert_f32_close(restored.height_ratio, 0.42);
        assert_eq!(restored.focused_group.0, 8);
        assert_eq!(restored.next_group_id, 9);
        assert_eq!(restored.next_split_id, 5);
        assert_eq!(restored.next_session_id, 33);
        assert_eq!(command_group_order_ids(&restored), vec![7, 8]);
        assert_eq!(
            command_group_session_ids(&restored, CommandPaneGroupId(7)),
            vec![30, 31]
        );
        assert_eq!(
            command_group_session_ids(&restored, CommandPaneGroupId(8)),
            vec![32]
        );

        let CommandPaneNode::Split(split) = &restored.root else {
            panic!("expected restored command split root");
        };
        assert_eq!(split.id.0, 4);
        assert_f32_close(split.ratio, 0.64);
        assert_eq!(
            restored
                .find_leaf(CommandPaneGroupId(7))
                .unwrap()
                .tab_group
                .active_session
                .0,
            31
        );
        assert_eq!(
            restored
                .find_leaf(CommandPaneGroupId(8))
                .unwrap()
                .tab_group
                .active_session
                .0,
            32
        );

        for (
            session_id,
            expected_title,
            expected_activity,
            expected_delayed_send_active,
            expected_tab_status,
        ) in [
            (
                CommandSessionId(30),
                "Command 30",
                CommandTerminalActivity::Working,
                false,
                CommandTerminalTabStatus::Working,
            ),
            (
                CommandSessionId(31),
                "Command 31",
                CommandTerminalActivity::Attention,
                false,
                CommandTerminalTabStatus::Attention,
            ),
            (
                CommandSessionId(32),
                "Command 32",
                CommandTerminalActivity::Working,
                true,
                CommandTerminalTabStatus::DelayedSend,
            ),
        ] {
            let session = restored.session(session_id).unwrap();
            assert_eq!(session.title, expected_title);
            assert!(session.activity == expected_activity);
            assert_eq!(session.delayed_send_active, expected_delayed_send_active);
            assert!(session.tab_status() == expected_tab_status);
        }
    }

    #[test]
    fn project_editor_shell_state_round_trip_preserves_lifecycle_without_paths_or_content() {
        let mut model = ProjectEditorShellModel::shell_default();
        model.left_companion_visible = false;
        model.left_companion_width_ratio = 0.47;
        model.source_lifecycle = ProjectEditorModeLifecycle {
            state: ProjectEditorLifecycleState::Sleeping,
            recency: 11,
        };
        model.browser_lifecycle = ProjectEditorModeLifecycle {
            state: ProjectEditorLifecycleState::Awake,
            recency: 12,
        };
        model.kanban_lifecycle = ProjectEditorModeLifecycle {
            state: ProjectEditorLifecycleState::Sleeping,
            recency: 13,
        };
        model.manage_lifecycle = ProjectEditorModeLifecycle {
            state: ProjectEditorLifecycleState::Awake,
            recency: 14,
        };
        model.next_lifecycle_recency = 30;

        let state = project_editor_shell_to_shell_state_json(&model);
        let persisted = shell_state_text(&state);
        assert_text_omits(
            &persisted,
            &[
                "/Users/madda/dev/_active/Ghostex/private-project",
                "secret editor buffer content",
                "projectPath",
                "surfaceContent",
            ],
        );

        let mut decoded: serde_json::Value = serde_json::from_str(&persisted).unwrap();
        let object = decoded.as_object_mut().unwrap();
        object.insert(
            "projectPath".to_string(),
            serde_json::json!("/Users/madda/dev/_active/Ghostex/private-project"),
        );
        object.insert(
            "surfaceContent".to_string(),
            serde_json::json!("secret editor buffer content"),
        );

        let restored =
            project_editor_shell_from_shell_state(&decoded, TitlebarMode::Browser).unwrap();
        assert!(!restored.left_companion_visible);
        assert_f32_close(restored.left_companion_width_ratio, 0.47);
        assert_eq!(restored.next_lifecycle_recency, 30);

        for (mode, expected_state, expected_recency) in [
            (
                TitlebarMode::Source,
                ProjectEditorLifecycleState::Sleeping,
                11,
            ),
            (
                TitlebarMode::Browser,
                ProjectEditorLifecycleState::Awake,
                12,
            ),
            (
                TitlebarMode::Kanban,
                ProjectEditorLifecycleState::Sleeping,
                13,
            ),
            (TitlebarMode::Manage, ProjectEditorLifecycleState::Awake, 14),
        ] {
            let lifecycle = restored.lifecycle(mode).unwrap();
            assert!(lifecycle.state == expected_state);
            assert_eq!(lifecycle.recency, expected_recency);
        }

        let restored_text = shell_state_text(&project_editor_shell_to_shell_state_json(&restored));
        assert_text_omits(
            &restored_text,
            &[
                "/Users/madda/dev/_active/Ghostex/private-project",
                "secret editor buffer content",
                "projectPath",
                "surfaceContent",
            ],
        );
    }

    #[test]
    fn browser_toolbar_feedback_and_profile_actions_are_bounded_and_history_safe() {
        for url in [
            "https://github.com/owner/repo?token=secret#fragment",
            "https://docs.github.com/en/private",
            "https://user:secret@github.com/private",
        ] {
            assert!(
                browser_feedback_tool_unavailable_url(url),
                "expected GitHub feedback action to be disabled for {url}"
            );
        }

        for url in [
            "",
            "about:blank",
            "file:///Users/madda/private.html",
            "http://localhost:3000/private",
            "https://notgithub.com/private",
            "https://github.com.evil.example/private",
        ] {
            assert!(
                !browser_feedback_tool_unavailable_url(url),
                "expected non-GitHub feedback action to remain eligible for injection for {url}"
            );
        }

        let agentation_script = browser_agentation_feedback_injection_script();
        assert!(agentation_script.contains(BROWSER_FEEDBACK_AGENTATION_PACKAGE_MODULE_URL));
        assert!(agentation_script.contains(BROWSER_FEEDBACK_AGENTATION_REACT_MODULE_URL));
        assert!(
            agentation_script.contains(BROWSER_FEEDBACK_AGENTATION_REACT_DOM_CLIENT_MODULE_URL)
        );
        assert!(agentation_script.contains("Start feedback mode"));

        let react_grab_script = browser_react_grab_feedback_injection_script();
        assert!(react_grab_script.contains(BROWSER_FEEDBACK_REACT_GRAB_SCRIPT_URL));
        assert!(react_grab_script.contains(BROWSER_FEEDBACK_REACT_GRAB_SCRIPT_INTEGRITY));
        assert!(react_grab_script.contains("script.integrity = scriptIntegrity"));
        assert!(react_grab_script.contains("react-grab:init"));

        for script in [&agentation_script, &react_grab_script] {
            assert!(!script.contains("console."));
            assert!(!script.contains("window.location"));
            assert!(!script.contains("document.title"));
        }

        let mut profiles = BrowserProfileModel::shell_default();
        assert_eq!(
            profiles.active_profile_id(),
            BrowserProfileId::default_profile()
        );
        assert_eq!(
            profiles.profile_ids().collect::<Vec<_>>(),
            vec![BrowserProfileId::default_profile()]
        );
        let created_profile = profiles.create_generated_profile().unwrap();
        assert_eq!(created_profile, BrowserProfileId(2));
        assert_eq!(created_profile.display_label(), "Profile 2");
        assert_eq!(created_profile.cef_profile_string(), "profile-2");
        assert_eq!(profiles.active_profile_id(), created_profile);
        assert!(profiles.select_profile(BrowserProfileId::default_profile()));
        assert_eq!(
            profiles.active_profile_id(),
            BrowserProfileId::default_profile()
        );
        assert!(!profiles.select_profile(BrowserProfileId(99)));
        assert_eq!(
            BROWSER_IMPORT_UNSUPPORTED_NOTIFICATION,
            "Browser data import is not supported in GPUI yet. No cookies, credentials, or history were imported."
        );

        let profile_state = browser_profile_model_to_shell_state_json(&profiles);
        let profile_state_text = shell_state_text(&profile_state);
        assert!(profile_state_text.contains("\"activeProfileId\":1"));
        assert!(profile_state_text.contains("\"nextProfileId\":3"));
        assert_text_omits(
            &profile_state_text,
            &[
                "Profile 2",
                "/Users/madda/private-profile",
                "cookies.sqlite",
                "Login Data",
                "History",
                "credentials",
            ],
        );
        let restored_profiles = browser_profile_model_from_shell_state(&profile_state).unwrap();
        assert_eq!(
            restored_profiles.profile_ids().collect::<Vec<_>>(),
            vec![BrowserProfileId::default_profile(), BrowserProfileId(2)]
        );
        assert_eq!(
            restored_profiles.active_profile_id(),
            BrowserProfileId::default_profile()
        );

        let first_url = "https://alpha.example/start?private=1#fragment";
        let current_url = "https://example.com/current?token=secret#section";
        let forward_url = "https://beta.example/next";
        let tab_id = BrowserTabId(77);
        let mut model = BrowserTabModel {
            tabs: vec![BrowserTab {
                id: tab_id,
                profile_id: BrowserProfileId::default_profile(),
                title: "Runtime fallback before history jump".to_string(),
                runtime_page_title: Some("Private account title".to_string()),
                runtime_favicon_url: Some(
                    "https://example.com/favicon.ico?token=secret".to_string(),
                ),
                runtime_favicon_image: None,
                runtime_favicon_fetch: Some(BrowserFaviconFetchSource {
                    url: "https://example.com/favicon.ico?token=secret".to_string(),
                }),
                url: current_url.to_string(),
                state: BrowserTabState::Loaded,
                navigation_history: BrowserNavigationHistory {
                    entries: vec![
                        first_url.to_string(),
                        current_url.to_string(),
                        forward_url.to_string(),
                    ],
                    current_index: Some(1),
                },
            }],
            root: BrowserNode::Leaf(BrowserLeaf {
                pane_id: BrowserPaneId(7),
                tab_group: BrowserTabGroup {
                    tabs: vec![BrowserPaneTab { tab_id }],
                    active_tab: tab_id,
                },
            }),
            focused_pane: BrowserPaneId(7),
            active_tab: tab_id,
            next_pane_id: 8,
            next_split_id: 1,
            next_tab_id: 78,
        };

        let rows = model.active_history_rows(BROWSER_HISTORY_MENU_MAX_ROWS);
        assert_eq!(
            rows.iter()
                .map(|row| (row.index, row.is_current))
                .collect::<Vec<_>>(),
            vec![(0, false), (1, true), (2, false)]
        );

        assert!(model.navigate_active_history_to(99).is_none());
        let unchanged_tab = model.tab(tab_id).unwrap();
        assert_eq!(unchanged_tab.url, current_url);
        assert_eq!(unchanged_tab.title, "Runtime fallback before history jump");
        assert_eq!(unchanged_tab.navigation_history.current_index, Some(1));
        assert_eq!(
            unchanged_tab.navigation_history.entries,
            vec![
                first_url.to_string(),
                current_url.to_string(),
                forward_url.to_string()
            ]
        );
        assert_eq!(
            unchanged_tab.runtime_page_title.as_deref(),
            Some("Private account title")
        );
        assert!(unchanged_tab.runtime_favicon_url.is_some());
        assert!(unchanged_tab.runtime_favicon_fetch.is_some());

        assert_eq!(
            model.navigate_active_history_to(0).as_deref(),
            Some(first_url)
        );
        let navigated_tab = model.tab(tab_id).unwrap();
        assert_eq!(navigated_tab.url, first_url);
        assert_eq!(navigated_tab.title, "alpha.example");
        assert_eq!(navigated_tab.navigation_history.current_index, Some(0));
        assert!(navigated_tab.runtime_page_title.is_none());
        assert!(navigated_tab.runtime_favicon_url.is_none());
        assert!(navigated_tab.runtime_favicon_image.is_none());
        assert!(navigated_tab.runtime_favicon_fetch.is_none());
    }

    #[test]
    fn browser_shell_default_uses_static_start_page_only() {
        assert_eq!(browser_shell_default_url(), DEFAULT_BROWSER_URL);

        let model = BrowserTabModel::shell_default();
        assert_eq!(model.tabs.len(), 1);
        assert_eq!(model.active_tab.0, 1);
        assert_eq!(model.focused_pane.0, 1);

        let tab = model
            .active_tab()
            .expect("Browser shell default should create one active tab");
        assert_eq!(tab.id.0, 1);
        assert_eq!(tab.profile_id, BrowserProfileId::default_profile());
        assert_eq!(tab.url, DEFAULT_BROWSER_URL);
        assert_eq!(tab.title, browser_tab_title_for_url(DEFAULT_BROWSER_URL));
        assert!(tab.state == BrowserTabState::Loaded);
        assert_eq!(
            tab.navigation_history.entries,
            vec![DEFAULT_BROWSER_URL.to_string()]
        );
        assert_eq!(tab.navigation_history.current_index, Some(0));
    }

    #[test]
    fn gpui_project_snapshot_contract_accepts_active_project_context() {
        let message = serde_json::json!({
            "version": 1,
            "type": GPUI_SIDEBAR_PROJECT_CONTEXT_MESSAGE_TYPE,
            "activeProject": {
                "activeProjectId": "project_7f4d",
                "displayName": "Private Ghostex Workspace",
                "projectPath": "/Users/madda/private/Ghostex",
                "isQuickProjectless": false,
                "workareaAvailability": {
                    "source": true,
                    "browser": true,
                    "kanban": true,
                    "manage": true,
                },
                "surfaceIds": {
                    "sourceWorkareaId": "source_project_7f4d",
                    "kanbanBoardId": "project-editor:project_7f4d:tasks",
                    "manageWorkspaceId": "project-editor:project_7f4d:manage",
                },
            },
        });

        let snapshot = gpui_project_snapshot_from_sidebar_contract_value(&message).unwrap();

        assert!(snapshot.project_context() == GpuiProjectContext::Project);
        assert_eq!(
            snapshot.active_project_id.as_ref().map(|id| id.0.as_str()),
            Some("project_7f4d")
        );
        assert_eq!(snapshot.display_name, "Private Ghostex Workspace");
        assert_eq!(
            snapshot.in_memory_project_path.as_deref(),
            Some(Path::new("/Users/madda/private/Ghostex"))
        );
        assert!(snapshot.feature_availability.source);
        assert!(snapshot.feature_availability.browser);
        assert!(snapshot.feature_availability.kanban);
        assert!(snapshot.feature_availability.manage);
        assert_eq!(
            snapshot
                .surface_ids
                .source_workarea_id
                .as_ref()
                .map(String::as_str),
            Some("source_project_7f4d")
        );
        assert_eq!(
            snapshot
                .surface_ids
                .kanban_board_id
                .as_ref()
                .map(String::as_str),
            Some("project-editor:project_7f4d:tasks")
        );
        assert_eq!(
            snapshot
                .surface_ids
                .manage_workspace_id
                .as_ref()
                .map(String::as_str),
            Some("project-editor:project_7f4d:manage")
        );

        let availability = snapshot.titlebar_availability(true);
        assert!(availability.titlebar_mode_available(TitlebarMode::Source));
        assert!(availability.titlebar_mode_available(TitlebarMode::Browser));
        assert!(availability.titlebar_mode_available(TitlebarMode::Kanban));
        assert!(availability.titlebar_mode_available(TitlebarMode::Manage));
    }

    #[test]
    fn gpui_project_snapshot_contract_accepts_quick_projectless_context() {
        let message = serde_json::json!({
            "version": 1,
            "type": GPUI_SIDEBAR_PROJECT_CONTEXT_MESSAGE_TYPE,
            "activeProject": {
                "activeProjectId": null,
                "displayName": "Quick",
                "projectPath": null,
                "isQuickProjectless": true,
                "workareaAvailability": {
                    "source": true,
                    "browser": false,
                    "kanban": false,
                    "manage": false,
                },
                "surfaceIds": {},
            },
        });

        let snapshot = gpui_project_snapshot_from_sidebar_contract_value(&message).unwrap();

        assert!(snapshot.project_context() == GpuiProjectContext::QuickProjectless);
        assert!(snapshot.active_project_id.is_none());
        assert_eq!(snapshot.display_name, "Quick");
        assert!(snapshot.in_memory_project_path.is_none());
        assert!(!snapshot.surface_ids.has_any());
        assert!(
            snapshot
                .feature_availability
                .is_quick_projectless_compatible()
        );

        let availability = snapshot.titlebar_availability(true);
        assert!(availability.titlebar_mode_available(TitlebarMode::Agents));
        assert!(availability.titlebar_mode_available(TitlebarMode::Source));
        assert!(!availability.titlebar_mode_available(TitlebarMode::Browser));
        assert!(!availability.titlebar_mode_available(TitlebarMode::Kanban));
        assert!(!availability.titlebar_mode_available(TitlebarMode::Manage));
    }

