    #[test]
    fn phase10_signoff_blocker_ledger_reports_all_current_areas() {
        let blockers = phase10_signoff_blockers();
        let areas = blockers
            .iter()
            .map(|blocker| blocker.area)
            .collect::<Vec<_>>();

        assert_eq!(
            areas.as_slice(),
            &[
                Phase10SignoffBlockerArea::SourceReadinessMount,
                Phase10SignoffBlockerArea::KanbanReadinessMount,
                Phase10SignoffBlockerArea::ManageReadinessMountFileBridge,
                Phase10SignoffBlockerArea::TerminalLifecycleActivationReattach,
                Phase10SignoffBlockerArea::TerminalClipboardPhysicalKeys,
                Phase10SignoffBlockerArea::BrowserImportBlankPopupSuspend,
                Phase10SignoffBlockerArea::ProjectWorkareaPaneEnginePolicy,
                Phase10SignoffBlockerArea::ProjectWorkareaCefSurfaceOwnershipSlots,
                Phase10SignoffBlockerArea::ProjectWorkareaRuntimeUrlIssuanceBoundary,
                Phase10SignoffBlockerArea::ProjectWorkareaSourceStartupNavigationReadinessBoundary,
                Phase10SignoffBlockerArea::ProjectWorkareaSourceRuntimeCefSurfaceOwnerGate,
                Phase10SignoffBlockerArea::ProjectWorkareaKanbanRuntimeCefSurfaceOwnerGate,
                Phase10SignoffBlockerArea::ProjectWorkareaManageRuntimeCefSurfaceOwnerGate,
                Phase10SignoffBlockerArea::CrossSurfaceRuntimeProcessContentTransfer,
                Phase10SignoffBlockerArea::ValidationOutsideAgentWorkflowRecord,
            ][..]
        );

        for blocker in blockers {
            assert!(!blocker.current_evidence.is_empty());
            assert!(!blocker.blocks_current_source_ledger());
            if blocker.blocks_current_source_ledger() {
                assert!(!blocker.missing_gates.is_empty());
            } else {
                assert!(blocker.missing_gates.is_empty());
            }
        }
    }

    #[test]
    fn phase10_signoff_blocker_ledger_keeps_source_ledger_accepted_areas_incomplete() {
        for blocker in phase10_signoff_blockers() {
            assert!(!blocker.is_complete());
            assert!(blocker.status != Phase10SignoffStatus::Complete);
            assert!(!blocker.blocks_current_source_ledger());
            if blocker.blocks_current_source_ledger() {
                assert!(!blocker.missing_gates.is_empty());
            } else {
                assert!(blocker.missing_gates.is_empty());
            }
        }
    }

