    #[test]
    fn source_workarea_runtime_blocks_project_snapshot_without_source_identity() {
        let snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::Project);
        let mut runtime = SourceWorkareaRuntimeState::new();
        runtime.reconcile_active_project(Some(&snapshot));

        assert!(runtime.active_identity.is_none());
        assert!(matches!(
            runtime.availability(Some(&snapshot)),
            SourceWorkareaRuntimeAvailability::Blocked(
                SourceWorkareaRuntimeBlockReason::MissingSourceWorkareaId
            )
        ));

        let persisted = shell_state_text(&runtime.shell_state_privacy_boundary_json());
        assert!(persisted.contains("\"hasActiveIdentity\":false"));
        assert!(persisted.contains("\"bridgeState\":\"missingExplicitBridge\""));
        assert!(persisted.contains("\"hasReadinessBridge\":false"));
        assert!(persisted.contains("\"isReady\":false"));
        assert_text_omits(&persisted, &["project_for_test", "sourceWorkareaId"]);
    }

