    #[test]
    fn source_workarea_runtime_identity_change_clears_runtime_readiness() {
        let mut snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::Project);
        snapshot.active_project_id = Some(GpuiProjectId("private_project_id".to_string()));
        snapshot.surface_ids.source_workarea_id = Some("source_private_surface".to_string());
        let mut runtime = SourceWorkareaRuntimeState::new();
        runtime.reconcile_active_project(Some(&snapshot));
        runtime.readiness_bridge = SourceWorkareaReadinessBridgeState::Ready;
        assert!(matches!(
            runtime.availability(Some(&snapshot)),
            SourceWorkareaRuntimeAvailability::Ready(_)
        ));

        let mut next_snapshot = snapshot.clone();
        next_snapshot.surface_ids.source_workarea_id =
            Some("source_private_next_surface".to_string());
        runtime.reconcile_active_project(Some(&next_snapshot));

        assert!(runtime.active_identity.as_ref().is_some_and(|identity| {
            identity.source_workarea_id.as_str() == "source_private_next_surface"
        }));
        assert!(
            runtime.readiness_bridge == SourceWorkareaReadinessBridgeState::MissingExplicitBridge
        );
        assert!(matches!(
            runtime.availability(Some(&next_snapshot)),
            SourceWorkareaRuntimeAvailability::Blocked(
                SourceWorkareaRuntimeBlockReason::MissingSourceReadinessBridge
            )
        ));

        let persisted = shell_state_text(&runtime.shell_state_privacy_boundary_json());
        assert!(persisted.contains("\"bridgeState\":\"missingExplicitBridge\""));
        assert!(persisted.contains("\"isReady\":false"));
    }

    /*
    CDXC:GPUISourceReadiness 2026-06-23-16:10:
    Source readiness contract tests are source-only boundary evidence. They prove future readiness can enter only as exact active-project/source identity plus enum state, and they must not add URL/path/code-server payloads, CEF mounts, persistence/logging of private details, localhost probing, fallback readiness, or placeholder replacement.
    */
    #[test]
    fn source_workarea_readiness_contract_accepts_strict_identity_only_payload() {
        let message = serde_json::json!({
            "version": GPUI_SOURCE_READINESS_MESSAGE_VERSION,
            "type": GPUI_SOURCE_READINESS_MESSAGE_TYPE,
            "activeProjectId": "private_project_id",
            "sourceWorkareaId": "source_private_surface",
            "state": "ready",
        });

        let parsed = source_workarea_readiness_from_contract_value(&message).unwrap();

        assert!(parsed.identity.active_project_id.0.as_str() == "private_project_id");
        assert!(parsed.identity.source_workarea_id == "source_private_surface");
        assert!(parsed.state == SourceWorkareaReadinessBridgeState::Ready);

        let object = message.as_object().unwrap();
        assert_eq!(object.len(), 5);
        for key in object.keys() {
            assert!(
                [
                    "version",
                    "type",
                    "activeProjectId",
                    "sourceWorkareaId",
                    "state"
                ]
                .contains(&key.as_str()),
                "unexpected Source readiness key: {key}"
            );
        }
    }

    #[test]
    fn source_workarea_readiness_contract_rejects_private_or_malformed_payloads_without_store_change()
     {
        let mut snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::Project);
        snapshot.active_project_id = Some(GpuiProjectId("private_project_id".to_string()));
        snapshot.surface_ids.source_workarea_id = Some("source_private_surface".to_string());
        let mut runtime = SourceWorkareaRuntimeState::new();
        runtime.reconcile_active_project(Some(&snapshot));
        runtime.readiness_bridge = SourceWorkareaReadinessBridgeState::Loading;

        assert_eq!(
            store_source_workarea_readiness_from_contract_json(&mut runtime, "{"),
            Err(SourceWorkareaReadinessContractError::MalformedJson)
        );
        assert!(runtime.readiness_bridge == SourceWorkareaReadinessBridgeState::Loading);

        let rejected_messages = [
            serde_json::json!([]),
            serde_json::json!({
                "version": 2,
                "type": GPUI_SOURCE_READINESS_MESSAGE_TYPE,
                "activeProjectId": "private_project_id",
                "sourceWorkareaId": "source_private_surface",
                "state": "ready",
            }),
            serde_json::json!({
                "version": 1,
                "type": "ghostex.gpui.source.unexpected",
                "activeProjectId": "private_project_id",
                "sourceWorkareaId": "source_private_surface",
                "state": "ready",
            }),
            serde_json::json!({
                "version": 1,
                "type": GPUI_SOURCE_READINESS_MESSAGE_TYPE,
                "activeProjectId": "private_project_id",
                "sourceWorkareaId": "source_private_surface",
                "state": "ready",
                "url": true,
            }),
            serde_json::json!({
                "version": 1,
                "type": GPUI_SOURCE_READINESS_MESSAGE_TYPE,
                "activeProjectId": "private_project_id",
                "sourceWorkareaId": "source_private_surface",
                "state": "ready",
                "codeServerUrl": true,
            }),
            serde_json::json!({
                "version": 1,
                "type": GPUI_SOURCE_READINESS_MESSAGE_TYPE,
                "activeProjectId": "private_project_id",
                "sourceWorkareaId": "source_private_surface",
                "state": "missingExplicitBridge",
            }),
            serde_json::json!({
                "version": 1,
                "type": GPUI_SOURCE_READINESS_MESSAGE_TYPE,
                "activeProjectId": null,
                "sourceWorkareaId": "source_private_surface",
                "state": "ready",
            }),
            serde_json::json!({
                "version": 1,
                "type": GPUI_SOURCE_READINESS_MESSAGE_TYPE,
                "sourceWorkareaId": "source_private_surface",
                "state": "ready",
            }),
            serde_json::json!({
                "version": 1,
                "type": GPUI_SOURCE_READINESS_MESSAGE_TYPE,
                "activeProjectId": "private_project_id",
                "state": "ready",
            }),
            serde_json::json!({
                "version": 1,
                "type": GPUI_SOURCE_READINESS_MESSAGE_TYPE,
                "activeProjectId": "",
                "sourceWorkareaId": "source_private_surface",
                "state": "ready",
            }),
            serde_json::json!({
                "version": 1,
                "type": GPUI_SOURCE_READINESS_MESSAGE_TYPE,
                "activeProjectId": "private_project_id",
                "sourceWorkareaId": " ",
                "state": "ready",
            }),
        ];

        for message in rejected_messages {
            let before = runtime.readiness_bridge;
            assert!(
                store_source_workarea_readiness_from_contract_json(
                    &mut runtime,
                    &message.to_string(),
                )
                .is_err(),
                "accepted invalid Source readiness contract: {message}"
            );
            assert!(runtime.readiness_bridge == before);
        }

        let persisted = shell_state_text(&runtime.shell_state_privacy_boundary_json());
        assert!(persisted.contains("\"bridgeState\":\"loading\""));
        assert_text_omits(
            &persisted,
            &[
                "private_project_id",
                "source_private_surface",
                "activeProjectId",
                "sourceWorkareaId",
                "/Users/madda/private",
                "localhost",
                "127.0.0.1",
                "folder=",
                "url",
                "codeServerUrl",
                "CEF",
                "code-server",
            ],
        );
    }

    #[test]
    fn source_workarea_readiness_store_requires_current_explicit_identity_and_keeps_placeholder() {
        let mut snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::Project);
        snapshot.active_project_id = Some(GpuiProjectId("private_project_id".to_string()));
        snapshot.surface_ids.source_workarea_id = Some("source_private_surface".to_string());
        let mut runtime = SourceWorkareaRuntimeState::new();
        runtime.reconcile_active_project(Some(&snapshot));

        assert_eq!(
            store_source_workarea_readiness_from_contract_json(
                &mut runtime,
                &source_readiness_contract_payload_text_for_test(
                    "private_project_id",
                    "source_private_surface",
                    "loading",
                ),
            ),
            Ok(SourceWorkareaReadinessStoreResult::Changed)
        );
        assert!(runtime.readiness_bridge == SourceWorkareaReadinessBridgeState::Loading);
        assert_eq!(
            store_source_workarea_readiness_from_contract_json(
                &mut runtime,
                &source_readiness_contract_payload_text_for_test(
                    "private_project_id",
                    "source_private_surface",
                    "loading",
                ),
            ),
            Ok(SourceWorkareaReadinessStoreResult::Unchanged)
        );

        for (active_project_id, source_workarea_id) in [
            ("stale_project_id", "source_private_surface"),
            ("private_project_id", "stale_source_surface"),
        ] {
            assert_eq!(
                store_source_workarea_readiness_from_contract_json(
                    &mut runtime,
                    &source_readiness_contract_payload_text_for_test(
                        active_project_id,
                        source_workarea_id,
                        "ready",
                    ),
                ),
                Ok(SourceWorkareaReadinessStoreResult::IgnoredStaleIdentity)
            );
            assert!(runtime.readiness_bridge == SourceWorkareaReadinessBridgeState::Loading);
        }

        assert_eq!(
            store_source_workarea_readiness_from_contract_json(
                &mut runtime,
                &source_readiness_contract_payload_text_for_test(
                    "private_project_id",
                    "source_private_surface",
                    "ready",
                ),
            ),
            Ok(SourceWorkareaReadinessStoreResult::Changed)
        );
        assert!(matches!(
            runtime.availability(Some(&snapshot)),
            SourceWorkareaRuntimeAvailability::Ready(_)
        ));

        let availability = runtime.availability(Some(&snapshot));
        let signature = ProjectEditorPlaceholderSignature::for_source_runtime_availability(
            &availability,
        )
        .expect("Source Ready state still renders placeholder until explicit runtime placeholder replacement is permitted");
        assert!(signature.mode == TitlebarMode::Source);
        assert_eq!(signature.title, TitlebarMode::Source.placeholder_title());
        assert_eq!(
            signature.message,
            TitlebarMode::Source.placeholder_message()
        );

        let quick_snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::QuickProjectless);
        let mut quick_runtime = SourceWorkareaRuntimeState::new();
        quick_runtime.reconcile_active_project(Some(&quick_snapshot));
        assert_eq!(
            store_source_workarea_readiness_from_contract_json(
                &mut quick_runtime,
                &source_readiness_contract_payload_text_for_test(
                    "private_project_id",
                    "source_private_surface",
                    "ready",
                ),
            ),
            Ok(SourceWorkareaReadinessStoreResult::MissingActiveIdentity)
        );
        assert!(
            quick_runtime.readiness_bridge
                == SourceWorkareaReadinessBridgeState::MissingExplicitBridge
        );

        let persisted = shell_state_text(&runtime.shell_state_privacy_boundary_json());
        assert!(persisted.contains("\"bridgeState\":\"ready\""));
        assert!(persisted.contains("\"hasReadinessBridge\":true"));
        assert!(persisted.contains("\"isReady\":true"));
        assert_text_omits(
            &persisted,
            &[
                "private_project_id",
                "source_private_surface",
                "activeProjectId",
                "sourceWorkareaId",
                "/Users/madda/private",
                "localhost",
                "127.0.0.1",
                "folder=",
                "url",
                "codeServerUrl",
                "CEF",
                "code-server",
            ],
        );
    }

