    /*
    CDXC:GPUIBrowserWorkareaReadiness 2026-06-23-16:24:
    Browser readiness contract tests are source-only boundary evidence. They prove future readiness can enter only as exact active-project plus exact Browser workarea identity and enum state, while Phase 1 still rejects browserWorkareaId and no URL/title/profile/cookie/history/import/content/failure-detail data, CEF materialization, logging, persistence, fallback probing, or placeholder replacement is introduced.
    */
    #[test]
    fn browser_workarea_readiness_contract_accepts_strict_identity_only_payloads() {
        for (state_text, expected_state) in [
            ("loading", BrowserWorkareaReadinessBridgeState::Loading),
            ("ready", BrowserWorkareaReadinessBridgeState::Ready),
            (
                "loadFailed",
                BrowserWorkareaReadinessBridgeState::LoadFailed,
            ),
        ] {
            let message = serde_json::json!({
                "version": GPUI_BROWSER_WORKAREA_READINESS_MESSAGE_VERSION,
                "type": GPUI_BROWSER_WORKAREA_READINESS_MESSAGE_TYPE,
                "activeProjectId": "private_project_id",
                "browserWorkareaId": "browser_private_surface",
                "state": state_text,
            });

            let parsed = browser_workarea_readiness_from_contract_value(&message).unwrap();

            assert!(parsed.identity.active_project_id.0.as_str() == "private_project_id");
            assert!(parsed.identity.browser_workarea_id == "browser_private_surface");
            assert!(parsed.state == expected_state);

            let object = message.as_object().unwrap();
            assert_eq!(object.len(), 5);
            for key in object.keys() {
                assert!(
                    [
                        "version",
                        "type",
                        "activeProjectId",
                        "browserWorkareaId",
                        "state"
                    ]
                    .contains(&key.as_str()),
                    "unexpected Browser workarea readiness key: {key}"
                );
            }
        }
    }

