    #[test]
    fn browser_workarea_readiness_store_requires_current_identity_and_keeps_phase1_rejection() {
        let mut snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::Project);
        snapshot.active_project_id = Some(GpuiProjectId("private_project_id".to_string()));
        let mut runtime = BrowserWorkareaRuntimeState::new();
        runtime.reconcile_explicit_active_project_identity(
            Some(&snapshot),
            Some("browser_private_surface"),
        );

        assert_eq!(
            store_browser_workarea_readiness_from_contract_json(
                &mut runtime,
                &browser_workarea_readiness_contract_payload_text_for_test(
                    "private_project_id",
                    "browser_private_surface",
                    "loading",
                ),
            ),
            Ok(BrowserWorkareaReadinessStoreResult::Changed)
        );
        assert!(runtime.readiness_bridge == BrowserWorkareaReadinessBridgeState::Loading);
        assert_eq!(
            store_browser_workarea_readiness_from_contract_json(
                &mut runtime,
                &browser_workarea_readiness_contract_payload_text_for_test(
                    "private_project_id",
                    "browser_private_surface",
                    "loading",
                ),
            ),
            Ok(BrowserWorkareaReadinessStoreResult::Unchanged)
        );

        for (active_project_id, browser_workarea_id) in [
            ("stale_project_id", "browser_private_surface"),
            ("private_project_id", "stale_browser_surface"),
        ] {
            assert_eq!(
                store_browser_workarea_readiness_from_contract_json(
                    &mut runtime,
                    &browser_workarea_readiness_contract_payload_text_for_test(
                        active_project_id,
                        browser_workarea_id,
                        "ready",
                    ),
                ),
                Ok(BrowserWorkareaReadinessStoreResult::IgnoredStaleIdentity)
            );
            assert!(runtime.readiness_bridge == BrowserWorkareaReadinessBridgeState::Loading);
        }

        assert_eq!(
            store_browser_workarea_readiness_from_contract_json(
                &mut runtime,
                &browser_workarea_readiness_contract_payload_text_for_test(
                    "private_project_id",
                    "browser_private_surface",
                    "ready",
                ),
            ),
            Ok(BrowserWorkareaReadinessStoreResult::Changed)
        );
        assert!(runtime.readiness_bridge == BrowserWorkareaReadinessBridgeState::Ready);

        let quick_snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::QuickProjectless);
        let mut quick_runtime = BrowserWorkareaRuntimeState::new();
        quick_runtime.reconcile_explicit_active_project_identity(
            Some(&quick_snapshot),
            Some("browser_private_surface"),
        );
        assert_eq!(
            store_browser_workarea_readiness_from_contract_json(
                &mut quick_runtime,
                &browser_workarea_readiness_contract_payload_text_for_test(
                    "private_project_id",
                    "browser_private_surface",
                    "ready",
                ),
            ),
            Ok(BrowserWorkareaReadinessStoreResult::MissingActiveIdentity)
        );
        assert!(
            quick_runtime.readiness_bridge
                == BrowserWorkareaReadinessBridgeState::MissingExplicitBridge
        );

        let mut missing_runtime = BrowserWorkareaRuntimeState::new();
        assert_eq!(
            store_browser_workarea_readiness_from_contract_json(
                &mut missing_runtime,
                &browser_workarea_readiness_contract_payload_text_for_test(
                    "private_project_id",
                    "browser_private_surface",
                    "ready",
                ),
            ),
            Ok(BrowserWorkareaReadinessStoreResult::MissingActiveIdentity)
        );
        assert!(
            missing_runtime.readiness_bridge
                == BrowserWorkareaReadinessBridgeState::MissingExplicitBridge
        );

        let phase1_message_with_browser_id = serde_json::json!({
            "version": 1,
            "type": GPUI_SIDEBAR_PROJECT_CONTEXT_MESSAGE_TYPE,
            "activeProject": {
                "activeProjectId": "private_project_id",
                "displayName": "Private Project",
                "projectPath": null,
                "isQuickProjectless": false,
                "workareaAvailability": {
                    "source": true,
                    "browser": true,
                    "kanban": true,
                    "manage": false,
                },
                "surfaceIds": {
                    "browserWorkareaId": "browser_private_surface",
                },
            },
        });
        assert!(
            gpui_project_snapshot_from_sidebar_contract_value(&phase1_message_with_browser_id)
                .is_err(),
            "Phase 1 active-project snapshot must still reject browserWorkareaId"
        );

        let persisted = shell_state_text(&runtime.shell_state_privacy_boundary_json());
        assert!(persisted.contains("\"bridgeState\":\"ready\""));
        assert!(persisted.contains("\"hasReadinessBridge\":true"));
        assert!(persisted.contains("\"isReady\":true"));
        assert_text_omits(
            &persisted,
            &[
                "private_project_id",
                "browser_private_surface",
                "activeProjectId",
                "browserWorkareaId",
                "https://private.example",
                "/Users/madda",
                "title",
                "profile",
                "cookie",
                "history",
                "import",
                "content",
                "failure",
                "CEF",
            ],
        );
    }

    #[test]
    fn browser_workarea_ready_does_not_materialize_or_replace_cef_surface_policy() {
        let mut snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::Project);
        snapshot.active_project_id = Some(GpuiProjectId("private_project_id".to_string()));
        let mut runtime = BrowserWorkareaRuntimeState::new();
        runtime.reconcile_explicit_active_project_identity(
            Some(&snapshot),
            Some("browser_private_surface"),
        );
        assert_eq!(
            store_browser_workarea_readiness_from_contract_json(
                &mut runtime,
                &browser_workarea_readiness_contract_payload_text_for_test(
                    "private_project_id",
                    "browser_private_surface",
                    "ready",
                ),
            ),
            Ok(BrowserWorkareaReadinessStoreResult::Changed)
        );
        assert!(runtime.readiness_bridge == BrowserWorkareaReadinessBridgeState::Ready);

        let visible_lifecycle = BrowserRuntimeLifecycleInput {
            active_mode: TitlebarMode::Browser,
            browser_awake: true,
            browser_tab_drag_active: false,
            command_tab_drag_active: false,
        };
        let restored_policy = BrowserRuntimeSurfacePolicy::for_tab(
            visible_lifecycle,
            Some(BrowserTabState::Loaded),
            true,
            false,
        );
        assert!(restored_policy == BrowserRuntimeSurfacePolicy::RestoredPlaceholder);
        assert!(!restored_policy.shows_cef_child_view());
        assert!(
            BrowserTabChromeStatus::from_state(BrowserTabState::Loaded, false)
                == BrowserTabChromeStatus::RestoredPlaceholder
        );
        assert!(!BrowserTabChromeStatus::RestoredPlaceholder.allows_runtime_favicon());

        let hidden_policy = BrowserRuntimeSurfacePolicy::for_tab(
            BrowserRuntimeLifecycleInput {
                active_mode: TitlebarMode::Source,
                browser_awake: true,
                browser_tab_drag_active: false,
                command_tab_drag_active: false,
            },
            Some(BrowserTabState::Loaded),
            true,
            true,
        );
        assert!(hidden_policy == BrowserRuntimeSurfacePolicy::HiddenHold);
        assert!(!hidden_policy.shows_cef_child_view());

        let existing_surface_policy = BrowserRuntimeSurfacePolicy::for_tab(
            visible_lifecycle,
            Some(BrowserTabState::Loaded),
            true,
            true,
        );
        assert!(existing_surface_policy == BrowserRuntimeSurfacePolicy::Visible);
        assert!(existing_surface_policy.shows_cef_child_view());
    }

    #[test]
    fn browser_cef_runtime_parity_plan_is_source_only_and_cef_only() {
        /*
        CDXC:GPUIBrowserRuntimeParity 2026-06-24-05:06:
        Browser source-only runtime parity must stay a CEF-only contract. The plan can credit existing tab-owned CEF visibility but must reject WKWebView/WebKit/non-CEF labels and must not broaden source parity into runtime URL issuance, new CEF creation, import, blank-popup content transfer, CEF suspend/teardown, hidden mounts, private logging/persistence, or restored-placeholder replacement.
        */
        let visible_lifecycle = BrowserRuntimeLifecycleInput {
            active_mode: TitlebarMode::Browser,
            browser_awake: true,
            browser_tab_drag_active: false,
            command_tab_drag_active: false,
        };
        let restored_policy = BrowserRuntimeSurfacePolicy::for_tab(
            visible_lifecycle,
            Some(BrowserTabState::Loaded),
            true,
            false,
        );
        let existing_surface_policy = BrowserRuntimeSurfacePolicy::for_tab(
            visible_lifecycle,
            Some(BrowserTabState::Loaded),
            true,
            true,
        );
        let plan = BrowserCefRuntimeParityPlan::from_source_contracts(
            true,
            BrowserDataImportPolicy::for_profile_action_available(true),
            BrowserPopupTargetPolicy::for_target_url(""),
            restored_policy,
            existing_surface_policy,
        )
        .expect("Browser source-only runtime parity should form from CEF-only source contracts");

        assert_eq!(plan.privacy_label(), "sourceOnlyRuntimeParityPlan");
        assert_eq!(plan.web_pane_engine_privacy_label(), "cef");
        assert!(plan.has_cef_only_web_pane_engine_contract());
        assert!(plan.rejects_non_cef_web_pane_engines());
        assert!(plan.counts_as_source_only_runtime_parity());
        assert!(plan.uses_existing_tab_owned_cef_surface_contract());
        assert!(!plan.creates_new_runtime_cef_surface());
        assert!(!plan.issues_runtime_url());
        assert!(!plan.imports_browser_data());
        assert!(!plan.transfers_blank_popup_content());
        assert!(!plan.can_materialize_restored_tab());
        assert!(!plan.can_suspend_or_teardown_cef());
        assert!(!plan.has_hidden_browser_surface_mount());
        assert!(!plan.has_logged_or_persisted_private_details());
        assert_eq!(
            BrowserCefWebPaneEngineContract::from_source_contract_label("cef"),
            Ok(BrowserCefWebPaneEngineContract::Cef)
        );
        for candidate in ["wkwebview", "webkit", "webview", ""] {
            let rejection = BrowserCefWebPaneEngineContract::from_source_contract_label(candidate)
                .expect_err("Browser runtime parity must reject non-CEF web-pane engines");
            assert_eq!(rejection.privacy_label(), "nonCefWebPaneEngineRejected");
        }

        let persisted = shell_state_text(&plan.shell_state_privacy_boundary_json());
        assert!(persisted.contains("\"surface\":\"browser\""));
        assert!(persisted.contains("\"runtimeParityState\":\"sourceOnlyRuntimeParityPlan\""));
        assert!(persisted.contains("\"webPaneEngine\":\"cef\""));
        assert!(persisted.contains("\"hasCefOnlyWebPaneEngineContract\":true"));
        assert!(persisted.contains("\"rejectsNonCefWebPaneEngines\":true"));
        assert!(persisted.contains("\"countsAsSourceOnlyRuntimeParity\":true"));
        assert!(persisted.contains("\"usesExistingTabOwnedCefSurfaceContract\":true"));
        assert!(persisted.contains("\"createsNewRuntimeCefSurface\":false"));
        assert!(persisted.contains("\"issuesRuntimeUrl\":false"));
        assert!(persisted.contains("\"importsBrowserData\":false"));
        assert!(persisted.contains("\"transfersBlankPopupContent\":false"));
        assert!(persisted.contains("\"canMaterializeRestoredTab\":false"));
        assert!(persisted.contains("\"canSuspendOrTeardownCef\":false"));
        assert!(persisted.contains("\"hasHiddenBrowserSurfaceMount\":false"));
        assert!(persisted.contains("\"hasLoggedOrPersistedPrivateDetails\":false"));
        assert_text_omits(
            &persisted,
            &[
                "private_project_id",
                "browser_private_surface",
                "activeProjectId",
                "browserWorkareaId",
                "https://private.example",
                "/Users/madda",
                "token",
                "cookie",
                "history",
                "bookmark",
                "pageTitle",
                "profilePath",
                "cefPayload",
                "openerData",
                "fallback",
            ],
        );
    }

    /*
    CDXC:GPUIProjectWorkareaReadiness 2026-06-23-16:17:
    Kanban/Manage readiness contract tests are source-only boundary evidence. They prove future readiness can enter only as exact active-project plus exact Kanban/Manage surface identity and enum state, without URL/path/file payloads, CEF/file-bridge mounts, file I/O, logging, persistence, fallback probing, failure details, or placeholder replacement.
    */
    #[test]
    fn project_workarea_readiness_contract_accepts_strict_identity_only_payloads() {
        for (surface, expected_kind, state_text, expected_state) in [
            (
                "kanban",
                ProjectScopedRealSurfaceKind::Kanban,
                "mounting",
                ProjectScopedRealSurfaceLifecycleBridgeState::Mounting,
            ),
            (
                "manage",
                ProjectScopedRealSurfaceKind::Manage,
                "ready",
                ProjectScopedRealSurfaceLifecycleBridgeState::Ready,
            ),
        ] {
            let message = serde_json::json!({
                "version": GPUI_PROJECT_WORKAREA_READINESS_MESSAGE_VERSION,
                "type": GPUI_PROJECT_WORKAREA_READINESS_MESSAGE_TYPE,
                "surface": surface,
                "activeProjectId": "private_project_id",
                "surfaceId": "private_surface_id",
                "state": state_text,
            });

            let parsed = project_workarea_readiness_from_contract_value(&message).unwrap();

            assert!(parsed.identity.kind == expected_kind);
            assert!(parsed.identity.kind.readiness_contract_surface() == surface);
            assert!(parsed.identity.active_project_id.0.as_str() == "private_project_id");
            assert!(parsed.identity.explicit_surface_id == "private_surface_id");
            assert!(parsed.state == expected_state);

            let object = message.as_object().unwrap();
            assert_eq!(object.len(), 6);
            for key in object.keys() {
                assert!(
                    [
                        "version",
                        "type",
                        "surface",
                        "activeProjectId",
                        "surfaceId",
                        "state"
                    ]
                    .contains(&key.as_str()),
                    "unexpected project workarea readiness key: {key}"
                );
            }
        }
    }

