    #[test]
    fn kanban_cef_mount_request_contract_blocks_non_ready_or_wrong_surface_inputs() {
        let mut kanban_snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::Project);
        kanban_snapshot.active_project_id = Some(GpuiProjectId("private_project_id".to_string()));
        kanban_snapshot.surface_ids.kanban_board_id =
            Some("project-editor:private_project_id:tasks".to_string());
        let mut kanban_runtime =
            ProjectScopedRealSurfaceRuntimeState::new(ProjectScopedRealSurfaceKind::Kanban);
        kanban_runtime.reconcile_active_project(Some(&kanban_snapshot));

        assert!(matches!(
            kanban_runtime.kanban_cef_mount_request_contract(Some(&kanban_snapshot)),
            KanbanCefMountRequestContract::Blocked(
                KanbanCefMountRequestBlockReason::RuntimeBlocked(
                    ProjectScopedRealSurfaceRuntimeBlockReason::MissingKanbanCefBridge
                )
            )
        ));

        let mut manage_snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::Project);
        manage_snapshot.active_project_id = Some(GpuiProjectId("private_project_id".to_string()));
        manage_snapshot.surface_ids.manage_workspace_id =
            Some("project-editor:private_project_id:manage".to_string());
        let mut manage_runtime =
            ProjectScopedRealSurfaceRuntimeState::new(ProjectScopedRealSurfaceKind::Manage);
        manage_runtime.reconcile_active_project(Some(&manage_snapshot));
        manage_runtime.lifecycle_bridge = ProjectScopedRealSurfaceLifecycleBridgeState::Ready;

        assert!(matches!(
            manage_runtime.kanban_cef_mount_request_contract(Some(&manage_snapshot)),
            KanbanCefMountRequestContract::Blocked(KanbanCefMountRequestBlockReason::WrongSurface)
        ));

        let blocked_privacy = shell_state_text(
            &kanban_runtime
                .kanban_cef_mount_request_contract(Some(&kanban_snapshot))
                .shell_state_privacy_boundary_json(),
        );
        assert!(blocked_privacy.contains("\"surface\":\"kanban\""));
        assert!(blocked_privacy.contains("\"requested\":false"));
        assert!(blocked_privacy.contains("\"blockReason\":\"runtimeBlocked\""));
        assert!(blocked_privacy.contains("\"runtimeParityState\":\"missingRuntimeParityPlan\""));
        assert!(blocked_privacy.contains("\"webPaneEngine\":\"none\""));
        assert!(blocked_privacy.contains("\"hasCefOnlyWebPaneEngineContract\":false"));
        assert!(blocked_privacy.contains("\"rejectsNonCefWebPaneEngines\":false"));
        assert!(blocked_privacy.contains("\"countsAsSourceOnlyRuntimeParity\":false"));
        assert!(blocked_privacy.contains("\"hasRuntimeUrl\":false"));
        assert!(blocked_privacy.contains("\"hasRuntimeCefBrowser\":false"));
        assert!(blocked_privacy.contains("\"hasHiddenKanbanSurfaceMount\":false"));
        assert!(blocked_privacy.contains(
            "\"placeholderReplacementPreflightState\":\"missingKanbanPlaceholderReplacementPreflightGate\""
        ));
        assert!(
            blocked_privacy
                .contains("\"placeholderReplacementPreflightRuntimeParityPlan\":\"none\"")
        );
        assert!(
            blocked_privacy.contains("\"placeholderReplacementPreflightWebPaneEngine\":\"none\"")
        );
        assert!(blocked_privacy.contains("\"hasKanbanPlaceholderReplacementPreflightGate\":false"));
        assert!(
            blocked_privacy.contains(
                "\"placeholderReplacementPreflightHasCefOnlyWebPaneEngineContract\":false"
            )
        );
        assert!(
            blocked_privacy
                .contains("\"placeholderReplacementPreflightRejectsNonCefWebPaneEngines\":false")
        );
        assert!(
            blocked_privacy
                .contains("\"placeholderReplacementPreflightHasIssuedRuntimeUrl\":false")
        );
        assert!(
            blocked_privacy
                .contains("\"placeholderReplacementPreflightHasRuntimeCefBrowser\":false")
        );
        assert!(
            blocked_privacy
                .contains("\"placeholderReplacementPreflightHasNormalLayoutCefSurface\":false")
        );
        assert!(
            blocked_privacy
                .contains("\"placeholderReplacementPreflightHasHiddenKanbanSurfaceMount\":false")
        );
        assert!(
            blocked_privacy
                .contains("\"placeholderReplacementPreflightHasPrivateRuntimeData\":false")
        );
        assert!(blocked_privacy.contains(
            "\"placeholderReplacementPreflightHasPlaceholderReplacementPermission\":false"
        ));
        assert!(blocked_privacy.contains("\"canReplaceKanbanPlaceholder\":false"));
        assert!(blocked_privacy.contains("\"canMountCef\":false"));
        assert_text_omits(
            &blocked_privacy,
            &[
                "private_project_id",
                "project-editor:private_project_id:tasks",
                "activeProjectId",
                "surfaceId",
                "url",
                "path",
                "board",
                "pageTitle",
                "cefPayload",
                "fallback",
            ],
        );
    }

