        assert!(persisted.contains("\"retainsRejectedWebPaneEngineLabels\":false"));
        assert!(persisted.contains("\"instantiatesCef\":false"));
        assert!(persisted.contains("\"startsCodeServer\":false"));
        assert!(persisted.contains("\"mountsFileBridge\":false"));
        assert!(persisted.contains("\"runsFileIo\":false"));
        assert!(persisted.contains("\"createsHiddenSurface\":false"));
        assert!(persisted.contains("\"logsOrPersistsPrivateDetails\":false"));
        assert!(persisted.contains("\"hasPrivateRuntimeData\":false"));
        assert!(persisted.contains("\"hasRuntimeCodeServerProcess\":false"));
        assert!(persisted.contains("\"hasIssuedRuntimeUrl\":false"));
        assert!(persisted.contains("\"hasRuntimeCefBrowser\":false"));
        assert!(persisted.contains("\"hasNormalLayoutCefSurface\":false"));
        assert!(persisted.contains("\"hasRuntimeFileBridge\":false"));
        assert!(persisted.contains("\"hasRunRuntimeFileOperation\":false"));
        assert!(persisted.contains("\"hasCefOrFileBridgePayload\":false"));
        assert!(persisted.contains("\"hasPlaceholderReplacementPermission\":false"));
        assert!(persisted.contains("\"canReplaceAnyPlaceholder\":false"));
        assert!(persisted.contains("\"pane\":\"source\""));
        assert!(persisted.contains("\"pane\":\"browser\""));
        assert!(persisted.contains("\"pane\":\"kanban\""));
