        let source_contract =
            source_runtime.source_cef_code_server_mount_request_contract(Some(&source_snapshot));
        let SourceCefCodeServerMountRequestContract::Requested(source_request) = &source_contract
        else {
            panic!("expected ready Source runtime to form source-only CEF evidence");
        };

        let mut kanban_snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::Project);
        kanban_snapshot.active_project_id = Some(GpuiProjectId("private_project_id".to_string()));
