    #[test]
    fn project_scoped_real_surface_identity_change_clears_runtime_lifecycle() {
        let mut snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::Project);
        snapshot.active_project_id = Some(GpuiProjectId("private_project_id".to_string()));
        snapshot.surface_ids.manage_workspace_id =
            Some("project-editor:private_project_id:manage".to_string());
        let mut runtime =
            ProjectScopedRealSurfaceRuntimeState::new(ProjectScopedRealSurfaceKind::Manage);
        runtime.reconcile_active_project(Some(&snapshot));
        runtime.lifecycle_bridge = ProjectScopedRealSurfaceLifecycleBridgeState::Ready;
        assert!(matches!(
            runtime.availability(Some(&snapshot)),
            ProjectScopedRealSurfaceRuntimeAvailability::Ready(_)
        ));

        let mut next_snapshot = snapshot.clone();
        next_snapshot.active_project_id =
            Some(GpuiProjectId("private_next_project_id".to_string()));
        next_snapshot.surface_ids.manage_workspace_id =
            Some("project-editor:private_next_project_id:manage".to_string());
        runtime.reconcile_active_project(Some(&next_snapshot));

        assert!(runtime.active_identity.as_ref().is_some_and(|identity| {
            identity.active_project_id.0.as_str() == "private_next_project_id"
                && identity.explicit_surface_id.as_str()
                    == "project-editor:private_next_project_id:manage"
        }));
        assert!(
            runtime.lifecycle_bridge
                == ProjectScopedRealSurfaceLifecycleBridgeState::MissingExplicitBridge
        );
        assert!(matches!(
            runtime.availability(Some(&next_snapshot)),
            ProjectScopedRealSurfaceRuntimeAvailability::Blocked(
                ProjectScopedRealSurfaceRuntimeBlockReason::MissingManageCefAndFileBridge
            )
        ));

        let persisted = shell_state_text(&runtime.shell_state_privacy_boundary_json());
        assert!(persisted.contains("\"hasActiveIdentity\":true"));
        assert!(persisted.contains("\"bridgeState\":\"missingExplicitBridge\""));
        assert!(persisted.contains("\"isReady\":false"));
        assert_text_omits(
            &persisted,
            &[
                "private_project_id",
                "project-editor:private_project_id:manage",
                "project-editor:private_next_project_id:manage",
                "manageWorkspaceId",
                "CEF",
                "file bridge",
            ],
        );
    }

    /*
    CDXC:GPUIManageFileWorkareaBridge 2026-06-23-13:58:
    These Phase 7 source-only tests pin the future Manage file/workarea bridge to an operation-kind allowlist. They must not perform file I/O, probe paths, mount CEF, create browser/CEF work, log payloads, persist private values, accept raw paths, accept file names, accept file contents, accept raw command args, accept raw JSON, or introduce fallback operation behavior.

    CDXC:GPUIManageFileWorkareaBridge 2026-06-23-14:02:
    The private-input rejection tests include credential/password/auth/access-key shaped operation names so future diagnostics can distinguish private bridge input from ordinary unknown operations without storing the submitted value.
    */
    #[test]
    fn manage_file_workarea_bridge_policy_accepts_allowlisted_operation_kinds() {
        let allowed_operations = [
            (
                "listWorkareaEntries",
                ManageFileWorkareaBridgeOperationKind::ListWorkareaEntries,
            ),
            (
                "readTextFile",
                ManageFileWorkareaBridgeOperationKind::ReadTextFile,
            ),
            (
                "writeTextFile",
                ManageFileWorkareaBridgeOperationKind::WriteTextFile,
            ),
            (
                "createWorkareaEntry",
                ManageFileWorkareaBridgeOperationKind::CreateWorkareaEntry,
            ),
            (
                "renameWorkareaEntry",
                ManageFileWorkareaBridgeOperationKind::RenameWorkareaEntry,
            ),
            (
                "deleteWorkareaEntry",
                ManageFileWorkareaBridgeOperationKind::DeleteWorkareaEntry,
            ),
            (
                "moveWorkareaEntry",
                ManageFileWorkareaBridgeOperationKind::MoveWorkareaEntry,
            ),
            (
                "searchWorkareaText",
                ManageFileWorkareaBridgeOperationKind::SearchWorkareaText,
            ),
        ];

        for (operation_name, expected_kind) in allowed_operations {
            let decision = manage_file_workarea_bridge_policy_for_operation_name(operation_name);
            assert!(
                decision
                    == ManageFileWorkareaBridgeOperationPolicyDecision::Accepted(expected_kind)
            );

            let safe_json = decision.shell_state_privacy_boundary_json();
            assert_eq!(
                safe_json.get("accepted").and_then(|value| value.as_bool()),
                Some(true)
            );
            assert_eq!(
                safe_json.get("rejected").and_then(|value| value.as_bool()),
                Some(false)
            );
            assert_eq!(
                safe_json
                    .get("operationCount")
                    .and_then(|value| value.as_u64()),
                Some(1)
            );
            assert_eq!(
                safe_json
                    .get("operationKind")
                    .and_then(|value| value.as_str()),
                Some(expected_kind.privacy_label())
            );

            let safe_text = shell_state_text(&safe_json);
            assert_text_omits(
                &safe_text,
                &[
                    "operationName",
                    "submittedValue",
                    "rawValue",
                    "path",
                    "fileName",
                    "content",
                    "payload",
                    "url",
                    "token",
                    "cookie",
                    "stdout",
                    "stderr",
                ],
            );
        }
    }

    #[test]
    fn manage_file_workarea_bridge_policy_rejects_unknown_malformed_and_private_values() {
        let rejected_operations: [(
            &str,
            ManageFileWorkareaBridgeOperationRejectionKind,
            &[&str],
        ); 13] = [
            (
                "",
                ManageFileWorkareaBridgeOperationRejectionKind::MalformedOperationName,
                &[],
            ),
            (
                " readTextFile",
                ManageFileWorkareaBridgeOperationRejectionKind::MalformedOperationName,
                &[" readTextFile"],
            ),
            (
                "readTextFile\n",
                ManageFileWorkareaBridgeOperationRejectionKind::MalformedOperationName,
                &["readTextFile\n"],
            ),
            (
                "openExternal",
                ManageFileWorkareaBridgeOperationRejectionKind::UnknownOperation,
                &["openExternal"],
            ),
            (
                "/Users/madda/private/secret.md",
                ManageFileWorkareaBridgeOperationRejectionKind::PrivateInputRejected,
                &["/Users/madda/private/secret.md", "secret.md"],
            ),
            (
                "notes.md",
                ManageFileWorkareaBridgeOperationRejectionKind::PrivateInputRejected,
                &["notes.md"],
            ),
            (
                "file:///private/secret.md",
                ManageFileWorkareaBridgeOperationRejectionKind::PrivateInputRejected,
                &["file:///private/secret.md", "secret.md"],
            ),
            (
                "readTextFile?path=/private/secret.md&token=abc",
                ManageFileWorkareaBridgeOperationRejectionKind::PrivateInputRejected,
                &[
                    "readTextFile?path=/private/secret.md&token=abc",
                    "path=/private",
                    "token=abc",
                ],
            ),
            (
                "{\"path\":\"/private/secret.md\",\"content\":\"private text\"}",
                ManageFileWorkareaBridgeOperationRejectionKind::PrivateInputRejected,
                &[
                    "{\"path\":\"/private/secret.md\",\"content\":\"private text\"}",
                    "private text",
                ],
            ),
            (
                "credentialBlob",
                ManageFileWorkareaBridgeOperationRejectionKind::PrivateInputRejected,
                &["credentialBlob"],
            ),
            (
                "passwordReset",
                ManageFileWorkareaBridgeOperationRejectionKind::PrivateInputRejected,
                &["passwordReset"],
            ),
            (
                "authorizationHeader",
                ManageFileWorkareaBridgeOperationRejectionKind::PrivateInputRejected,
                &["authorizationHeader"],
            ),
            (
                "accessKeyMaterial",
                ManageFileWorkareaBridgeOperationRejectionKind::PrivateInputRejected,
                &["accessKeyMaterial"],
            ),
        ];

        for (operation_name, expected_rejection, forbidden_values) in rejected_operations {
            let decision = manage_file_workarea_bridge_policy_for_operation_name(operation_name);
            assert!(
                decision
                    == ManageFileWorkareaBridgeOperationPolicyDecision::Rejected(
                        expected_rejection
                    )
            );

            let safe_json = decision.shell_state_privacy_boundary_json();
            assert_eq!(
                safe_json.get("accepted").and_then(|value| value.as_bool()),
                Some(false)
            );
            assert_eq!(
                safe_json.get("rejected").and_then(|value| value.as_bool()),
                Some(true)
            );
            assert_eq!(
                safe_json
                    .get("operationCount")
                    .and_then(|value| value.as_u64()),
                Some(0)
            );
            assert_eq!(
                safe_json
                    .get("rejectionKind")
                    .and_then(|value| value.as_str()),
                Some(expected_rejection.privacy_label())
            );
            assert!(safe_json.get("operationKind").is_none());

            let safe_text = shell_state_text(&safe_json);
            assert_text_omits(&safe_text, forbidden_values);
            assert_text_omits(
                &safe_text,
                &[
                    "operationName",
                    "submittedValue",
                    "rawValue",
                    "fileName",
                    "content",
                    "payload",
                    "url",
                    "token=abc",
                    "cookie",
                    "credentialBlob",
                    "passwordReset",
                    "authorizationHeader",
                    "accessKeyMaterial",
                    "stdout",
                    "stderr",
                ],
            );
        }
    }

    #[test]
    fn manage_file_workarea_bridge_privacy_json_uses_only_safe_decision_keys() {
        let accepted = manage_file_workarea_bridge_policy_for_operation_name("readTextFile")
            .shell_state_privacy_boundary_json();
        let rejected = manage_file_workarea_bridge_policy_for_operation_name(
            "readTextFile?path=/private/secret.md&token=abc",
        )
        .shell_state_privacy_boundary_json();

        for (value, allowed_keys) in [
            (
                &accepted,
                &["accepted", "rejected", "operationCount", "operationKind"][..],
            ),
            (
                &rejected,
                &["accepted", "rejected", "operationCount", "rejectionKind"][..],
            ),
        ] {
            let object = value
                .as_object()
                .expect("privacy boundary json should be an object");
            for key in object.keys() {
                assert!(
                    allowed_keys.contains(&key.as_str()),
                    "unexpected privacy boundary key: {key}"
                );
            }
        }

        let persisted = format!(
            "{}{}",
            shell_state_text(&accepted),
            shell_state_text(&rejected)
        );
        assert_text_omits(
            &persisted,
            &[
                "operationName",
                "submittedValue",
                "rawValue",
                "rawPayloadJson",
                "path=/private",
                "/private/secret.md",
                "secret.md",
                "token=abc",
                "private text",
                "command",
                "stdout",
                "stderr",
                "error detail",
            ],
        );
    }

    /*
    CDXC:GPUIManageFileWorkareaBridge 2026-06-23-16:35:
    Manage operation request tests are source-only boundary evidence. A future file bridge may submit only a strict v1 identity-plus-operation message, and GPUI may record only the privacy-safe allowlist decision for the exact current Manage identity without accepting args, paths, file names, file contents, URLs, command output, secrets, CEF state, bridge/runtime payloads, file I/O, readiness promotion, or placeholder replacement.
    */
    #[test]
    fn manage_file_workarea_operation_request_contract_accepts_strict_identity_and_operation_payloads()
     {
        let allowed_operations = [
            (
                "listWorkareaEntries",
                ManageFileWorkareaBridgeOperationKind::ListWorkareaEntries,
            ),
            (
                "readTextFile",
                ManageFileWorkareaBridgeOperationKind::ReadTextFile,
            ),
            (
                "writeTextFile",
                ManageFileWorkareaBridgeOperationKind::WriteTextFile,
            ),
            (
                "createWorkareaEntry",
                ManageFileWorkareaBridgeOperationKind::CreateWorkareaEntry,
            ),
            (
                "renameWorkareaEntry",
                ManageFileWorkareaBridgeOperationKind::RenameWorkareaEntry,
            ),
            (
                "deleteWorkareaEntry",
                ManageFileWorkareaBridgeOperationKind::DeleteWorkareaEntry,
            ),
            (
                "moveWorkareaEntry",
                ManageFileWorkareaBridgeOperationKind::MoveWorkareaEntry,
            ),
            (
                "searchWorkareaText",
                ManageFileWorkareaBridgeOperationKind::SearchWorkareaText,
            ),
        ];

        for (operation, expected_kind) in allowed_operations {
            let message = serde_json::json!({
                "version": GPUI_MANAGE_FILE_WORKAREA_OPERATION_REQUEST_MESSAGE_VERSION,
                "type": GPUI_MANAGE_FILE_WORKAREA_OPERATION_REQUEST_MESSAGE_TYPE,
                "activeProjectId": "private_project_id",
                "manageWorkspaceId": "project-editor:private_project_id:manage",
                "operation": operation,
            });

            let parsed =
                manage_file_workarea_operation_request_from_contract_value(&message).unwrap();

            assert!(parsed.identity.kind == ProjectScopedRealSurfaceKind::Manage);
            assert!(parsed.identity.active_project_id.0.as_str() == "private_project_id");
            assert!(
                parsed.identity.explicit_surface_id.as_str()
                    == "project-editor:private_project_id:manage"
            );
            assert!(
                parsed.decision
                    == ManageFileWorkareaBridgeOperationPolicyDecision::Accepted(expected_kind)
            );

            let object = message.as_object().unwrap();
            assert_eq!(object.len(), 5);
            for key in object.keys() {
                assert!(
                    [
                        "version",
                        "type",
                        "activeProjectId",
                        "manageWorkspaceId",
                        "operation",
                    ]
                    .contains(&key.as_str()),
                    "unexpected Manage operation request key: {key}"
                );
            }
        }
    }

