    #[test]
    fn manage_file_workarea_operation_request_store_requires_current_manage_identity() {
        let mut manage_snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::Project);
        manage_snapshot.active_project_id = Some(GpuiProjectId("private_project_id".to_string()));
        manage_snapshot.surface_ids.manage_workspace_id =
            Some("project-editor:private_project_id:manage".to_string());
        let mut runtime =
            ProjectScopedRealSurfaceRuntimeState::new(ProjectScopedRealSurfaceKind::Manage);
        runtime.reconcile_active_project(Some(&manage_snapshot));

        assert_eq!(
            store_manage_file_workarea_operation_request_from_contract_json(
                &mut runtime,
                &manage_file_workarea_operation_request_payload_text_for_test(
                    "private_project_id",
                    "project-editor:private_project_id:manage",
                    "writeTextFile",
                ),
            ),
            Ok(ManageFileWorkareaOperationRequestStoreResult::Changed)
        );
        assert!(
            runtime.manage_file_workarea_operation_decision
                == Some(ManageFileWorkareaBridgeOperationPolicyDecision::Accepted(
                    ManageFileWorkareaBridgeOperationKind::WriteTextFile
                ))
        );
        assert_eq!(
            store_manage_file_workarea_operation_request_from_contract_json(
                &mut runtime,
                &manage_file_workarea_operation_request_payload_text_for_test(
                    "private_project_id",
                    "project-editor:private_project_id:manage",
                    "writeTextFile",
                ),
            ),
            Ok(ManageFileWorkareaOperationRequestStoreResult::Unchanged)
        );

        assert_eq!(
            store_manage_file_workarea_operation_request_from_contract_json(
                &mut runtime,
                &manage_file_workarea_operation_request_payload_text_for_test(
                    "private_project_id",
                    "project-editor:private_project_id:manage",
                    "openExternal",
                ),
            ),
            Ok(ManageFileWorkareaOperationRequestStoreResult::Changed)
        );
        assert!(
            runtime.manage_file_workarea_operation_decision
                == Some(ManageFileWorkareaBridgeOperationPolicyDecision::Rejected(
                    ManageFileWorkareaBridgeOperationRejectionKind::UnknownOperation
                ))
        );

        for (active_project_id, manage_workspace_id) in [
            (
                "stale_project_id",
                "project-editor:private_project_id:manage",
            ),
            (
                "private_project_id",
                "project-editor:private_project_id:stale",
            ),
        ] {
            assert_eq!(
                store_manage_file_workarea_operation_request_from_contract_json(
                    &mut runtime,
                    &manage_file_workarea_operation_request_payload_text_for_test(
                        active_project_id,
                        manage_workspace_id,
                        "readTextFile",
                    ),
                ),
                Ok(ManageFileWorkareaOperationRequestStoreResult::IgnoredStaleIdentity)
            );
            assert!(
                runtime.manage_file_workarea_operation_decision
                    == Some(ManageFileWorkareaBridgeOperationPolicyDecision::Rejected(
                        ManageFileWorkareaBridgeOperationRejectionKind::UnknownOperation
                    ))
            );
        }

        let mut no_active_runtime =
            ProjectScopedRealSurfaceRuntimeState::new(ProjectScopedRealSurfaceKind::Manage);
        assert_eq!(
            store_manage_file_workarea_operation_request_from_contract_json(
                &mut no_active_runtime,
                &manage_file_workarea_operation_request_payload_text_for_test(
                    "private_project_id",
                    "project-editor:private_project_id:manage",
                    "readTextFile",
                ),
            ),
            Ok(ManageFileWorkareaOperationRequestStoreResult::MissingActiveIdentity)
        );
        assert!(
            no_active_runtime
                .manage_file_workarea_operation_decision
                .is_none()
        );

        let quick_snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::QuickProjectless);
        let mut quick_runtime =
            ProjectScopedRealSurfaceRuntimeState::new(ProjectScopedRealSurfaceKind::Manage);
        quick_runtime.reconcile_active_project(Some(&quick_snapshot));
        assert_eq!(
            store_manage_file_workarea_operation_request_from_contract_json(
                &mut quick_runtime,
                &manage_file_workarea_operation_request_payload_text_for_test(
                    "private_project_id",
                    "project-editor:private_project_id:manage",
                    "readTextFile",
                ),
            ),
            Ok(ManageFileWorkareaOperationRequestStoreResult::MissingActiveIdentity)
        );
        assert!(
            quick_runtime
                .manage_file_workarea_operation_decision
                .is_none()
        );

        let mut kanban_snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::Project);
        kanban_snapshot.active_project_id = Some(GpuiProjectId("private_project_id".to_string()));
        kanban_snapshot.surface_ids.kanban_board_id =
            Some("project-editor:private_project_id:tasks".to_string());
        let mut kanban_runtime =
            ProjectScopedRealSurfaceRuntimeState::new(ProjectScopedRealSurfaceKind::Kanban);
        kanban_runtime.reconcile_active_project(Some(&kanban_snapshot));
        assert_eq!(
            store_manage_file_workarea_operation_request_from_contract_json(
                &mut kanban_runtime,
                &manage_file_workarea_operation_request_payload_text_for_test(
                    "private_project_id",
                    "project-editor:private_project_id:manage",
                    "readTextFile",
                ),
            ),
            Ok(ManageFileWorkareaOperationRequestStoreResult::IgnoredWrongSurface)
        );
        assert!(
            kanban_runtime
                .manage_file_workarea_operation_decision
                .is_none()
        );
    }

