    #[test]
    fn manage_project_context_routing_requires_real_project_and_open_gate() {
        let quick_snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::QuickProjectless);
        let open_gate_project_fallback =
            ProjectScopedWorkareaAvailability::new(GpuiProjectContext::Project, true);
        let quick_effective = project_scoped_workarea_availability_from_latest_sidebar_snapshot(
            Some(&quick_snapshot),
            open_gate_project_fallback,
        );
        let quick_manage_item = quick_effective
            .titlebar_mode_switcher_items()
            .into_iter()
            .find(|item| item.mode == TitlebarMode::Manage)
            .expect("open Manage gate should expose a disabled Quick/projectless item");

        assert!(!quick_effective.titlebar_mode_available(TitlebarMode::Manage));
        assert!(!quick_manage_item.is_available);
        assert!(
            quick_manage_item.disabled_reason == Some(TITLEBAR_PROJECT_CONTEXT_DISABLED_REASON)
        );
        assert!(
            quick_effective.available_titlebar_mode_or_agents(TitlebarMode::Manage)
                == TitlebarMode::Agents
        );

        let mut quick_runtime =
            ProjectScopedRealSurfaceRuntimeState::new(ProjectScopedRealSurfaceKind::Manage);
        quick_runtime.reconcile_active_project(Some(&quick_snapshot));
        assert!(quick_runtime.active_identity.is_none());
        assert!(matches!(
            quick_runtime.availability(Some(&quick_snapshot)),
            ProjectScopedRealSurfaceRuntimeAvailability::Blocked(
                ProjectScopedRealSurfaceRuntimeBlockReason::QuickProjectlessContext
            )
        ));

        let project_snapshot = gpui_project_snapshot_for_test(GpuiProjectContext::Project);
        let closed_gate_project_fallback =
            ProjectScopedWorkareaAvailability::new(GpuiProjectContext::Project, false);
        let closed_gate_effective =
            project_scoped_workarea_availability_from_latest_sidebar_snapshot(
                Some(&project_snapshot),
                closed_gate_project_fallback,
            );

        assert!(!closed_gate_effective.titlebar_mode_available(TitlebarMode::Manage));
        assert!(
            closed_gate_effective.available_titlebar_mode_or_agents(TitlebarMode::Manage)
                == TitlebarMode::Agents
        );
        assert!(
            closed_gate_effective
                .titlebar_mode_switcher_items()
                .into_iter()
                .all(|item| item.mode != TitlebarMode::Manage)
        );

        let mut closed_gate_snapshot = project_snapshot.clone();
        closed_gate_snapshot.feature_availability.manage = false;
        let mut closed_gate_runtime =
            ProjectScopedRealSurfaceRuntimeState::new(ProjectScopedRealSurfaceKind::Manage);
        closed_gate_runtime.reconcile_active_project(Some(&closed_gate_snapshot));
        assert!(closed_gate_runtime.active_identity.is_none());
        assert!(matches!(
            closed_gate_runtime.availability(Some(&closed_gate_snapshot)),
            ProjectScopedRealSurfaceRuntimeAvailability::Blocked(
                ProjectScopedRealSurfaceRuntimeBlockReason::ManageUnavailableInSnapshot
            )
        ));
    }

