    /*
    CDXC:GPUISettingsAgentsActionsMetadata 2026-06-24-14:09:
    Settings Agents/Actions metadata tests stay pure and exercise only in-memory normalization/state helpers. They must not call gxserver, launch the app, write files, or include real project names, paths, URLs, command text, tokens, stdout, stderr, or user content.
    */
    #[test]
    fn gpui_sidebar_agent_default_delete_hides_and_icon_save_restores_default() {
        let stored_agents = vec![GpuiStoredSidebarAgent {
            accept_all_mode: Some("enabled".to_string()),
            agent_id: "codex".to_string(),
            command: "agent-command-a".to_string(),
            hidden: false,
            icon: Some("codex".to_string()),
            name: "Codex".to_string(),
        }];
        let stored_order = vec!["codex".to_string(), "claude".to_string()];

        let (hidden_agents, hidden_order, _) = gpui_next_sidebar_agent_metadata_state(
            stored_agents,
            stored_order,
            GpuiSidebarAgentMetadataWrite::Delete {
                agent_id: "codex".to_string(),
            },
        )
        .expect("default agent delete should update metadata");

        let hidden_codex = hidden_agents
            .iter()
            .find(|agent| agent.agent_id == "codex")
            .expect("default agent row should remain stored");
        assert!(hidden_codex.hidden);
        assert!(!hidden_order.iter().any(|agent_id| agent_id == "codex"));

        let (restored_agents, _, _) = gpui_next_sidebar_agent_metadata_state(
            hidden_agents,
            hidden_order,
            GpuiSidebarAgentMetadataWrite::Save {
                accept_all_mode: GpuiAgentAcceptAllModeUpdate::Preserve,
                agent_id: None,
                command: "agent-command-b".to_string(),
                icon: Some("codex".to_string()),
                name: "Codex".to_string(),
            },
        )
        .expect("icon save should restore hidden default agent");

        let restored_codex = restored_agents
            .iter()
            .find(|agent| agent.agent_id == "codex")
            .expect("default agent should be restored by id");
        assert!(!restored_codex.hidden);
        assert_eq!(restored_codex.command, "agent-command-b");
        assert!(
            !restored_agents
                .iter()
                .any(|agent| agent.agent_id.starts_with("custom-"))
        );
    }

    #[test]
    fn gpui_sidebar_default_action_save_restores_and_delete_marks_deleted() {
        let (saved_commands, saved_order, saved_deleted, _) =
            gpui_next_sidebar_command_metadata_state(
                Vec::new(),
                Vec::new(),
                vec!["build".to_string()],
                GpuiSidebarCommandMetadataWrite::Save {
                    action_type: "terminal",
                    active_project_id: "project-alpha".to_string(),
                    close_terminal_on_exit: false,
                    command: Some("action-command-a".to_string()),
                    command_id: Some("build".to_string()),
                    icon: None,
                    name: "Build".to_string(),
                    play_completion_sound: true,
                    url: None,
                },
            )
            .expect("default action save should restore a deleted default");

        assert!(!saved_deleted.iter().any(|command_id| command_id == "build"));
        assert!(saved_commands.iter().any(|command| {
            command.command_id == "build"
                && command.is_default
                && command.command.as_deref() == Some("action-command-a")
        }));

        let (deleted_commands, deleted_order, deleted_ids, _) =
            gpui_next_sidebar_command_metadata_state(
                saved_commands,
                saved_order,
                saved_deleted,
                GpuiSidebarCommandMetadataWrite::Delete {
                    active_project_id: "project-alpha".to_string(),
                    command_id: "build".to_string(),
                },
            )
            .expect("default action delete should mark deleted default id");

        assert!(
            !deleted_commands
                .iter()
                .any(|command| command.command_id == "build")
        );
        assert!(!deleted_order.iter().any(|command_id| command_id == "build"));
        assert_eq!(deleted_ids, vec!["build".to_string()]);
    }

    #[test]
    fn gpui_sidebar_worktree_action_state_uses_parent_owner_project() {
        let domain_projects = vec![
            serde_json::json!({
                "projectId": "project-parent",
                "customCommands": [
                    {
                        "actionType": "terminal",
                        "closeTerminalOnExit": false,
                        "command": "action-command-parent",
                        "commandId": "custom-parent",
                        "isDefault": false,
                        "name": "Parent Action",
                        "playCompletionSound": true,
                    }
                ],
                "customCommandOrder": ["custom-parent"],
                "deletedDefaultCommandIds": ["setup"],
            }),
            serde_json::json!({
                "projectId": "project-child",
                "worktree": {
                    "parentProjectId": "project-parent",
                },
                "customCommands": [
                    {
                        "actionType": "terminal",
                        "closeTerminalOnExit": false,
                        "command": "action-command-child",
                        "commandId": "custom-child",
                        "isDefault": false,
                        "name": "Child Action",
                        "playCompletionSound": true,
                    }
                ],
            }),
        ];

        let (owner_project_id, commands, order, deleted_default_ids) =
            gpui_sidebar_command_state_for_active_project(&domain_projects, "project-child")
                .expect("worktree child should resolve to parent owner state");

        assert_eq!(owner_project_id, "project-parent");
        assert_eq!(order, vec!["custom-parent".to_string()]);
        assert_eq!(deleted_default_ids, vec!["setup".to_string()]);
        assert!(
            commands
                .iter()
                .any(|command| command.command_id == "custom-parent")
        );
        assert!(
            !commands
                .iter()
                .any(|command| command.command_id == "custom-child")
        );
    }

