    #[test]
    fn gpui_remote_machine_password_marker_updates_existing_machine_only() {
        let mut settings = json_object(serde_json::json!({
            "remoteMachines": [
                {
                    "id": "remote-alpha",
                    "name": "Alpha",
                    "sshHost": "example.invalid"
                }
            ]
        }));

        assert!(gpui_set_remote_machine_password_marker(
            &mut settings,
            "remote-alpha",
            true,
        ));
        let machine = settings
            .get("remoteMachines")
            .and_then(serde_json::Value::as_array)
            .and_then(|machines| machines.first())
            .and_then(serde_json::Value::as_object)
            .expect("remote machine should remain an object");
        assert_eq!(
            machine
                .get("sshPasswordSaved")
                .and_then(serde_json::Value::as_bool),
            Some(true)
        );
        assert!(!machine.contains_key("sshPassword"));

        assert!(gpui_set_remote_machine_password_marker(
            &mut settings,
            "remote-alpha",
            false,
        ));
        let machine = settings
            .get("remoteMachines")
            .and_then(serde_json::Value::as_array)
            .and_then(|machines| machines.first())
            .and_then(serde_json::Value::as_object)
            .expect("remote machine should remain an object");
        assert!(!machine.contains_key("sshPasswordSaved"));
        assert!(!gpui_set_remote_machine_password_marker(
            &mut settings,
            "remote-missing",
            true,
        ));
    }

