    #[test]
    fn gpui_remote_machine_config_reads_saved_settings_only() {
        /*
        CDXC:GPUIRemoteMachinesSettings 2026-06-24-14:34:
        Remote reconnect tests stay pure: validate settings parsing, token extraction, SSH option selection, and status classification without opening SSH, reading Keychain, writing Settings, including real hosts/users/paths/tokens, or logging command/output data.
        */
        let settings = json_object(serde_json::json!({
            "remoteMachines": [
                {
                    "id": "remote-alpha",
                    "name": "Alpha",
                    "sshHost": " host.invalid ",
                    "sshIdentityFile": " identity-file ",
                    "sshPasswordSaved": true,
                    "sshPort": 2222,
                    "sshUser": " user ",
                },
                {
                    "id": "remote-beta",
                    "name": "Beta",
                    "sshHost": "other.invalid",
                    "sshPort": 100000,
                }
            ]
        }));

        assert_eq!(
            gpui_remote_machine_config_from_settings(&settings, "remote-alpha"),
            Some(GpuiRemoteMachineConfig {
                remote_machine_id: "remote-alpha".to_string(),
                ssh_host: "host.invalid".to_string(),
                ssh_identity_file: Some("identity-file".to_string()),
                ssh_port: Some(2222),
                ssh_user: Some("user".to_string()),
                has_saved_password: true,
            })
        );
        let beta =
            gpui_remote_machine_config_from_settings(&settings, "remote-beta").expect("beta");
        assert_eq!(beta.ssh_port, None);
        assert_eq!(beta.has_saved_password, false);
        assert!(gpui_remote_machine_config_from_settings(&settings, "remote-missing").is_none());
    }

    #[test]
    fn gpui_remote_gxserver_token_extraction_requires_bounded_token_shape() {
        let token = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdef";
        let stdout = format!(
            "noise\n{GPUI_REMOTE_GXSERVER_TOKEN_START_MARKER}\n{token}\n{GPUI_REMOTE_GXSERVER_TOKEN_END_MARKER}\n"
        );
        assert_eq!(
            gpui_extract_remote_gxserver_token(stdout.as_str()),
            Some(token.to_string())
        );
        assert!(gpui_is_valid_remote_gxserver_token(token));
        assert_eq!(
            gpui_extract_remote_gxserver_token("prefix ABCDEFGHIJKLMNOPQRSTUVWXYZabcdef suffix"),
            Some(token.to_string())
        );
        assert!(!gpui_is_valid_remote_gxserver_token("short"));
        assert!(!gpui_is_valid_remote_gxserver_token(
            "ABCDEFGHIJKLMNOPQRSTUVWXYZabcde!"
        ));
    }

    #[test]
    fn gpui_remote_token_read_failure_classification_matches_install_approval_flow() {
        assert_eq!(gpui_remote_token_read_failure_state(0, false), None);
        assert_eq!(
            gpui_remote_token_read_failure_state(127, false),
            Some(GpuiRemoteGxserverConnectState::InstallApprovalRequired)
        );
        assert_eq!(
            gpui_remote_token_read_failure_state(127, true),
            Some(GpuiRemoteGxserverConnectState::InstallUnavailable)
        );
        assert_eq!(
            gpui_remote_token_read_failure_state(126, false),
            Some(GpuiRemoteGxserverConnectState::SshFailed)
        );
        let message = gpui_remote_token_read_failure_message(
            GpuiRemoteGxserverConnectState::SshFailed,
            &GpuiRemoteProcessResult {
                exit_code: 255,
                stderr: "Permission denied".to_string(),
                stdout: String::new(),
            },
        );
        assert_eq!(message, "SSH authentication failed for the remote machine.");
    }

    #[test]
    fn gpui_remote_ssh_options_separate_key_only_and_password_backed_modes() {
        let key_only = gpui_remote_ssh_client_options(false);
        assert!(
            key_only
                .windows(2)
                .any(|pair| pair == ["-o", "BatchMode=yes"])
        );
        assert!(
            !key_only
                .windows(2)
                .any(|pair| pair == ["-o", "PasswordAuthentication=yes"])
        );

        let password_backed = gpui_remote_ssh_client_options(true);
        assert!(
            password_backed
                .windows(2)
                .any(|pair| pair == ["-o", "BatchMode=no"])
        );
        assert!(
            password_backed
                .windows(2)
                .any(|pair| pair == ["-o", "NumberOfPasswordPrompts=1"])
        );
        assert!(
            password_backed
                .windows(2)
                .any(|pair| pair == ["-o", "PasswordAuthentication=yes"])
        );
    }

