    #[test]
    fn gpui_gxserver_agent_settings_read_response_parses_persisted_state_and_settings() {
        let body = serde_json::json!({
            "ok": true,
            "product": GPUI_GXSERVER_PRODUCT,
            "protocolVersion": GPUI_GXSERVER_PROTOCOL_VERSION,
            "result": {
                "isPersisted": true,
                "settings": {
                    "agentAcceptAllEnabled": false,
                    "defaultPromptAgentId": " claude ",
                },
            },
        })
        .to_string();
        let parsed = parse_gpui_gxserver_read_agent_settings_response(&body)
            .expect("readAgentSettings response should parse");
        assert_eq!(
            parsed,
            GpuiGxserverReadAgentSettingsResult {
                is_persisted: true,
                settings: shared_settings::SharedGxserverAgentSettings::new(false, "claude"),
            }
        );

        let missing_row_body = serde_json::json!({
            "ok": true,
            "product": GPUI_GXSERVER_PRODUCT,
            "protocolVersion": GPUI_GXSERVER_PROTOCOL_VERSION,
            "result": {
                "isPersisted": false,
                "settings": {
                    "agentAcceptAllEnabled": true,
                    "defaultPromptAgentId": "codex",
                },
            },
        })
        .to_string();
        assert!(
            !parse_gpui_gxserver_read_agent_settings_response(&missing_row_body)
                .expect("missing-row readAgentSettings response should parse")
                .is_persisted
        );

        let malformed = serde_json::json!({
            "ok": true,
            "product": GPUI_GXSERVER_PRODUCT,
            "protocolVersion": GPUI_GXSERVER_PROTOCOL_VERSION,
            "result": {
                "isPersisted": "false",
                "settings": {
                    "agentAcceptAllEnabled": true,
                    "defaultPromptAgentId": "codex",
                },
            },
        })
        .to_string();
        assert!(parse_gpui_gxserver_read_agent_settings_response(&malformed).is_err());
    }

    #[test]
    fn gpui_gxserver_agent_settings_reconciliation_action_seeds_or_applies_canonical_only() {
        let local = shared_settings::SharedGxserverAgentSettings::new(true, "codex");
        let canonical = shared_settings::SharedGxserverAgentSettings::new(false, "claude");

        assert_eq!(
            gpui_gxserver_agent_settings_reconciliation_action(
                &local,
                &GpuiGxserverReadAgentSettingsResult {
                    is_persisted: false,
                    settings: canonical.clone(),
                },
            ),
            GpuiGxserverAgentSettingsReconciliationAction::SeedLocal(local.clone())
        );
        assert_eq!(
            gpui_gxserver_agent_settings_reconciliation_action(
                &local,
                &GpuiGxserverReadAgentSettingsResult {
                    is_persisted: true,
                    settings: canonical.clone(),
                },
            ),
            GpuiGxserverAgentSettingsReconciliationAction::ApplyCanonical(canonical)
        );
        assert_eq!(
            gpui_gxserver_agent_settings_reconciliation_action(
                &local,
                &GpuiGxserverReadAgentSettingsResult {
                    is_persisted: true,
                    settings: local.clone(),
                },
            ),
            GpuiGxserverAgentSettingsReconciliationAction::Noop
        );
    }

