    /*
    CDXC:GPUIProjectWorkareaLifecycle 2026-06-24-08:16:
    Placeholder signature tests cover the Phase 6/7 source-only lifecycle copy directly. Mounting and load-failed states must be visible, generic, and non-mounting, while ready/default states stay on the normal placeholder until explicit runtime placeholder replacement is permitted.

    CDXC:GPUISourceWorkarea 2026-06-24-08:16:
    Source placeholder signature tests cover the Phase 5 loading/load-failed bridge copy directly. Loading and load-failed states must be visible, generic, and non-mounting, while ready/default states stay on the normal Source placeholder until explicit runtime placeholder replacement is permitted.
    */
    #[test]
    fn source_loading_and_load_failed_placeholder_signatures_are_distinct_and_generic() {
        let default =
            ProjectEditorPlaceholderSignature::for_mode(TitlebarMode::Source).expect("source");
        let loading_availability = SourceWorkareaRuntimeAvailability::Blocked(
            SourceWorkareaRuntimeBlockReason::SourceReadinessBridgeLoading,
        );
        let failed_availability = SourceWorkareaRuntimeAvailability::Blocked(
            SourceWorkareaRuntimeBlockReason::SourceReadinessBridgeLoadFailed,
        );
        let loading = ProjectEditorPlaceholderSignature::for_source_runtime_availability(
            &loading_availability,
        )
        .expect("source loading placeholder");
        let failed = ProjectEditorPlaceholderSignature::for_source_runtime_availability(
            &failed_availability,
        )
        .expect("source failed placeholder");

        assert!(loading.mode == TitlebarMode::Source);
        assert!(failed.mode == TitlebarMode::Source);
        assert!(loading.color_identity == default.color_identity);
        assert!(failed.color_identity == default.color_identity);
        assert!(loading.title != default.title);
        assert!(failed.title != default.title);
        assert!(loading.message != default.message);
        assert!(failed.message != default.message);
        assert!(loading.title != failed.title);
        assert!(loading.message != failed.message);
        assert!(loading.title.contains("loading"));
        assert!(failed.title.contains("load failed"));
        assert!(loading.message.contains("not ready"));
        assert!(failed.message.contains("retried later"));
        assert_text_omits(
            &format!(
                "{} {} {} {}",
                loading.title, loading.message, failed.title, failed.message
            ),
            &[
                "failure details",
                "source-only",
                "GPUI shell",
                "private_project_id",
                "source_private_surface",
                "project-editor:",
                "/Users/",
                "file://",
                "https://",
                "localhost",
                "127.0.0.1",
                "?token=",
                "secret",
                "stack trace",
                "error:",
                "CEF",
                "code-server",
            ],
        );
    }

