    #[test]
    fn project_editor_sleeping_placeholder_signatures_identify_distinct_restored_modes() {
        let source = ProjectEditorSleepingPlaceholderSignature::for_mode(TitlebarMode::Source)
            .expect("source");
        let browser = ProjectEditorSleepingPlaceholderSignature::for_mode(TitlebarMode::Browser)
            .expect("browser");
        let kanban = ProjectEditorSleepingPlaceholderSignature::for_mode(TitlebarMode::Kanban)
            .expect("kanban");
        let manage = ProjectEditorSleepingPlaceholderSignature::for_mode(TitlebarMode::Manage)
            .expect("manage");

        assert!(source.mode == TitlebarMode::Source);
        assert!(source.badge_label == "Sleeping / restored");
        assert!(source.title == "Source is sleeping");
        assert!(
            source.message
                == "Source shell state is retained. Activate this surface to restore it."
        );
        assert!(source.action_label == "Activate Source");
        assert!(source.color_identity == ProjectEditorSleepingPlaceholderColorIdentity::SourceTeal);

        assert!(browser.mode == TitlebarMode::Browser);
        assert!(browser.badge_label == "Sleeping / restored");
        assert!(browser.title == "Browser is sleeping");
        assert!(
            browser.message
                == "Browser shell state is retained. Activate this surface to restore it."
        );
        assert!(browser.action_label == "Activate Browser");
        assert!(
            browser.color_identity
                == ProjectEditorSleepingPlaceholderColorIdentity::BrowserBlueCefHidden
        );

        assert!(kanban.mode == TitlebarMode::Kanban);
        assert!(kanban.badge_label == "Sleeping / restored");
        assert!(kanban.title == "Kanban is sleeping");
        assert!(
            kanban.message
                == "Kanban shell state is retained. Activate this surface to restore it."
        );
        assert!(kanban.action_label == "Activate Kanban");
        assert!(
            kanban.color_identity == ProjectEditorSleepingPlaceholderColorIdentity::KanbanPurple
        );

        assert!(manage.mode == TitlebarMode::Manage);
        assert!(manage.badge_label == "Sleeping / restored");
        assert!(manage.title == "Manage is sleeping");
        assert!(
            manage.message
                == "Manage shell state is retained. Activate this surface to restore it."
        );
        assert!(manage.action_label == "Activate Manage");
        assert!(manage.color_identity == ProjectEditorSleepingPlaceholderColorIdentity::ManagePink);

        assert!(source.title != browser.title);
        assert!(source.title != kanban.title);
        assert!(source.title != manage.title);
        assert!(browser.title != kanban.title);
        assert!(browser.title != manage.title);
        assert!(kanban.title != manage.title);
        assert!(source.message != browser.message);
        assert!(source.message != kanban.message);
        assert!(source.message != manage.message);
        assert!(browser.message != kanban.message);
        assert!(browser.message != manage.message);
        assert!(kanban.message != manage.message);
        assert!(source.action_label != browser.action_label);
        assert!(source.action_label != kanban.action_label);
        assert!(source.action_label != manage.action_label);
        assert!(browser.action_label != kanban.action_label);
        assert!(browser.action_label != manage.action_label);
        assert!(kanban.action_label != manage.action_label);
        assert!(source.color_identity != browser.color_identity);
        assert!(source.color_identity != kanban.color_identity);
        assert!(source.color_identity != manage.color_identity);
        assert!(browser.color_identity != kanban.color_identity);
        assert!(browser.color_identity != manage.color_identity);
        assert!(kanban.color_identity != manage.color_identity);
    }

